function addNewSection(data = {title: "New Section", col: "main", order: 5, items: []}) {
    const id = 'sec_' + Math.random().toString(36).substr(2, 9);
    const div = document.createElement('div');
    div.className = 'section-box';
    div.setAttribute('data-id', id);
    div.innerHTML = `
        <div class="section-header">
            <input type="text" class="sec-title-input" value="${data.title}">
            <div class="controls-small">
                Order: <input type="number" class="sec-order" value="${data.order}">
                Col: <select class="sec-col">
                    <option value="main" ${data.col==='main'?'selected':''}>Main</option>
                    <option value="side" ${data.col==='side'?'selected':''}>Side</option>
                </select>
                <button type="button" class="btn-remove" style="position:static" onclick="this.closest('.section-box').remove()">×</button>
            </div>
        </div>
        <div id="rows_${id}"></div>
        <button type="button" class="btn-add" onclick="addRow('rows_${id}')">+ Add Row</button>
    `;
    document.getElementById('sections-container').appendChild(div);
    if(data.items.length > 0) data.items.forEach(item => addRow(`rows_${id}`, item));
    else addRow(`rows_${id}`);
}

