/* eslint-disable @typescript-eslint/no-var-requires */
const fs = require('fs');
const path = require('path');

const srcDir = 'C:/Users/Sura/Documents/IE/service-desk-redesign/src/imports/';
const destDir =
  'C:/Users/Sura/Documents/IE/service-desk-frontend/public/imports/';

if (!fs.existsSync(destDir)) {
  fs.mkdirSync(destDir, { recursive: true });
}

fs.readdirSync(srcDir).forEach((file) => {
  if (file.endsWith('.png')) {
    fs.copyFileSync(path.join(srcDir, file), path.join(destDir, file));
    const stat = fs.statSync(path.join(destDir, file));
    console.log(`Copied ${file} - ${stat.size} bytes`);
  }
});

