/* eslint-env node */
'use strict';

module.exports = {
  'data-cy-required': {
    meta: {
      docs: {
        description:
          'Require data-cy attribute on JSX elements for E2E testing',
        category: 'Best Practices',
      },
      schema: [],
    },
    create(context) {
      return {
        JSXOpeningElement(node) {
          const hasDataCy = node.attributes.some(
            (attr) =>
              attr.type === 'JSXAttribute' &&
              attr.name &&
              attr.name.name === 'data-cy',
          );
          if (!hasDataCy) {
            context.report({
              node,
              message:
                'JSX elements must have a data-cy attribute for E2E testing.',
            });
          }
        },
      };
    },
  },
};

