import { NextResponse } from 'next/server';
import type { NextRequest } from 'next/server';
import {
  hasRequiredPermissions,
  isAdminRole,
  requiredPermissionsForPath,
} from './lib/rbac/core';

sd/service-desk-frontend/middleware.ts@8.content:
const AUTH_PUBLIC_EXACT = new Set([
  '/authentication/login',
  '/authentication/forget-password',
  '/authentication/reset-password',
  '/authentication/2fa',
]);

function isPublicPath(pathname: string) {
  if (AUTH_PUBLIC_EXACT.has(pathname)) return true;
  const legacyPublic = new Set([
    '/login',
    '/forgot-password',
    '/reset-password',
    '/confirmpassword',
  ]);
  if (legacyPublic.has(pathname)) return true;
  if (pathname.startsWith('/_next')) return true;
  if (pathname.startsWith('/api')) return true;
  if (pathname === '/favicon.ico') return true;
  if (/\.[a-zA-Z0-9]+$/.test(pathname)) return true;
  return false;
}

export function middleware(req: NextRequest) {
  const { pathname } = req.nextUrl;
  const token = req.cookies.get('token')?.value;
  const rolePermissionsCookie = req.cookies.get('rolePermissions')?.value || '';
  const loggedUserRole = req.cookies.get('loggedUserRole')?.value || '';

  if (pathname === '/') {
    const url = req.nextUrl.clone();
    url.pathname = token ? '/dashboard' : '/authentication/login';
    return NextResponse.redirect(url);
  }

  if (isPublicPath(pathname)) return NextResponse.next();

  if (!token) {
    const url = req.nextUrl.clone();
    url.pathname = '/authentication/login';
    return NextResponse.redirect(url);
  }

  if (isAdminRole(loggedUserRole)) {
    return NextResponse.next();
  }

  const routePermissions = requiredPermissionsForPath(pathname);
  if (routePermissions.length) {
    const rolePermissions = rolePermissionsCookie
      .split(',')
      .map((permission) => permission.trim())
      .filter(Boolean);
    // Enforce server-side route guard when permission cookie is present.
    // If cookie is absent (legacy sessions), fall back to client-side guard.
    if (
      rolePermissions.length &&
      !hasRequiredPermissions(rolePermissions, routePermissions)
    ) {
      const url = req.nextUrl.clone();
      url.pathname = '/setting';
      return NextResponse.redirect(url);
    }
  }

  return NextResponse.next();
}

export const config = {
  matcher: ['/((?!_next/static|_next/image|favicon.ico).*)'],
};

