async function bootstrap() {
  const app = await NestFactory.create(AppModule);
  const logger = new Logger('HTTP');
  const appConfig = app.get(AppConfigService);

  if (!admin.apps.length && appConfig.firebase.enableAuth) {
    const privateKey = appConfig.firebase.privateKey?.replace(/\\n/g, '\n');
    const projectId = appConfig.firebase.projectId;
    const clientEmail = appConfig.firebase.clientEmail;
    if (privateKey && projectId && clientEmail) {
      admin.initializeApp({
        credential: admin.credential.cert({
          privateKey,
          projectId,
          clientEmail,
        }),
      });
    } else {
      admin.initializeApp();
    }
  }

  app.setGlobalPrefix('api/v1');
  app.enableCors();

  app.use(express.json({ limit: '50mb' }));
  app.use(express.urlencoded({ extended: false }));
  app.use((req: Request, res: Response, next: NextFunction) => {
    const startedAt = Date.now();
    res.on('finish', () => {
      const durationMs = Date.now() - startedAt;
      logger.log(
        `${req.method} ${req.originalUrl} ${res.statusCode} - ${durationMs}ms`,
      );
    });
    next();
  });

  app.useGlobalPipes(
    new ValidationPipe({
      whitelist: true,
      transform: true,
      transformOptions: { enableImplicitConversion: true },
    }),
  );
  app.useGlobalFilters(new HttpExceptionFilter());

  const port = process.env.APP_PORT ?? 3003;
  await app.listen(port, '0.0.0.0');
}
void bootstrap();

