'use client';

import { MutationCache } from '@tanstack/react-query';
import type { Mutation } from '@tanstack/react-query';
import { notification } from '@/components/notification';

export type MutationMeta = {
  successMessage?: string;
  errorMessage?: string;
  skipSuccessNotification?: boolean;
  skipErrorNotification?: boolean;
};

function getErrorMessage(error: unknown): string {
  if (error == null) return 'Something went wrong';
  if (typeof error === 'string') return error;
  if (error instanceof Error) return error.message;
  if (typeof error === 'object' && error !== null && 'message' in error) {
    const msg = (error as { message?: unknown }).message;
    return typeof msg === 'string' ? msg : 'Something went wrong';
  }
  return 'Something went wrong';
}

export function buildMutationNotificationCache() {
  return new MutationCache({
    onSuccess: (
      _data,
      _variables,
      _context,
      mutation: Mutation<unknown, unknown, unknown, unknown>,
    ) => {
      const meta = mutation.meta as MutationMeta | undefined;
      if (meta?.skipSuccessNotification) return;
      const message =
        meta?.successMessage ?? 'Operation completed successfully';
      notification.success(message);
    },
    onError: (
      error,
      _variables,
      _context,
      mutation: Mutation<unknown, unknown, unknown, unknown>,
    ) => {
      const meta = mutation.meta as MutationMeta | undefined;
      if (meta?.skipErrorNotification) return;
      const message = meta?.errorMessage ?? getErrorMessage(error);
      notification.error({
        message: 'Error',
        description: message,
        duration: 6,
      });
    },
  });
}

