'use client';

import { useEffect } from 'react';
import { usePathname, useRouter } from 'next/navigation';
import {
  useAuthStore,
  AUTH_SESSION_COOKIE_MAX_AGE_SEC,
  type AuthUser,
} from '@/store/auth';
import { fetchJson } from '@/utils/api';

type ApiEnvelope<T> = { data?: T };

function unwrapData<T>(value: T | ApiEnvelope<T>): T {
  if (value && typeof value === 'object' && 'data' in value) {
    return (value as ApiEnvelope<T>).data as T;
  }
  return value as T;
}

/**
 * Syncs the session token into an HTTP cookie for middleware, and prevents
 * /confirmpassword flicker when the user is not in a forced password-change flow.
 */
export function AuthSessionBridge() {
  const token = useAuthStore((s) => s.token);
  const user = useAuthStore((s) => s.user);
  const userId = useAuthStore((s) => s.userId);
  const tenantId = useAuthStore((s) => s.tenantId);
  const setUserData = useAuthStore((s) => s.setUserData);
  const userIdForPasswordChange = useAuthStore(
    (s) => s.userIdForPasswordChange,
  );
  const pathname = usePathname();
  const router = useRouter();

  useEffect(() => {
    if (!token) return;
    try {
      document.cookie = `token=${encodeURIComponent(token)}; path=/; max-age=${AUTH_SESSION_COOKIE_MAX_AGE_SEC}; SameSite=Lax`;
    } catch {
      // ignore
    }
  }, [token]);

  useEffect(() => {
    if (!token || !tenantId || !userId) return;

    let cancelled = false;
    const refreshKey = `${tenantId}:${userId}`;
    const refreshStorageKey = 'rbac:user-data-refresh-key';

    try {
      const lastKey = sessionStorage.getItem(refreshStorageKey);
      if (lastKey === refreshKey) return;
      sessionStorage.setItem(refreshStorageKey, refreshKey);
    } catch {
      // If sessionStorage is unavailable, continue with a single runtime fetch.
    }

    void (async () => {
      try {
        const response = await fetchJson<ApiEnvelope<AuthUser> | AuthUser>(
          '/users/user-data',
          { token },
        );
        if (cancelled) return;

        const refreshedUser = unwrapData<AuthUser>(response);
        if (!refreshedUser) return;

        const current = useAuthStore.getState().userData ?? user ?? {};
        setUserData({
          ...current,
          ...refreshedUser,
          tenantId,
        });
      } catch {
        // Keep the current session usable; API calls remain the source of enforcement.
      }
    })();

    return () => {
      cancelled = true;
    };
  }, [setUserData, tenantId, token, userId]);

  useEffect(() => {
    if (pathname !== '/confirmpassword') return;
    if (!token || !user) {
      router.replace('/authentication/login');
      return;
    }
    if (userIdForPasswordChange) return;
    if (user.password_changed === false) return;
    router.replace('/dashboard');
  }, [pathname, router, token, user, userIdForPasswordChange]);

  return null;
}

