const fs = require('fs');
const path = require('path');

const root = path.join(__dirname, '..', 'components', 'ui');

function walk(dir) {
  for (const ent of fs.readdirSync(dir, { withFileTypes: true })) {
    const p = path.join(dir, ent.name);
    if (ent.isDirectory()) walk(p);
    else if (/\.(tsx|ts)$/.test(ent.name)) fixFile(p);
  }
}

function fixFile(p) {
  let s = fs.readFileSync(p, 'utf8');
  const orig = s;

  s = s.replace(/origin-\(--([^)]+)\)/g, 'origin-[var(--$1)]');
  s = s.replace(/max-h-\(--([^)]+)\)/g, 'max-h-[var(--$1)]');
  s = s.replace(/max-w-\(--([^)]+)\)/g, 'max-w-[var(--$1)]');
  s = s.replace(/w-\(--([^)]+)\)/g, 'w-[var(--$1)]');
  s = s.replace(/border-\(--([^)]+)\)/g, 'border-[var(--$1)]');
  s = s.replace(/bg-\(--([^)]+)\)/g, 'bg-[var(--$1)]');

  s = s.replace(/\(--spacing\(4\)\)/g, '1rem');
  s = s.replace(/min-h-svh/g, 'min-h-[100svh]');
  s = s.replace(/\bh-svh\b/g, 'h-[100svh]');

  s = s.replace(/\brounded-xs\b/g, 'rounded-sm');
  s = s.replace(/\boutline-hidden\b/g, 'outline-none');
  s = s.replace(/\bshadow-xs\b/g, 'shadow-sm');

  s = s.replace(
    /\*\*:data-\[slot=navigation-menu-link\]:focus:ring-0 \*\*:data-\[slot=navigation-menu-link\]:focus:outline-none/g,
    '[&_[data-slot=navigation-menu-link]]:focus:ring-0 [&_[data-slot=navigation-menu-link]]:focus:outline-none',
  );
  s = s.replace(
    /\*\*:data-\[slot=command-input-wrapper\]:h-12/g,
    '[&_[data-slot=command-input-wrapper]]:h-12',
  );

  s = s.replace(/has-data-\[variant=inset\]/g, 'has-[[data-variant=inset]]');
  s = s.replace(/has-data-\[slot=card-action\]/g, 'has-[[data-slot=card-action]]');

  s = s.replace(/focus-visible:outline-ring/g, 'focus-visible:outline-none');

  s = s.replace(
    /group-data-\[collapsible=icon\]:size-8!/g,
    'group-data-[collapsible=icon]:!size-8',
  );
  s = s.replace(
    /group-data-\[collapsible=icon\]:p-2!/g,
    'group-data-[collapsible=icon]:!p-2',
  );
  s = s.replace(
    /group-data-\[collapsible=icon\]:p-0!/g,
    'group-data-[collapsible=icon]:!p-0',
  );

  s = s.replace(
    /group-has-data-\[sidebar=menu-action\]\/menu-item:pr-8/g,
    '',
  );

  s = s.replace(
    /has-\[>svg\]:grid-cols-\[calc\(var\(--spacing\)\*4\)_1fr\]/g,
    'has-[>svg]:grid-cols-[2.5rem_1fr]',
  );

  s = s.replace(
    /shadow-\[0_0_0_1px_hsl\(var\(--sidebar-border\)\)\]/g,
    'shadow-[0_0_0_1px_var(--sidebar-border)]',
  );
  s = s.replace(
    /shadow-\[0_0_0_1px_hsl\(var\(--sidebar-accent\)\)\]/g,
    'shadow-[0_0_0_1px_var(--sidebar-accent)]',
  );

  if (s !== orig) fs.writeFileSync(p, s);
}

if (!fs.existsSync(root)) {
  console.error('Missing', root);
  process.exit(1);
}
walk(root);
