function toRequestPath(path: string): string {
  return path.startsWith('/') ? path : `/${path}`;
}

export function resolveTenantIdForRequest(): string | undefined {
  const s = useAuthStore.getState();
  const fromRoot =
    s.tenantId != null && String(s.tenantId).trim() !== ''
      ? String(s.tenantId).trim()
      : undefined;
  if (fromRoot) return fromRoot;

  const user = s.user as Record<string, unknown> | null;
  const ud = s.userData as Record<string, unknown> | null;
  const fromUser = user?.tenantId ?? user?.tenant_id;
  if (fromUser != null && String(fromUser).trim() !== '') {
    return String(fromUser).trim();
  }
  const fromUd = ud?.tenantId ?? ud?.tenant_id;
  if (fromUd != null && String(fromUd).trim() !== '') {
    return String(fromUd).trim();
  }
  if (typeof window !== 'undefined') {
    try {
      const ls = localStorage.getItem('tenantId');
      if (ls && ls.trim()) return ls.trim();
    } catch {
      // ignore
    }
  }
  return undefined;
}

/** Tenant + actor headers for every Service Desk API call. */
export function tenantAndUserHeaders(): Record<string, string> {
  const user = useAuthStore.getState().user as Record<string, unknown> | null;
  const h: Record<string, string> = {};
  const tenantId = resolveTenantIdForRequest();
  if (tenantId) {
    h['tenantId'] = tenantId;
    h['x-tenant-id'] = tenantId;
  }
  const actorId = user?.id ?? useAuthStore.getState().userId;
  if (actorId != null && String(actorId).trim() !== '') {
    h['userId'] = String(actorId);
  }
  return h;
}

export async function resolveBearerToken(
  explicit: string | null | undefined,
): Promise<string | null> {
  if (typeof window !== 'undefined') {
    try {
      const mod = await import('@/utils/getCurrentToken');
      const fresh = await mod.getCurrentToken();
      if (fresh) {
        useAuthStore.getState().setToken(fresh);
        return fresh;
      }
    } catch {
      // ignore and continue fallbacks
    }
  }

  if (explicit) return explicit;
  if (typeof window !== 'undefined') {
    try {
      const mod = await import('@/utils/getCurrentToken');
      // Always force-refresh so we never reuse an expired cached token.
      const fresh = await mod.getCurrentToken(true);
      if (fresh) return fresh;
    } catch {
      // ignore
    }
  }
  return null;
}

