export async function fetchJson<T>(
  path: string,
  opts?: {
    token?: string | null;
    method?: string;
    body?: unknown;
    headers?: Record<string, string>;
  },
): Promise<T> {
  const client = getServiceDeskHttp();

  const config: AxiosRequestConfig = {
    method: opts?.method ?? 'GET',
    url: toRequestPath(path),
    headers: AxiosHeaders.from({
      'Content-Type': 'application/json',
      ...(opts?.headers ?? {}),
    }),
    data: opts?.body !== undefined ? opts.body : undefined,
  };

  try {
    const res = await client.request<T>(config);
    return res.data as T;
  } catch (err) {
    mapAxiosError(err);
  }
}

export async function fetchMultipart<T>(
  path: string,
  opts: { token: string | null; method: string; form: FormData },
): Promise<T> {
  const client = getServiceDeskHttp();

  const config: AxiosRequestConfig = {
    method: opts.method,
    url: toRequestPath(path),
    headers: AxiosHeaders.from({}),
    data: opts.form,
  };

  try {
    const res = await client.request<T>(config);
    return res.data as T;
  } catch (err) {
    mapAxiosError(err);
  }
}

