  path: string,
  opts?: { token?: string | null },
): Promise<Blob> {
  const client = getServiceDeskHttp();

  const config: AxiosRequestConfig = {
    method: 'GET',
    url: toRequestPath(path),
    responseType: 'blob',
    headers: AxiosHeaders.from({}),
  };

  try {
    const res = await client.request<Blob>(config);
    return res.data;
  } catch (err) {
    mapAxiosError(err);
  }
}

