/** Keep type-only to avoid runtime cycles with `store/auth`. */
export type RoleDisplayUser = {
  role?:
    | string
    | {
        roleName?: string;
        rolename?: string;
        name?: string;
        slug?: string;
        roleSlug?: string;
      };
};

export function getRoleDisplayName(
  user: RoleDisplayUser | null | undefined,
): string {
  const r = user?.role;
  if (r && typeof r === 'object') {
    const o = r as Record<string, unknown>;
    const name =
      (typeof o.roleName === 'string' && o.roleName.trim()) ||
      (typeof o.rolename === 'string' && o.rolename.trim()) ||
      (typeof o.name === 'string' && o.name.trim()) ||
      '';
    if (name) return name;
    const slug =
      (typeof o.slug === 'string' && o.slug.trim()) ||
      (typeof o.roleSlug === 'string' && o.roleSlug.trim()) ||
      '';
    if (slug) return slug;
  }
  if (typeof r === 'string' && r.trim()) return r.trim();
  return 'Member';
}

