import CryptoJS from 'crypto-js';

const disabled = process.env.NEXT_PUBLIC_ENCRYPTION_DISABLED === 'true';

export function encryptPayload(plain: string): string {
  if (disabled) return plain;
  const key = process.env.NEXT_PUBLIC_ENCRYPTION_KEY;
  const iv = process.env.NEXT_PUBLIC_ENCRYPTION_IV;
  if (!key || !iv) return plain;
  return CryptoJS.AES.encrypt(plain, CryptoJS.enc.Hex.parse(key), {
    iv: CryptoJS.enc.Hex.parse(iv),
    mode: CryptoJS.mode.CBC,
    padding: CryptoJS.pad.Pkcs7,
  }).toString();
}

export function decryptPayload(cipher: string): string {
  if (disabled) return cipher;
  const key = process.env.NEXT_PUBLIC_ENCRYPTION_KEY;
  const iv = process.env.NEXT_PUBLIC_ENCRYPTION_IV;
  if (!key || !iv) return cipher;
  const bytes = CryptoJS.AES.decrypt(cipher, CryptoJS.enc.Hex.parse(key), {
    iv: CryptoJS.enc.Hex.parse(iv),
    mode: CryptoJS.mode.CBC,
    padding: CryptoJS.pad.Pkcs7,
  });
  return bytes.toString(CryptoJS.enc.Utf8);
}

