export function getUserExternalId(
  record: Record<string, unknown> | null | undefined,
): string | undefined {
  if (!record || typeof record !== 'object') return undefined;
  const candidates = [
    record.firebaseId,
    record.firebase_id,
    record.localId,
    record.local_id,
    record.externalId,
    record.external_id,
    record.externalUserId,
    record.userExternalId,
    record.user_external_id,
    record.principalId,
    record.principal_id,
  ];
  for (const c of candidates) {
    if (typeof c === 'string' && c.length > 0) return c;
    if (typeof c === 'number' && !Number.isNaN(c)) return String(c);
  }
  if (record.id !== undefined && record.id !== null) {
    const s = String(record.id);
    if (s.length > 0) return s;
  }
  return undefined;
}

