import { onAuthStateChanged } from 'firebase/auth';
import { getFirebaseAuth } from '@/utils/firebaseConfig';

let ready = false;
let readyPromise: Promise<void> | null = null;

/**
 * Firebase Auth needs a short time after a hard refresh to restore the session.
 * During that window `auth.currentUser` can be null even though the user is
 * signed in. This helper lets callers wait until the first auth state is known.
 */
export function waitForFirebaseAuthReady(timeoutMs = 4000): Promise<void> {
  if (typeof window === 'undefined') return Promise.resolve();
  if (ready) return Promise.resolve();
  if (readyPromise) return readyPromise;

  readyPromise = new Promise<void>((resolve) => {
    const auth = getFirebaseAuth();
    const done = () => {
      ready = true;
      resolve();
    };

    const unsubscribe = onAuthStateChanged(
      auth,
      () => {
        unsubscribe();
        done();
      },
      () => {
        unsubscribe();
        done();
      },
    );

    // Safety net: never hang forever if the SDK callback is delayed.
    window.setTimeout(() => {
      try {
        unsubscribe();
      } catch {
        // ignore
      }
      done();
    }, timeoutMs);
  });

  return readyPromise;
}

export function isFirebaseAuthReady(): boolean {
  return ready;
}

