import { getFirebaseAuth } from '@/utils/firebaseConfig';
import { waitForFirebaseAuthReady } from '@/utils/firebaseAuthReady';

/**
 * Returns a Firebase ID token for API authentication.
 *
 * Important:
 * - This function does NOT fall back to localStorage / Zustand tokens (those may be expired).
 * - It waits for Firebase Auth rehydration after refresh before reading `currentUser`.
 */
export async function getCurrentToken(forceRefresh = false): Promise<string | null> {
  if (typeof window === 'undefined') return null;
  await waitForFirebaseAuthReady();
  try {
    const user = getFirebaseAuth().currentUser;
    if (user) {
      return await user.getIdToken(forceRefresh);
    }
  } catch {
    // ignore
  }
  return null;
}

/** @deprecated Use getCurrentToken */
export async function getCurrentFirebaseIdToken(): Promise<string | null> {
  return getCurrentToken();
}

sd/service-desk-frontend/utils/normalize.content:
/**
 * Strips wrapping quotes and trailing slashes from env-provided URLs.
 * Helps when .env accidentally includes JSON-style quotes or bad encoding.
 */
export function normalizeEnvUrl(raw: string | undefined | null): string {
  if (raw == null) return '';
  let s = String(raw).trim();
  if (
    (s.startsWith('"') && s.endsWith('"')) ||
    (s.startsWith("'") && s.endsWith("'"))
  ) {
    s = s.slice(1, -1).trim();
  }
  try {
    if (s.includes('%22')) s = decodeURIComponent(s);
  } catch {
    // ignore
  }
  return s.replace(/\/+$/, '');
}

