'use client';

import {
  useAuthStore,
  type AuthUser,
  AUTH_ROLE_PERMISSIONS_COOKIE,
} from '@/store/auth';
import {
  PERMISSIONS,
  hasRequiredPermissions,
  isAdminRole,
  normalizePermissionSlugs,
} from '@/lib/rbac/core';

/** Permission slug required to add a private note on a ticket (from permissions catalog). */

/** Permission slug required to add a private note on a ticket (from permissions catalog). */
export const ADD_PRIVATE_NOTE_PERMISSION = PERMISSIONS.addPrivateNote;

export { PERMISSIONS };

function permissionSlug(permission: { slug?: string } | string): string | null {
  const value = typeof permission === 'string' ? permission : permission?.slug;
  return value?.trim().toLowerCase() || null;
}

export function getUserRolePermissionSlugs(user?: AuthUser | null): string[] {
  if (!user) return [];
  const rolePermissions =
    typeof user.role === 'object' && user.role
      ? (user.role.permissions ?? [])
      : [];
  const fromNested = normalizePermissionSlugs(
    rolePermissions.map(permissionSlug),
  ) as string[];
  if (fromNested.length) return fromNested;

  const flat = (user as { rolePermissionSlugs?: string[] }).rolePermissionSlugs;
  if (Array.isArray(flat) && flat.length) {
    return normalizePermissionSlugs(flat) as string[];
  }

  const top = user.permissions;
  if (Array.isArray(top) && top.length) {
    return normalizePermissionSlugs(top.map(permissionSlug)) as string[];
  }
  return [];
}

function parsePermissionCookie(): string[] {
  if (typeof document === 'undefined') return [];
  try {
    const parts = document.cookie.split(';');
    for (const part of parts) {
      const idx = part.indexOf('=');
      if (idx === -1) continue;
      const k = part.slice(0, idx).trim();
      if (k !== AUTH_ROLE_PERMISSIONS_COOKIE) continue;
      const v = decodeURIComponent(part.slice(idx + 1).trim());
      return v
        .split(',')
        .map((s) => s.trim().toLowerCase())
        .filter(Boolean);
    }
  } catch {
    // ignore
  }
  return [];
}

export function getCurrentRolePermissionSlugs(): string[] {
  const state = useAuthStore.getState();
  const fromStore = getUserRolePermissionSlugs(state.userData ?? state.user);
  if (fromStore.length) return fromStore;

  const fromCookie = parsePermissionCookie();
  if (fromCookie.length) return fromCookie;

  try {
    const raw = localStorage?.getItem('permissions') || '';
    return raw
      .split(',')
      .map((p) => p.trim().toLowerCase())
      .filter(Boolean);
  } catch {
    return [];
  }
}

function getCurrentRoleSlug(): string | null {
  const state = useAuthStore.getState();
  const r = state.userData?.role;
  const roleFromStore =
    typeof r === 'string'
      ? r
      : (() => {
          if (!r || typeof r !== 'object') return null;
          const o = r as { slug?: string; roleName?: string; rolename?: string };
          return (
            (typeof o.roleName === 'string' && o.roleName.trim()) ||
            (typeof o.rolename === 'string' && o.rolename.trim()) ||
            (typeof o.slug === 'string' && o.slug.trim()) ||
            null
          );
        })();
  if (roleFromStore && roleFromStore.trim()) return roleFromStore.trim();
  try {
    const fromLegacy = localStorage?.getItem('role') || '';
    return fromLegacy.trim() || null;
  } catch {
    return null;
  }
}

export function checkUserPermission(necessaryPermissions: string[] = []) {
  if (isAdminRole(getCurrentRoleSlug())) return true;
  return hasRequiredPermissions(
    getCurrentRolePermissionSlugs(),
    necessaryPermissions,
  );
}

/** True if the user has at least one of the given permission slugs (or admin). */
export function checkUserHasAnyPermission(slugs: string[]): boolean {
  if (!slugs.length) return false;
  if (isAdminRole(getCurrentRoleSlug())) return true;
  const have = new Set(getCurrentRolePermissionSlugs());
  return slugs.some((s) => have.has(String(s).trim().toLowerCase()));
}

