function legacyRows(ticket: Record<string, unknown> | null | undefined): any[] {
  if (!ticket || typeof ticket !== 'object') return [];
  const v =
    (ticket as any).assigned_users_legacy ??
    (ticket as any).assigned_users ??
    (ticket as any).agents ??
    [];
  return Array.isArray(v) ? v : [];
}

function externalIdList(
  ticket: Record<string, unknown> | null | undefined,
): string[] | null {
  if (!ticket || typeof ticket !== 'object') return null;
  const ext = (ticket as any).assigned_user_external_ids;
  if (!Array.isArray(ext) || ext.length === 0) return null;
  return ext.map(String);
}

export function resolveTicketAssigneeRows(
  ticket: Record<string, unknown> | null | undefined,
  directory?: readonly any[] | null,
): any[] {
  const dir = directory ?? [];
  const legacy = legacyRows(ticket);
  const ext = externalIdList(ticket);
  if (!ext) return legacy;

  return ext.map((id) => {
    const fromDir = dir.find(
      (u: any) => getUserExternalId(u) === id || String(u?.id) === id,
    );
    const fromLegacy = legacy.find((r: any) => {
      if (r == null) return false;
      if (typeof r === 'object')
        return getUserExternalId(r) === id || String(r?.id) === id;
      return String(r) === id;
    });
    if (fromDir) return fromDir;
    if (fromLegacy && typeof fromLegacy === 'object') return fromLegacy;
    if (fromLegacy != null)
      return {
        id,
        email: undefined,
        first_name: String(fromLegacy),
        last_name: '',
      };
    return { id, external_id: id, first_name: 'Assignee', last_name: '' };
  });
}

export function hasResolvedAssignees(
  ticket: Record<string, unknown> | null | undefined,
): boolean {
  return resolveTicketAssigneeRows(ticket).length > 0;
}

export function getTicketAssigneeExternalIds(
  ticket: Record<string, unknown> | null | undefined,
): Set<string> {
  const ext = externalIdList(ticket);
  if (ext) return new Set(ext);
  const legacy = legacyRows(ticket);
  const out = new Set<string>();
  for (const row of legacy) {
    if (row == null) continue;
    if (typeof row === 'object') {
      const e = getUserExternalId(row);
      if (e) out.add(e);
      else if ((row as any).id != null) out.add(String((row as any).id));
    } else out.add(String(row));
  }
  return out;
}

