import { Controller, Get, Query, UseGuards } from '@nestjs/common';
import { AuthGuard } from '../core/guards/auth.guard';
import { CurrentUser } from '../common/decorators/current-user.decorator';
import { User } from '../user/user.entity';
import { ActivitiesService } from './activities.service';
import { ActivityLog, ActivitiesMeta } from './activities.service';

@Controller('activities')
@UseGuards(AuthGuard)
export class ActivitiesController {
  constructor(private readonly activitiesService: ActivitiesService) {}

  @Get()
  async getActivities(
    @CurrentUser() user: User,
    @Query('page') page?: string,
    @Query('limit') limit?: string,
  ): Promise<{ status: 'Success'; data: ActivityLog[]; meta: ActivitiesMeta }> {
    const data = await this.activitiesService.getActivities(
      {
        page: page ? parseInt(page, 10) : undefined,
        limit: limit ? parseInt(limit, 10) : undefined,
      },
      user,
    );

    return { status: 'Success', data: data.data, meta: data.meta };
  }
}

import { Module } from '@nestjs/common';
import { TypeOrmModule } from '@nestjs/typeorm';
import { ActivitiesController } from './activities.controller';
import { ActivitiesService } from './activities.service';
import { Notification } from '../notification/notification.entity';
import { Comment } from '../comment/comment.entity';
import { Note } from '../note/note.entity';

@Module({
  imports: [TypeOrmModule.forFeature([Notification, Comment, Note])],
  controllers: [ActivitiesController],
  providers: [ActivitiesService],
})
export class ActivitiesModule {}

import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Notification } from '../notification/notification.entity';
import { Comment } from '../comment/comment.entity';
import { Note } from '../note/note.entity';
import { User } from '../user/user.entity';

interface ActivitiesQuery {
  page?: number;
  limit?: number;
}

export interface ActivityLog {
  action: string;
  description: string;
  created_at: string;
  type?: string;
  user?: { name: string };
}

export interface ActivitiesMeta {
  page: number;
  limit: number;
  total: number;
  totalPages: number;
}

export interface ActivitiesResult {
  data: ActivityLog[];
  meta: ActivitiesMeta;
}

@Injectable()
export class ActivitiesService {
  constructor(
    @InjectRepository(Notification)
    private readonly notificationRepository: Repository<Notification>,
    @InjectRepository(Comment)
    private readonly commentRepository: Repository<Comment>,
    @InjectRepository(Note)
    private readonly noteRepository: Repository<Note>,
  ) {}

  async getActivities(
    query: ActivitiesQuery,
    user: User,
  ): Promise<ActivitiesResult> {
    const page =
      Number.isFinite(query.page) && (query.page ?? 0) > 0 ? query.page! : 1;
    const requestedLimit =
      Number.isFinite(query.limit) && (query.limit ?? 0) > 0
        ? query.limit!
        : 20;
    const limit = Math.min(requestedLimit, 100);
    const offset = (page - 1) * limit;
    const fetchWindow = Math.min(Math.max(limit * 2, 20), 200);

    const [
      notifications,
      comments,
      notes,
      totalNotifications,
      totalComments,
      totalNotes,
    ] = await Promise.all([
      this.notificationRepository.find({
        where: [{ to: user.id }, { type: 'system' }],
        relations: ['created_by', 'created_to', 'ticket'],
        order: { created_at: 'DESC' },
        take: fetchWindow,
      }),
      this.commentRepository.find({
        relations: ['created_by'],
        order: { created_at: 'DESC' },
        take: fetchWindow,
      }),
      this.noteRepository.find({
        relations: ['created_by'],
        order: { created_at: 'DESC' },
        take: fetchWindow,
      }),
      this.notificationRepository.count({
        where: [{ to: user.id }, { type: 'system' }],
      }),
      this.commentRepository.count(),
      this.noteRepository.count(),
    ]);

    const merged = [
      ...notifications.map((n) => this.mapNotificationToActivity(n)),
      ...comments.map((c) => this.mapCommentToActivity(c)),
      ...notes.map((n) => this.mapNoteToActivity(n)),
    ].filter((item): item is ActivityLog => item !== null);

    merged.sort(
      (a, b) =>
        this.getTimestampValue(b.created_at) -
        this.getTimestampValue(a.created_at),
    );

    const data = merged.slice(offset, offset + limit);
    const total = totalNotifications + totalComments + totalNotes;
    const totalPages = Math.max(1, Math.ceil(total / limit));

    return {
      data,
      meta: { page, limit, total, totalPages },
    };
  }

  private mapNotificationToActivity(
    notification: Notification,
  ): ActivityLog | null {
    const created_at = this.normalizeTimestamp(notification.created_at);
    if (!created_at) return null;
    const parsedDescription = this.parseNotificationMessage(notification);
    const fallbackDescription = this.safeDescription(
      this.stripUuids(
        this.formatDescription(
          this.stripHtml(notification.message || notification.title || ''),
        ),
      ),
    );

    return {
      action: this.getNotificationAction(notification),
      description:
        parsedDescription || fallbackDescription || 'Notification event',
      created_at,
      type: notification.type || undefined,
      user: { name: this.buildUserName(notification.created_by) },
    };
  }

  private mapCommentToActivity(comment: Comment): ActivityLog | null {
    const created_at = this.normalizeTimestamp(comment.created_at);
    if (!created_at) return null;

    const action = comment.is_escalation
      ? 'comment_escalated'
      : comment.is_private
        ? 'comment_private_added'
        : 'comment_added';
    const type = comment.is_escalation
      ? 'escalation'
      : comment.is_private
        ? 'private'
        : 'comment';

    const userName = this.resolveUserDisplayName(comment.created_by, 'User');
    const sourceText =
      this.formatDescription(this.stripHtml(comment.description || '')) ||
      this.formatDescription(this.stripHtml(comment.title || ''));
    const subject = this.extractSubject(sourceText || '');

  let description = `${userName} added a comment`;
  if (action === 'comment_escalated') {
    description = subject
      ? `${userName} escalated a ticket: ${subject}`
      : `${userName} escalated a ticket`;
  } else if (action === 'comment_private_added') {
    description = `${userName} added a private note`;
  }

  return {
    action,
    description: this.safeDescription(description),
    created_at,
    type,
    user: { name: this.buildUserName(comment.created_by) },
  };
}

private mapNoteToActivity(note: Note): ActivityLog | null {
  const created_at = this.normalizeTimestamp(note.created_at);
  if (!created_at) return null;

  return {
    action: 'note_added',
    description:
      this.safeDescription(
        this.formatDescription(this.stripHtml(note.body || '')) ||
          'Note added',
      ) || 'Note added',
    created_at,
    type: 'note',
    user: { name: this.buildUserName(note.created_by) },
  };
}

private buildUserName(user?: Partial<User> | null): string {
  return this.resolveUserDisplayName(user, 'Unknown User');
}

private resolveUserDisplayName(
  user?: Partial<User> | null,
  fallback = 'User',
): string {
  if (!user) return fallback;

  const firstName = user.first_name?.trim() || '';
  const lastName = user.last_name?.trim() || '';
  const fullName = `${firstName} ${lastName}`.trim();

  if (fullName) return this.formatUserName(fullName);
  if (user.email?.trim()) return user.email.trim();

  return fallback;
}

private normalizeTimestamp(
  value: Date | string | null | undefined,
): string | null {
  if (!value) return null;
  const date = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(date.getTime())) return null;
  return date.toISOString();
}

private getTimestampValue(value: string): number {
  const parsed = Date.parse(value);
  return Number.isNaN(parsed) ? 0 : parsed;
}

private stripHtml(html: string): string {
  return html
    .replace(/<\s*br\s*\/?>/gi, '\n')
    .replace(/<\s*\/p\s*>/gi, '\n')
    .replace(/<\s*\/div\s*>/gi, '\n')
    .replace(/<\s*\/li\s*>/gi, '\n')
    .replace(/<[^>]*>/g, ' ')
    .replace(/\r\n/g, '\n')
    .replace(/[ \t\f\v]+/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

private formatDescription(input: string): string {
  if (!input) return '';

  const withBreaks = input
    .replace(/\s*[—-]\s*(?=(Ticket ID:|Subject:|Priority:|Status:))/gi, '\n')
    .replace(/\s+(?=(Ticket ID:|Subject:|Priority:|Status:))/gi, '\n')
    .replace(/\s+[—-]+\s*$/g, '')
    .replace(/\s+Sent via Support Desk\s*$/i, '');

  return withBreaks
    .split('\n')
    .map((line) => line.trim())
    .filter(Boolean)
    .join('\n')
    .trim();
}

private parseNotificationMessage(notification: Notification): string {
  const rawMessage = this.formatDescription(
    this.stripHtml(notification.message || ''),
  );
  const rawTitle = this.formatDescription(
    this.stripHtml(notification.title || ''),
  );
  const baseText = this.safeDescription(rawMessage || rawTitle);
  if (!baseText) return 'Notification event';

  const actorName = this.resolveUserDisplayName(
    notification.created_by,
    'User',
  );
  const assigneeName = this.resolveUserDisplayName(
    notification.created_to || notification.created_by,
    'User',
  );
  const ticketReference = this.getTicketReference(notification);
  const normalized = baseText.toLowerCase();

  if (normalized.includes('assigned')) {
    return this.safeDescription(
      `${assigneeName} was assigned to ${ticketReference}`,
    );
  }

  if (normalized.includes('created')) {
    return this.safeDescription(
      `${actorName} created a new ${ticketReference}`,
    );
  }

  if (
    normalized.includes('updated') ||
    normalized.includes('changed') ||
    normalized.includes('modified')
  ) {
    return this.safeDescription(`${actorName} updated ${ticketReference}`);
  }

  return this.safeDescription(baseText) || 'Notification event';
}

private getTicketReference(notification: Notification): string {
  const ticket = (
    notification as Notification & {
      ticket?: { subject?: string; code?: string };
    }
  ).ticket;
  const subject = ticket?.subject?.trim();
  if (subject) return `ticket '${this.truncateText(subject, 60)}'`;
  const code = ticket?.code?.trim();
  if (code) return `ticket ${code}`;
  return 'a ticket';
}

  private stripUuids(text: string): string {
    if (!text) return '';
    return text.replace(
      /\b[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}\b/gi,
      '',
    );
  }

  private extractSubject(text: string): string | null {
    if (!text) return null;
    const match = text.match(/subject:\s*([^\n\r]+)/i);
    const subject = (match?.[1] || '').trim();
    if (!subject) return null;
    return this.truncateText(this.safeDescription(subject), 60) || null;
  }

  private formatUserName(name: string): string {
    return name
      .trim()
      .split(/\s+/)
      .filter(Boolean)
      .map((part) => part.charAt(0).toUpperCase() + part.slice(1).toLowerCase())
      .join(' ');
  }

  private truncateText(text: string, maxLength: number): string {
    if (text.length <= maxLength) return text;
    return `${text.slice(0, Math.max(0, maxLength - 3)).trim()}...`;
  }

  private safeDescription(text: string): string {
    return this.stripUuids(text)
      .replace(/\bTicket ID:\s*[^\n\r]+/gi, '')
      .replace(/\bSent via Support Desk\b/gi, '')
      .replace(/\s*[—-]\s*$/g, '')
      .replace(/\s{2,}/g, ' ')
      .replace(/\n{3,}/g, '\n\n')
      .trim();
  }

  private getNotificationAction(notification: Notification): string {
    const type = (notification.type || '').trim().toLowerCase();
    if (type === 'user') return 'notification_user';
    if (type === 'system') return 'notification_system';
    return 'notification_created';
  }
}

