import { Injectable, NotFoundException } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Catagory } from './category.entity';

@Injectable()
export class CategoryService {
  constructor(
    @InjectRepository(Catagory)
    private readonly categoryRepository: Repository<Catagory>,
  ) {}

  async findAll(): Promise<Catagory[]> {
    return this.categoryRepository.find({
      relations: ['knowledgebase'],
    });
  }

  async findOne(id: string): Promise<Catagory> {
    const category = await this.categoryRepository.findOne({
      where: { id },
      relations: ['knowledgebase'],
    });
    if (!category)
      throw new NotFoundException('Catagory with the given id is not found');
    return category;
  }

  async create(data: {
    name: string;
    description?: string;
  }): Promise<Catagory> {
    const entity = this.categoryRepository.create(data);
    return this.categoryRepository.save(entity);
  }

  async update(id: string, data: Partial<Catagory>): Promise<Catagory> {
    const entity = await this.categoryRepository.findOne({ where: { id } });
    if (!entity)
      throw new NotFoundException('Catagory with the given id is not found.');
    this.categoryRepository.merge(entity, data);
    return this.categoryRepository.save(entity);
  }

  async remove(id: string): Promise<void> {
