  async getAllClientTicketsByAdmin(@CurrentUser() user: User) {
    const roleName = (user as User & { role?: { roleName?: string } })?.role
      ?.roleName;
    if (roleName !== 'Admin')
      throw new ForbiddenException(
        "You don't have access to view client tickets",
      );
    const data = await this.clientService.getAllClientTicketsByAdmin();
    return { status: 'Success', data };
  }

