  async getProjectByClientId(@CurrentUser() user: User) {
    const data = await this.clientService.getProjectByClientId(user.id);
    return { status: 'Success', data };
  }

  @Get('get-ticket/for-current-logged-in-user/by-project-id/:id')
  async getTicketByProjectIdForCurrentLoggedInUser(
    @Param('id') id: string,
    @CurrentUser() user: User,
  ) {
    if (user.user_type !== UserType.Client)
