        user.id,
        id,
      );
    return { status: 'Success', data };
  }

  @Get('dashboard')
  getDashboard(@CurrentUser() user: User) {
    return this.clientService.getDashboard(user);
  }

  @Get(':id')
  async singleClient(@Param('id') id: string) {
    const data = await this.clientService.findOne(id);
    return { status: 'Success', data };
  }

  @Post('tickets')
  @UseGuards(PermissionsGuard)
  @RequirePermissions('create-client-ticket')
  async createNewTicket(
    @Body() body: CreateClientTicketDto,
    @CurrentUser() user: User,
  ) {
    const payload = {
      subject: body.subject,
      description: body.description,
      type_id: body.type_id,
      supportId: body.supportId,
      support_id: body.support_id ?? body.supportId,
      projectId: body.projectId,
      isCSAT: body.isCSAT,
    };
    const data = await this.clientService.createTicketAsClient(
      user.id,
      payload,
    );
    return {
      status: 'new Ticket is created Successfully',
      data,
      statusCode: '201',
    };
  }

  @Post()
  @HttpCode(HttpStatus.CREATED)
  @UseGuards(PermissionsGuard)
  @RequirePermissions('create-contact')
  @UseInterceptors(FileInterceptor('profile_pic', imageUploadOptions))
  async createClient(
    @Body() body: CreateClientDto,
    @UploadedFile() file: Express.Multer.File,
    @CurrentUser() user: User,
  ) {
    const profile_pic = file?.path ? toUploadRelativePath(file.path) : null;
    const payload: CreateClientData = {
      first_name: body.first_name,
      last_name: body.last_name,
      email: body.email,
      phone_number: body.phone_number,
      company_id: body.company_id,
      profile_pic,
      created_by: user.id,
    };
    const data = await this.clientService.create(payload);
    return { status: 'Success', data };
  }

  @Patch('me')
  async updateProfile(
    @Body() body: UpdateClientProfileDto,
    @CurrentUser() user: User,
  ) {
    const data = await this.clientService.update(
      user.id,
      body as Partial<User>,
    );
    return { status: 'Success', data };
  }

  @Patch('tickets/assignClientTicketToTeamByAdmin/:id')
  @UseGuards(PermissionsGuard)
  @RequirePermissions('assign-client-ticket-to-team-by-admin')
  async assignClientTicketToTeamByAdmin(
    @Param('id') id: string,
    @Body() body: AssignTeamsDto,
  ) {
    const data = await this.clientService.assignClientTicketToTeamByAdmin(
      id,
      body.teams ?? [],
    );
    return { message: 'Success', data };
  }

  @Patch('issue/assignClientIssueToTeamByAdmin/:issueId')
  @UseGuards(PermissionsGuard)
  @RequirePermissions('assign-issue-to-agent')

  @RequirePermissions('assign-issue-to-agent')
  async assignClientIssueToTeamByAdmin(
    @Param('issueId') issueId: string,
    @Body() body: AssignIssueTeamsDto,
    @CurrentUser() user: User,
  ) {
    const roleName = (user as User & { role?: { roleName?: string } })?.role
      ?.roleName;
    if (roleName !== 'Admin')
      throw new ForbiddenException(
        'Only admins can assign client issues to teams',
      );
    const data = await this.clientService.assignClientIssueToTeamByAdmin(
      issueId,
      body.teamIds ?? [],
    );
    return { message: 'Issue successfully assigned to selected teams', data };
  }

  @Patch(':id')
  @UseGuards(PermissionsGuard)
  @RequirePermissions('update-client ')
  @UseInterceptors(FileInterceptor('profile_pic', imageUploadOptions))
  async updateClient(
    @Param('id') id: string,
    @Body() body: UpdateClientDto,
    @UploadedFile() file: Express.Multer.File,
  ) {
    const updates = { ...body };
    if (file?.path)
      (updates as UpdateClientDto).profile_pic = toUploadRelativePath(
