import {
  Injectable,
  NotFoundException,
  BadRequestException,
  ForbiddenException,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { DeepPartial } from 'typeorm';
import { JwtService } from '@nestjs/jwt';
import { User, UserType } from '../user/user.entity';
import { Ticket } from '../ticket/ticket.entity';
import { TicketService } from '../ticket/ticket.service';
import { IssuesService } from '../issues/issues.service';
import { IssueTeam } from '../issues/issue-team.entity';
import { StatusService } from '../status/status.service';
import { KnowledgeBase } from '../knowledge-base/knowledge-base.entity';
import { Support } from '../support/support.entity';
import { CryptoService } from '../common/services/crypto.service';
import { generateRandomPassword } from '../common/utils/random-password.util';
import { AppConfigService } from '../common/config/app-config.service';
import { EmailService } from '../common/services/email.service';
import { generateVerificationCode } from '../common/utils/verification-code.util';

/** Data for creating a client (user with user_type Client). */

/** Data for creating a client (user with user_type Client). */
export type CreateClientData = {
  first_name: string;
  last_name: string;
  email: string;
  phone_number?: string;
  profile_pic?: string | null;
  created_by?: string;
  company_id?: string;
};

@Injectable()
export class ClientService {
  constructor(
    @InjectRepository(User)
    private readonly userRepository: Repository<User>,
    @InjectRepository(Ticket)
    private readonly ticketRepository: Repository<Ticket>,
    @InjectRepository(IssueTeam)
    private readonly issueTeamRepository: Repository<IssueTeam>,
    private readonly ticketService: TicketService,
    private readonly issuesService: IssuesService,
    private readonly statusService: StatusService,
    @InjectRepository(KnowledgeBase)
    private readonly kbRepository: Repository<KnowledgeBase>,
    @InjectRepository(Support)
    private readonly supportRepository: Repository<Support>,
    private readonly crypto: CryptoService,
    private readonly jwtService: JwtService,
    private readonly appConfig: AppConfigService,
    private readonly emailService: EmailService,
  ) {}

  async findAll(): Promise<User[]> {
    const clients = await this.userRepository.find({
      where: { user_type: UserType.Client, is_deleted: false },
      relations: ['company', 'client_tickets'],
    });
    if (!clients?.length) throw new NotFoundException('No client data found');
    return clients;
  }

  async findOne(id: string): Promise<User> {
    const client = await this.userRepository.findOne({
      where: { id, user_type: UserType.Client, is_deleted: false },
      relations: ['company', 'client_tickets'],
    });
    if (!client)
      throw new NotFoundException('client with the given id not found');
    return client;
  }

  async create(data: CreateClientData): Promise<User> {
    const existing = await this.userRepository.findOne({
      where: { email: data.email, is_deleted: false },
    });
    if (existing) throw new BadRequestException('User email already exists');

    const password = generateRandomPassword(8, true, true);
    const hashedPassword = this.crypto.hash(password);

    const user = this.userRepository.create({
      first_name: data.first_name,
      last_name: data.last_name,
      email: data.email,
      password: hashedPassword,
      user_type: UserType.Client,
      phone_number: data.phone_number ?? null,
      profile_pic: data.profile_pic ?? null,
      manager_id: null,
      created_by: data.created_by ?? null,
      company_id: data.company_id ?? null,
    } as unknown as DeepPartial<User>);

    const saved = await this.userRepository.save(user);

    if (this.emailService.isConfigured() && data.email) {
      const name =
        [saved.first_name, saved.last_name].filter(Boolean).join(' ') || 'User';
      const loginUrl =
        (this.appConfig.frontendUrl ?? 'http://localhost:3000').replace(
          /\/?$/,
          '',
        ) + '/login';
      await this.emailService.send({
        to: data.email,
        subject: '[SD] Your account invitation',
        html: `<p>Hello ${name},</p><p>Your account has been created. Temporary password: <strong>${password}</strong></p><p><a href="${loginUrl}">Log in here</a></p>`,
      });
    }

    return this.findOne(saved.id);
  }

  async update(id: string, data: Partial<User>): Promise<User> {
    const client = await this.findOne(id);
    this.userRepository.merge(client, data);
    return this.userRepository.save(client);
  }

  async remove(id: string): Promise<void> {
    const client = await this.findOne(id);
    client.is_deleted = true;
    await this.userRepository.save(client);
  }

  /**
   * Tickets for the given client user.
   * Matches Express: tickets of that client's company (ticket.company_id = client's company_id).
   * If the client has no company, falls back to tickets where client_id = user id.
   * When statusId is provided, only tickets with that ticket status are returned.
   */
  async getClientTickets(
    clientUserId: string,
    statusId?: string,
  ): Promise<Ticket[]> {
    const client = await this.userRepository.findOne({
      where: { id: clientUserId, is_deleted: false },
      select: ['id', 'company_id'],
    });
    if (!client) return [];

    const companyId = client.company_id;
    type WhereItem =
      | { company_id: string; is_deleted: boolean; status_id?: string }
      | { client_id: string; is_deleted: boolean; status_id?: string };

    | { client_id: string; is_deleted: boolean; status_id?: string };
  const whereConditions: WhereItem[] = companyId
    ? [{ company_id: companyId, is_deleted: false }]
    : [{ client_id: clientUserId, is_deleted: false }];

  if (statusId?.trim()) {
    whereConditions.forEach((w) => {
      w.status_id = statusId.trim();
    });
  }

  return this.ticketRepository.find({
    where: whereConditions,
    relations: [
      'ticket_status',
      'ticket_type',
      'ticket_priority',
      'team',
      'project',
      'comments',
      'client',
      'company',
      'issues',
      'issues.status',
      'issues.team',
      'issues.agent',
      'issues.issue_teams',
      'issues.issue_teams.team',
      'issues.issue_agents',
      'issues.issue_agents.agent',
    ],
    order: { created_at: 'DESC' },
  });
}

/** Resolve status id from issue (column or relation; supports statusId, status_id, status.id). */
private getIssueStatusId(issue: {
  statusId?: string;
  status?: { id?: string };
}): string | undefined {
  const fromRelation = (issue as { status?: { id?: string } })?.status?.id;
  const fromColumn =
    issue?.statusId ??
    (issue as { status_id?: string })?.status_id ??
    fromRelation;
  const raw = fromColumn;
  return raw != null ? String(raw).trim() : undefined;
}

/** Get client tickets, optionally filtered by status_id (ticket-level or any issue with that status). */
async getClientTicketsGrouped(
  clientUserId: string,
  statusId?: string,
): Promise<Ticket[]> {
  let tickets = await this.getClientTickets(clientUserId);

  if (statusId?.trim()) {
    const id = String(statusId).trim();
    tickets = tickets.filter((t) => {
      const ticketStatusId =
        t.status_id != null ? String(t.status_id).trim() : '';
      if (ticketStatusId === id) return true;
      const hasIssueWithStatus = t.issues?.some((i) => {
        const issueStatusId = this.getIssueStatusId(i);
        return issueStatusId != null && String(issueStatusId) === id;
      });
      return !!hasIssueWithStatus;
    });
  }

  return tickets;
}

/** Single ticket by id (for client context). */
async getClientTicketById(ticketId: string): Promise<Ticket> {
  return this.ticketService.findOne(ticketId);
}

/** All client tickets where team is null (admin view). */
async getAllClientTicketsByAdmin(): Promise<Ticket[]> {
  const tickets = await this.ticketRepository.find({
    where: { is_deleted: false, team_id: null as unknown as string },
    relations: [
      'ticket_status',
      'ticket_type',
      'client',
      'company',
      'team',
      'issues',
      'issues.issue_teams',
      'issues.issue_teams.team',
      'issues.issue_agents',
      'issues.issue_agents.agent',
    ],
    order: { created_at: 'DESC' },
  });
  return tickets.filter((t) => !t.team_id);
}

/** Create ticket as client (client user). */
async createTicketAsClient(
  clientUserId: string,
  body: Record<string, unknown>,
): Promise<Ticket> {
  const client = await this.findOne(clientUserId);
  if (client.user_type !== UserType.Client)
    throw new ForbiddenException('Unauthorized user');
  const payload = {
    subject: (body.subject as string) || 'Client ticket',
    description: (body.description as string) ?? undefined,
    type_id: body.type_id as string,
    client_id: clientUserId,
    client_external_id: client.local_id ?? undefined,
    tenant_id: client.tenant_id ?? undefined,
    company_id: client.company_id ?? undefined,
    project_id: (body.projectId as string) ?? undefined,
    support_id: (body.supportId as string) ?? undefined,
    is_csat: !!(body.isCSAT ?? body.is_csat),
  };
  return this.ticketService.create(payload, {
    userId: clientUserId,
    externalUserId: client.local_id ?? undefined,
    tenantId: client.tenant_id ?? undefined,
  });
}

/** Assign ticket to team(s) by admin. */
async assignClientTicketToTeamByAdmin(
  ticketId: string,
  teamIds: string[],
): Promise<Ticket> {
  const ticket = await this.ticketService.findOne(ticketId);
  if (!ticket) throw new NotFoundException('Ticket not found');
  const firstTeamId = teamIds?.[0];
  if (firstTeamId) {
    await this.ticketService.update(ticketId, { team_id: firstTeamId });
  }
  return this.ticketService.findOne(ticketId);
}

/** Assign issue to team(s) by admin. Persists to issue_team table (matches Express). */
async assignClientIssueToTeamByAdmin(
  issueId: string,
  teamIds: string[],
): Promise<Ticket> {
  const issue = await this.issuesService.findOne(issueId);
  await this.issueTeamRepository.delete({ issue_id: issueId });
  if (teamIds?.length) {
    const relations = teamIds.map((team_id) =>
      this.issueTeamRepository.create({ issue_id: issueId, team_id }),
    );
    await this.issueTeamRepository.save(relations);
    await this.issuesService.update(issueId, { teamId: teamIds[0] });
  }
  return this.ticketService.findOne(issue.ticketId);
}

/** Send activation/verification email to client. */

/** Send activation/verification email to client. */
async sendActivationCode(clientUserId: string): Promise<User> {
  const user = await this.findOne(clientUserId);
  const { code, expiresAt } = generateVerificationCode();
  const resetToken = this.jwtService.sign({ sub: user.id });
  user.verificationCode = String(code);
  user.passwordChangeToken = resetToken;
  user.tokenExpirationTime = String(expiresAt);
  await this.userRepository.save(user);
  const frontendUrl = this.appConfig.frontendUrl || 'http://localhost:3000';
  const link = `${frontendUrl}/verification/${user.id}`;
  if (this.emailService.isConfigured()) {
    await this.emailService.send({
      to: user.email,
      subject: '[SD] Account activation – set your password',
      html: `<p>Hello ${user.first_name ?? ''} ${user.last_name ?? ''},</p><p>Your account has been created in the SD system.</p><p>To activate and set your password, click the link below:</p><p><a href="${link}">Set your password</a></p><p>Your verification code is <strong>${code}</strong>.</p><p>If you did not expect this email, you can ignore it.</p>`,
    });
  }
  return user;
}

/** Projects for current client: supports for the given client user id. */
async getProjectByClientId(clientUserId?: string) {
  const where = clientUserId ? { clientId: clientUserId } : {};
  const supports = await this.supportRepository.find({
    where,
    relations: ['client', 'project'],
  });
  return supports;
}

/** Tickets for client filtered by support (project) and grouped. */
async getTicketByProjectIdForCurrentLoggedInUser(
  clientUserId: string,
  supportId: string,
): Promise<{
  openTickets: Ticket[];
  pendingTickets: Ticket[];
  closedTickets: Ticket[];
  escalateTickets: Ticket[];
  fullyUnAssignedTickets: Ticket[];
  partiallyAssignedTickets: Ticket[];
  fullyAssignedTickets: Ticket[];
}> {
  const tickets = await this.getClientTickets(clientUserId);
  const filtered = tickets.filter((t) => t.support_id === supportId);
  const openTickets = filtered.filter((t) =>
    t.issues?.some((i) => !i.isClosed),
  );
  const closedTickets = filtered.filter(
    (t) => t.issues?.length && t.issues.every((i) => i.isClosed),
  );
  const pendingTickets = filtered.filter(
    (t) =>
      t.issues?.length &&
      t.issues.some((i) => !i.isClosed) &&
      t.issues.some((i) => i.isClosed),
  );
  const escalateTickets = filtered.filter(
    (t) =>
      (t as { ticket_status?: { type?: string } }).ticket_status?.type ===
      'Escalet',
  );
  const fullyUnAssignedTickets = filtered.filter(
    (t) => t.issues?.length && t.issues.every((i) => !i.teamId),
  );
  const partiallyAssignedTickets = filtered.filter(
    (t) =>
      t.issues?.length &&
      t.issues.some((i) => i.teamId) &&
      t.issues.some((i) => !i.teamId),
  );
  const fullyAssignedTickets = filtered.filter(
    (t) => t.issues?.length && t.issues.every((i) => i.teamId),
  );
  return {
    openTickets,
    pendingTickets,
    closedTickets,
    escalateTickets,
    fullyUnAssignedTickets,
    partiallyAssignedTickets,
    fullyAssignedTickets,
  };
}

async getDashboard(user: User) {
  const tickets = await this.getClientTickets(user.id);
  const hasOpenIssues = tickets.filter(
    (t) =>
      t.issues?.length && t.issues.some((i) => i?.status?.type === 'Open'),
  );
  const hasPendingIssues = tickets.filter(
    (t) =>
      t.issues?.length && t.issues.some((i) => i?.status?.type === 'Pending'),
  );
  const hasClosedIssues = tickets.filter(
    (t) =>
      t.issues?.length && t.issues.some((i) => i?.status?.type === 'Closed'),
  );
  const hasEscalatedIssues = tickets.filter(
    (t) =>
      t.issues?.length && t.issues.some((i) => i?.status?.type === 'Escalet'),
  );
  const summary = {
    totalTickets: tickets.length,
    open: hasOpenIssues.length,
    pending: hasPendingIssues.length,
    closed: hasClosedIssues.length,
    escalated: hasEscalatedIssues.length,
  };
  const sorted = [...tickets].sort(
    (a, b) =>
      new Date(b.created_at).getTime() - new Date(a.created_at).getTime(),
  );
  const recentTickets = sorted.slice(0, 5).map((t) => ({
    id: t.id,
    subject: t.subject,
    created_at: t.created_at,
    ticket_status: t.ticket_status,
    ticket_priority: t.ticket_priority,
  }));
  let recentArticles: Array<{
    id: string;
    title: string;
    created_at: Date;
    author: string | null;
    catagory: { id: string; name: string } | null;
  }> = [];
  try {
    const companyId = user.company_id;

      const companyId = user.company_id;
      const kbList =
        companyId != null
          ? await this.kbRepository
              .createQueryBuilder('kb')
              .leftJoinAndSelect('kb.createdByUser', 'creator')
              .leftJoinAndSelect('kb.catagory', 'catagory')
              .where('creator.companyId = :companyId', { companyId })
              .orderBy('kb.created_at', 'DESC')
              .take(5)
              .getMany()
          : [];
      recentArticles = kbList.map((k) => ({
        id: k.id,
        title: k.title,
        created_at: k.created_at,
        author: k.createdByUser
          ? `${k.createdByUser.first_name ?? ''} ${k.createdByUser.last_name ?? ''}`.trim() ||
            k.createdByUser.email
          : null,
        catagory: k.catagory
          ? { id: k.catagory.id, name: (k.catagory as { name: string }).name }
          : null,
      }));
    } catch {
      // optional
    }
    return {
      status: 'Success',
      data: { summary, recentTickets, recentArticles },
    };
  }
}

