@Controller('comments')
@UseGuards(AuthGuard)

@UseGuards(AuthGuard)
export class CommentController {
  constructor(private readonly commentService: CommentService) {}

  @Get()
  async getAllComments(@CurrentUser() user: User) {
    const data = await this.commentService.findAll(user.tenant_id ?? undefined);
    return { status: 'Success', data };
  }

  @Get('ticket/:id')
  async getCommentByTicket(@Param('id') id: string, @CurrentUser() user: User) {
    const data = await this.commentService.findByTicketId(
      id,
      user.tenant_id ?? undefined,
    );
    return { status: 'Success', data };
  }

  @Get(':id')
  async getOneComment(@Param('id') id: string) {
    const data = await this.commentService.findOne(id);
    return { status: 'Success', data };
  }

  @Post()
  @UseGuards(PermissionsGuard)
  @RequirePermissions('create-comment')
  async createComment(
    @Body() body: CreateCommentDto,
    @CurrentUser() user: User,
  ) {
    const data = await this.commentService.create({
      ...body,
      user_id: user.id,
      user_external_id: user.local_id ?? undefined,
      tenant_id: user.tenant_id ?? undefined,
    } as Parameters<CommentService['create']>[0]);
    return { status: 'Success', data };
  }

  @Post('private')
  @UseGuards(PermissionsGuard)
  @RequirePermissions('create-private-comment')
  async createPrivateComment(
    @Body() body: CreateCommentDto,
    @CurrentUser() user: User,
  ) {
    const data = await this.commentService.createPrivate({
      ...body,
      user_id: user.id,
      user_external_id: user.local_id ?? undefined,
      tenant_id: user.tenant_id ?? undefined,
      is_private: true,
    } as Parameters<CommentService['createPrivate']>[0]);
    return { status: 'Success', data };
  }

  @Post('escalate')
  @UseGuards(PermissionsGuard)
  @RequirePermissions('create-comment-escalation')
  async createEscalation(
    @Body() body: CreateCommentDto,
    @CurrentUser() user: User,
  ) {
    const data = await this.commentService.createEscalation({
      ...body,
      user_id: user.id,
      user_external_id: user.local_id ?? undefined,
      tenant_id: user.tenant_id ?? undefined,
      is_escalation: true,
    } as Parameters<CommentService['createEscalation']>[0]);
    return { status: 'Success', data };
  }

  @Patch()
  @UseGuards(PermissionsGuard)
  @RequirePermissions('update-comment')
  async editComment(@Body() body: UpdateCommentDto) {
    const { id, ...rest } = body;
    const data = await this.commentService.update(id, rest as Partial<Comment>);
    return { status: 'Success', data };
  }

  @Delete('deleteAllComments')
  @UseGuards(PermissionsGuard)
  @RequirePermissions('delete-all-comments')
  async deleteAllComments() {
    const data = await this.commentService.removeAll();
    return { status: 'Success', data };
  }

  @Delete(':id')
  @UseGuards(PermissionsGuard)
  @RequirePermissions('delete-comment')
  async deleteComment(@Param('id') id: string) {
    await this.commentService.remove(id);
    return { status: 'Success', data: null };
  }

  @Patch('comment-replay/by-comment-id/:id')
  @UseGuards(PermissionsGuard)
  @RequirePermissions('update-comment')
