import { Comment } from './comment.entity';
import { CommentController } from './comment.controller';
import { CommentService } from './comment.service';

@Module({
  imports: [TypeOrmModule.forFeature([Comment])],
  controllers: [CommentController],
  providers: [CommentService],
  exports: [TypeOrmModule, CommentService],
})
export class CommentModule {}

import { Injectable, NotFoundException } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Comment } from './comment.entity';

@Injectable()

@Injectable()
export class CommentService {
  constructor(
    @InjectRepository(Comment)
    private readonly commentRepository: Repository<Comment>,
  ) {}

  async findAll(tenantId?: string): Promise<Comment[]> {
    return this.commentRepository.find({
      where: tenantId?.trim() ? { tenant_id: tenantId.trim() } : {},
      relations: ['created_by', 'ticket'],
    });
  }

  async findByTicketId(
    ticketId: string,
    tenantId?: string,
  ): Promise<Comment[]> {
    return this.commentRepository.find({
      order: { created_at: 'DESC' },
      where: {
        ticket_id: ticketId,
        ...(tenantId?.trim() ? { tenant_id: tenantId.trim() } : {}),
      },
      relations: ['created_by', 'ticket'],
    });
  }

  async findOne(id: string): Promise<Comment> {
    const comment = await this.commentRepository.findOne({
      where: { id },
      relations: ['created_by', 'ticket'],
    });
    if (!comment) throw new NotFoundException('Comment does not exist');
    return comment;
  }

  async create(
    data: Partial<Comment> & {
      user_id: string;
      user_external_id?: string;
      tenant_id?: string;
    },
  ): Promise<Comment> {
    const comment = this.commentRepository.create(data);
    return this.commentRepository.save(comment);
  }

  async createPrivate(
    data: Partial<Comment> & {
      user_id: string;
      user_external_id?: string;
      tenant_id?: string;
    },
  ): Promise<Comment> {
    const comment = this.commentRepository.create({
      ...data,
      is_private: true,
    });
    return this.commentRepository.save(comment);
  }

  async createEscalation(
    data: Partial<Comment> & {
      user_id: string;
      user_external_id?: string;
      tenant_id?: string;
    },
  ): Promise<Comment> {
    const comment = this.commentRepository.create({
      ...data,
      is_escalation: true,
    });
    return this.commentRepository.save(comment);
  }

  async update(id: string, data: Partial<Comment>): Promise<Comment> {
    const comment = await this.findOne(id);
    this.commentRepository.merge(comment, data);
    return this.commentRepository.save(comment);
  }

  async createReplay(
    commentId: string,
    data: Partial<Comment>,
  ): Promise<Comment> {
    return this.update(commentId, data);
  }

  async remove(id: string): Promise<void> {
    await this.findOne(id);
    await this.commentRepository.delete({ id });
  }

  /** Returns deleted comments to match Express deleteAllComments response. */
  async removeAll(): Promise<Comment[]> {
    const comments = await this.commentRepository.find();
    await this.commentRepository.clear();
    return comments;
  }
}

