@Controller('company')
@UseGuards(AuthGuard)

@UseGuards(AuthGuard)
export class CompanyController {
  constructor(private readonly companyService: CompanyService) {}

  @Get()
  async allCompanies() {
    const data = await this.companyService.findAll();
    return { status: 'Success', data };
  }

  @Get('company/statisifaction/by-percent')
  async totalCompanySatisfaction() {
    const data = await this.companyService.totalCompanySatisfaction();
    return { status: 'Success', data };
  }

  @Get(':id')
  @UseGuards(PermissionsGuard)
  @RequirePermissions('view-company')
  async singleCompany(@Param('id') id: string) {
    const data = await this.companyService.findOne(id);
    return { status: 'Success', data };
  }

  @Post()
  @UseGuards(PermissionsGuard)
  @RequirePermissions('create-company')
  @HttpCode(HttpStatus.CREATED)
  @UseInterceptors(FileInterceptor('company_logo', imageUploadOptions))
  async create(
    @Body() body: Partial<Company>,
    @UploadedFile() file: Express.Multer.File,
  ) {
    const company_logo = file?.path
      ? toUploadRelativePath(file.path)
      : undefined;
    const data = await this.companyService.create({ ...body, company_logo });
    return { status: 'Success', data };
  }

  @Patch(':id')
  @UseGuards(PermissionsGuard)
  @RequirePermissions('update-company')
  @UseInterceptors(FileInterceptor('company_logo', imageUploadOptions))
  async update(
    @Param('id') id: string,
    @Body() body: Partial<Company>,
    @UploadedFile() file: Express.Multer.File,
  ) {
    const updates = { ...body };
    if (file?.path) updates.company_logo = toUploadRelativePath(file.path);
    const data = await this.companyService.update(id, updates);
    return { status: 'Success', data };
  }

  @Delete(':id')
  @UseGuards(PermissionsGuard)
  @RequirePermissions('delete-company')
  async delete(@Param('id') id: string) {
    const data = await this.companyService.remove(id);
    return { status: 'Success', data };
  }
}

