import { Injectable, NotFoundException, HttpException } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Company } from './company.entity';

@Injectable()

@Injectable()
export class CompanyService {
  constructor(
    @InjectRepository(Company)
    private readonly companyRepository: Repository<Company>,
  ) {}

  async findAll(): Promise<Company[]> {
    const companies = await this.companyRepository.find({
      relations: ['clients', 'tickets'],
    });
    if (!companies?.length)
      throw new NotFoundException('No company data found');
    return companies;
  }

  async findOne(id: string): Promise<Company> {
    const company = await this.companyRepository.findOne({
      where: { id },
      relations: ['clients', 'tickets'],
    });
    if (!company)
      throw new NotFoundException('company with the given id not found');
    return company;
  }

  async findByName(company_name: string): Promise<Company | null> {
    return this.companyRepository.findOne({ where: { company_name } });
  }

  async create(data: Partial<Company>): Promise<Company> {
    const existing = await this.findByName(data.company_name!);
    if (existing?.company_name === data.company_name) {
      throw new HttpException(
        'Company with the same name is already exist',
        500,
      );
    }
    const company = this.companyRepository.create(data);
    return this.companyRepository.save(company);
  }

  async update(id: string, data: Partial<Company>): Promise<Company> {
    const company = await this.findOne(id);
    this.companyRepository.merge(company, data);
    return this.companyRepository.save(company);
  }

  /** Returns deleted company to match Express deleteCompany response. */
  async remove(id: string): Promise<Company> {
    const company = await this.findOne(id);
    await this.companyRepository.delete({ id });
    return company;
  }

  /** Satisfaction by percent: placeholder; can be extended with ticket rates. */
  async totalCompanySatisfaction(): Promise<{
    positivePercentage: number;
    negativePercentage: number;
    per: unknown;
  }> {
    const companies = await this.companyRepository.find({
      relations: ['tickets'],
    });
    if (!companies?.length) {
      throw new NotFoundException('No companies found');
    }
    let totalTickets = 0;
    let positive = 0;
    let negative = 0;
    for (const company of companies) {
      for (const ticket of company.tickets || []) {
        const rate =
          parseInt((ticket as { rate?: string }).rate ?? '0', 10) || 0;
        if (rate !== 0) {
          totalTickets++;
          if (rate >= 3) positive++;
          else negative++;
        }
      }
    }
    const positivePercentage = totalTickets
      ? (positive / totalTickets) * 100
      : 0;
    const negativePercentage = totalTickets
      ? (negative / totalTickets) * 100
      : 0;
    const totalSatisfaction = companies.reduce(
      (sum, c) => sum + (parseInt(c.health_score || '0', 10) || 0),
      0,
    );
    return {
      positivePercentage,
      negativePercentage,
      per: { totalSatisfaction },
    };
  }
}

