import { Module } from '@nestjs/common';
import { TypeOrmModule } from '@nestjs/typeorm';
import { Ticket } from '../ticket/ticket.entity';
import { Status } from '../status/status.entity';
import { Priority } from '../priority/priority.entity';
import { DashboardController } from './dashboard.controller';
import { DashboardService } from './dashboard.service';

@Module({
  imports: [TypeOrmModule.forFeature([Ticket, Status, Priority])],
  controllers: [DashboardController],
  providers: [DashboardService],
})
export class DashboardModule {}

import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Ticket } from '../ticket/ticket.entity';
import { Status } from '../status/status.entity';
import { Priority } from '../priority/priority.entity';

interface StatusRow {
  statusId: string;
  statusType: string;
  count: string;
}

interface PriorityRow {
  priorityId: string;
  priorityType: string;
  count: string;
}

interface AgentAssignmentRow {
  userId: string;
  firstName: string;
  lastName: string;
  email: string;
  totalAssigned: string;
}

interface AgentResolvedRow {
  userId: string;
  resolved: string;
}

type TicketActivityPeriod = '7d' | '30d' | '90d';

type TicketActivityRow = {
  // Depending on driver/config, DATE() may come back as string or Date.
  date: string | Date;
  count: string;
};

/**
 * Dashboard service: summary, tickets by status/priority, recent tickets, agent performance.
 * Same response data shape as Express.
 */
@Injectable()
export class DashboardService {
  constructor(
    @InjectRepository(Ticket)
    private readonly ticketRepo: Repository<Ticket>,
    @InjectRepository(Status)
    private readonly statusRepo: Repository<Status>,
    @InjectRepository(Priority)
    private readonly priorityRepo: Repository<Priority>,
  ) {}

  async getSummary(tenantId?: string): Promise<{
    totalTickets: number;
    openTickets: number;
    resolvedToday: number;
    overdueTickets: number;
    slaBreaches: number;
  }> {
    const todayStart = new Date();
    todayStart.setHours(0, 0, 0, 0);
    const now = new Date();

    const openStatus = await this.statusRepo.findOne({
      where: { type: 'Open', is_deleted: false },
    });

    const tenantClause = tenantId?.trim() ? tenantId.trim() : null;

    const [totalTickets, openTickets, resolvedToday, overdueTickets] =
      await Promise.all([
        this.ticketRepo.count({
          where: {
            is_deleted: false,
            ...(tenantClause ? { tenant_id: tenantClause } : {}),
          },
        }),
        openStatus
          ? this.ticketRepo
              .createQueryBuilder('ticket')
              .innerJoin('ticket.ticket_status', 'openStatus')
              .where('ticket.is_deleted = :is_deleted', { is_deleted: false })
              .andWhere(
                tenantClause ? 'ticket.tenant_id = :tenantId' : '1=1',
                tenantClause ? { tenantId: tenantClause } : {},
              )
              .andWhere('openStatus.id = :statusId', {
                statusId: openStatus.id,
              })
              .getCount()
          : 0,
        this.ticketRepo
          .createQueryBuilder('ticket')
          .innerJoin('ticket.ticket_status', 'status')
          .where('ticket.is_deleted = :is_deleted', { is_deleted: false })
          .andWhere(
            tenantClause ? 'ticket.tenant_id = :tenantId' : '1=1',
            tenantClause ? { tenantId: tenantClause } : {},
          )
          .andWhere('ticket.closed = :closed', { closed: true })
          .andWhere('ticket.updated_at >= :today', { today: todayStart })
          .getCount(),
        this.ticketRepo
          .createQueryBuilder('ticket')
          .where('ticket.is_deleted = :is_deleted', { is_deleted: false })
          .andWhere(
            tenantClause ? 'ticket.tenant_id = :tenantId' : '1=1',
            tenantClause ? { tenantId: tenantClause } : {},
          )
          .andWhere('ticket.closed = :closed', { closed: false })
          .andWhere('ticket.due_date IS NOT NULL')
          .andWhere('ticket.due_date < :now', { now })
          .getCount(),
      ]);

    return {
      totalTickets,
      openTickets,
      resolvedToday,
      overdueTickets,
      slaBreaches: overdueTickets,
    };
  }

  async getTicketsByStatus(
    tenantId?: string,
  ): Promise<{ statusId: string; statusType: string; count: number }[]> {
    const tenantClause = tenantId?.trim() ? tenantId.trim() : null;
    const rows = await this.ticketRepo
      .createQueryBuilder('ticket')
      .leftJoin('ticket.ticket_status', 'status')
      .select('status.id', 'statusId')
      .addSelect('status.type', 'statusType')
      .addSelect('COUNT(ticket.id)', 'count')
      .where('ticket.is_deleted = :is_deleted', { is_deleted: false })
      .andWhere(
        tenantClause ? 'ticket.tenant_id = :tenantId' : '1=1',
        tenantClause ? { tenantId: tenantClause } : {},
      )
      .groupBy('status.id')
      .addGroupBy('status.type')
      .getRawMany<StatusRow>();

    return rows.map((r) => ({
      statusId: r.statusId,
      statusType: r.statusType ?? 'Unassigned',
      count: parseInt(r.count, 10),
    }));
  }

  async getTicketsByPriority(
    tenantId?: string,
  ): Promise<{ priorityId: string; priorityType: string; count: number }[]> {
    const tenantClause = tenantId?.trim() ? tenantId.trim() : null;

  const tenantClause = tenantId?.trim() ? tenantId.trim() : null;
  const rows = await this.ticketRepo
    .createQueryBuilder('ticket')
    .leftJoin('ticket.ticket_priority', 'priority')
    .select('priority.id', 'priorityId')
    .addSelect('priority.type', 'priorityType')
    .addSelect('COUNT(ticket.id)', 'count')
    .where('ticket.is_deleted = :is_deleted', { is_deleted: false })
    .andWhere(
      tenantClause ? 'ticket.tenant_id = :tenantId' : '1=1',
      tenantClause ? { tenantId: tenantClause } : {},
    )
    .groupBy('priority.id')
    .addGroupBy('priority.type')
    .getRawMany<PriorityRow>();

  return rows.map((r) => ({
    priorityId: r.priorityId,
    priorityType: r.priorityType ?? 'Unassigned',
    count: parseInt(r.count, 10),
  }));
}

async getRecentTickets(
  limit: number = 10,
  tenantId?: string,
): Promise<
  Array<{
    id: string;
    subject: string;
    created_at: Date;
    due_date: Date | null;
    closed: boolean;
    ticket_status?: { id: string; type: string; status_color?: string };
    ticket_priority?: { id: string; type: string; priority_color?: string };
    created_by_user?: {
      id: string;
      first_name: string;
      last_name: string;
      email: string;
    };
    company?: { id?: string; name: string };
  }>
> {
  const safeLimit = Math.min(
    Math.max(parseInt(String(limit), 10) || 10, 1),
    100,
  );
  const tenantClause = tenantId?.trim() ? tenantId.trim() : null;

  const tickets = await this.ticketRepo
    .createQueryBuilder('ticket')
    .leftJoinAndSelect('ticket.ticket_status', 'status')
    .leftJoinAndSelect('ticket.ticket_priority', 'priority')
    .leftJoinAndSelect('ticket.created_by_user', 'created_by')
    .leftJoinAndSelect('ticket.company', 'company')
    .select([
      'ticket.id',
      'ticket.subject',
      'ticket.created_at',
      'ticket.due_date',
      'ticket.closed',
      'status.id',
      'status.type',
      'status.status_color',
      'priority.id',
      'priority.type',
      'priority.priority_color',
      'created_by.id',
      'created_by.first_name',
      'created_by.last_name',
      'created_by.email',
      'company.id',
      'company.company_name',
    ])
    .where('ticket.is_deleted = :is_deleted', { is_deleted: false })
    .andWhere(
      tenantClause ? 'ticket.tenant_id = :tenantId' : '1=1',
      tenantClause ? { tenantId: tenantClause } : {},
    )
    .orderBy('ticket.created_at', 'DESC')
    .take(safeLimit)
    .getMany();

  // Map to the frontend's expected JSON shape (`company.name` vs `company.company_name`, etc.)
  return tickets.map((t) => ({
    id: t.id,
    subject: t.subject,
    created_at: t.created_at,
    due_date: (t.due_date as unknown as Date | null) ?? null,
    closed: t.closed,
    ticket_status: t.ticket_status
      ? {
          id: t.ticket_status.id,
          type: t.ticket_status.type,
          status_color: t.ticket_status.status_color,
        }
      : undefined,
    ticket_priority: t.ticket_priority
      ? {
          id: t.ticket_priority.id,
          type: t.ticket_priority.type,
          priority_color: t.ticket_priority.priority_color,
        }
      : undefined,
    created_by_user: t.created_by_user
      ? {
          id: t.created_by_user.id,
          first_name: t.created_by_user.first_name,
          last_name: t.created_by_user.last_name,
          email: t.created_by_user.email,
        }
      : undefined,
    company: t.company
      ? { id: t.company.id, name: t.company.company_name }
      : undefined,
  }));
}

async getAgentPerformance(tenantId?: string): Promise<
  {
    agentId: string;
    firstName: string;
    lastName: string;
    email: string;
    totalAssigned: number;
    resolved: number;
  }[]
> {
  const closedStatus = await this.statusRepo.findOne({
    where: { type: 'Closed', is_deleted: false },
  });
  const tenantClause = tenantId?.trim() ? tenantId.trim() : null;

  const assignments = await this.ticketRepo
    .createQueryBuilder('ticket')
    .innerJoin('ticket.assigned_users', 'user')
    .select('user.id', 'userId')
    .addSelect('user.first_name', 'firstName')
    .addSelect('user.last_name', 'lastName')
    .addSelect('user.email', 'email')
    .addSelect('COUNT(ticket.id)', 'totalAssigned')
    .where('user.is_deleted = :is_deleted', { is_deleted: false })
    .andWhere('ticket.is_deleted = :ticketDeleted', { ticketDeleted: false })
    .andWhere(
      tenantClause ? 'ticket.tenant_id = :tenantId' : '1=1',
      tenantClause ? { tenantId: tenantClause } : {},
    )
    .groupBy('user.id')
    .addGroupBy('user.first_name')
    .addGroupBy('user.last_name')
    .addGroupBy('user.email')
    .getRawMany<AgentAssignmentRow>();

    const resolvedCounts: AgentResolvedRow[] = closedStatus
      ? await this.ticketRepo
          .createQueryBuilder('ticket')
          .innerJoin('ticket.assigned_users', 'user')
          .innerJoin('ticket.ticket_status', 'status')
          .select('user.id', 'userId')
          .addSelect('COUNT(ticket.id)', 'resolved')
          .where('ticket.is_deleted = :is_deleted', { is_deleted: false })
          .andWhere(
            tenantClause ? 'ticket.tenant_id = :tenantId' : '1=1',
            tenantClause ? { tenantId: tenantClause } : {},
          )
          .andWhere('status.id = :statusId', { statusId: closedStatus.id })
          .groupBy('user.id')
          .getRawMany()
      : [];

    const resolvedMap = new Map(
      resolvedCounts.map((r) => [r.userId, parseInt(r.resolved, 10)]),
    );

    return assignments.map((r) => ({
      agentId: r.userId,
      firstName: r.firstName ?? '',
      lastName: r.lastName ?? '',
      email: r.email ?? '',
      totalAssigned: parseInt(r.totalAssigned, 10),
      resolved: resolvedMap.get(r.userId) ?? 0,
    }));
  }

  async getTicketActivity(
    periodRaw?: string,
    tenantId?: string,
  ): Promise<Array<{ date: string; created: number; resolved: number }>> {
    const period = this.normalizePeriod(periodRaw);
    const days = period === '90d' ? 90 : period === '30d' ? 30 : 7;

    const start = this.startOfDay(new Date());
    start.setDate(start.getDate() - (days - 1));
    const end = this.startOfDay(new Date());
    end.setDate(end.getDate() + 1); // exclusive upper bound

    const tenantClause = tenantId?.trim() ? tenantId.trim() : null;

    const createdRows = await this.ticketRepo
      .createQueryBuilder('ticket')
      .select('DATE(ticket.created_at)', 'date')
      .addSelect('COUNT(ticket.id)', 'count')
      .where('ticket.is_deleted = :is_deleted', { is_deleted: false })
      .andWhere(
        tenantClause ? 'ticket.tenant_id = :tenantId' : '1=1',
        tenantClause ? { tenantId: tenantClause } : {},
      )
      .andWhere('ticket.created_at >= :start', { start })
      .andWhere('ticket.created_at < :end', { end })
      .groupBy('DATE(ticket.created_at)')
      .orderBy('DATE(ticket.created_at)', 'ASC')
      .getRawMany<TicketActivityRow>();

    const resolvedRows = await this.ticketRepo
      .createQueryBuilder('ticket')
      .select('DATE(ticket.updated_at)', 'date')
      .addSelect('COUNT(ticket.id)', 'count')
      .where('ticket.is_deleted = :is_deleted', { is_deleted: false })
      .andWhere(
        tenantClause ? 'ticket.tenant_id = :tenantId' : '1=1',
        tenantClause ? { tenantId: tenantClause } : {},
      )
      .andWhere('ticket.closed = :closed', { closed: true })
      .andWhere('ticket.updated_at >= :start', { start })
      .andWhere('ticket.updated_at < :end', { end })
      .groupBy('DATE(ticket.updated_at)')
      .orderBy('DATE(ticket.updated_at)', 'ASC')
      .getRawMany<TicketActivityRow>();

    const createdMap = new Map(
      createdRows.map((r) => [
        this.normalizeDateKey(r.date),
        parseInt(r.count, 10),
      ]),
    );
    const resolvedMap = new Map(
      resolvedRows.map((r) => [
        this.normalizeDateKey(r.date),
        parseInt(r.count, 10),
      ]),
    );

    const points: Array<{ date: string; created: number; resolved: number }> =
      [];
    for (let i = 0; i < days; i++) {
      const d = new Date(start);
      d.setDate(start.getDate() + i);
      const key = this.toYyyyMmDd(d);
      points.push({
        date: key,
        created: createdMap.get(key) ?? 0,
        resolved: resolvedMap.get(key) ?? 0,
      });
    }
    return points;
  }

  private normalizePeriod(periodRaw?: string): TicketActivityPeriod {
    const v = (periodRaw ?? '').trim().toLowerCase();
    if (v === '30d' || v === '90d') return v;
    return '7d';
  }

  private startOfDay(d: Date): Date {
    const x = new Date(d);
    x.setHours(0, 0, 0, 0);
    return x;
  }

  private toYyyyMmDd(d: Date): string {
    const yyyy = d.getFullYear();
    const mm = String(d.getMonth() + 1).padStart(2, '0');
    const dd = String(d.getDate()).padStart(2, '0');
    return `${yyyy}-${mm}-${dd}`;
  }

  private normalizeDateKey(raw: unknown): string {
    // Postgres DATE() often comes back like '2026-04-30', but can also be a Date object.
    if (raw instanceof Date) {
      return this.toYyyyMmDd(raw);
    }
    if (typeof raw === 'string') {
      const v = raw.trim();
      return v.length >= 10 ? v.slice(0, 10) : v;
    }
    if (typeof raw === 'number' && Number.isFinite(raw)) {
      // Best-effort: treat as epoch ms.
      return this.toYyyyMmDd(new Date(raw));
    }
    return '';
  }
}

