import {
  Controller,
  Get,
  Post,
  Patch,
  Delete,
  Body,
  Param,
  UseGuards,
} from '@nestjs/common';
import { DepartmentService } from './department.service';
import { AuthGuard } from '../core/guards/auth.guard';
import { PermissionsGuard } from '../core/guards/permissions.guard';
import { RequirePermissions } from '../common/decorators/require-permissions.decorator';
import { Department } from './department.entity';

@Controller('departments')
@UseGuards(AuthGuard)

@UseGuards(AuthGuard)
export class DepartmentController {
  constructor(private readonly departmentService: DepartmentService) {}

  @Get()
  async getAll() {
    const data = await this.departmentService.findAll();
    return { status: 'Success', data };
  }

  @Get(':id')
  async getOne(@Param('id') id: string) {
    const data = await this.departmentService.findOne(id);
    return { status: 'Success', data };
  }

  @Post()
  @UseGuards(PermissionsGuard)
  @RequirePermissions('create-department')
  async create(@Body() body: Partial<Department>) {
    const data = await this.departmentService.create(body);
    return { status: 'Success', data };
  }

  @Patch()
  @UseGuards(PermissionsGuard)
  @RequirePermissions('update-department')
  async edit(@Body() body: { id: string } & Partial<Department>) {
    const { id, ...rest } = body;
    const data = await this.departmentService.update(id, rest);
    return { status: 'Success', data };
  }

  @Delete('deleteAllDepartments')
  @UseGuards(PermissionsGuard)
  @RequirePermissions('delete-departments')
  async deleteAll() {
    const data = await this.departmentService.removeAll();
    return { status: 'Success', data };
  }

  @Delete(':id')
  @UseGuards(PermissionsGuard)
  @RequirePermissions('delete-department')
  async delete(@Param('id') id: string) {
    await this.departmentService.remove(id);
    return { status: 'Success', data: null };
  }
}

import {
