}

import { Module } from '@nestjs/common';
import { TypeOrmModule } from '@nestjs/typeorm';
import { Department } from './department.entity';
import { DepartmentController } from './department.controller';
import { DepartmentService } from './department.service';

@Module({
  imports: [TypeOrmModule.forFeature([Department])],
  controllers: [DepartmentController],
  providers: [DepartmentService],
  exports: [TypeOrmModule, DepartmentService],
})
export class DepartmentModule {}

import { Injectable, NotFoundException } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Department } from './department.entity';

@Injectable()
export class DepartmentService {
  constructor(
    @InjectRepository(Department)
    private readonly departmentRepository: Repository<Department>,
  ) {}

  async findAll(): Promise<Department[]> {
    return this.departmentRepository.find();
  }

  async findOne(id: string): Promise<Department> {
    const dept = await this.departmentRepository.findOne({ where: { id } });
    if (!dept) throw new NotFoundException('Department Does Not Exist!');
    return dept;
  }

  async create(data: Partial<Department>): Promise<Department> {
    const entity = this.departmentRepository.create(data);
    return this.departmentRepository.save(entity);
  }

  async update(id: string, data: Partial<Department>): Promise<Department> {
    const entity = await this.departmentRepository.findOne({ where: { id } });
    if (!entity) throw new NotFoundException("Department Doesn't Exist!");
    Object.assign(entity, data);
    return this.departmentRepository.save(entity);
  }

  async remove(id: string): Promise<void> {
    const dept = await this.departmentRepository.findOne({ where: { id } });
    if (!dept) throw new NotFoundException('Department Does Not Exist!');
    await this.departmentRepository.delete({ id });
  }

  /** Returns deleted departments to match Express deleteAllDepartments response. */
  async removeAll(): Promise<Department[]> {
    const list = await this.departmentRepository.find();
    await this.departmentRepository.clear();
    return list;
  }
}

