import {
  Controller,
  Get,
  Post,
  Delete,
  Body,
  Param,
  UseGuards,
  UseInterceptors,
  UploadedFile,
  HttpCode,
  HttpStatus,
  NotFoundException,
  StreamableFile,
  BadRequestException,
  ForbiddenException,
} from '@nestjs/common';
import { FileInterceptor } from '@nestjs/platform-express';
import { createReadStream, existsSync } from 'fs';
import { DocumentService } from './document.service';
import { KnowledgeBaseService } from '../knowledge-base/knowledge-base.service';
import { AuthGuard } from '../core/guards/auth.guard';
import { PermissionsGuard } from '../core/guards/permissions.guard';
import { RequirePermissions } from '../common/decorators/require-permissions.decorator';
import { CurrentUser } from '../common/decorators/current-user.decorator';
import { User } from '../user/user.entity';
import { documentUploadOptions } from '../common/upload/multer.config';

@Controller('knowledgebase/documents')
@UseGuards(AuthGuard)

@UseGuards(AuthGuard)
export class DocumentController {
  constructor(
    private readonly documentService: DocumentService,
    private readonly knowledgeBaseService: KnowledgeBaseService,
  ) {}

  @Post('upload')
  @HttpCode(HttpStatus.CREATED)
  @UseGuards(PermissionsGuard)
  @RequirePermissions('update-Knowledge-base')
  @UseInterceptors(FileInterceptor('document', documentUploadOptions))
  async uploadDocument(
    @Body() body: Record<string, unknown>,
    @UploadedFile() file: Express.Multer.File,
    @CurrentUser() user: User,
  ) {
    if (!file) throw new BadRequestException('Please upload a file');
    const knowledgeBaseId = body?.knowledgeBaseId as string | undefined;
    if (!knowledgeBaseId)
      throw new BadRequestException('Knowledge Base ID is required');
    const hasAccess = await this.knowledgeBaseService.verifyUserKBAccess(
      user.id,
      knowledgeBaseId,
      user,
    );
    if (!hasAccess)
      throw new ForbiddenException('Access denied to this knowledge base');
    const data = await this.documentService.create({
      ...body,
      knowledgeBaseId,
      uploadedBy: user.id,
      filename: file.filename,
      originalName: file.originalname,
      filePath: file.path,
      fileSize: file.size ?? 0,
      mimeType: file.mimetype ?? '',
    } as Partial<import('./document.entity').Document>);
    return { status: 'Success', data };
  }

  @Get('knowledgebase/:knowledgeBaseId')
  async getDocumentsByKnowledgeBaseId(
    @Param('knowledgeBaseId') knowledgeBaseId: string,
    @CurrentUser() user: User,
  ) {
    const hasAccess = await this.knowledgeBaseService.verifyUserKBAccess(
      user.id,
      knowledgeBaseId,
      user,
    );
    if (!hasAccess)
      throw new ForbiddenException('Access denied to this knowledge base');
    const data =
      await this.documentService.findByKnowledgeBaseId(knowledgeBaseId);
    return { status: 'Success', data: data ?? [] };
  }

  @Get('download/:documentId')
  async downloadDocument(
    @Param('documentId') documentId: string,
    @CurrentUser() user: User,
  ) {
    const document = await this.documentService.findOne(documentId);
    const hasAccess = await this.knowledgeBaseService.verifyUserKBAccess(
      user.id,
      document.knowledgeBaseId,
      user,
    );
    if (!hasAccess)
      throw new ForbiddenException('Access denied to this document');
    if (!existsSync(document.filePath)) {
      throw new NotFoundException(
        'File not found on server. It may have been deleted or moved.',
      );
    }
    const file = createReadStream(document.filePath);
    return new StreamableFile(file, {
      type: document.mimeType,
      disposition: `attachment; filename="${document.originalName}"`,
    });
  }

  @Delete(':documentId')
  @UseGuards(PermissionsGuard)
  @RequirePermissions('delete-Knowledge-base')
  async deleteDocument(
    @Param('documentId') documentId: string,
    @CurrentUser() user: User,
  ) {
    const document = await this.documentService.findOne(documentId);
    const isOwner = document.uploadedBy === user.id;
    const hasKBAccess = await this.knowledgeBaseService.verifyUserKBAccess(
      user.id,
      document.knowledgeBaseId,
      user,
    );
    if (!isOwner && !hasKBAccess)
      throw new ForbiddenException('Access denied to delete this document');
    await this.documentService.remove(documentId);
    return {
      status: 'Document deleted successfully',
      data: null,
    };
  }
}

