import { Module } from '@nestjs/common';
import { TypeOrmModule } from '@nestjs/typeorm';
import { Issues } from './issues.entity';
import { IssuesController } from './issues.controller';
import { IssuesService } from './issues.service';

@Module({
  imports: [TypeOrmModule.forFeature([Issues])],
  controllers: [IssuesController],
  providers: [IssuesService],
  exports: [TypeOrmModule, IssuesService],
})
export class IssuesModule {}

import { Injectable, NotFoundException } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Issues } from './issues.entity';

@Injectable()

@Injectable()
export class IssuesService {
  constructor(
    @InjectRepository(Issues)
    private readonly issuesRepository: Repository<Issues>,
  ) {}

  async findAll(): Promise<Issues[]> {
    const issues = await this.issuesRepository.find({
      relations: [
        'ticket',
        'agent',
        'team',
        'status',
        'issue_teams',
        'issue_teams.team',
        'issue_agents',
        'issue_agents.agent',
      ],
    });
    if (!issues) throw new NotFoundException('No data found.');
    return issues;
  }

  async findOne(id: string): Promise<Issues> {
    const issue = await this.issuesRepository.findOne({
      where: { id },
      relations: [
        'ticket',
        'agent',
        'team',
        'status',
        'issue_teams',
        'issue_teams.team',
        'issue_agents',
        'issue_agents.agent',
      ],
    });
    if (!issue) throw new NotFoundException('Issue does not exist');
    return issue;
  }

  async update(
    id: string,
    data: Partial<
      Pick<
        Issues,
        'name' | 'description' | 'statusId' | 'agentId' | 'teamId' | 'isClosed'
      >
    >,
  ): Promise<Issues> {
    const issue = await this.findOne(id);
    Object.assign(issue, data);
    return this.issuesRepository.save(issue);
  }

  /**
   * Create issues for a ticket (matches Express createTicketIssues).
   * Each issue is created with the ticket's initial status (e.g. Open).
   */
  async createForTicket(
    ticketId: string,
    statusId: string,
    issues: Array<{
      name?: string;
      description?: string;
      expectedEndDate?: string;
    }>,
  ): Promise<Issues[]> {
    if (!issues?.length) return [];
    const entities: Issues[] = issues.map((issue) => {
      const entity = this.issuesRepository.create();
      entity.name = issue.name ?? 'Untitled';
      entity.description = issue.description ?? '';
      entity.ticketId = ticketId;
      entity.statusId = statusId;
      entity.expectedEndDate = issue.expectedEndDate ?? '';
      return entity;
    });
    return this.issuesRepository.save(entities);
  }
}

