import {
  Controller,
  Get,
  Post,
  Patch,
  Delete,
  Body,
  Param,
  Query,
  UseGuards,
  UseInterceptors,
  UploadedFile,
  ForbiddenException,
} from '@nestjs/common';
import { FileInterceptor } from '@nestjs/platform-express';
import {
  KnowledgeBaseService,
  type KnowledgeBaseFilters,
} from './knowledge-base.service';
import { AuthGuard } from '../core/guards/auth.guard';
import { PermissionsGuard } from '../core/guards/permissions.guard';
import { RequirePermissions } from '../common/decorators/require-permissions.decorator';
import { CurrentUser } from '../common/decorators/current-user.decorator';
import { User } from '../user/user.entity';
import { imageUploadOptions } from '../common/upload/multer.config';
import { CreateKnowledgeBaseDto, UpdateKnowledgeBaseDto } from './dto';
import { KnowledgeBase } from './knowledge-base.entity';

@Controller('knowledgebase')
@UseGuards(AuthGuard)

@UseGuards(AuthGuard)
export class KnowledgeBaseController {
  constructor(private readonly knowledgeBaseService: KnowledgeBaseService) {}

  @Get()
  @UseGuards(PermissionsGuard)
  @RequirePermissions('view-Knowledge-base')
  async getKnowledgeBases(
    @CurrentUser() user: User,
    @Query('projectId') projectId?: string,
    @Query('categoryId') categoryId?: string,
    @Query('ticketId') ticketId?: string,
    @Query('status') status?: string,
    @Query('search') search?: string,
  ) {
    const filters: KnowledgeBaseFilters = {};
    if (projectId) filters.projectId = projectId;
    if (categoryId) filters.categoryId = categoryId;
    if (ticketId) filters.ticketId = ticketId;
    if (status && ['Draft', 'Published', 'Archived'].includes(status)) {
      filters.status = status as KnowledgeBaseFilters['status'];
    }
    if (search) filters.search = search;
    const data = await this.knowledgeBaseService.findForUser(user, filters);
    return { status: 'List of Knowledge base', data };
  }

  @Get('catagoryId/:id')
  @UseGuards(PermissionsGuard)
  @RequirePermissions('view-Knowledge-base')
  async getKnowledgeBaseByCatagoryId(@Param('id') id: string) {
    const data = await this.knowledgeBaseService.findByCatagoryId(id);
    return { status: 'Success', data };
  }

  @Get('ticket/:ticketId')
  @UseGuards(PermissionsGuard)
  @RequirePermissions('view-Knowledge-base')
  async getKnowledgeBaseByTicketId(@Param('ticketId') ticketId: string) {
    const data = await this.knowledgeBaseService.findByTicketId(ticketId);
    return { status: 'Success', data };
  }

  @Get(':id')
  @UseGuards(PermissionsGuard)
  @RequirePermissions('view-Knowledge-base')
  async getKnowlegeBaseById(
    @Param('id') id: string,
    @CurrentUser() user: User,
  ) {
    const hasAccess = await this.knowledgeBaseService.verifyUserKBAccess(
      user.id,
      id,
      user,
    );
    if (!hasAccess)
      throw new ForbiddenException('Access denied to this knowledge base');
    const data: KnowledgeBase = await this.knowledgeBaseService.findOne(id);
    await this.knowledgeBaseService.incrementReadCount(id);
    return {
      status: 'Success',
      data: {
        ...data,
        read_count: (data.read_count ?? 0) + 1,
      } as KnowledgeBase,
    };
  }

  @Post()
  @UseGuards(AuthGuard, PermissionsGuard)
  @RequirePermissions('create-Knowledge-base')
  @UseInterceptors(FileInterceptor('image', imageUploadOptions))
  async createKnowledgeBase(
    @Body() body: CreateKnowledgeBaseDto,
    @UploadedFile() _file: Express.Multer.File,
    @CurrentUser() user?: User,
  ) {
    const payload = {
      ...body,
      createdBy: body.createdBy ?? user?.id,
    };
    const data = await this.knowledgeBaseService.create(
      payload as Partial<import('./knowledge-base.entity').KnowledgeBase>,
    );
    return { status: 'Success', data };
  }

  @Patch(':id')
  @UseGuards(AuthGuard, PermissionsGuard)
  @RequirePermissions('update-Knowledge-base')
  async updateKnowledgeBaseById(
    @Param('id') id: string,
    @Body() body: UpdateKnowledgeBaseDto,
  ) {
    const data = await this.knowledgeBaseService.update(
      id,
      body as Partial<import('./knowledge-base.entity').KnowledgeBase>,
    );
    return { status: 'Success', data };
  }

  /**
   * Lightweight endpoint so the redesigned UI can toggle Publish/Draft/Archive
   * without resending the whole article body.
   */
  @Patch(':id/status')
  @UseGuards(AuthGuard, PermissionsGuard)
  @RequirePermissions('update-Knowledge-base')
  async updateKnowledgeBaseStatus(
    @Param('id') id: string,
    @Body() body: { status: 'Draft' | 'Published' | 'Archived' },
  ) {
    const data = await this.knowledgeBaseService.update(id, {
      status: body.status,
    } as Partial<import('./knowledge-base.entity').KnowledgeBase>);
    return { status: 'Success', data };
  }

  @Delete(':id')
  @UseGuards(AuthGuard, PermissionsGuard)
  @RequirePermissions('delete-Knowledge-base')
  async deleteKnowledgeBaseById(@Param('id') id: string) {
    await this.knowledgeBaseService.remove(id);
    return {
      status: 'Knowledge base is successfully deleted',
      data: null,
    };
  }
}

import {
  Entity,
  PrimaryGeneratedColumn,
  Column,
  CreateDateColumn,
  UpdateDateColumn,
  ManyToOne,
  OneToMany,
  JoinColumn,
} from 'typeorm';
import { User } from '../user/user.entity';
import { Catagory } from '../category/category.entity';
import { Ticket } from '../ticket/ticket.entity';
import { Project } from '../project/project.entity';
import { KnowledgeBaseComment } from '../knowledge-base-comment/knowledge-base-comment.entity';
import { Document } from '../document/document.entity';

export type KnowledgeBaseStatus = 'Draft' | 'Published' | 'Archived';

@Entity('knowledge_base')
export class KnowledgeBase {
  @PrimaryGeneratedColumn('uuid')
  id: string;

  @Column({ type: 'varchar' })
  title: string;

  @Column({ type: 'text', nullable: true })
  description: string;

  @Column({ type: 'uuid', nullable: true, name: 'createdBy' })
  createdBy: string;

  @Column({ type: 'uuid', nullable: true, name: 'catagoryId' })
  catagoryId: string;

  @CreateDateColumn({ name: 'created_at' })
  created_at: Date;

  @UpdateDateColumn({ name: 'updated_at' })
  updated_at: Date;

  @Column({ type: 'uuid', nullable: true, name: 'ticketId' })
  ticketId: string;

  /**
   * Direct link to a project so KB articles can be grouped by project even
   * when there is no ticket. When `ticketId` is provided, the service copies
   * the ticket's project_id here automatically.
   */
  @Column({ type: 'uuid', nullable: true, name: 'project_id' })
  project_id: string | null;

  /**
   * Publication state shown in the redesigned UI list/detail views.
   * Defaults to 'Draft' so legacy rows continue to render correctly.
   */
  @Column({
    type: 'varchar',
    length: 16,
    default: 'Draft',
    name: 'status',
  })
  status: KnowledgeBaseStatus;

  @Column({ type: 'integer', default: 0, name: 'read_count' })
  read_count: number;

  @ManyToOne(() => User, (user) => user.knowledgebase)
  @JoinColumn({ name: 'createdBy' })
  createdByUser: User;

  @ManyToOne(() => Catagory, (cat) => cat.knowledgebase)
  @JoinColumn({ name: 'catagoryId' })
  catagory: Catagory;

  @ManyToOne(() => Ticket)
  @JoinColumn({ name: 'ticketId' })
  ticket: Ticket;

  @ManyToOne(() => Project, { nullable: true })
  @JoinColumn({ name: 'project_id' })
  project: Project | null;

  @OneToMany(() => KnowledgeBaseComment, (c) => c.knowledgebase)
  comments: KnowledgeBaseComment[];

  @OneToMany(() => Document, (d) => d.knowledgebase)
  documents: Document[];
}

