import { Injectable, NotFoundException } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { KnowledgeBase } from './knowledge-base.entity';
import { Ticket } from '../ticket/ticket.entity';
import { User, UserType } from '../user/user.entity';

/**
 * Server-side filters accepted by GET /knowledgebase. All optional;
 * unset values are skipped so the response stays compatible with the
 * pre-redesign behaviour (return everything the user is allowed to see).
 */

 */
export interface KnowledgeBaseFilters {
  projectId?: string;
  categoryId?: string;
  ticketId?: string;
  status?: 'Draft' | 'Published' | 'Archived';
  search?: string;
}

/**
 * Minimal shape accepted by hasPermission. Loose because it needs to handle
 * both the AuthenticatedPrincipal payload (flat permissions array, role as
 * string) and the full TypeORM User entity (role relation with permissions).
 */
type PermissionLike = string | { slug?: string };
type PermissionUserLike = {
  permissions?: string[];
  role?:
    | string
    | {
        roleName?: string;
        permissions?: PermissionLike[];
      };
};

/** Relations loaded for every read so the redesigned UI has all the data it needs. */
const KB_RELATIONS = [
  'createdByUser',
  'catagory',
  'ticket',
  'ticket.project',
  'ticket.support',
  'ticket.support.project',
  'project',
  'documents',
];

@Injectable()
export class KnowledgeBaseService {
  constructor(
    @InjectRepository(KnowledgeBase)
    private readonly kbRepository: Repository<KnowledgeBase>,
    @InjectRepository(Ticket)
    private readonly ticketRepository: Repository<Ticket>,
  ) {}

  async findAll(filters?: KnowledgeBaseFilters): Promise<KnowledgeBase[]> {
    if (!filters || !this.hasAnyFilter(filters)) {
      return this.kbRepository.find({ relations: KB_RELATIONS });
    }
    return this.runFilteredQuery(filters);
  }

  /** Match Express: filter KB list by user permission or user type */
  async findForUser(
    user: User,
    filters?: KnowledgeBaseFilters,
  ): Promise<KnowledgeBase[]> {
    if (this.hasPermission(user, 'view-Knowledge-base')) {
      return this.findAll(filters);
    }
    if (user.user_type === UserType.Client) {
      return this.findByClientId(user.id, filters);
    }
    if (user.user_type === UserType.Employee) {
      return this.findByEmployeeId(user.id, filters);
    }
    return [];
  }

  hasPermission(
    user: PermissionUserLike | null | undefined,
    permissionSlug: string,
  ): boolean {
    if (!user) return false;
    const slug = permissionSlug.toLowerCase();

    // 1. AuthenticatedPrincipal handling
    if (Array.isArray(user.permissions)) {
      if (user.permissions.some((p) => p.toLowerCase() === slug)) {
        return true;
      }
    }
    if (
      typeof user.role === 'string' &&
      user.role.trim().toLowerCase() === 'admin'
    ) {
      return true;
    }

    // 2. User entity handling
    if (user.role && typeof user.role === 'object') {
      if (user.role.roleName?.trim().toLowerCase() === 'admin') {
        return true;
      }
      const check = (p: PermissionLike) =>
        (typeof p === 'string' ? p : p?.slug)?.toLowerCase() === slug;
      if (user.role.permissions?.some(check)) return true;
    }

    return false;
  }

  async verifyUserTicketAccess(
    userId: string,
    ticketId: string,
  ): Promise<boolean> {
    const ticket = await this.ticketRepository.findOne({
      where: { id: ticketId, is_deleted: false },
      relations: ['assigned_users', 'client', 'issues', 'issues.agent'],
    });
    if (!ticket) return false;
    if (ticket.client_id === userId) return true;
    if (ticket.created_by === userId) return true;
    if (ticket.assigned_users?.some((u) => u.id === userId)) return true;
    if (
      ticket.issues?.some(
        (i) =>
          (i as { agent?: { id: string }; agentId?: string }).agent?.id ===
            userId || (i as { agentId?: string }).agentId === userId,
      )
    )
      return true;
    return false;
  }

  async verifyUserKBAccess(
    userId: string,
    kbId: string,
    user?: User | null,
  ): Promise<boolean> {
    const kb = await this.kbRepository.findOne({
      where: { id: kbId },
      relations: ['createdByUser', 'ticket'],
    });
    if (!kb) return false;
    let u = user;
    if (!u) {
      u = await this.kbRepository.manager.getRepository(User).findOne({
        where: { id: userId },
        relations: ['role', 'role.permissions'],
      });
    }
    if (u && this.hasPermission(u, 'view-Knowledge-base')) return true;
    const creatorId =
      typeof kb.createdBy === 'string' ? kb.createdBy : kb.createdByUser?.id;
    if (creatorId === userId) return true;
    if (!kb.ticketId) return false;
    return this.verifyUserTicketAccess(userId, kb.ticketId);
  }

  async findByClientId(
    clientId: string,
    filters?: KnowledgeBaseFilters,
  ): Promise<KnowledgeBase[]> {

): Promise<KnowledgeBase[]> {
  const qb = this.baseQueryBuilder().where('ticket.client_id = :clientId', {
    clientId,
  });
  this.applyFilters(qb, filters);
  return qb.getMany();
}

async findByEmployeeId(
  employeeId: string,
  filters?: KnowledgeBaseFilters,
): Promise<KnowledgeBase[]> {
  const qb = this.baseQueryBuilder()
    .leftJoin('ticket.issues', 'issues')
    .leftJoin('issues.agent', 'agent')
    .where('agent.id = :employeeId', { employeeId });
  this.applyFilters(qb, filters);
  return qb.getMany();
}

async findOne(id: string): Promise<KnowledgeBase> {
  const kb = await this.kbRepository.findOne({
    where: { id },
    relations: [...KB_RELATIONS, 'comments'],
  });
  if (!kb)
    throw new NotFoundException(`Knowledgebase with ID ${id} is not found`);
  return kb;
}

/** Increment read_count by 1 for the given knowledge base (e.g. when viewed). */
async incrementReadCount(id: string): Promise<void> {
  await this.kbRepository.increment({ id }, 'read_count', 1);
}

async findByCatagoryId(catagoryId: string): Promise<KnowledgeBase[]> {
  return this.kbRepository.find({
    where: { catagoryId },
    relations: KB_RELATIONS,
  });
}

async findByTicketId(ticketId: string): Promise<KnowledgeBase[]> {
  return this.kbRepository.find({
    where: { ticketId },
    relations: KB_RELATIONS,
  });
}

async create(data: Partial<KnowledgeBase>): Promise<KnowledgeBase> {
  const payload = await this.withDerivedProject(data);
  const kb = this.kbRepository.create(payload);
  return this.kbRepository.save(kb);
}

async update(
  id: string,
  data: Partial<KnowledgeBase>,
): Promise<KnowledgeBase> {
  const kb = await this.findOne(id);
  const payload = await this.withDerivedProject(data, kb);
  this.kbRepository.merge(kb, payload);
  return this.kbRepository.save(kb);
}

async remove(id: string): Promise<void> {
  await this.findOne(id);
  await this.kbRepository.delete({ id });
}

/**
 * Ensures `project_id` is set whenever `ticketId` is present but no explicit
 * `project_id` is provided. Looks up the ticket and copies its `project_id`.
 * Keeps the old ticket-only flow working without requiring frontend changes.
 */
private async withDerivedProject(
  data: Partial<KnowledgeBase>,
  existing?: KnowledgeBase,
): Promise<Partial<KnowledgeBase>> {
  const next: Partial<KnowledgeBase> = { ...data };
  const hasExplicitProject =
    Object.hasOwn(next, 'project_id') && next.project_id != null;
  if (hasExplicitProject) return next;

  const ticketId =
    next.ticketId ?? (existing ? existing.ticketId : undefined);
  if (!ticketId) return next;

  const ticket = await this.ticketRepository.findOne({
    where: { id: ticketId, is_deleted: false },
    select: ['id', 'project_id'],
  });
  if (ticket?.project_id) {
    next.project_id = ticket.project_id;
  }
  return next;
}

private baseQueryBuilder() {
  return this.kbRepository
    .createQueryBuilder('kb')
    .leftJoinAndSelect('kb.createdByUser', 'createdBy')
    .leftJoinAndSelect('kb.catagory', 'catagory')
    .leftJoinAndSelect('kb.ticket', 'ticket')
    .leftJoinAndSelect('ticket.project', 'ticketProject')
    .leftJoinAndSelect('ticket.support', 'ticketSupport')
    .leftJoinAndSelect('ticketSupport.project', 'ticketSupportProject')
    .leftJoinAndSelect('kb.project', 'project')
    .leftJoinAndSelect('kb.documents', 'documents');
}

private hasAnyFilter(filters: KnowledgeBaseFilters): boolean {
  return Boolean(
    filters.projectId ||
      filters.categoryId ||
      filters.ticketId ||
      filters.status ||
      (filters.search && filters.search.trim()),
  );
}

private applyFilters(
  qb: ReturnType<KnowledgeBaseService['baseQueryBuilder']>,
  filters?: KnowledgeBaseFilters,
) {
  if (!filters) return;
  if (filters.projectId) {
    // Match either the direct project link or the ticket's project (inherited)
    qb.andWhere(
      '(kb.project_id = :projectId OR ticket.project_id = :projectId)',
      { projectId: filters.projectId },
    );
  }
  if (filters.categoryId) {
    qb.andWhere('kb.catagoryId = :categoryId', {
      categoryId: filters.categoryId,
    });
  }
  if (filters.ticketId) {
    qb.andWhere('kb.ticketId = :ticketId', { ticketId: filters.ticketId });
  }
  if (filters.status) {
    qb.andWhere('kb.status = :status', { status: filters.status });
  }
  if (filters.search && filters.search.trim()) {
    qb.andWhere(
      '(LOWER(kb.title) LIKE :search OR LOWER(kb.description) LIKE :search)',
      { search: `%${filters.search.trim().toLowerCase()}%` },
    );
  }
}

private runFilteredQuery(
  filters: KnowledgeBaseFilters,
): Promise<KnowledgeBase[]> {

  ): Promise<KnowledgeBase[]> {
    const qb = this.baseQueryBuilder();
    this.applyFilters(qb, filters);
    return qb.getMany();
  }
}

import {
  Controller,
  Get,
  Post,
  Put,
  Delete,
  Body,
  Param,
  UseGuards,
  HttpCode,
  HttpStatus,
  BadRequestException,
} from '@nestjs/common';
import { KnowledgeBaseCommentService } from './knowledge-base-comment.service';
import { AuthGuard } from '../core/guards/auth.guard';
import { PermissionsGuard } from '../core/guards/permissions.guard';
import { RequirePermissions } from '../common/decorators/require-permissions.decorator';
import { CurrentUser } from '../common/decorators/current-user.decorator';
import { User } from '../user/user.entity';

@Controller('knowledgeBaseComments')
@UseGuards(AuthGuard)

@UseGuards(AuthGuard)
export class KnowledgeBaseCommentController {
  constructor(private readonly service: KnowledgeBaseCommentService) {}

  @Post()
  @HttpCode(HttpStatus.CREATED)
  @UseGuards(PermissionsGuard)
  @RequirePermissions('create-comment')
  async createComment(
    @Body() body: { comment: string; knowledgeBaseId: string },
    @CurrentUser() user: User,
  ) {
    const data = await this.service.create({
      comment: body.comment,
      knowledgeBaseId: body.knowledgeBaseId,
      commentedBy: user.id,
    });
    const completeComment = await this.service.getCommentById(data.id);
    return { status: 'Comment created successfully', data: completeComment };
  }

  @Put(':id')
  @UseGuards(PermissionsGuard)
  @RequirePermissions('update-comment')
  async updateComment(
    @Param('id') id: string,
    @Body() body: { comment?: string },
    @CurrentUser() user: User,
  ) {
    if (!id) throw new BadRequestException('Comment ID is required');
    const data = await this.service.updateCommentAsUser(id, user.id, body);
    return { status: 'Comment updated successfully', data };
  }

  @Get('knowledge-base/:knowledgeBaseId')
  async getCommentsByKnowledgeBase(
    @Param('knowledgeBaseId') knowledgeBaseId: string,
  ) {
    const data = await this.service.findByKnowledgeBaseId(knowledgeBaseId);
    return { status: 'Comments retrieved successfully', data };
  }

  @Delete(':id')
  @UseGuards(PermissionsGuard)
  @RequirePermissions('delete-comment')
  async deleteComment(@Param('id') id: string, @CurrentUser() user: User) {
    await this.service.removeCommentAsUser(id, user.id);
    return { status: 'Comment deleted successfully', data: null };
  }
}

import {
  Entity,
  PrimaryGeneratedColumn,
  Column,
  CreateDateColumn,
  UpdateDateColumn,
  ManyToOne,
  JoinColumn,
} from 'typeorm';
import { KnowledgeBase } from '../knowledge-base/knowledge-base.entity';
import { User } from '../user/user.entity';

@Entity('knowledge_base_comments')
export class KnowledgeBaseComment {
  @PrimaryGeneratedColumn('uuid')
  id: string;

  @Column({ type: 'text' })
  comment: string;

  @Column({ type: 'uuid', name: 'knowledgeBaseId' })
  knowledgeBaseId: string;

  @Column({ type: 'uuid', name: 'commentedBy' })
  commentedBy: string;

  @CreateDateColumn({ name: 'createdAt' })
  createdAt: Date;

  @UpdateDateColumn({ name: 'updatedAt' })
  updatedAt: Date;

  @Column({ type: 'timestamp', nullable: true, name: 'deletedAt' })
  deletedAt: Date;

  @ManyToOne(() => KnowledgeBase, (kb) => kb.comments)
  @JoinColumn({ name: 'knowledgeBaseId' })
  knowledgebase: KnowledgeBase;

  @ManyToOne(() => User)
  @JoinColumn({ name: 'commentedBy' })
  user: User;
}

import { Module } from '@nestjs/common';
import { TypeOrmModule } from '@nestjs/typeorm';
import { KnowledgeBaseComment } from './knowledge-base-comment.entity';
import { KnowledgeBaseCommentController } from './knowledge-base-comment.controller';
import { KnowledgeBaseCommentService } from './knowledge-base-comment.service';

@Module({
  imports: [TypeOrmModule.forFeature([KnowledgeBaseComment])],
  controllers: [KnowledgeBaseCommentController],
  providers: [KnowledgeBaseCommentService],
  exports: [TypeOrmModule, KnowledgeBaseCommentService],
})
export class KnowledgeBaseCommentModule {}

import { Injectable, NotFoundException } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository, IsNull } from 'typeorm';
import { KnowledgeBaseComment } from './knowledge-base-comment.entity';

@Injectable()

@Injectable()
export class KnowledgeBaseCommentService {
  constructor(
    @InjectRepository(KnowledgeBaseComment)
    private readonly repo: Repository<KnowledgeBaseComment>,
  ) {}

  async findByKnowledgeBaseId(
    knowledgeBaseId: string,
  ): Promise<KnowledgeBaseComment[]> {
    return this.repo.find({
      where: { knowledgeBaseId, deletedAt: IsNull() },
      relations: ['user', 'knowledgebase'],
      order: { createdAt: 'ASC' },
    });
  }

  async getCommentById(id: string): Promise<KnowledgeBaseComment> {
    const c = await this.repo.findOne({
      where: { id, deletedAt: IsNull() },
      relations: ['user', 'knowledgebase'],
    });
    if (!c) throw new NotFoundException('Comment not found');
    return c;
  }

  async findOne(id: string): Promise<KnowledgeBaseComment> {
    return this.getCommentById(id);
  }

  /** Get comment by id only if it belongs to the given user (for edit/delete permission). */
  async getUserCommentById(
    id: string,
    userId: string,
  ): Promise<KnowledgeBaseComment | null> {
    return this.repo.findOne({
      where: { id, commentedBy: userId, deletedAt: IsNull() },
      relations: ['user', 'knowledgebase'],
    });
  }

  async create(
    data: Partial<KnowledgeBaseComment>,
  ): Promise<KnowledgeBaseComment> {
    const comment = this.repo.create(data);
    return this.repo.save(comment);
  }

  async update(
    id: string,
    data: Partial<KnowledgeBaseComment>,
  ): Promise<KnowledgeBaseComment> {
    const comment = await this.findOne(id);
    this.repo.merge(comment, data);
    await this.repo.save(comment);
    return this.getCommentById(id);
  }

  /** Update only if the comment belongs to the given user. */
  async updateCommentAsUser(
    id: string,
    userId: string,
    data: { comment?: string },
  ): Promise<KnowledgeBaseComment> {
    const existing = await this.getUserCommentById(id, userId);
    if (!existing)
      throw new NotFoundException(
        "Comment not found or you don't have permission to edit it.",
      );
    return this.update(id, data);
  }

  /** Soft-delete: set deletedAt. */
  async removeCommentAsUser(id: string, userId: string): Promise<void> {
    const existing = await this.getUserCommentById(id, userId);
    if (!existing)
      throw new NotFoundException(
        "Comment not found or you don't have permission to delete it.",
      );
    await this.repo.update(id, { deletedAt: new Date() });
  }

  async remove(id: string): Promise<void> {
    await this.findOne(id);
    await this.repo.update(id, { deletedAt: new Date() });
  }
}

