import {
  Controller,
  Get,
  Post,
  Patch,
  Delete,
  Body,
  Param,
  UseGuards,
} from '@nestjs/common';
import { NoteService } from './note.service';
import { CreateNoteDto, UpdateNoteDto } from './dto';
import { AuthGuard } from '../core/guards/auth.guard';
import { PermissionsGuard } from '../core/guards/permissions.guard';
import { RequirePermissions } from '../common/decorators/require-permissions.decorator';
import { CurrentUser } from '../common/decorators/current-user.decorator';
import { User } from '../user/user.entity';
import { Note } from './note.entity';

@Controller('notes')
@UseGuards(AuthGuard)

@UseGuards(AuthGuard)
export class NoteController {
  constructor(private readonly noteService: NoteService) {}

  @Get()
  async getAllNotes() {
    const data = await this.noteService.findAll();
    return { status: 'Success', data };
  }

  @Get(':id')
  async getOneNote(@Param('id') id: string) {
    const data = await this.noteService.findOne(id);
    return { status: 'Success', data };
  }

  @Post()
  @UseGuards(PermissionsGuard)
  @RequirePermissions('create-note')
  async createNote(@Body() body: CreateNoteDto, @CurrentUser() user: User) {
    const userId = body.userID ?? user.id;
    const data = await this.noteService.create(body, userId);
    return { status: 'Success', data };
  }

  @Patch()
  @UseGuards(PermissionsGuard)
  @RequirePermissions('update-note')
  async editNote(@Body() body: UpdateNoteDto) {
    const { id, ...rest } = body;
    const data = await this.noteService.update(id, rest as Partial<Note>);
    return { status: 'Success', data };
  }

  @Delete('deleteAllNotes')
  @UseGuards(PermissionsGuard)
  @RequirePermissions('delete-notes')
  async deleteAllNotes() {
    const data = await this.noteService.removeAll();
    return { status: 'Success', data };
  }

  @Delete(':id')
  @UseGuards(PermissionsGuard)
  @RequirePermissions('delete-note')
  async deleteNote(@Param('id') id: string) {
    await this.noteService.remove(id);
    return { status: 'Success', data: null };
  }
}

