import { Injectable, NotFoundException } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Note } from './note.entity';

@Injectable()
export class NoteService {
  constructor(
    @InjectRepository(Note)
    private readonly noteRepository: Repository<Note>,
  ) {}

  async findAll(): Promise<Note[]> {
    return this.noteRepository.find({ relations: ['created_by', 'ticket'] });
  }

  async findOne(id: string): Promise<Note> {
    const note = await this.noteRepository.findOne({
      where: { id },
      relations: ['created_by', 'ticket'],
    });
    if (!note) throw new NotFoundException('Note does not exist');
    return note;
  }

  async create(data: Partial<Note>, userId: string): Promise<Note> {
    const note = this.noteRepository.create({ ...data, user_id: userId });
    return this.noteRepository.save(note);
  }

  async update(id: string, data: Partial<Note>): Promise<Note> {
    const note = await this.noteRepository.findOne({
      where: { id },
      relations: ['created_by', 'ticket'],
    });
    if (!note) throw new NotFoundException('Note Does Not Exist!');
    this.noteRepository.merge(note, data);
    return this.noteRepository.save(note);
  }

  async remove(id: string): Promise<void> {
    const note = await this.noteRepository.findOne({
      where: { id },
      relations: ['created_by', 'ticket'],
    });
    if (!note) throw new NotFoundException('Note Does Not Exist!');
    await this.noteRepository.delete({ id });
  }

  /** Returns deleted notes to match Express deleteAllNotes response. */
  async removeAll(): Promise<Note[]> {
    const notes = await this.noteRepository.find();
    await this.noteRepository.clear();
    return notes;
  }
}

