import {
  Controller,
  Get,
  Post,
  Patch,
  Delete,
  Body,
  Param,
  UseGuards,
} from '@nestjs/common';
import { NotificationService } from './notification.service';
import { CreateNotificationDto, UpdateNotificationDto } from './dto';
import { AuthGuard } from '../core/guards/auth.guard';
import { PermissionsGuard } from '../core/guards/permissions.guard';
import { RequirePermissions } from '../common/decorators/require-permissions.decorator';
import { CurrentUser } from '../common/decorators/current-user.decorator';
import { User } from '../user/user.entity';
import { Notification } from './notification.entity';

@Controller('notifications')
@UseGuards(AuthGuard)

@UseGuards(AuthGuard)
export class NotificationController {
  constructor(private readonly notificationService: NotificationService) {}

  @Get()
  async getAllNotifications(@CurrentUser() user: User) {
    const data = await this.notificationService.findForUser(
      user.id,
      user.local_id ?? undefined,
      user.tenant_id ?? undefined,
    );
    return { status: 'Success', data };
  }

  @Get('userNotifications')
  async getAllUserNotifications(@CurrentUser() user: User) {
    const data = await this.notificationService.findUserNotifications(
      user.tenant_id ?? undefined,
    );
    return { status: 'Success', data };
  }

  @Get('systemNotifications')
  async getAllSystemNotifications(@CurrentUser() user: User) {
    const data = await this.notificationService.findSystemNotifications(
      user.tenant_id ?? undefined,
    );
    return { status: 'Success', data };
  }

  @Get(':id')
  async getOneNotification(@Param('id') id: string) {
    const data = await this.notificationService.findOne(id);
    return { status: 'Success', data };
  }

  @Post()
  @UseGuards(PermissionsGuard)
  @RequirePermissions('create-notification')
  async createNotification(
    @Body() body: CreateNotificationDto,
    @CurrentUser() user: User,
  ) {
    const data = await this.notificationService.create({
      ...body,
      from_external_id: body.from ?? user.local_id ?? null,
      to_external_id: body.to ?? null,
      tenant_id: user.tenant_id ?? null,
    } as Partial<Notification>);
    return { status: 'Success', data };
  }

  @Delete('deleteAllNotifications')
  @UseGuards(PermissionsGuard)
  @RequirePermissions('delete-notifications')
  async deleteAllNotifications() {
    await this.notificationService.removeAll();
    return {
      status: 'Success',
      message: 'Notifications are Deleted Successfully!',
    };
  }

  @Delete(':id')
  @UseGuards(PermissionsGuard)
  @RequirePermissions('delete-notifications')
  async deleteNotification(@Param('id') id: string) {
    await this.notificationService.remove(id);
    return {
      status: 'Success',
      message: 'Notification Deleted Successfully!',
    };
  }

  @Patch(':id')
  @UseGuards(PermissionsGuard)
  @RequirePermissions('update-notification')
  async updateNotificationById(
    @Param('id') id: string,
    @Body() body: UpdateNotificationDto,
  ) {
    const data = await this.notificationService.update(
      id,
      body as Partial<Notification>,
    );
    return { status: 'Success', data };
  }
}

