import {
  Injectable,
  NotFoundException,
  BadRequestException,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Notification } from './notification.entity';

@Injectable()

@Injectable()
export class NotificationService {
  constructor(
    @InjectRepository(Notification)
    private readonly notificationRepository: Repository<Notification>,
  ) {}

  async findAll(): Promise<Notification[]> {
    return this.notificationRepository.find({
      relations: ['created_by', 'ticket'],
    });
  }

  async findForUser(
    userId: string,
    externalUserId?: string,
    tenantId?: string,
  ): Promise<Notification[]> {
    const qb = this.notificationRepository
      .createQueryBuilder('n')
      .leftJoinAndSelect('n.created_by', 'created_by')
      .leftJoinAndSelect('n.ticket', 'ticket')
      .where('n.to = :userId', { userId });

    if (externalUserId?.trim()) {
      qb.orWhere('n.to = :externalUserId', {
        externalUserId: externalUserId.trim(),
      });
      qb.orWhere('n.to_external_id = :externalUserId', {
        externalUserId: externalUserId.trim(),
      });
    }
    if (tenantId?.trim()) {
      qb.andWhere('n.tenant_id = :tenantId', { tenantId: tenantId.trim() });
    }
    return qb.orderBy('n.created_at', 'DESC').getMany();
  }

  async findUserNotifications(tenantId?: string): Promise<Notification[]> {
    return this.notificationRepository.find({
      where: {
        type: 'user',
        ...(tenantId?.trim() ? { tenant_id: tenantId.trim() } : {}),
      },
      order: { created_at: 'DESC' },
    });
  }

  async findSystemNotifications(tenantId?: string): Promise<Notification[]> {
    return this.notificationRepository.find({
      where: {
        type: 'system',
        ...(tenantId?.trim() ? { tenant_id: tenantId.trim() } : {}),
      },
      order: { created_at: 'DESC' },
    });
  }

  async findOne(id: string): Promise<Notification> {
    const notification = await this.notificationRepository.findOne({
      where: { id },
      relations: ['created_by', 'ticket'],
    });
    if (!notification)
      throw new NotFoundException('Notification does not exist');
    return notification;
  }

  /** Used by delete: same as findOne but with Express message. */
  async findOneForDelete(id: string): Promise<Notification> {
    const notification = await this.notificationRepository.findOne({
      where: { id },
      relations: ['created_by', 'ticket'],
    });
    if (!notification)
      throw new NotFoundException('Notification Does Not Exist!');
    return notification;
  }

  async create(data: Partial<Notification>): Promise<Notification> {
    const notification = this.notificationRepository.create(data);
    return this.notificationRepository.save(notification);
  }

  async update(id: string, data: Partial<Notification>): Promise<Notification> {
    const result = await this.notificationRepository.findOne({
      where: { id },
      relations: ['created_by', 'ticket'],
    });
    if (!result) throw new NotFoundException('Notification id is Not Found');
    this.notificationRepository.merge(result, data);
    const updated = await this.notificationRepository.save(result);
    if (!updated) throw new BadRequestException('Unable to update');
    return this.notificationRepository.findOne({
      where: { id },
      relations: ['created_by', 'ticket'],
    }) as Promise<Notification>;
  }

  async remove(id: string): Promise<void> {
    await this.findOneForDelete(id);
    await this.notificationRepository.delete({ id });
  }

  async removeAll(): Promise<void> {
    const allNotification = await this.notificationRepository.find();
    if (!allNotification)
      throw new NotFoundException('Unable to delete notification');
    await this.notificationRepository.clear();
  }
}

