import { Injectable, NotFoundException } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { existsSync, readFileSync } from 'fs';
import { join } from 'path';
import { Permission } from './permission.entity';

type PermissionCatalogEntry = {
  key?: string;
  slug: string;
  name: string;
};

type PermissionCatalog = {
  permissions: PermissionCatalogEntry[];
};

function readPermissionCatalog(): PermissionCatalogEntry[] {
  const candidates = [
    join(__dirname, 'permissions.catalog.json'),
    join(process.cwd(), 'src', 'permission', 'permissions.catalog.json'),
  ];
  const catalogPath = candidates.find((path) => existsSync(path));
  if (!catalogPath) return [];
  const raw = readFileSync(catalogPath, 'utf8');
  const parsed = JSON.parse(raw) as PermissionCatalog;
  return (parsed.permissions ?? []).filter(
    (permission) => permission.slug?.trim() && permission.name?.trim(),
  );
}

@Injectable()
export class PermissionService {
  constructor(
    @InjectRepository(Permission)
    private readonly permissionRepository: Repository<Permission>,
  ) {}

  async findAll(): Promise<Permission[]> {
    const list = await this.permissionRepository.find({
      order: { name: 'ASC' },
    });
    return list ?? [];
  }

  /**
   * Upserts rows from `permissions.catalog.json` (bundled next to compiled code via nest-cli assets).
   * Used by the permission seeder HTTP route — permissions are not created via the public API.
   */
  async runSeeder(): Promise<Permission[] | null> {
    try {
      const catalogPermissions = readPermissionCatalog();
      for (const item of catalogPermissions) {
        const existing = await this.permissionRepository.findOne({
          where: { slug: item.slug },
        });
        if (existing) {
          const nextName = item.name || existing.name;
          if (existing.name !== nextName) {
            existing.name = nextName;
            await this.permissionRepository.save(existing);
          }
          continue;
        }
        await this.permissionRepository.save(
          this.permissionRepository.create({
            name: item.name,
            slug: item.slug,
          }),
        );
      }
      return await this.permissionRepository.find({
        order: { name: 'ASC' },
      });
    } catch {
      return null;
    }
  }

  async findOne(id: string): Promise<Permission> {
    const permission = await this.permissionRepository.findOne({
      where: { id },
    });
    if (!permission)
      throw new NotFoundException(`Permission with id ${id} was not found`);
    return permission;
  }
}

