import { Controller, Post, UseGuards } from '@nestjs/common';
import { PermissionSeederService } from './permission-seeder.service';
import { AuthGuard } from '../core/guards/auth.guard';
import { PermissionsGuard } from '../core/guards/permissions.guard';
import { RequirePermissions } from '../common/decorators/require-permissions.decorator';

@Controller('permissionSeeder')
export class PermissionSeederController {
  constructor(
    private readonly permissionSeederService: PermissionSeederService,
  ) {}

  @Post()
  @UseGuards(AuthGuard, PermissionsGuard)
  @RequirePermissions('update-role')
  async seedPermissions() {
    const data = await this.permissionSeederService.seedPermissions();
    return { status: 200, message: 'Data inserted successfully', data };
  }
}

import { Module } from '@nestjs/common';
import { PermissionSeederController } from './permission-seeder.controller';
import { PermissionSeederService } from './permission-seeder.service';
import { PermissionModule } from '../permission/permission.module';

@Module({
  imports: [PermissionModule],
  controllers: [PermissionSeederController],
  providers: [PermissionSeederService],
})
export class PermissionSeederModule {}

import { Injectable, BadRequestException } from '@nestjs/common';
import { PermissionService } from '../permission/permission.service';
import { Permission } from '../permission/permission.entity';

@Injectable()
export class PermissionSeederService {
  constructor(private readonly permissionService: PermissionService) {}

  /** Applies `permissions.catalog.json` to the DB via PermissionService.runSeeder. */
  async seedPermissions(): Promise<Permission[]> {
    try {
      const permissions = await this.permissionService.runSeeder();
      if (permissions == null || !permissions.length) {
        throw new BadRequestException('Permission is unable to seed');
      }
      return permissions;
    } catch (err) {
      if (err instanceof BadRequestException) throw err;
      throw new BadRequestException('Permission must be Unique');
    }
  }
}

