import {
  Controller,
  Get,
  Post,
  Patch,
  Delete,
  Body,
  Param,
  UseGuards,
} from '@nestjs/common';
import { PriorityService } from './priority.service';
import { AuthGuard } from '../core/guards/auth.guard';
import { PermissionsGuard } from '../core/guards/permissions.guard';
import { RequirePermissions } from '../common/decorators/require-permissions.decorator';
import { Priority } from './priority.entity';
import { CreatePriorityDto } from './dto/create-priority.dto';

@Controller('priorities')

@Controller('priorities')
export class PriorityController {
  constructor(private readonly priorityService: PriorityService) {}

  @Get()
  @UseGuards(AuthGuard, PermissionsGuard)
  @RequirePermissions('view-priorities')
  async getAll() {
    const data = await this.priorityService.findAll();
    return { status: 'Success', data };
  }

  @Get(':id')
  @UseGuards(AuthGuard)
  async getOne(@Param('id') id: string) {
    const data = await this.priorityService.findOne(id);
    return { status: 'Success', data };
  }

  @Post()
  @UseGuards(AuthGuard, PermissionsGuard)
  @RequirePermissions('create-priority')
  async create(@Body() body: CreatePriorityDto) {
    const data = await this.priorityService.create(body);
    return { status: 'Success', data };
  }

  @Patch()
  @UseGuards(AuthGuard, PermissionsGuard)
  @RequirePermissions('update-priority')
  async edit(@Body() body: { id: string } & Partial<Priority>) {
    const { id, ...rest } = body;
    const data = await this.priorityService.update(id, rest);
    return { status: 'Success', data };
  }

  @Delete('deleteAllPriorities')
  @UseGuards(AuthGuard, PermissionsGuard)
  @RequirePermissions('delete-priorities')
  async deleteAll() {
    const data = await this.priorityService.removeAll();
    return { status: 'Success', data };
  }

  @Delete(':id')
  @UseGuards(AuthGuard, PermissionsGuard)
  @RequirePermissions('delete-priority')
  async delete(@Param('id') id: string) {
    await this.priorityService.remove(id);
    return { status: 'Success', data: null };
  }
}

import {
  Entity,
  PrimaryGeneratedColumn,
  Column,
  CreateDateColumn,
  UpdateDateColumn,
  OneToMany,
} from 'typeorm';
import { Ticket } from '../ticket/ticket.entity';

@Entity('priority')
export class Priority {
  @PrimaryGeneratedColumn('uuid')
  id: string;

  @Column({ type: 'varchar' })
  type: string;

  @Column({ type: 'varchar', name: 'priority_color' })
  priority_color: string;

  @Column({ type: 'boolean', default: false, name: 'is_deleted' })
  is_deleted: boolean;

  @CreateDateColumn({ name: 'created_at' })
  created_at: Date;

  @UpdateDateColumn({ name: 'updated_at' })
  updated_at: Date;

  @OneToMany(() => Ticket, (ticket) => ticket.ticket_priority)
  tickets: Ticket[];
}

import { Module } from '@nestjs/common';
import { TypeOrmModule } from '@nestjs/typeorm';
import { Priority } from './priority.entity';
import { PriorityController } from './priority.controller';
import { PriorityService } from './priority.service';

@Module({
  imports: [TypeOrmModule.forFeature([Priority])],
  controllers: [PriorityController],
  providers: [PriorityService],
  exports: [TypeOrmModule, PriorityService],
})
export class PriorityModule {}

import { Injectable, NotFoundException } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Priority } from './priority.entity';

@Injectable()
export class PriorityService {
  constructor(
    @InjectRepository(Priority)
    private readonly priorityRepository: Repository<Priority>,
  ) {}

  async findAll(): Promise<Priority[]> {
    return this.priorityRepository.find({ where: { is_deleted: false } });
  }

  async findOne(id: string): Promise<Priority> {
    const priority = await this.priorityRepository.findOne({
      where: { id, is_deleted: false },
    });
    if (!priority)
      throw new NotFoundException('Ticket Does Not Have Any Priority');
    return priority;
  }

  async create(data: Partial<Priority>): Promise<Priority> {
    const priority = this.priorityRepository.create({
      type: data.type,
      priority_color: data.priority_color,
    });
    return this.priorityRepository.save(priority);
  }

  async update(id: string, data: Partial<Priority>): Promise<Priority> {
    const priority = await this.priorityRepository.findOne({ where: { id } });
    if (!priority)
      throw new NotFoundException('Ticket Does Not Have Any Priority!');
    Object.assign(priority, data);
    return this.priorityRepository.save(priority);
  }

  async remove(id: string): Promise<void> {
    const priority = await this.priorityRepository.findOne({ where: { id } });
    if (!priority) throw new NotFoundException('Priority Does Not Exist!');
    await this.priorityRepository.delete({ id });
  }

  /** Returns deleted priorities to match Express deleteAllPriorities response. */
  async removeAll(): Promise<Priority[]> {
    const list = await this.priorityRepository.find();
    await this.priorityRepository.clear();
    return list;
  }
}

