import { Injectable, NotFoundException, HttpException } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Role } from './role.entity';

@Injectable()

@Injectable()
export class RoleService {
  constructor(
    @InjectRepository(Role)
    private readonly roleRepository: Repository<Role>,
  ) {}

  async findAll(): Promise<Role[]> {
    const roles = await this.roleRepository.find({
      relations: ['permissions'],
    });
    return roles ?? [];
  }

  async findOne(id: string): Promise<Role> {
    const role = await this.roleRepository.findOne({
      where: { id },
      relations: ['permissions'],
    });
    if (!role)
      throw new NotFoundException('Role with the given id is not found.');
    return role;
  }

  async findOneByName(roleName: string): Promise<Role> {
    const role = await this.roleRepository.findOne({ where: { roleName } });
    if (!role)
      throw new NotFoundException('Role with the given roleName is not found.');
    return role;
  }

  async create(data: { roleName: string }): Promise<Role> {
    const existing = await this.roleRepository.findOne({
      where: { roleName: data.roleName },
    });
    if (existing) throw new HttpException('role name must be unique.', 406);
    const entity = this.roleRepository.create(data);
    return this.roleRepository.save(entity);
  }

  async update(id: string, data: Partial<Role>): Promise<Role> {
    const role = await this.findOne(id);
    if (data.roleName && data.roleName !== role.roleName) {
      const existing = await this.roleRepository.findOne({
        where: { roleName: data.roleName },
      });
      if (existing) throw new HttpException('Role name must be unique.', 406);
    }
    this.roleRepository.merge(role, data);
    return this.roleRepository.save(role);
  }

  async remove(id: string): Promise<void> {
    const role = await this.findOne(id);
    await this.roleRepository.remove(role);
  }
}

