import { Injectable, NotFoundException } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Role } from '../role/role.entity';
import { RoleService } from '../role/role.service';
import { PermissionService } from '../permission/permission.service';

@Injectable()
export class RolePermissionService {
  constructor(
    @InjectRepository(Role)
    private readonly roleRepository: Repository<Role>,
    private readonly roleService: RoleService,
    private readonly permissionService: PermissionService,
  ) {}

  async getAllRolePermission() {
    const roles = await this.roleRepository.find({
      relations: ['permissions'],
    });
    const data = roles.map((r) => ({
      role_id: r.id,
      permissions: r.permissions || [],
    }));
    if (!data.length)
      throw new NotFoundException('Role Permission table is Empty');
    return data;
  }

  async getRolePermissionById(id: string) {
    const role = await this.roleRepository.findOne({
      where: { id },
      relations: ['permissions'],
    });
    if (!role) throw new NotFoundException('Role Permission id is Not Found');
    return { role_id: role.id, permissions: role.permissions || [] };
  }

  async assignPermissionToRole(roleId: string, permissionIds: string[]) {
    const role = await this.roleRepository.findOne({
      where: { id: roleId },
      relations: ['permissions'],
    });
    if (!role) throw new NotFoundException('Role Id NOT FOUND');
    const permissions = await Promise.all(
      permissionIds.map((id) => this.permissionService.findOne(id)),
    ).catch(() => {
      throw new NotFoundException('Permission Id NOT FOUND');
    });
    role.permissions = permissions;
    await this.roleRepository.save(role);
    return { role_id: roleId, permissions };
  }
}

