import { Injectable, NotFoundException } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Status } from './status.entity';

@Injectable()
export class StatusService {
  constructor(
    @InjectRepository(Status)
    private readonly statusRepository: Repository<Status>,
  ) {}

  async findAll(): Promise<Status[]> {
    return this.statusRepository.find({ where: { is_deleted: false } });
  }

  async findOne(id: string): Promise<Status> {
    const status = await this.statusRepository.findOne({
      where: { id, is_deleted: false },
    });
    if (!status) throw new NotFoundException('Ticket Does Not Have Any Status');
    return status;
  }

  async findByType(type: string): Promise<Status> {
    const status = await this.statusRepository.findOne({
      where: { type, is_deleted: false },
    });
    if (!status)
      throw new NotFoundException(`Status with type '${type}' not found`);
    return status;
  }

  async create(data: Partial<Status>): Promise<Status> {
    const status = this.statusRepository.create(data);
    return this.statusRepository.save(status);
  }

  async update(id: string, data: Partial<Status>): Promise<Status> {
    const status = await this.statusRepository.findOne({ where: { id } });
    if (!status)
      throw new NotFoundException('Ticket Does Not Have Any Status!');
    Object.assign(status, data);
    return this.statusRepository.save(status);
  }

  async remove(id: string): Promise<void> {
    const status = await this.statusRepository.findOne({ where: { id } });
    if (!status) throw new NotFoundException('Status Does Not Exist!');
    await this.statusRepository.delete({ id });
  }

  /** Returns deleted statuses to match Express deleteAllStatuses response. */
  async removeAll(): Promise<Status[]> {
    const list = await this.statusRepository.find();
    await this.statusRepository.clear();
    return list;
  }
}

