import {
  Controller,
  Get,
  Post,
  Patch,
  Delete,
  Body,
  Param,
  UseGuards,
  NotFoundException,
  BadRequestException,
} from '@nestjs/common';
import { SupportService } from './support.service';
import { AuthGuard } from '../core/guards/auth.guard';
import { PermissionsGuard } from '../core/guards/permissions.guard';
import { RequirePermissions } from '../common/decorators/require-permissions.decorator';
import { CurrentUser } from '../common/decorators/current-user.decorator';
import { User } from '../user/user.entity';
import {
  CreateSupportDto,
  UpdateSupportDto,
  SupportCommentDto,
  ApproveSupportDto,
} from './dto';

@Controller('support')
@UseGuards(AuthGuard)

@UseGuards(AuthGuard)
export class SupportController {
  constructor(private readonly supportService: SupportService) {}

  @Get()
  async getSupports(@CurrentUser() user: User) {
    const data = await this.supportService.findAll(user.tenant_id ?? undefined);
    return { status: 'Success', data };
  }

  @Get('all/projects/get')
  async getProjects() {
    const data = await this.supportService.getProjects();
    return { status: 'Success', data };
  }

  /** GET /support/status – matches Express route for approval status list */
  @Get('status')
  async getApprovalStatus() {
    const data = await this.supportService.getApprovalStatuses();
    return { status: 'Success', data };
  }

  @Get('approval/status')
  async getApprovalStatusAlternate() {
    const data = await this.supportService.getApprovalStatuses();
    return { status: 'Success', data };
  }

  @Get('junk/get-all/support')
  async getAllEmailSupports() {
    const data = await this.supportService.getAllEmailSupports();
    return { status: 'Success', data };
  }

  @Get('junk/untransfered')
  async getAllUnTransferedEmailSupports() {
    const data = await this.supportService.getAllUnTransferedEmailSupports();
    return { status: 'Success', data };
  }

  @Get('junk/:id')
  async getEmailSupportById(@Param('id') id: string) {
    const data = await this.supportService.getEmailSupportById(id);
    if (!data) throw new NotFoundException('Support NOT FOUND');
    return { status: 'Success', data };
  }

  @Get(':key/:value')
  async getSupport(
    @Param('key') key: string,
    @Param('value') value: string,
    @CurrentUser() user: User,
  ) {
    const data = await this.supportService.findByKeyValue(
      key,
      value,
      user.tenant_id ?? undefined,
    );
    if (!data?.length) throw new NotFoundException('Support Not Found');
    return { status: 'Success', data };
  }

  @Get(':id')
  async getSupportById(@Param('id') id: string, @CurrentUser() user: User) {
    const data = await this.supportService.findOne(
      id,
      user.tenant_id ?? undefined,
    );
    return { status: 'Success', data };
  }

  @Post()
  @UseGuards(PermissionsGuard)
  @RequirePermissions('create-support')
  async createSupport(
    @Body() body: CreateSupportDto,
    @CurrentUser() user?: User,
  ) {
    const payload = {
      ...body,
      supportStartDate: body.supportStartDate
        ? new Date(body.supportStartDate)
        : undefined,
      supportEndDate: body.supportEndDate
        ? new Date(body.supportEndDate)
        : undefined,
      createdById: user?.id,
      createdByExternalId: user?.local_id ?? undefined,
      senderExternalId: user?.local_id ?? undefined,
      tenant_id: user?.tenant_id ?? undefined,
    };
    const data = await this.supportService.create(payload);
    return { status: 'Success', data };
  }

  @Post('comment')
  @UseGuards(PermissionsGuard)
  @RequirePermissions('create-comment')
  async supportComment(
    @Body() body: SupportCommentDto,
    @CurrentUser() user: User,
  ) {
    if (body.supportId) {
      const existing = await this.supportService.findByKeyValue(
        'id',
        body.supportId,
        user.tenant_id ?? undefined,
      );
      if (!existing?.length)
        throw new NotFoundException('Support Does not exist');
    }
    return { status: 'Success', data: body };
  }

  @Post('junk/:id')
  @UseGuards(PermissionsGuard)
  @RequirePermissions('transfer-junk-tickets')
  async transferEmailSupportToNormalSupport(
    @Param('id') id: string,
    @Body() body: CreateSupportDto,
  ) {
    const data = await this.supportService.transferEmailSupportToSupport(
      id,
      body as Partial<import('./support.entity').Support>,
    );
    return { status: 'Success', data };
  }

  @Patch('approval/status')
  @UseGuards(PermissionsGuard)
  @RequirePermissions('update-support')
  async approveSupport(
    @Body() body: ApproveSupportDto,
    @CurrentUser() user: User,
  ) {
    if (!body.supportId) throw new BadRequestException('supportId is required');
    const existing = await this.supportService.findByKeyValue(
      'id',
      body.supportId,
      user.tenant_id ?? undefined,
    );
    if (!existing?.length)
      throw new NotFoundException('Support Does not exist');
    const data = await this.supportService.update(body.supportId, {
      approvedById: body.userId,
      approvedByExternalId: user.local_id ?? undefined,
    });
    return { status: 'Success', data };
  }

  @Patch(':id')
  @UseGuards(PermissionsGuard)
  @RequirePermissions('update-support')
  async updateSupport(@Param('id') id: string, @Body() body: UpdateSupportDto) {

  async updateSupport(@Param('id') id: string, @Body() body: UpdateSupportDto) {
    const data = await this.supportService.update(
      id,
      body as Partial<import('./support.entity').Support>,
    );
    return { message: 'Support is successfully updated', data };
  }

  @Delete('junk/:id')
  @UseGuards(PermissionsGuard)
  @RequirePermissions('delete-junk-ticket')
  async deleteEmailSupport(@Param('id') id: string) {
    await this.supportService.removeEmailSupport(id);
    return {
      status: 'Email support is deleted Successfully',
      statusCode: 200,
    };
  }

  @Delete(':id')
  @UseGuards(PermissionsGuard)
  @RequirePermissions('delete-support')
  async deleteSupport(@Param('id') id: string) {
    await this.supportService.remove(id);
    return { message: 'Support is Deleted Successfully' };
  }
}

import {
  Entity,
  PrimaryGeneratedColumn,
  Column,
  CreateDateColumn,
  UpdateDateColumn,
  ManyToOne,
  ManyToMany,
  JoinColumn,
} from 'typeorm';
import { User } from '../user/user.entity';
import { Project } from '../project/project.entity';
import { ApprovalStatus } from '../approval-status/approval-status.entity';
import { Team } from '../team/team.entity';

@Entity('support')

@Entity('support')
export class Support {
  @PrimaryGeneratedColumn('uuid')
  id: string;

  @Column({ type: 'varchar' })
  name: string;

  @Column({ type: 'timestamp', nullable: true, name: 'supportStartDate' })
  supportStartDate: Date;

  @Column({ type: 'timestamp', nullable: true, name: 'supportEndDate' })
  supportEndDate: Date;

  @Column({ type: 'integer', nullable: true, name: 'supportDuration' })
  supportDuration: number;

  @Column({ type: 'varchar', name: 'clientId' })
  clientId: string;

  @Column({ type: 'uuid', nullable: true, name: 'projectId' })
  projectId: string;

  @Column({ type: 'boolean', default: false, name: 'isCSAT' })
  isCSAT: boolean;

  @Column({ type: 'varchar', nullable: true, name: 'approvalStatusId' })
  approvalStatusId: string;

  @Column({ type: 'uuid', nullable: true, name: 'approvedById' })
  approvedById: string;

  @Column({ type: 'uuid', nullable: true, name: 'createdById' })
  createdById: string;

  @Column({ type: 'uuid', nullable: true, name: 'senderId' })
  senderId: string;

  @Column({
    type: 'varchar',
    nullable: true,
    name: 'createdByExternalId',
  })
  createdByExternalId: string | null;

  @Column({ type: 'varchar', nullable: true, name: 'senderExternalId' })
  senderExternalId: string | null;

  @Column({ type: 'varchar', nullable: true, name: 'approvedByExternalId' })
  approvedByExternalId: string | null;

  @Column({ type: 'varchar', nullable: true, name: 'clientExternalId' })
  clientExternalId: string | null;

  @Column({ type: 'varchar', nullable: true, name: 'tenant_id' })
  tenant_id: string | null;

  @Column({ type: 'timestamp', nullable: true, name: 'CSATSupportStartDate' })
  CSATSupportStartDate: Date;

  @Column({ type: 'timestamp', nullable: true, name: 'CSATSupportEndDate' })
  CSATSupportEndDate: Date;

  @Column({ type: 'integer', nullable: true, name: 'CSATSupportDuration' })
  CSATSupportDuration: number;

  @CreateDateColumn({ name: 'created_at' })
  created_at: Date;

  @UpdateDateColumn({ name: 'updated_at' })
  updated_at: Date;

  @ManyToOne(() => User)
  @JoinColumn({ name: 'clientId' })
  client: User;

  @ManyToOne(() => Project, (project) => project.supports)
  @JoinColumn({ name: 'projectId' })
  project: Project;

  @ManyToOne(() => ApprovalStatus)
  @JoinColumn({ name: 'approvalStatusId' })
  approvalStatus: ApprovalStatus;

  @ManyToOne(() => User)
  @JoinColumn({ name: 'approvedById' })
  approvedBy: User;

  @ManyToOne(() => User)
  @JoinColumn({ name: 'createdById' })
  createdBy: User;

  @ManyToOne(() => User)
  @JoinColumn({ name: 'senderId' })
  sender: User;

  @ManyToMany(() => Team, (team) => team.support)
  teams: Team[];
}

import { Module } from '@nestjs/common';
import { TypeOrmModule } from '@nestjs/typeorm';
import { Support } from './support.entity';
import { EmailSupport } from './email-support.entity';
import { Project } from '../project/project.entity';
import { ApprovalStatus } from '../approval-status/approval-status.entity';
import { Team } from '../team/team.entity';
import { ImapService } from './imap.service';
import { SupportController } from './support.controller';
import { SupportService } from './support.service';
import { CommonModule } from '../common/common.module';

@Module({
  imports: [
    TypeOrmModule.forFeature([
      Support,
      EmailSupport,
      Project,
      ApprovalStatus,
      Team,
    ]),
    CommonModule,
  ],
  controllers: [SupportController],
  providers: [ImapService, SupportService],
  exports: [TypeOrmModule, SupportService],
})
export class SupportModule {}

import {
  Injectable,
  NotFoundException,
  BadRequestException,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository, In } from 'typeorm';
import { Support } from './support.entity';
import { EmailSupport } from './email-support.entity';
import { Project } from '../project/project.entity';
import { ApprovalStatus } from '../approval-status/approval-status.entity';
import { Team } from '../team/team.entity';

@Injectable()

@Injectable()
export class SupportService {
  constructor(
    @InjectRepository(Support)
    private readonly supportRepository: Repository<Support>,
    @InjectRepository(EmailSupport)
    private readonly emailSupportRepository: Repository<EmailSupport>,
    @InjectRepository(Project)
    private readonly projectRepository: Repository<Project>,
    @InjectRepository(ApprovalStatus)
    private readonly approvalStatusRepository: Repository<ApprovalStatus>,
    @InjectRepository(Team)
    private readonly teamRepository: Repository<Team>,
  ) {}

  async findAll(tenantId?: string): Promise<Support[]> {
    return this.supportRepository.find({
      where: tenantId?.trim() ? { tenant_id: tenantId.trim() } : {},
      relations: ['client', 'project', 'teams'],
    });
  }

  async findByKeyValue(
    key: string,
    value: string,
    tenantId?: string,
  ): Promise<Support[]> {
    const keyCondition = key === 'client_id' ? 'clientId' : key;
    const where = {
      [keyCondition]: value,
      ...(tenantId?.trim() ? { tenant_id: tenantId.trim() } : {}),
    } as Record<string, string>;
    return this.supportRepository.find({
      where: where as never,
      relations: ['client', 'project'],
    });
  }

  async findOne(id: string, tenantId?: string): Promise<Support> {
    const s = await this.supportRepository.findOne({
      where: {
        id,
        ...(tenantId?.trim() ? { tenant_id: tenantId.trim() } : {}),
      },
      relations: ['client', 'project', 'teams'],
    });
    if (!s) throw new NotFoundException('Support Not Found');
    return s;
  }

  /** Get approval status by status name (e.g. "Request"). */
  async getApprovalStatusByStatus(statusName: string): Promise<ApprovalStatus> {
    const status = await this.approvalStatusRepository.findOne({
      where: { status: statusName },
    });
    if (!status)
      throw new NotFoundException(`Approval status "${statusName}" not found`);
    return status;
  }

  /** Create support with Express-like logic: approval status, duplicate check, duration, project update, team assignment. */
  async create(
    data: Partial<Support> & {
      supportStartDate?: Date;
      supportEndDate?: Date;
      supportType?: string;
      hasProject?: string;
      teamsId?: string[];
      createdById?: string;
      createdByExternalId?: string;
      senderExternalId?: string;
      tenant_id?: string;
      clientExternalId?: string;
    },
  ): Promise<Support> {
    const approvalStatus = await this.getApprovalStatusByStatus('Request');
    if (data.projectId != null) {
      const existingProject = await this.projectRepository.findOne({
        where: { id: data.projectId },
      });
      if (existingProject?.hasSupport) {
        throw new BadRequestException(
          "Can't create another support for the same project",
        );
      }
    }

    const startDate = data.supportStartDate
      ? new Date(data.supportStartDate)
      : null;
    const endDate = data.supportEndDate ? new Date(data.supportEndDate) : null;
    const supportDuration =
      startDate && endDate
        ? Math.round(
            (endDate.getTime() - startDate.getTime()) / (1000 * 60 * 60 * 24),
          )
        : undefined;

    const support = this.supportRepository.create({
      name: data.name,
      clientId: data.clientId,
      projectId: data.projectId ?? undefined,
      supportDuration,
      supportStartDate: startDate ?? undefined,
      supportEndDate: endDate ?? undefined,
      approvalStatusId: approvalStatus.id,
      isCSAT: data.supportType === 'CSAT',
      createdById: data.createdById,
      createdByExternalId: data.createdByExternalId ?? null,
      senderId: data.createdById,
      senderExternalId:
        data.senderExternalId ?? data.createdByExternalId ?? null,
      tenant_id: data.tenant_id ?? null,
      clientExternalId: data.clientExternalId ?? null,
    });
    const saved = await this.supportRepository.save(support);

    if (data.projectId != null) {
      await this.projectRepository.update(
        { id: data.projectId },
        { hasSupport: true },
      );
    }

    const teamIds = data.teamsId ?? [];
    if (teamIds.length > 0) {
      const teams = await this.teamRepository.find({
        where: { id: In(teamIds) },
      });
      const isNormal = data.supportType !== 'CSAT';
      const useProjectTeams = isNormal || data.hasProject === 'YES';
      if (useProjectTeams && data.projectId) {
        const project = await this.projectRepository.findOne({
          where: { id: data.projectId },
          relations: ['teams'],
        });
        if (project) {
          project.teams = teams;
          await this.projectRepository.save(project);
        }
      } else {
        saved.teams = teams;
        await this.supportRepository.save(saved);
      }
    }

    return this.findOne(saved.id);
  }

  async update(id: string, data: Partial<Support>): Promise<Support> {
    const support = await this.findOne(id);
    this.supportRepository.merge(support, data);
    return this.supportRepository.save(support);
  }

  async remove(id: string): Promise<void> {

  async remove(id: string): Promise<void> {
    const support = await this.supportRepository.findOne({
      where: { id },
      relations: ['client', 'project', 'teams'],
    });
    if (!support) throw new NotFoundException('Support NOT FOUND');
    const result = await this.supportRepository.delete({ id });
    if (result.affected === 0) throw new NotFoundException('Delete Failed');
  }

  /** All projects (for support context). */
  async getProjects(): Promise<Project[]> {
    return this.projectRepository.find({ relations: ['client', 'teams'] });
  }

  /** All approval statuses. */
  async getApprovalStatuses(): Promise<ApprovalStatus[]> {
    return this.approvalStatusRepository.find();
  }

  /** Email/junk supports: fetch from email_support table. */
  async getAllEmailSupports(): Promise<EmailSupport[]> {
    return this.emailSupportRepository.find({
      order: { created_at: 'DESC' },
    });
  }

  async getEmailSupportById(id: string): Promise<EmailSupport | null> {
    return this.emailSupportRepository.findOne({
      where: { id },
    });
  }

  /** Un-transferred: fetch from email_support where isTransfered = false. */
  async getAllUnTransferedEmailSupports(): Promise<EmailSupport[]> {
    return this.emailSupportRepository.find({
      where: { isTransfered: false },
      order: { created_at: 'DESC' },
    });
  }

  /** Delete a record from the email_support table (junk). */
  async removeEmailSupport(id: string): Promise<void> {
    const result = await this.emailSupportRepository.delete({ id });
    if (result.affected === 0)
      throw new NotFoundException('Email support not found');
  }

  /**
   * Transfer an email support (junk) to a normal Support: create a new Support from body
   * and mark the EmailSupport as transferred. Uses body for the new Support (name, clientId, projectId, etc.).
   */
  async transferEmailSupportToSupport(
    emailSupportId: string,
    body: Partial<Support> & {
      name?: string;
      clientId?: string;
      projectId?: string;
    },
  ): Promise<Support> {
    const emailSupport = await this.getEmailSupportById(emailSupportId);
    if (!emailSupport) throw new NotFoundException('Email support not found');
    if (!body.clientId)
      throw new BadRequestException(
        'clientId is required to transfer email support',
      );

    const approvalStatus = await this.getApprovalStatusByStatus('Request');
    const support = this.supportRepository.create({
      name: body.name ?? emailSupport.subject,
      clientId: body.clientId,
      projectId: body.projectId ?? undefined,
      approvalStatusId: body.approvalStatusId ?? approvalStatus.id,
      approvedById: body.approvedById,
      isCSAT: body.isCSAT ?? false,
      createdById: body.createdById,
      createdByExternalId: body.createdByExternalId ?? null,
      senderId: body.createdById,
      senderExternalId:
        body.senderExternalId ?? body.createdByExternalId ?? null,
      tenant_id: body.tenant_id ?? null,
      clientExternalId: body.clientExternalId ?? null,
    });
    const saved = await this.supportRepository.save(support);

    await this.emailSupportRepository.update(
      { id: emailSupportId },
      { isTransfered: true },
    );

    return this.findOne(saved.id);
  }
}

