import { Project } from '../project/project.entity';
import { Support } from '../support/support.entity';

@Entity('team')

@Entity('team')
export class Team {
  @PrimaryGeneratedColumn('uuid')
  id: string;

  @Column({ type: 'varchar' })
  name: string;

  @Column({ type: 'boolean', default: false, name: 'is_deleted' })
  is_deleted: boolean;

  @CreateDateColumn({ name: 'created_at' })
  created_at: Date;

  @UpdateDateColumn({ name: 'updated_at' })
  updated_at: Date;

  @Column({ type: 'uuid', nullable: true, name: 'createdBy_id' })
  createdBy_id: string;

  @Column({ type: 'uuid', nullable: true, name: 'department_id' })
  department_id: string;

  @Column({ type: 'uuid', nullable: true, name: 'teamlead_id' })
  teamlead_id: string | null;

  @Column({ type: 'varchar', nullable: true, name: 'teamlead_external_id' })
  teamlead_external_id: string | null;

  @ManyToOne(() => User)
  @JoinColumn({ name: 'createdBy_id' })
  created_by: User;

  @ManyToOne(() => Department, (dept) => dept.teams)
  @JoinColumn({ name: 'department_id' })
  department: Department;

  @ManyToOne(() => User)
  @JoinColumn({ name: 'teamlead_id' })
  team_lead: User;

  @OneToMany(() => Ticket, (ticket) => ticket.team)
  tickets: Ticket[];

  @ManyToMany(() => User, (user) => user.teams_access)
  members: User[];

  @ManyToMany(() => Project, (project) => project.teams)
  @JoinTable({
    name: 'projects_team',
    joinColumn: { name: 'teamId', referencedColumnName: 'id' },
    inverseJoinColumn: { name: 'projectId', referencedColumnName: 'id' },
  })
  projects: Project[];

  @ManyToMany(() => Support, (support) => support.teams)
  @JoinTable({
    name: 'support_team',
    joinColumn: { name: 'teamId', referencedColumnName: 'id' },
    inverseJoinColumn: { name: 'supportId', referencedColumnName: 'id' },
  })
  support: Support[];
}

