import {
  Injectable,
  NotFoundException,
  BadRequestException,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Team } from './team.entity';
import { User } from '../user/user.entity';
import type { DeepPartial } from 'typeorm';

@Injectable()

@Injectable()
export class TeamService {
  constructor(
    @InjectRepository(Team)
    private readonly teamRepository: Repository<Team>,
    @InjectRepository(User)
    private readonly userRepository: Repository<User>,
  ) {}

  private shapeTeamResponse(team: Team): Team {
    const hasExternalLead = !!team.teamlead_external_id?.trim();
    if (!hasExternalLead) return team;
    const dto = {
      ...(team as unknown as Record<string, unknown>),
      // Keep legacy relation only as fallback metadata.
      team_lead_legacy: team.team_lead ?? null,
      team_lead: null,
    };
    return dto as unknown as Team;
  }

  async findAll(): Promise<Team[]> {
    const teams = await this.teamRepository.find({
      where: { is_deleted: false },
      relations: ['tickets', 'team_lead', 'department'],
    });
    return teams.map((team) => this.shapeTeamResponse(team));
  }

  async findOne(id: string): Promise<Team> {
    const team = await this.teamRepository.findOne({
      where: { id, is_deleted: false },
      relations: ['tickets', 'team_lead', 'department'],
    });
    if (!team) throw new NotFoundException('Team with the given id Not Found');
    return this.shapeTeamResponse(team);
  }

  async create(data: {
    name: string;
    teamlead_id?: string;
    teamlead_external_id?: string;
    department_id?: string;
    created_by?: User;
  }): Promise<Team> {
    const teamLeadId = data.teamlead_id?.trim();
    const teamLeadExternalId = data.teamlead_external_id?.trim();
    let teamLead: User | null = null;
    if (teamLeadId) {
      teamLead = await this.userRepository.findOne({
        where: { id: teamLeadId },
      });
      if (!teamLead) throw new BadRequestException('team lead does not exist');
    }

    const team = this.teamRepository.create({
      name: data.name,
      teamlead_id: teamLeadId ?? undefined,
      teamlead_external_id: teamLeadExternalId ?? teamLead?.local_id ?? null,
      team_lead: teamLead ?? undefined,
      department_id: data.department_id,
      created_by: data.created_by,
      createdBy_id: data.created_by?.id,
    } as DeepPartial<Team>);
    return this.teamRepository.save(team);
  }

  async update(
    id: string,
    data: Partial<{
      name: string;
      teamlead_id: string;
      teamlead_external_id: string;
      department_id: string;
    }>,
  ): Promise<Team> {
    const team = await this.teamRepository.findOne({
      where: { id, is_deleted: false },
      relations: ['tickets', 'team_lead', 'department'],
    });
    if (!team) throw new NotFoundException('Team with the given id Not Found');
    if (data.name != null) team.name = data.name;
    if (data.teamlead_id != null) {
      const teamLead = await this.userRepository.findOne({
        where: { id: data.teamlead_id },
      });
      if (!teamLead) throw new BadRequestException('team lead does not exist');
      team.teamlead_id = data.teamlead_id;
      team.team_lead = teamLead;
      team.teamlead_external_id = teamLead.local_id ?? null;
    } else if (data.teamlead_external_id != null) {
      team.teamlead_external_id = data.teamlead_external_id || null;
      if (data.teamlead_external_id) {
        const localLead = await this.userRepository.findOne({
          where: { local_id: data.teamlead_external_id },
        });
        if (localLead) {
          team.teamlead_id = localLead.id;
          team.team_lead = localLead;
        } else {
          team.teamlead_id = null;
          team.team_lead = null as unknown as User;
        }
      }
    }
    if (data.department_id != null) team.department_id = data.department_id;
    const result = await this.teamRepository.save(team);
    if (!result) throw new BadRequestException('Error team Updating');
    return this.findOne(id);
  }

  async remove(id: string): Promise<void> {
    const team = await this.teamRepository.findOne({
      where: { id, is_deleted: false },
    });
    if (!team)
      throw new NotFoundException('Team with the given id is not found.');
    await this.teamRepository.delete({ id });
  }
}

