    @Param('id') id: string,
    @Body() body: UpdateTicketPriorityDto,
  ) {
    if (!body.priority_id) {
      const data = await this.ticketService.findOne(id);
      return { status: 'Success', message: 'No priority_id provided', data };
    }
    const data = await this.ticketService.updatePriority(id, body.priority_id);
    return { status: 'Success', data };
  }

  @Patch('issue/change-issue-status/:issueId/:statusId')
  @UseGuards(PermissionsGuard)
  @RequirePermissions('update-ticket')
  async changeIssueStatus(
    @Param('issueId') issueId: string,
    @Param('statusId') statusId: string,
  ) {
    const data = await this.ticketService.changeIssueStatus(issueId, statusId);
    return { status: 'Success', data };
  }

  @Patch('issue/:issueId')
  @UseGuards(PermissionsGuard)
  @RequirePermissions('update-ticket')
  async updateIssueDetails(
    @Param('issueId') issueId: string,
    @Body() body: UpdateIssueDto,
  ) {
    const data = await this.ticketService.updateIssueDetails(issueId, body);
    return { status: 'Success', data };
  }

  @Post('tickets/save-image-referance-to-local-file')
  @HttpCode(HttpStatus.CREATED)
  @UseGuards(PermissionsGuard)
  @RequirePermissions('update-ticket')
  @UseInterceptors(FileInterceptor('upload_image', imageUploadOptions))
  saveImageToLocalFile(
    @UploadedFile() file: Express.Multer.File,
    @Req() req: { protocol?: string; get?: (name: string) => string },
    @Res({ passthrough: false }) res: Response,
  ): void {
    const base =
      req?.protocol && req?.get ? `${req.protocol}://${req.get('host')}` : '';
    const relative = file?.path ? toUploadRelativePath(file.path) : '';
    const imagePath = relative ? `${base}/api/v1/uploads/${relative}` : '';
    res.status(201).send(imagePath || '');
  }

  @Delete('tickets/delete-image-referance-from-local-file')
  @UseGuards(PermissionsGuard)
  @RequirePermissions('update-ticket')
  deleteImageFromLocalFile(
    @Body() body: DeleteImageDto,
    @Res({ passthrough: false }) res: Response,
  ): void {
    const urlPart = body?.imageUrl ?? '';
    const relative =
      urlPart.replace(/^.*\/api\/v1\/uploads\/?/i, '').replace(/\\/g, '/') ||
      urlPart;
    if (!relative) {
      res.status(404).send('Image not found');
      return;
    }
    const fullPath = join(UPLOADS_ROOT, relative);
    if (!fs.existsSync(fullPath)) {
      res.status(404).send('Image not found');
      return;
    }
    fs.unlinkSync(fullPath);
    res.status(200).send('Image deleted successfully');
  }
}

