  private async getTeamIdsForExternalUser(
    externalUserId: string,
    tenantId?: string,
  ): Promise<string[]> {
    const rows: Array<{ team_id: string }> = await this.ticketRepository.query(
      `
      SELECT team_id
      FROM team_member_external
      WHERE user_external_id = $1
        AND ($2::varchar IS NULL OR tenant_id = $2)
      `,
      [externalUserId, tenantId?.trim() || null],
    );
    return rows.map((row) => row.team_id);
  }

  private async shapeTicketsWithExternalAssignments(
    tickets: Ticket[],
  ): Promise<Ticket[]> {
    if (!tickets.length) return tickets;
    const ticketIds = tickets.map((t) => t.id);
    const rows: Array<{ ticket_id: string; user_external_id: string }> =
      await this.ticketRepository.query(
        `
      SELECT ticket_id, user_external_id
      FROM ticket_assignment_external
      WHERE ticket_id = ANY($1::uuid[])
        AND user_external_id IS NOT NULL
      `,
        [ticketIds],
      );
    const byTicket = new Map<string, string[]>();
    for (const row of rows) {
      const current = byTicket.get(row.ticket_id) ?? [];
      current.push(row.user_external_id);
      byTicket.set(row.ticket_id, current);
    }

    return tickets.map((ticket) => {
      const externalIds = byTicket.get(ticket.id) ?? [];
      if (!externalIds.length) return ticket;
      const shaped = ticket as unknown as Record<string, unknown>;
      shaped.assigned_users_legacy = shaped.assigned_users ?? [];
      shaped.assigned_users = [];
      shaped.assigned_user_external_ids = externalIds;
      return shaped as unknown as Ticket;
    });
  }

  async getTicketsByTeamAccess(
    externalUserId: string,
    statusId?: string,
    tenantId?: string,
  ): Promise<Ticket[]> {
    const teamIds = await this.getTeamIdsForExternalUser(
      externalUserId,
      tenantId,
    );
    if (!teamIds.length) throw new NotFoundException('userData does not exist');

    const qb = this.ticketRepository
      .createQueryBuilder('ticket')
      .leftJoinAndSelect('ticket.ticket_priority', 'ticket_priority')
      .leftJoinAndSelect('ticket.ticket_status', 'ticket_status')
      .leftJoinAndSelect('ticket.ticket_type', 'ticket_type')
      .leftJoinAndSelect('ticket.team', 'team')
      .leftJoinAndSelect('ticket.ticket_teams', 'ticket_teams')
      .leftJoinAndSelect('ticket_teams.team', 'ticket_team_team')
      .leftJoinAndSelect('ticket.assigned_users', 'assigned_users')
      .leftJoinAndSelect('ticket.client', 'client')
      .leftJoinAndSelect('ticket.company', 'company')
      .leftJoinAndSelect('ticket.comments', 'comments')
      .leftJoinAndSelect('ticket.issues', 'issues')
      .leftJoinAndSelect('issues.issue_teams', 'issues_issue_teams')
      .leftJoinAndSelect('issues_issue_teams.team', 'issues_team')
      .leftJoinAndSelect('issues.issue_agents', 'issues_issue_agents')
      .leftJoinAndSelect('issues_issue_agents.agent', 'issues_agent')
      .where('ticket.is_deleted = :is_deleted', { is_deleted: false })
      .andWhere(
        '(ticket.team_id IN (:...teamIds) OR ticket.id IN (SELECT tt.ticket_id FROM ticket_team tt WHERE tt.team_id IN (:...teamIds)))',
        { teamIds },
      );
    if (tenantId?.trim()) {
      qb.andWhere('ticket.tenant_id = :tenantId', {
        tenantId: tenantId.trim(),
      });
    }

    if (statusId?.trim()) {
      qb.andWhere('ticket.status_id = :statusId', {
        statusId: statusId.trim(),
      });
    }

    const tickets = await qb.orderBy('ticket.created_at', 'DESC').getMany();
    return this.shapeTicketsWithExternalAssignments(tickets);
  }

  async deleteAllTickets(): Promise<{ deletedTickets: number }> {
    const deletedTickets = await this.ticketRepository.count({
      where: { is_deleted: false },
    });

    await this.ticketRepository.manager.transaction(async (manager) => {
      await manager.query('DELETE FROM "issue_agents"');
      await manager.query('DELETE FROM "issue_team"');
      await manager.query('DELETE FROM "issues"');
      await manager.query('DELETE FROM "ticket_team"');
      await manager.query('DELETE FROM "ticket_user"');
      await manager.query('DELETE FROM "comment"');
      await manager.query('DELETE FROM "note"');
      await manager.query('DELETE FROM "notification"');
      await manager.query(
        'DELETE FROM "knowledge_base_comments" WHERE "knowledgeBaseId" IN (SELECT id FROM "knowledge_base" WHERE "ticketId" IS NOT NULL)',
      );
      await manager.query(
        'DELETE FROM "document" WHERE "knowledgeBaseId" IN (SELECT id FROM "knowledge_base" WHERE "ticketId" IS NOT NULL)',
      );
      await manager.query(
        'DELETE FROM "knowledge_base" WHERE "ticketId" IS NOT NULL',
      );
      await manager.query('DELETE FROM "ticket"');
      // Table may not exist in older databases.
      try {
        await manager.query('DELETE FROM "ticket_assignment_external"');
      } catch {
        // noop
      }
    });

    return { deletedTickets };
  }

