async getTicketsByTeamAccessPaginated(
  externalUserId: string,
  statusId: string | undefined,
  pagination: PaginationInput,
  tenantId?: string,
): Promise<{ data: Ticket[]; total: number }> {
  const teamIds = await this.getTeamIdsForExternalUser(
    externalUserId,
    tenantId,
  );
  if (!teamIds.length) throw new NotFoundException('userData does not exist');
  const { skip, take } = this.paginationService.getParams(pagination);

  const qb = this.ticketRepository
    .createQueryBuilder('ticket')
    .leftJoinAndSelect('ticket.ticket_priority', 'ticket_priority')
    .leftJoinAndSelect('ticket.ticket_status', 'ticket_status')
    .leftJoinAndSelect('ticket.ticket_type', 'ticket_type')
    .leftJoinAndSelect('ticket.team', 'team')
    .leftJoinAndSelect('ticket.ticket_teams', 'ticket_teams')
    .leftJoinAndSelect('ticket_teams.team', 'ticket_team_team')
    .leftJoinAndSelect('ticket.assigned_users', 'assigned_users')
    .leftJoinAndSelect('ticket.client', 'client')
    .leftJoinAndSelect('ticket.company', 'company')
    .leftJoinAndSelect('ticket.comments', 'comments')
    .leftJoinAndSelect('ticket.issues', 'issues')
    .leftJoinAndSelect('issues.issue_teams', 'issues_issue_teams')
    .leftJoinAndSelect('issues_issue_teams.team', 'issues_team')
    .leftJoinAndSelect('issues.issue_agents', 'issues_issue_agents')
    .leftJoinAndSelect('issues_issue_agents.agent', 'issues_agent')
    .where('ticket.is_deleted = :is_deleted', { is_deleted: false })
    .andWhere(
      '(ticket.team_id IN (:...teamIds) OR ticket.id IN (SELECT tt.ticket_id FROM ticket_team tt WHERE tt.team_id IN (:...teamIds)))',
      { teamIds },
    );
  if (tenantId?.trim()) {
    qb.andWhere('ticket.tenant_id = :tenantId', {
      tenantId: tenantId.trim(),
    });
  }

  if (statusId?.trim()) {
    qb.andWhere('ticket.status_id = :statusId', {
      statusId: statusId.trim(),
    });
  }

  qb.orderBy('ticket.created_at', 'DESC').skip(skip).take(take);
  const [data, total] = await qb.getManyAndCount();
  return {
    data: await this.shapeTicketsWithExternalAssignments(data),
    total,
  };
}

