/**
 * Generate ticket number string (matches Express generateTicketNumber).
 * Format: 000001/MM/DD/YYYY/INTERNAL|EXTERNAL/SubjectLabel
 */
private async generateTicketNumber(
  subjectLabel: string,
  isExternal = false,
): Promise<string> {
  const count = await this.ticketRepository.count();
  const formattedNumber = String(count + 1).padStart(6, '0');
  const dateStr = new Date().toLocaleDateString('en-US', {
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
  });
  const check = isExternal ? 'EXTERNAL' : 'INTERNAL';
  return `${formattedNumber}/${dateStr}/${check}/${subjectLabel ?? 'Ticket'}`;
}

async create(
  data: Omit<Partial<Ticket>, 'issues'> & {
    subject?: string;
    description?: string;
    type_id?: string;
    support_id?: string;
    project_id?: string;
    client_id?: string;
    client_external_id?: string;
    company_id?: string;
    expectedEndDate?: string;
    tenant_id?: string;
    issues?: Array<{
      name?: string;
      description?: string;
      expectedEndDate?: string;
    }>;
    team_ids?: string[];
  },
  actor: {
    userId?: string;
    externalUserId?: string;
    tenantId?: string;
  },
): Promise<Ticket> {
  const openStatus = await this.statusService.findByType('Open');
  const typeId = data.type_id;
  if (!typeId) {
    throw new NotFoundException('type_id is required');
  }
  await this.typeService.findOne(typeId);

  let companyId: string | undefined = data.company_id;
  if (data.client_id && !companyId) {
    const client = await this.userRepository.findOne({
      where: { id: data.client_id },
      relations: ['company'],
    });
    if (client?.company?.id) {
      companyId = client.company.id;
    }
  }

  const subject = await this.generateTicketNumber(
    data.subject ?? 'Ticket',
    false,
  );

  const ticket = this.ticketRepository.create({
    id: randomUUID(),
    subject,
    description: data.description ?? undefined,
    status_id: openStatus.id,
    type_id: typeId,
    client_id: data.client_id ?? actor.userId,
    client_external_id:
      data.client_external_id ?? actor.externalUserId ?? null,
    company_id: companyId ?? undefined,
    created_by: actor.userId,
    created_by_external_id: actor.externalUserId ?? null,
    tenant_id: data.tenant_id ?? actor.tenantId ?? null,
    project_id: data.project_id ?? undefined,
    support_id: data.support_id ?? undefined,
    expectedEndDate:
      data.expectedEndDate != null && data.expectedEndDate !== ''
        ? String(data.expectedEndDate)
        : undefined,
  });

  const saved = await this.ticketRepository.save(ticket);

  const teamIds = data.team_ids ?? [];
  if (teamIds.length > 0) {
    const ticketTeams = teamIds.map((team_id: string) =>
      this.ticketTeamRepository.create({
        ticket_id: saved.id,
        team_id,
      }),
    );
    await this.ticketTeamRepository.save(ticketTeams);
  }

  const issues = Array.isArray(data.issues) ? data.issues : [];
  if (issues.length > 0) {
    await this.issuesService.createForTicket(saved.id, openStatus.id, issues);
  }

  return this.findOne(saved.id);
}

async update(
  id: string,
  data: Partial<Omit<Ticket, 'due_date'>> & {
    due_date?: string | Date;
    ticket_team_ids?: string[];
  },
): Promise<Ticket> {
  const existing = await this.ticketRepository.findOne({
    where: { id, is_deleted: false },
  });
  if (!existing)
    throw new NotFoundException('Ticket with the given id not found');

  const updatePayload: Record<string, unknown> = {};
  const scalarKeys = [
    'subject',
    'description',
    'priority_id',
    'status_id',
    'type_id',
    'team_id',
    'client_id',
    'expectedEndDate',
    'project_id',
    'support_id',
  ] as const;
  for (const key of scalarKeys) {
    if ((data as Record<string, unknown>)[key] !== undefined)
      updatePayload[key] = (data as Record<string, unknown>)[key];
  }
  if (data.due_date !== undefined)
    updatePayload.due_date =
      typeof data.due_date === 'string'
        ? new Date(data.due_date)
        : data.due_date;
  if (data.closed !== undefined) updatePayload.closed = data.closed;

  if (data.status_id !== undefined) {
    const status = await this.statusService.findOne(data.status_id);
    updatePayload.closed = status.type === 'Closed';
  }

  if (Object.keys(updatePayload).length > 0) {
    await this.ticketRepository.update(id, updatePayload);
  }

  const ticket_team_ids = data.ticket_team_ids;
  if (Array.isArray(ticket_team_ids)) {
    const existingLinks = await this.ticketTeamRepository.find({
      where: { ticket_id: id },
      relations: ['team'],
    });
    const existingIds = existingLinks.map((l) => l.team_id);
    const toAdd = ticket_team_ids.filter((tid) => !existingIds.includes(tid));

    const toAdd = ticket_team_ids.filter((tid) => !existingIds.includes(tid));
    const toRemove = existingLinks.filter(
      (l) => !ticket_team_ids.includes(l.team_id),
    );
    for (const rel of toRemove) {
      await this.ticketTeamRepository.remove(rel);
    }
    for (const team_id of toAdd) {
      await this.ticketTeamRepository.save(
        this.ticketTeamRepository.create({ ticket_id: id, team_id }),
      );
    }
  }

  return this.findOne(id);
}

