/** Filter tickets by priority, status, type, department (team_id). */
async applyFilter(query: {
  priority?: string;
  status?: string;
  type?: string;
  department?: string;
}): Promise<Ticket[]> {
  const qb = this.ticketRepository
    .createQueryBuilder('ticket')
    .leftJoinAndSelect('ticket.ticket_priority', 'priority')
    .leftJoinAndSelect('ticket.ticket_status', 'status')
    .leftJoinAndSelect('ticket.ticket_type', 'type')
    .leftJoinAndSelect('ticket.team', 'team')
    .leftJoinAndSelect('ticket.ticket_teams', 'ticket_teams')
    .leftJoinAndSelect('ticket_teams.team', 'ticket_team_team')
    .leftJoinAndSelect('ticket.assigned_users', 'users')
    .leftJoinAndSelect('ticket.client', 'client')
    .leftJoinAndSelect('ticket.company', 'company')
    .leftJoinAndSelect('ticket.comments', 'comments')
    .leftJoinAndSelect('ticket.issues', 'issues')
    .leftJoinAndSelect('issues.issue_teams', 'issue_teams')
    .leftJoinAndSelect('issue_teams.team', 'issue_team_team')
    .leftJoinAndSelect('issues.issue_agents', 'issue_agents')
    .leftJoinAndSelect('issue_agents.agent', 'issue_agent_user')
    .where('ticket.is_deleted = :is_deleted', { is_deleted: false });

  if (query.priority) {
    try {
      await this.priorityService.findOne(query.priority);
    } catch {
      throw new NotFoundException('no such priority');
    }
    qb.andWhere('ticket.priority_id = :priority', {
      priority: query.priority,
    });
  }
  if (query.status) {
    try {
      await this.statusService.findOne(query.status);
    } catch {
      throw new NotFoundException('no such status');
    }
    qb.andWhere('ticket.status_id = :status', { status: query.status });
  }
  if (query.type) {
    try {
      await this.typeService.findOne(query.type);
    } catch {
      throw new NotFoundException('no such ticket type');
    }
    qb.andWhere('ticket.type_id = :type', { type: query.type });
  }
  if (query.department) {
    try {
      await this.departmentService.findOne(query.department);
    } catch {
      throw new NotFoundException('no such department');
    }
    qb.andWhere('ticket.team_id = :department', {
      department: query.department,
    });
  }
  const tickets = await qb.orderBy('ticket.created_at', 'DESC').getMany();
  return this.shapeTicketsWithExternalAssignments(tickets);
}

