/** Assign users to ticket (append to assigned_users). */
async assignUserToTicket(
  ticketId: string,
  userExternalIds: string[],
  tenantId?: string,
): Promise<string[]> {
  const ticket = await this.ticketRepository.findOne({
    where: { id: ticketId, is_deleted: false },
  });
  if (!ticket) throw new NotFoundException('ticket does not exist');
  const normalized = userExternalIds.map((u) => u.trim()).filter(Boolean);
  if (!normalized.length) return [];

  const existingRows: Array<{ user_external_id: string | null }> =
    await this.ticketRepository.query(
      `
    SELECT user_external_id
    FROM ticket_assignment_external
    WHERE ticket_id = $1
      AND user_external_id IS NOT NULL
    `,
      [ticketId],
    );
  const existingSet = new Set(
    existingRows.map((r) => r.user_external_id ?? '').filter(Boolean),
  );

  for (const externalId of normalized) {
    if (existingSet.has(externalId)) continue;
    await this.ticketRepository.query(
      `
      INSERT INTO ticket_assignment_external (ticket_id, user_external_id, tenant_id)
      VALUES ($1, $2, $3)
      `,
      [ticketId, externalId, tenantId ?? null],
    );
  }

  const rows: Array<{ user_external_id: string }> =
    await this.ticketRepository.query(
      `
    SELECT user_external_id
    FROM ticket_assignment_external
    WHERE ticket_id = $1
      AND user_external_id IS NOT NULL
    `,
      [ticketId],
    );
  return rows.map((r) => r.user_external_id);
}

