/** Ticket counts by status (raw group by). */
async getTicketsByStatus(): Promise<
  Array<{ statusId: string; statusType: string; ticketCount: string }>
> {
  const rows = await this.ticketRepository
    .createQueryBuilder('ticket')
    .leftJoin('ticket.ticket_status', 'status')
    .select('status.id', 'statusId')
    .addSelect('status.type', 'statusType')
    .addSelect('COUNT(ticket.id)', 'ticketCount')
    .where('ticket.is_deleted = :v', { v: false })
    .groupBy('status.id')
    .addGroupBy('status.type')
    .getRawMany();
  return rows as Array<{
    statusId: string;
    statusType: string;
    ticketCount: string;
  }>;
}

