  tenantId?: string,
): Promise<Ticket[]> {
  const qb = this.ticketRepository
    .createQueryBuilder('ticket')
    .innerJoin(
      'ticket_assignment_external',
      'tu',
      'tu.ticket_id = ticket.id AND tu.user_external_id = :userExternalId',
      { userExternalId },
    )
    .leftJoinAndSelect('ticket.ticket_status', 'status')
    .leftJoinAndSelect('ticket.ticket_type', 'type')
    .leftJoinAndSelect('ticket.ticket_priority', 'priority')
    .where('ticket.is_deleted = :v', { v: false });
