/** Agent status for a team: members and their ticket counts by status. */

/** Agent status for a team: members and their ticket counts by status. */
async getAgentStatusForTeamById(teamId: string): Promise<
  Array<{
    total: number;
    userExternalId?: string;
    [statusType: string]: number | string | undefined;
  }>
> {
  const rows: Array<{
    user_external_id: string;
    status_type: string | null;
    count: number;
  }> = await this.ticketRepository.query(
    `
    SELECT tu.user_external_id, s.type AS status_type, COUNT(*)::int AS count
    FROM ticket_assignment_external tu
    JOIN ticket t ON t.id = tu.ticket_id
    LEFT JOIN status s ON s.id = t.status_id
    WHERE t.is_deleted = false
      AND (
        t.team_id = $1
        OR t.id IN (SELECT tt.ticket_id FROM ticket_team tt WHERE tt.team_id = $1)
      )
      AND tu.user_external_id IS NOT NULL
    GROUP BY tu.user_external_id, s.type
    `,
    [teamId],
  );

  const grouped: Record<string, Record<string, number | string>> = {};
  for (const row of rows) {
    const key = row.user_external_id;
    if (!grouped[key]) grouped[key] = { total: 0, userExternalId: key };
    grouped[key].total = (grouped[key].total as number) + Number(row.count);
    const statusType = row.status_type ?? 'Unknown';
    grouped[key][statusType] =
      ((grouped[key][statusType] as number) ?? 0) + Number(row.count);
  }
  return Object.values(grouped) as Array<{
    total: number;
    userExternalId?: string;
    [statusType: string]: number | string | undefined;
  }>;
}

/** All teams' ticket counts by status. */
async getAllAgentStatus(): Promise<
  Array<{
    total: number;
    teamName?: string;
    tickets?: Ticket[];
    [key: string]: number | string | Ticket[] | undefined;
  }>
> {
  const tickets = await this.ticketRepository.find({
    where: { is_deleted: false },
    relations: ['team', 'ticket_status'],
    order: { created_at: 'DESC' },
  });
  const byTeam: Record<string, Ticket[]> = {};
  for (const t of tickets) {
    const name = t.team?.name ?? 'Unassigned';
    if (!byTeam[name]) byTeam[name] = [];
    byTeam[name].push(t);
  }
  return Object.entries(byTeam).map(([teamName, list]) => {
    const count: {
      total: number;
      teamName?: string;
      tickets?: Ticket[];
      [key: string]: number | string | Ticket[] | undefined;
    } = {
      total: list.length,
      teamName,
      tickets: list,
    };
    for (const t of list) {
      const type = t.ticket_status?.type ?? 'Unknown';
      count[type] = ((count[type] as number) ?? 0) + 1;
    }
    return count;
  });
}

/** Close ticket by id: set status to Closed, closed=true, and email client if available. */
async closeTicketById(
  ticketId: string,
  _fromEmail?: string,
): Promise<Ticket> {
  const closedStatus = await this.statusService.findByType('Closed');
  const ticket = await this.findOne(ticketId);
  const clientEmail = ticket.client?.email;
  return this.closeTicketWithStatus(
    ticketId,
    closedStatus.id,
    _fromEmail,
    clientEmail,
  );
}

/** Close ticket: set status to Closed and closed=true; optionally email client. */
async closeTicketWithStatus(
  ticketId: string,
  closedStatusId: string,
  fromEmail?: string,
  clientEmail?: string,
): Promise<Ticket> {
  const ticket = await this.findOne(ticketId);
  ticket.status_id = closedStatusId;
  ticket.closed = true;
  await this.ticketRepository.save(ticket);
  if (fromEmail && clientEmail && this.emailService.isConfigured()) {
    await this.emailService.send({
      to: clientEmail,
      subject: 'Ticket Notification',
      html: 'Dear client, Your ticket is closed successfully',
    });
  }
  return this.findOne(ticketId);
}

/** Set close requested flag and notify admins (notification creation can be done by controller). */
