/** Tickets for current user by project/support and grouped (simplified). */
async getAllTicketsForCurrentLoggedInUser(
  userId: string,
  externalUserId: string | undefined,
  tenantId: string | undefined,
  body: { projectId?: string; supportId?: string },
): Promise<{
  userTicket: Ticket[];
  listOfTicketsByAgent: Ticket[];
  groupedTeam: Array<{ teamName: string; tickets: Ticket[] }>;
  unAssignedTickets: { teamAssigned: Ticket[]; unAssigned: Ticket[] };
  AssignedTickets: Ticket[];
}> {

}> {
  let filtered = await this.findAll();
  if (tenantId?.trim()) {
    filtered = filtered.filter((t) => t.tenant_id === tenantId);
  }
  if (body.projectId)
    filtered = filtered.filter((t) => t.project_id === body.projectId);
  if (body.supportId)
    filtered = filtered.filter((t) => t.support_id === body.supportId);

  const userCreated = filtered.filter(
    (t) =>
      t.created_by === userId ||
      (!!externalUserId && t.created_by_external_id === externalUserId),
  );
  const byTeam: Record<string, Ticket[]> = {};
  for (const t of filtered) {
    const name = t.team?.name ?? 'Unassigned';
    if (!byTeam[name]) byTeam[name] = [];
    byTeam[name].push(t);
  }
  const groupedTeam = Object.entries(byTeam).map(([teamName, list]) => ({
    teamName,
    tickets: list,
  }));
  const assigned = filtered.filter((t) => t.assigned_users?.length);
  const teamOnly = filtered.filter(
    (t) => t.team && (!t.assigned_users || !t.assigned_users.length),
  );
  const unAssigned = filtered.filter(
    (t) => !t.team && (!t.assigned_users || !t.assigned_users.length),
  );

  const userAssignedTickets = externalUserId
    ? await this.getAssignedTickets(externalUserId, tenantId)
    : [];
  const listOfTicketsByAgent = userAssignedTickets as unknown as Ticket[];

  return {
    userTicket: userCreated,
    listOfTicketsByAgent,
    groupedTeam,
    unAssignedTickets: { teamAssigned: teamOnly, unAssigned },
    AssignedTickets: assigned,
  };
}

/** Tickets by project id for current user. */
async getAllTicketsForCurrentLoggedInUserByProjectId(
  projectId: string,
  userId: string,
  externalUserId?: string,
  tenantId?: string,
  principalRole?: string,
): Promise<{
  userTicket: Ticket[];
  listOfTicketsByAgent: Ticket[];
  groupedTeam: Array<{ teamName: string; tickets: Ticket[] }>;
  unAssignedTickets: Ticket[] | undefined;
}> {
  const tickets = await this.ticketRepository.find({
    where: {
      project_id: projectId,
      is_deleted: false,
      ...(tenantId?.trim() ? { tenant_id: tenantId.trim() } : {}),
    },
    relations: [
      'team',
      'ticket_teams',
      'ticket_teams.team',
      'assigned_users',
      'ticket_status',
      'created_by_user',
      'issues',
      'issues.issue_teams',
      'issues.issue_teams.team',
      'issues.issue_agents',
      'issues.issue_agents.agent',
    ],
    order: { created_at: 'DESC' },
  });
  const userTicket = tickets.filter(
    (t) =>
      t.created_by === userId ||
      (!!externalUserId && t.created_by_external_id === externalUserId),
  );
  const listOfTicketsByAgent = externalUserId
    ? ((await this.getAssignedTickets(
        externalUserId,
        tenantId,
      )) as unknown as Ticket[])
    : [];
  const byTeam: Record<string, Ticket[]> = {};
  for (const t of tickets) {
    const name = t.team?.name ?? 'Unassigned';
    if (!byTeam[name]) byTeam[name] = [];
    byTeam[name].push(t);
  }
  const groupedTeam = Object.entries(byTeam).map(([teamName, list]) => ({
    teamName,
    tickets: list,
  }));
  let unAssignedTickets: Ticket[] | undefined;
  const roleName = principalRole;
  if (['Admin', 'Manager', 'Director', 'CEO'].includes(roleName ?? '')) {
    unAssignedTickets = tickets.filter((t) => !t.team);
  } else if (roleName === 'team-lead') {
    unAssignedTickets = tickets.filter((t) => !t.assigned_users?.length);
  }
  return { userTicket, listOfTicketsByAgent, groupedTeam, unAssignedTickets };
}

/** Assign agent(s) to issue. Persists to issue_agents table (matches Express). */
async assignIssueToAgent(
  issueId: string,
  agentIds: string[],
): Promise<Ticket> {
  const issue = await this.issuesService.findOne(issueId);
  await this.issueAgentRepository.delete({ issue_id: issueId });
  if (agentIds?.length) {
    const relations = agentIds.map((agent_id) =>
      this.issueAgentRepository.create({ issue_id: issueId, agent_id }),
    );
    await this.issueAgentRepository.save(relations);
    await this.issuesService.update(issueId, { agentId: agentIds[0] });
  }
  return this.findOne(issue.ticketId);
}

/** Change issue status. */
async changeIssueStatus(issueId: string, statusId: string): Promise<Ticket> {
  const issue = await this.issuesService.findOne(issueId);
  const status = await this.statusService.findOne(statusId);
  await this.issuesService.update(issueId, {
    statusId,
    isClosed: status.type === 'Closed',
  });
  return this.findOne(issue.ticketId);
}

/** Update issue details (name, description). */
async updateIssueDetails(
  issueId: string,
  data: { name?: string; description?: string },
): Promise<Ticket> {
  await this.issuesService.findOne(issueId);
  await this.issuesService.update(issueId, data);
  const issue = await this.issuesService.findOne(issueId);
  return this.findOne(issue.ticketId);
}

/** Get all escalated tickets (status type Escalet). */
async getAllEscalates(): Promise<Ticket[]> {
  const status = await this.statusService
    .findByType('Escalet')
    .catch(() => null);
  if (!status) return [];

    if (!status) return [];
    const tickets = await this.ticketRepository.find({
      where: { status_id: status.id, is_deleted: false },
      relations: ['ticket_status', 'team', 'client', 'assigned_users'],
    });
    return this.shapeTicketsWithExternalAssignments(tickets);
  }
}

