import { Injectable, NotFoundException } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Todo } from './todo.entity';

@Injectable()
export class TodoService {
  constructor(
    @InjectRepository(Todo)
    private readonly todoRepository: Repository<Todo>,
  ) {}

  async findAll(): Promise<Todo[]> {
    const todos = await this.todoRepository.find({ relations: ['user'] });
    if (!todos) throw new NotFoundException('No todo data found');
    return todos;
  }

  async findOne(id: string): Promise<Todo> {
    const todo = await this.todoRepository.findOne({
      where: { id },
      relations: ['user'],
    });
    if (!todo) throw new NotFoundException('Todo with the given id not found');
    return todo;
  }

  async create(data: Partial<Todo> & { user_id: string }): Promise<Todo> {
    const todo = this.todoRepository.create({
      ...data,
      user_id: data.user_id,
    });
    return this.todoRepository.save(todo);
  }

  async update(id: string, data: Partial<Todo>): Promise<Todo> {
    const todo = await this.findOne(id);
    this.todoRepository.merge(todo, data);
    return this.todoRepository.save(todo);
  }

  async remove(id: string): Promise<void> {
    await this.findOne(id);
    await this.todoRepository.delete({ id });
  }
}

