import { Injectable, NotFoundException } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Type } from './type.entity';

@Injectable()
export class TypeService {
  constructor(
    @InjectRepository(Type)
    private readonly typeRepository: Repository<Type>,
  ) {}

  async findAll(): Promise<Type[]> {
    return this.typeRepository.find({ where: { is_deleted: false } });
  }

  async findOne(id: string): Promise<Type> {
    const type = await this.typeRepository.findOne({
      where: { id, is_deleted: false },
    });
    if (!type) throw new NotFoundException('Type does not exist');
    return type;
  }

  async create(data: Partial<Type>): Promise<Type> {
    const entity = this.typeRepository.create(data);
    return this.typeRepository.save(entity);
  }

  async update(id: string, data: Partial<Type>): Promise<Type> {
    const entity = await this.typeRepository.findOne({ where: { id } });
    if (!entity) throw new NotFoundException('Type Does Not Exist!');
    Object.assign(entity, data);
    return this.typeRepository.save(entity);
  }

  async remove(id: string): Promise<void> {
    const type = await this.typeRepository.findOne({ where: { id } });
    if (!type) throw new NotFoundException('Type Does Not Exist!');
    await this.typeRepository.delete({ id });
  }

  /** Returns deleted types to match Express deleteAllTypes response. */
  async removeAll(): Promise<Type[]> {
    const list = await this.typeRepository.find();
    await this.typeRepository.clear();
    return list;
  }
}

