/** Normalize team IDs from body (form may send string or array). */

/** Normalize team IDs from body (form may send string or array). */
function normalizeTeamIds(value: string | string[] | undefined): string[] {
  if (value == null) return [];
  if (Array.isArray(value)) return value.filter(Boolean);
  if (typeof value !== 'string') return [];
  try {
    const parsed = JSON.parse(value) as unknown;
    return Array.isArray(parsed)
      ? parsed.filter((id): id is string => typeof id === 'string')
      : [];
  } catch {
    return value
      .split(',')
      .map((s) => s.trim())
      .filter(Boolean);
  }
}

@Controller('users')
export class UserController {
  constructor(private readonly userService: UserService) {}

  @Get()
  @UseGuards(AuthGuard, PermissionsGuard)
  @RequirePermissions('view-user')
  async getAll(
    @CurrentUser() user: AuthenticatedPrincipal,
    @Query('page') page?: string,
    @Query('limit') limit?: string,
  ) {
    const pageNumber = page ? parseInt(page, 10) : 1;
    const limitNumber = limit ? parseInt(limit, 10) : 50;
    const { data, total } = await this.userService.findEmployeesPaginated(
      pageNumber,
      limitNumber,
      user.tenant_id ?? user.tenantId ?? undefined,
    );
    return {
      status: 'Success',
      data,
      meta: {
        page: Number.isFinite(pageNumber) && pageNumber > 0 ? pageNumber : 1,
        limit:
          Number.isFinite(limitNumber) && limitNumber > 0
            ? Math.min(limitNumber, 1000)
            : 50,
        total,
      },
    };
  }

  @Get('user-data')
  @UseGuards(AuthGuard)
  getLoggedUserData(@CurrentUser() user: User) {
    if (!user) throw new NotFoundException('user does not exist');
    return { status: 'Success', data: user };
  }

  @Get('me/settings')
  @UseGuards(AuthGuard)
  async getMySettings(@CurrentUser() user: User) {
    const data = await this.userService.getMySettings(user.id);
    return { status: 'Success', data };
  }

  @Get('get-all-agents/for-a-single-team/:id')
  @UseGuards(AuthGuard, PermissionsGuard)
  @RequirePermissions('view-team-agents')
  async getAllAgents(@Param('id') id: string) {
    const data = await this.userService.getAllAgentsForTeamByUserId(id);
    return { status: 'Success', data };
  }

  @Get('firebase/:localId')
  @UseGuards(AuthGuard)
  async getByFirebaseLocalId(@Param('localId') localId: string) {
    const data = await this.userService.findByFirebaseLocalId(localId);
    if (!data) throw new NotFoundException('user does not exist');
    return { status: 'Success', data };
  }

  @Get(':id')
  @UseGuards(AuthGuard, PermissionsGuard)
  @RequirePermissions('view-user')
  async getOne(@Param('id') id: string) {
    const data = await this.userService.findOne(id);
    return { status: 'Success', data };
  }

  @Post()
  @UseGuards(AuthGuard, PermissionsGuard)
  @RequirePermissions('create-user')
  @UseInterceptors(FileInterceptor('profile_pic', imageUploadOptions))
  async create(
    @Body() body: CreateUserDto,
    @UploadedFile() file: Express.Multer.File,
    @CurrentUser() currentUser?: User,
  ) {
    const profile_pic = file?.path
      ? toUploadRelativePath(file.path)
      : undefined;
    const teams = normalizeTeamIds(body.teams ?? body.team_id_list);
    const data = await this.userService.create({
      ...body,
      teams: teams.length ? teams : undefined,
      profile_pic,
      created_by: currentUser?.id,
    });
    return { status: 'Success', data };
  }

  @Patch(':id')
  @UseGuards(AuthGuard, PermissionsGuard)
  @RequirePermissions('update-user')
  @UseInterceptors(FileInterceptor('profile_pic', imageUploadOptions))
  async edit(
    @Param('id') id: string,
    @Body()
    body: Partial<{
      first_name: string;
      last_name: string;
      phone_number: string;
      role_id: string;
      team_id: string;
      team_id_list: string[];
    }>,
    @UploadedFile() file: Express.Multer.File,
  ) {
    const payload = { ...body };
    if (file?.path)
      (payload as { profile_pic?: string }).profile_pic = toUploadRelativePath(
        file.path,
      );
    const data = await this.userService.update(id, payload);
    return { status: 'Success', data };
  }

  @Patch('me/profile')
  @UseGuards(AuthGuard)
  @UseInterceptors(FileInterceptor('profile_pic', imageUploadOptions))
  async updateMyProfile(
    @CurrentUser() user: User,
    @Body() body: UpdateMyProfileDto,
    @UploadedFile() file: Express.Multer.File,
  ) {
    const payload = { ...body };
    if (file?.path) {
      payload.profile_pic = toUploadRelativePath(file.path);
    }
    const data = await this.userService.updateMyProfile(user.id, payload);
    return { status: 'Success', data };
  }

  @Patch('change-password/:id')
  @UseGuards(AuthGuard)

  @UseGuards(AuthGuard)
  async changePassword(
    @Param('id') id: string,
    @Body() body: ChangePasswordDto,
    @CurrentUser() currentUser: User,
  ) {
    const roleName = currentUser.role?.roleName;
    const data = await this.userService.changePassword(
      id,
      currentUser.id,
      roleName,
      body.old_password,
      body.password,
    );
    return { status: 'Success', data };
  }

  @Delete(':id')
  @UseGuards(AuthGuard, PermissionsGuard)
  @RequirePermissions('delete-user')
  async delete(@Param('id') id: string) {
    await this.userService.remove(id);
    return { status: 'Success', message: 'User is successfully deleted' };
  }

  @Delete('deleteAllUsers/:id')
  @UseGuards(AuthGuard, PermissionsGuard)
  @RequirePermissions('delete-users')
  async deleteAll(@Param('id') id: string) {
    void id; // route segment required for Express compatibility
    const data = await this.userService.removeAll();
    return { status: 'Success', data };
  }

  @Post('login')
