    const { user, token } = await this.userService.login(
      body.email,
      body.password,
    );
    return { status: 'Success', data: { user, token } };
  }

  @Post('logout')
  @UseGuards(AuthGuard)
  logout() {
    return {
      status: 'success',
      message: 'User is successfully logout',
      statusCode: 200,
    };
  }

  @Post('resetPassword')
  @UseGuards(AuthGuard, PermissionsGuard)
  @RequirePermissions('reset-user-password')
  async resetPassword(@Body() body: ResetPasswordDto) {
    const data = await this.userService.resetPassword(body.email);
    return { status: 'Success', data };
  }

  @Post('forgotPassword')
  @UseGuards(AuthGuard, PermissionsGuard)
  @RequirePermissions('forget-user-password')
  async forgotPassword(@Body() body: ForgotPasswordDto) {
    const data = await this.userService.forgotPassword(body.email);
    return { status: 'Success', data };
  }

  @Post('team-access/:id')
  @UseGuards(AuthGuard, PermissionsGuard)
  @RequirePermissions('team-access')
  async teamAccess(@Param('id') id: string, @Body() body: TeamAccessDto) {
    const data = await this.userService.teamAccess(id, body.teams);
    return { status: 'Success', data };
  }

  @Post('sendChangePasswordAlertByEmail')
  @UseGuards(AuthGuard, PermissionsGuard)
  @RequirePermissions('send-change-password-request')
  async sendChangePasswordAlertByEmail(@CurrentUser() user: User) {
    const data = await this.userService.sendChangePasswordAlertByEmail(
      user.email,
    );
    return { status: 'Success', data };
  }

  @Patch('sendChangePasswordRequest/:id')
  @UseGuards(AuthGuard, PermissionsGuard)
