export enum UserType {
  Client = 'client',
  Employee = 'employee',
}

@Entity('user')
export class User {
  @PrimaryGeneratedColumn('uuid')
  id: string;

  @Column({ type: 'varchar', nullable: true, name: 'first_name' })
  first_name: string;

  @Column({ type: 'varchar', nullable: true, name: 'last_name' })
  last_name: string;

  @Column({ type: 'varchar', unique: true })
  email: string;

  @Column({ type: 'varchar', nullable: true })
  password: string;

  @Column({ type: 'varchar', nullable: true, name: 'phone_number' })
  phone_number: string;

  @Column({ type: 'varchar', nullable: true, name: 'profile_pic' })
  profile_pic: string;

  @Column({ type: 'varchar', nullable: true, name: 'manager_id' })
  manager_id: string;

  @Column({ type: 'boolean', default: false, name: 'is_deleted' })
  is_deleted: boolean;

  @Column({
    type: 'enum',
    enum: UserType,
    default: UserType.Client,
    name: 'user_type',
  })
  user_type: UserType;

  @Column({ type: 'boolean', default: false, name: 'password_changed' })
  password_changed: boolean;

  @Column({ type: 'varchar', nullable: true })
  verificationCode: string | null;

  @Column({ type: 'varchar', nullable: true })
  passwordChangeToken: string | null;

  @Column({ type: 'bigint', nullable: true, name: 'tokenExpirationTime' })
  tokenExpirationTime: string | null;

  @CreateDateColumn({ name: 'created_at' })
  created_at: Date;

  @UpdateDateColumn({ name: 'updated_at' })
  updated_at: Date;

  @Column({ type: 'uuid', nullable: true, name: 'role_id' })
  role_id: string;

  @Column({ type: 'uuid', nullable: true, name: 'companyId' })
  company_id: string;

  @Column({ type: 'uuid', nullable: true, name: 'team_id' })
  team_id: string;

  @Column({ type: 'uuid', nullable: true, name: 'type_id' })
  type_id: string;

  @Column({ type: 'uuid', nullable: true, name: 'priority_id' })
  priority_id: string;

  @Column({ type: 'uuid', nullable: true, name: 'status_id' })
  status_id: string;

  @Column({ type: 'uuid', nullable: true, name: 'created_by' })
  created_by: string;

  @Column({ type: 'varchar', nullable: true, name: 'local_id' })
  local_id: string | null;

  @Column({ type: 'varchar', nullable: true, name: 'tenant_id' })
  tenant_id: string | null;

  @ManyToOne(() => Role, (role) => role.users)
  @JoinColumn({ name: 'role_id' })
