  @ManyToOne(() => Company, (company) => company.clients)
  @JoinColumn({ name: 'companyId' })
  company: Company;

  @ManyToOne(() => Team)
  @JoinColumn({ name: 'team_id' })
  team: Team;

  @ManyToOne(() => Type)
  @JoinColumn({ name: 'type_id' })
  ticket_type: Type;

  @ManyToOne(() => Department)
  @JoinColumn({ name: 'priority_id' })
