import {
  Injectable,
  NotFoundException,
  BadRequestException,
  ForbiddenException,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository, In, DeepPartial } from 'typeorm';
import { JwtService } from '@nestjs/jwt';
import { User, UserType } from './user.entity';
import { CryptoService } from '../common/services/crypto.service';
import { EmailService } from '../common/services/email.service';
import { generateRandomPassword } from '../common/utils/random-password.util';
import {
  generateVerificationCode,
  checkVerificationCode as checkCode,
} from '../common/utils/verification-code.util';
import { AppConfigService } from '../common/config/app-config.service';
import { RoleService } from '../role/role.service';
import { Team } from '../team/team.entity';
import { CreateUserDto } from './dto/create-user.dto';
import { UpdateMyProfileDto } from './dto/update-my-profile.dto';

export type CreateUserData = CreateUserDto & {
  teams?: string[];
  profile_pic?: string;
  created_by?: string;
};

@Injectable()
export class UserService {
  constructor(
    @InjectRepository(User)
    private readonly userRepository: Repository<User>,
    @InjectRepository(Team)
    private readonly teamRepository: Repository<Team>,
    private readonly jwtService: JwtService,
    private readonly crypto: CryptoService,
    private readonly emailService: EmailService,
    private readonly roleService: RoleService,
    private readonly appConfig: AppConfigService,
  ) {}

  private async syncExternalTeamAccess(
    localId: string | null | undefined,
    tenantId: string | null | undefined,
    teamIds: string[],
  ): Promise<void> {
    if (!localId?.trim()) return;
    await this.userRepository.query(
      `
      DELETE FROM team_member_external
      WHERE user_external_id = $1
        AND ($2::varchar IS NULL OR tenant_id = $2)
      `,
      [localId.trim(), tenantId?.trim() || null],
    );
    for (const teamId of teamIds) {
      await this.userRepository.query(
        `
        INSERT INTO team_member_external (team_id, user_external_id, tenant_id)
        VALUES ($1, $2, $3)
        ON CONFLICT (team_id, user_external_id) DO UPDATE SET tenant_id = EXCLUDED.tenant_id
        `,
        [teamId, localId.trim(), tenantId?.trim() || null],
      );
    }
  }

  async findAll(): Promise<Partial<User>[]> {
    return this.userRepository.find({
      select: [
        'id',
        'first_name',
        'last_name',
        'email',
        'user_type',
        'profile_pic',
        'phone_number',
      ],
      relations: [
        'team',
        'manager',
        'role',
        'role.permissions',
        'teams_access',
      ],
    });
  }

  async findEmployeesPaginated(
    page: number,
    limit: number,
    tenantId?: string,
  ): Promise<{ data: Partial<User>[]; total: number }> {
    const safePage = Number.isFinite(page) && page > 0 ? page : 1;
    const safeLimit =
      Number.isFinite(limit) && limit > 0 ? Math.min(limit, 1000) : 50;
    const skip = (safePage - 1) * safeLimit;

    const qb = this.userRepository
      .createQueryBuilder('u')
      .leftJoinAndSelect('u.role', 'role')
      .where('u.is_deleted = :isDeleted', { isDeleted: false })
      .andWhere('u.user_type = :userType', { userType: UserType.Employee })
      .orderBy('u.created_at', 'DESC')
      .skip(skip)
      .take(safeLimit);

    if (tenantId?.trim()) {
      qb.andWhere('u.tenant_id = :tenantId', { tenantId: tenantId.trim() });
    }

    qb.select([
      'u.id',
      'u.first_name',
      'u.last_name',
      'u.email',
      'u.user_type',
      'u.profile_pic',
      'u.phone_number',
      'u.local_id',
      'u.tenant_id',
      'u.created_at',
      'role.id',
      'role.roleName',
    ]);

    const [data, total] = await qb.getManyAndCount();
    return { data, total };
  }

  async findOne(id: string): Promise<User> {
    const user = await this.userRepository.findOne({
      where: { id, is_deleted: false },
      select: [
        'id',
        'email',
        'first_name',
        'last_name',
        'user_type',
        'password',
        'verificationCode',
        'tokenExpirationTime',
        'profile_pic',
        'created_by',
        'phone_number',
        'role_id',
        'local_id',
        'tenant_id',
      ],
      relations: [
        'manager',
        'role',
        'role.permissions',
        'created_by_user',
        'teams_access',
      ],
    });
    if (!user) throw new NotFoundException('user does not exist');
    return user;
  }

  async findByEmail(email: string): Promise<User | null> {
    return this.userRepository.findOne({
      where: { email, is_deleted: false },
      relations: ['role', 'role.permissions'],
    });
  }

  async findForAuthById(id: string): Promise<User | null> {
    return this.userRepository.findOne({
      where: { id, is_deleted: false },
      relations: ['role', 'role.permissions', 'company'],
    });
  }

async findByFirebaseLocalId(localId: string): Promise<User | null> {
  return this.userRepository.findOne({
    where: { local_id: localId, is_deleted: false },
    relations: ['role', 'role.permissions', 'company'],
  });
}

async getMySettings(userId: string) {
  const user = await this.findOne(userId);
  return {
    profile: {
      first_name: user.first_name ?? null,
      last_name: user.last_name ?? null,
      email: user.email ?? null,
      phone_number: user.phone_number ?? null,
      profile_pic: user.profile_pic ?? null,
    },
  };
}

async updateMyProfile(
  userId: string,
  data: UpdateMyProfileDto,
): Promise<User> {
  const user = await this.userRepository.findOne({
    where: { id: userId, is_deleted: false },
    select: [
      'id',
      'email',
      'first_name',
      'last_name',
      'phone_number',
      'profile_pic',
    ],
  });
  if (!user) throw new NotFoundException('user does not exist');
  if (data.first_name !== undefined) user.first_name = data.first_name;
  if (data.last_name !== undefined) user.last_name = data.last_name;
  if (data.phone_number !== undefined) user.phone_number = data.phone_number;
  if (data.profile_pic !== undefined) user.profile_pic = data.profile_pic;

  await this.userRepository.update(userId, {
    first_name: user.first_name,
    last_name: user.last_name,
    phone_number: user.phone_number,
    profile_pic: user.profile_pic,
  });

  const updated = await this.findForAuthById(userId);
  if (!updated) throw new NotFoundException('user does not exist');
  return updated;
}

async create(data: CreateUserData): Promise<User> {
  const existing = await this.findByEmail(data.email);
  if (existing) throw new BadRequestException('User email already exists');

  const password = generateRandomPassword(8, true, true);
  const hashedPassword = this.crypto.hash(password);

  const user = this.userRepository.create({
    first_name: data.first_name,
    last_name: data.last_name,
    email: data.email,
    password: hashedPassword,
    user_type: (data.user_type as UserType) ?? UserType.Employee,
    phone_number: data.phone_number ?? null,
    local_id: data.local_id ?? null,
    tenant_id: data.tenant_id ?? null,
    profile_pic: data.profile_pic ?? null,
    manager_id: null,
    created_by: data.created_by ?? null,
  } as unknown as DeepPartial<User>);

  if (data.role_id) {
    const role = await this.roleService.findOne(data.role_id);
    user.role_id = role.id;
    user.role = role;
  }

  if (data.team_id && typeof data.team_id === 'string') {
    const team = await this.teamRepository.findOne({
      where: { id: data.team_id, is_deleted: false },
    });
    if (!team) throw new BadRequestException('Team does not exist');
    user.team_id = team.id;
    user.team = team;
  }

  let saved = await this.userRepository.save(user);

  if (data.teams?.length) {
    const teams = await this.teamRepository.find({
      where: { id: In(data.teams), is_deleted: false },
    });
    if (teams.length !== data.teams.length) {
      throw new BadRequestException('One or more team IDs are invalid');
    }
    saved.teams_access = teams;
    saved = await this.userRepository.save(saved);
    await this.syncExternalTeamAccess(
      saved.local_id,
      saved.tenant_id,
      teams.map((team) => team.id),
    );
  }

  if (this.emailService.isConfigured() && data.email) {
    await this.sendInvitationEmail(
      data.email,
      password,
      saved.first_name ?? '',
      saved.last_name ?? '',
    );
  }

  return this.findOne(saved.id);
}

/** Request password reset: send reset link to email (same email setup as signup). */
async requestPasswordReset(body: { email: string }) {
  const user = await this.userRepository.findOne({
    where: { email: body.email, is_deleted: false },
  });
  const message =
    'If an account exists for this email, you will receive a reset link.';
  if (!user) {
    return { status: 'Success', message };
  }
  const resetToken = this.jwtService.sign(
    { userId: user.id, purpose: 'password-reset' },
    { expiresIn: '10m' },
  );
  const frontendUrl = this.appConfig.frontendUrl ?? 'http://localhost:3000';
  const resetUrl = `${frontendUrl.replace(/\/?$/, '')}/reset-password?token=${encodeURIComponent(resetToken)}`;
  if (this.emailService.isConfigured()) {
    await this.emailService.send({
      to: body.email,
      subject: '[SD] Reset your password',
      html: `<p>Hello ${user.first_name || 'User'},</p><p>You requested a password reset. Click the link below (link expires in 10 minutes):</p><p><a href="${resetUrl}">Reset password</a></p><p>If the button above doesn't work, copy and paste the URL below into your browser:</p><p>${resetUrl}</p><p>If you did not request this, ignore this email.</p>`,
    });
  }
  return { status: 'Success', message };
}

/** Set new password using the token from the reset link (same token from requestPasswordReset). */
async resetPasswordWithToken(body: { token?: string; password: string }) {

async resetPasswordWithToken(body: { token?: string; password: string }) {
  const token = body.token;
  if (!token) throw new BadRequestException('Reset token is required');
  if (!body.password?.trim())
    throw new BadRequestException('Password is required');
  let decoded: { userId?: string; purpose?: string };
  try {
    decoded = this.jwtService.verify(token);
  } catch {
    throw new BadRequestException(
      'Invalid or expired reset link. Please request a new one.',
    );
  }
  if (decoded.purpose !== 'password-reset' || !decoded.userId) {
    throw new BadRequestException('Invalid reset token');
  }
  const user = await this.userRepository.findOne({
    where: { id: decoded.userId, is_deleted: false },
  });
  if (!user) throw new NotFoundException('User not found');
  const hashed = this.crypto.hash(body.password.trim());
  await this.userRepository.update(decoded.userId, {
    password: hashed,
    password_changed: true,
  });
  return {
    status: 'Success',
    message: 'Password has been reset successfully.',
  };
}
/** Whether email is configured (for invitation emails). */
isEmailConfigured(): boolean {
  return this.emailService.isConfigured();
}

/** Send invitation email with temp password (used by user and client create). */
async sendInvitationEmail(
  email: string,
  plainPassword: string,
  firstName: string,
  lastName: string,
): Promise<void> {
  const name = [firstName, lastName].filter(Boolean).join(' ') || 'User';
  const loginUrl =
    (this.appConfig.frontendUrl ?? 'http://localhost:3000').replace(
      /\/?$/,
      '',
    ) + '/login';
  await this.emailService.send({
    to: email,
    subject: '[SD] Your account invitation',
    html: `<p>Hello ${name},</p><p>Your account has been created. Temporary password: <strong>${plainPassword}</strong></p><p><a href="${loginUrl}">Log in here</a></p>`,
  });
}

async setNewPassword(
  body: { new_password: string },
  currentUser: User,
): Promise<User> {
  const user = await this.userRepository.findOne({
    where: { id: currentUser.id, is_deleted: false },
  });
  if (!user) throw new NotFoundException('User not found');
  if (user.password_changed === true) {
    throw new BadRequestException(
      'Password was already changed. Use change-password to update.',
    );
  }
  user.password = this.crypto.hash(body.new_password);
  (user as User & { password_changed: boolean }).password_changed = true;
  await this.userRepository.save(user);
  return this.findOne(user.id);
}

async update(
  id: string,
  data: Partial<{
    first_name: string;
    last_name: string;
    phone_number: string;
    user_type: UserType;
    profile_pic: string;
    role_id: string;
    team_id: string;
    team_id_list: string[];
  }>,
): Promise<User> {
  const user = await this.userRepository.findOne({
    where: { id, is_deleted: false },
  });
  if (!user) throw new NotFoundException('User does not exist');

  if (data.first_name != null) user.first_name = data.first_name;
  if (data.last_name != null) user.last_name = data.last_name;
  if (data.phone_number != null) user.phone_number = data.phone_number;
  if (data.user_type != null) user.user_type = data.user_type;
  if (data.profile_pic != null) user.profile_pic = data.profile_pic;

  if (data.role_id != null) {
    const role = await this.roleService.findOne(data.role_id);
    user.role_id = role.id;
    user.role = role;
  }

  if (data.team_id != null) {
    const team = await this.teamRepository.findOne({
      where: { id: data.team_id },
    });
    if (!team) throw new BadRequestException('Team does not exist');
    user.team_id = team.id;
    user.team = team;
  }

  if (data.team_id_list != null) {
    const teams = await this.teamRepository.find({
      where: { id: In(data.team_id_list) },
    });
    user.teams_access = teams;
    await this.syncExternalTeamAccess(
      user.local_id,
      user.tenant_id,
      teams.map((team) => team.id),
    );
  }

  return this.userRepository.save(user);
}

async remove(id: string): Promise<void> {
  const result = await this.userRepository.delete({ id });
  if (result.affected === 0)
    throw new BadRequestException('User is not Deleted');
}

/** Returns deleted count/result to match Express deleteAllUsers response. */
async removeAll() {
  const result = await this.userRepository
    .createQueryBuilder()
    .delete()
    .execute();
  return result;
}

async changePassword(
  userId: string,
  currentUserId: string,
  currentUserRoleName: string | undefined,
  oldPassword: string,
  newPassword: string,
): Promise<User> {
  if (currentUserId !== userId && currentUserRoleName !== 'Admin') {
    throw new ForbiddenException('Unauthorized');
  }

  const user = await this.findOne(userId);
  if (!this.crypto.compare(oldPassword, user.password)) {
    throw new BadRequestException('Old password is incorrect');
  }

  user.password = this.crypto.hash(newPassword);
  (user as { password_changed?: boolean }).password_changed = true;
  await this.userRepository.save(user);
  return this.findOne(userId);
}

async login(
  email: string,
  password: string,
): Promise<{ user: Partial<User>; token: string }> {
  const user = await this.findByEmail(email);
  if (!user) throw new NotFoundException('User Not Found!');

  if (!this.crypto.compare(password, user.password)) {
    throw new BadRequestException('please check your credential');
  }

  const token = this.jwtService.sign({ id: user.id });
  const { password: _pw, ...rest } = user;
  void _pw;
  return { user: rest, token };
}

/** Reset password to fixed temp password (admin reset); email user (same setup as signup). */
async resetPassword(email: string): Promise<User> {
  const user = await this.findByEmail(email);
  if (!user) throw new NotFoundException('User not found');
  const tempPassword = '%TGBnhy6';
  user.password = this.crypto.hash(tempPassword);
  await this.userRepository.save(user);
  if (this.emailService.isConfigured()) {
    const loginUrl =
      (this.appConfig.frontendUrl ?? 'http://localhost:3000').replace(
        /\/?$/,
        '',
      ) + '/login';
    await this.emailService.send({
      to: email,
      subject: '[SD] Your password has been reset',
      html: `<p>Hello ${user.first_name || 'User'},</p><p>Your password was reset by an administrator. Temporary password: <strong>${tempPassword}</strong></p><p><a href="${loginUrl}">Log in here</a></p><p>Please change your password after logging in.</p>`,
    });
  }
  return this.findOne(user.id);
}

/** Forgot password: set new random password and email it (same email setup as signup). */
async forgotPassword(email: string): Promise<User> {
  const user = await this.findByEmail(email);
  if (!user) throw new NotFoundException('User not found');
  const newPassword = generateRandomPassword(8, true, true);
  user.password = this.crypto.hash(newPassword);
  await this.userRepository.save(user);
  if (this.emailService.isConfigured()) {
    const loginUrl =
      (this.appConfig.frontendUrl ?? 'http://localhost:3000').replace(
        /\/?$/,
        '',
      ) + '/login';
    await this.emailService.send({
      to: email,
      subject: '[SD] Your new password',
      html: `<p>Hello ${user.first_name || 'User'},</p><p>Your password was reset. New password: <strong>${newPassword}</strong></p><p><a href="${loginUrl}">Log in here</a></p><p>Please change your password after logging in.</p>`,
    });
  }
  return this.findOne(user.id);
}

/** Assign teams to user (replace teams_access). */
async teamAccess(userId: string, teamIds: string[]): Promise<User> {
  const user = await this.userRepository.findOne({
    where: { id: userId, is_deleted: false },
    relations: ['teams_access'],
  });
  if (!user) throw new NotFoundException('User does not exist');
  const teams = await this.teamRepository.find({
    where: { id: In(teamIds) },
  });
  if (teams.length !== teamIds.length)
    throw new BadRequestException('One or more team IDs are invalid');
  user.teams_access = teams;
  await this.userRepository.save(user);
  await this.syncExternalTeamAccess(
    user.local_id,
    user.tenant_id,
    teams.map((team) => team.id),
  );
  return this.findOne(userId);
}

/** Send change-password email with verification code and link. */
async sendChangePasswordAlertByEmail(email: string): Promise<User> {
  const user = await this.userRepository.findOne({
    where: { email, is_deleted: false },
    relations: ['role', 'role.permissions'],
  });
  if (!user)
    throw new NotFoundException('User not found with the email you provided');
  const { code, expiresAt } = generateVerificationCode();
  const resetToken = this.jwtService.sign({ sub: user.id });
  user.verificationCode = String(code);
  user.passwordChangeToken = resetToken;
  user.tokenExpirationTime = String(expiresAt);
  await this.userRepository.save(user);
  const frontendUrl = this.appConfig.frontendUrl || 'http://localhost:3000';
  const link = `${frontendUrl}/verification/${user.id}`;
  if (this.emailService.isConfigured()) {
    await this.emailService.send({
      to: email,
      subject: '[SD] Account activation – set your password',
      html: `<p>Hello ${user.first_name ?? ''} ${user.last_name ?? ''},</p><p>Your account has been created in the SD system.</p><p>To activate and set your password, click the link below:</p><p><a href="${link}">Set your password</a></p><p>Your verification code is <strong>${code}</strong>.</p><p>If you did not expect this email, you can ignore it.</p>`,
    });
  }
  return user;
}

/** Verify code; throw if invalid or expired. */
async checkVerificationCode(
  userId: string,
  code: string | number,
): Promise<boolean> {
  const user = await this.findOne(userId);
  if (!checkCode(user.verificationCode, code)) {
    throw new BadRequestException('Incorrect verification code');
  }
  const exp = parseInt(String(user.tokenExpirationTime || '0'), 10);
  if (Date.now() > exp) {
    await this.sendChangePasswordAlertByEmail(user.email);
    throw new BadRequestException('The verification code is expired');
  }
  return true;
}

/** Set new password (from verification flow); clear token and code. */
async sendChangePasswordRequest(
  userId: string,
  newPassword: string,
): Promise<User> {
  const user = await this.findOne(userId);
  if (!user) throw new NotFoundException('User not found');
  user.password = this.crypto.hash(newPassword);
  user.passwordChangeToken = null;
  user.verificationCode = null;
  (user as User & { password_changed?: boolean }).password_changed = true;
  user.tokenExpirationTime = null;
  await this.userRepository.save(user);
  return this.findOne(userId);
}

/** Get all agents (users) that share the same team as the given user (by user id). */
async getAllAgentsForTeamByUserId(userId: string): Promise<Partial<User>[]> {

  async getAllAgentsForTeamByUserId(userId: string): Promise<Partial<User>[]> {
    const refUser = await this.userRepository.findOne({
      where: { id: userId, is_deleted: false },
      select: [
        'id',
        'local_id',
        'tenant_id',
        'first_name',
        'last_name',
        'email',
        'user_type',
        'profile_pic',
        'phone_number',
      ],
    });
    if (!refUser) throw new NotFoundException('User not found');
    if (!refUser.local_id?.trim())
      throw new NotFoundException('User external identity not found');
    const teamRows: Array<{ team_id: string }> =
      await this.userRepository.query(
        `
      SELECT team_id
      FROM team_member_external
      WHERE user_external_id = $1
        AND ($2::varchar IS NULL OR tenant_id = $2)
      `,
        [refUser.local_id.trim(), refUser.tenant_id?.trim() || null],
      );
    const teamIds = teamRows.map((r) => r.team_id);
    if (!teamIds.length) throw new NotFoundException('User team not found');

    const memberRows: Array<{ user_external_id: string | null }> =
      await this.userRepository.query(
        `
      SELECT DISTINCT user_external_id
      FROM team_member_external
      WHERE team_id = $1
        AND ($2::varchar IS NULL OR tenant_id = $2)
      `,
        [teamIds[0], refUser.tenant_id?.trim() || null],
      );
    const memberExternalIds = memberRows
      .map((r) => r.user_external_id ?? '')
      .filter(Boolean);
    if (!memberExternalIds.length) return [];

    return this.userRepository.find({
      select: [
        'id',
        'first_name',
        'last_name',
        'email',
        'user_type',
        'profile_pic',
        'phone_number',
      ],
      where: {
        is_deleted: false,
        local_id: In(memberExternalIds),
      },
    });
  }

  /** Update only role_id. */
  async updateUserRole(userId: string, roleId: string): Promise<User> {
    await this.roleService.findOne(roleId);
    const user = await this.findOne(userId);
    user.role_id = roleId;
    const role = await this.roleService.findOne(roleId);
    user.role = role;
    await this.userRepository.save(user);
    return this.findOne(userId);
  }
}

