import { ORG_AND_EMP_URL, TENANT_MGMT_URL, URL } from '@/utils/constants';

export const SERVICE_KEYS = {
  serviceDesk: 'serviceDesk',
  orgEmp: 'orgEmp',
  tenantMgmt: 'tenantMgmt',
} as const;

export type ServiceKey = (typeof SERVICE_KEYS)[keyof typeof SERVICE_KEYS];

type ServiceRegistry = Record<ServiceKey, string>;

function trimBase(url: string | undefined | null): string {
  return (url ?? '').trim().replace(/\/+$/, '');
}

export function getServiceBaseUrl(service: ServiceKey): string {
  const registry: ServiceRegistry = {
    [SERVICE_KEYS.serviceDesk]: trimBase(URL),
    [SERVICE_KEYS.orgEmp]: trimBase(ORG_AND_EMP_URL),
    [SERVICE_KEYS.tenantMgmt]: trimBase(TENANT_MGMT_URL),
  };
  return registry[service];
}

