export function unwrapData<T>(payload: unknown, fallback: T): T {
  if (!payload || typeof payload !== 'object') return fallback;
  const row = payload as Record<string, unknown>;
  const data = row.data as T | undefined;
  return data ?? fallback;
}

export function unwrapRowsAndTotal<T>(payload: unknown): {
  rows: T[];
  total: number;
} {
  if (!payload || typeof payload !== 'object') {
    return { rows: [], total: 0 };
  }
  const row = payload as Record<string, unknown>;
  const rowsCandidate = row.data ?? row.rows;
  const rows = Array.isArray(rowsCandidate) ? (rowsCandidate as T[]) : [];
  const totalCandidate =
    row.meta && typeof row.meta === 'object'
      ? (row.meta as Record<string, unknown>).total
      : undefined;
  const total =
    Number(row.total ?? row.totalUsers ?? totalCandidate ?? rows.length) || 0;
  return { rows, total };
}

