import axios from 'axios';

export type ApiError = Error & {
  status?: number;
  code?: string;
  details?: unknown;
};

function messageFromData(data: unknown): string | undefined {
  if (!data || typeof data !== 'object') return undefined;
  const row = data as Record<string, unknown>;
  const raw = row.message ?? row.error ?? row.detail;
  if (typeof raw === 'string' && raw.trim()) return raw.trim();
  return undefined;
}

export function toApiError(
  error: unknown,
  fallback = 'Request failed',
): ApiError {
  if (axios.isAxiosError(error)) {
    const status = error.response?.status;
    const data = error.response?.data;
    const msg = messageFromData(data) ?? error.message ?? fallback;
    const apiError = new Error(msg) as ApiError;
    apiError.status = status;
    apiError.code = error.code;
    apiError.details = data;
    return apiError;
  }

  if (error instanceof Error) {
    return error as ApiError;
  }

  return new Error(fallback) as ApiError;
}

