'use client';

import React, { useEffect, useLayoutEffect, useState } from 'react';
import { usePathname, useRouter } from 'next/navigation';
import SideBar, { SIDEBAR_COLLAPSED_PX, SIDEBAR_EXPANDED_PX } from '@/components/sideBar';
import NavBar from '@/components/navBar';
import { useLayoutUiStore } from '@/store/layoutUi';
import { Sheet, SheetContent, SheetHeader, SheetTitle } from '@/components/ui/sheet';
import { checkUserPermission } from '@/utils/permissions';
import { requiredPermissionsForPath } from '@/lib/rbac/core';
import { DashboardRouteSkeleton } from './_components/DashboardRouteSkeleton';
import { ClientPortalRouteSkeleton } from './_components/ClientPortalRouteSkeleton';

export default function AfterLoginLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  const pathname = usePathname();
  const router = useRouter();
  const [userType, setUserType] = useState<string | null>(null);
  const [isClient, setIsClient] = useState(false);
  const [isChecking, setIsChecking] = useState(true);
  const sidebarCollapsed = useLayoutUiStore((s) => s.sidebarCollapsed);
  const mobileSidebarOpen = useLayoutUiStore((s) => s.mobileSidebarOpen);
  const setMobileSidebarOpen = useLayoutUiStore((s) => s.setMobileSidebarOpen);

  useLayoutEffect(() => {
    if (typeof window === 'undefined') return;

    let user_type: string | null = null;
    try {
      user_type = localStorage.getItem('user_type');
    } catch {
      user_type = null;
    }

    setUserType(user_type);
    setIsClient(user_type === 'client');
    setIsChecking(false);

    if (user_type === 'client') {
      if (pathname && !pathname.startsWith('/client-portal')) {
        router.replace('/client-portal');
      }
    } else if (user_type && user_type !== 'client') {
      if (pathname && pathname.startsWith('/client-portal')) {
        router.replace('/dashboard');
      }
    }
  }, [pathname, router]);

  // Close mobile sidebar on route change
  useEffect(() => {
    setMobileSidebarOpen(false);
  }, [pathname, setMobileSidebarOpen]);

  /** Before user_type is readable from storage, align bootstrap UI with destination route to reduce flicker. */
  if (isChecking && userType === null) {
    const p = pathname ?? '';
    if (p.startsWith('/client-portal')) {
      return <ClientPortalRouteSkeleton variant="fullscreen" />;
    }
    if (p === '/dashboard' || p.startsWith('/dashboard')) {
      return (
        <div className="bg-muted flex min-h-screen w-full overflow-x-hidden">
          <SideBar />
          <div
            className={`flex min-h-screen min-w-0 flex-1 flex-col transition-[padding] duration-200 ${
              sidebarCollapsed ? 'pl-[60px]' : 'pl-[220px]'
            }`}
          >
            <NavBar />
            <main className="bg-muted/30 min-h-[calc(100vh-3.5rem)] flex-1 px-0 pt-14 pb-8">
              <DashboardRouteSkeleton />
            </main>
          </div>
        </div>
      );
    }

    return (
      <div className="flex min-h-screen items-center justify-center bg-muted text-muted-foreground">
        <div className="text-center">
          <div className="mx-auto mb-4 h-12 w-12 animate-spin rounded-full border-2 border-muted border-t-primary" />
          <p className="text-sm">Loading workspace…</p>
        </div>
      </div>
    );
  }

  const isClientPortalRoute = pathname?.startsWith('/client-portal') ?? false;

  if (isClient || isClientPortalRoute) {
    return <>{children}</>;
  }

  const normalizedPath = pathname || '/dashboard';
  const routePermissions = requiredPermissionsForPath(normalizedPath);
  const canViewRoute = checkUserPermission(routePermissions);

  const isFramelessShellRoute =
    pathname === '/createticket' ||
    pathname === '/support' ||
    pathname === '/support/new';

  const useZeroHorizontalPadding =
    isFramelessShellRoute ||
    pathname === '/dashboard' ||
    pathname?.startsWith('/tickets') ||
    pathname?.startsWith('/email-support') ||
    pathname?.startsWith('/contacts') ||
    pathname?.startsWith('/employees') ||
    pathname?.startsWith('/companies') ||
    pathname?.startsWith('/knowledge');

  const isTicketsRoute = pathname?.startsWith('/tickets') ?? false;
  const isDashboard = pathname === '/dashboard';

  return (
    <div className="h-screen overflow-hidden bg-muted text-foreground">
      {/* Desktop Sidebar */}
      <SideBar className="fixed left-0 top-0 z-40 hidden md:flex" />

      {/* Mobile Sidebar (Drawer) */}
      <Sheet open={mobileSidebarOpen} onOpenChange={setMobileSidebarOpen}>
        <SheetContent
          side="left"
          className="p-0 bg-sidebar border-none"
          style={{ width: sidebarCollapsed ? SIDEBAR_COLLAPSED_PX : SIDEBAR_EXPANDED_PX }}
        >
          <SheetHeader className="sr-only">
            <SheetTitle>Navigation Menu</SheetTitle>
          </SheetHeader>
          <SideBar className="flex h-full" />
        </SheetContent>
      </Sheet>

      <div
        className={`flex h-full flex-col ${
          sidebarCollapsed
            ? 'pl-0 md:pl-[60px]'
            : 'pl-0 md:pl-[220px]'
        }`}
      >
        <NavBar />
        <main
          className={`flex-1 pt-14 ${
            isDashboard || isTicketsRoute
              ? 'overflow-hidden'
              : 'overflow-auto'
          } ${useZeroHorizontalPadding ? 'px-0' : 'px-6'}`}
        >
          {canViewRoute ? (
            children
          ) : (
            <div className="flex min-h-[calc(100vh-8rem)] items-center justify-center">
              <div className="bg-card max-w-md rounded-xl border p-6 text-center shadow-sm">
                <h1 className="text-lg font-semibold">Access denied</h1>
                <p className="text-muted-foreground mt-2 text-sm">
                  Your role does not have permission to view this page.
                </p>
              </div>
            </div>
          )}
        </main>
      </div>
    </div>
  );
}

