import { Drawer } from 'antd';
import type { DrawerProps } from 'antd';
import { ReactNode, useEffect } from 'react';

export interface CustomDrawerProps extends Omit<
  DrawerProps,
  'open' | 'onClose' | 'title'
> {
  open: boolean;
  onClose: () => void;
  title?: ReactNode;
  children: ReactNode;
  lockScroll?: boolean;
}

export default function CustomDrawer({
  open,
  onClose,
  title,
  children,
  lockScroll = true,
  destroyOnClose = true,
  width = 480,
  ...rest
}: CustomDrawerProps) {
  useEffect(() => {
    if (!lockScroll) return;

    if (open) {
      const previousOverflow = document.body.style.overflow;
      document.body.style.overflow = 'hidden';
      return () => {
        document.body.style.overflow = previousOverflow;
      };
    }
  }, [open, lockScroll]);

  return (
    <Drawer
      open={open}
      onClose={onClose}
      title={title}
      destroyOnClose={destroyOnClose}
      width={width}
      styles={{
        body: {
          padding: 20,
        },
      }}
      {...rest}
    >
      {children}
    </Drawer>
  );
}

