function open(type: NotificationType, options: NotificationOptions | string) {
  const opts = typeof options === 'string' ? { message: options } : options;
  const { message, description, duration = DEFAULT_DURATION } = opts;
  antdNotification[type]({
    message,
    description: description || undefined,
    duration,
    placement: 'topRight',
  });
}

