export type NotificationAlertProps = Omit<AlertProps, 'type'> & {
  type?: 'success' | 'error' | 'info' | 'warning';
};

/**
 * Inline alert component for contextual messages (e.g. banners).
 * For toast-style notifications after mutations, use the global notification
 * (triggered automatically by mutation cache or via useNotification hook).
 */
export function NotificationAlert({
  type = 'info',
  message,
  description,
  showIcon = true,
