'use client';

import Link from 'next/link';
import Image from 'next/image';
import { usePathname, useRouter } from 'next/navigation';
import type { LucideIcon } from 'lucide-react';
import {
  LayoutDashboard,
  Ticket,
  Users,
  Building2,
  UserCircle,
  BookOpen,
  LifeBuoy,
  Settings as SettingsIcon,
  PanelLeftClose,
  PanelLeftOpen,
  Mail,
  LogOut,
} from 'lucide-react';
import { useAuthStore } from '@/store/auth';
import { useLayoutUiStore } from '@/store/layoutUi';
import { checkUserPermission, PERMISSIONS } from '@/utils/permissions';
import { getRoleDisplayName } from '@/utils/displayRole';
import { Button } from '@/components/ui/button';
import { cn } from '@/lib/utils';

/** Matches `service-desk-redesign` `MainLayout.tsx` sidebar rail */

/** Matches `service-desk-redesign` `MainLayout.tsx` sidebar rail */
export const SIDEBAR_EXPANDED_PX = 220;
export const SIDEBAR_COLLAPSED_PX = 60;

type SidebarNavItem = {
  name: string;
  href: string;
  icon: LucideIcon;
  /** When true, active only on exact path match */
  exact?: boolean;
  match?: (pathname: string) => boolean;
  permission?: string[];
  dataCy?: string;
};

type SidebarGroup = {
  label: string;
  items: SidebarNavItem[];
};

/** Mirrors `MainLayout` `navGroups` — labels, order, and icons */
const NAV_GROUPS: SidebarGroup[] = [
  {
    label: 'Overview',
    items: [
      {
        name: 'Dashboard',
        href: '/dashboard',
        icon: LayoutDashboard,
        exact: true,
        match: (p) => p === '/dashboard',
        permission: [PERMISSIONS.dashboardView],
        dataCy: 'sidebar-dashboard-link',
      },
    ],
  },
  {
    label: 'Helpdesk',
    items: [
      {
        name: 'Tickets',
        href: '/tickets',
        icon: Ticket,
        match: (p) => p.startsWith('/tickets'),
        permission: [PERMISSIONS.ticketView],
        dataCy: 'sidebar-tickets-link',
      },
      {
        name: 'Support',
        href: '/support',
        icon: LifeBuoy,
        match: (p) => p === '/support' || p.startsWith('/support/'),
        permission: [PERMISSIONS.supportView],
      },
      {
        name: 'Email Support',
        href: '/email-support',
        icon: Mail,
        match: (p) => p.startsWith('/email-support'),
        permission: [PERMISSIONS.supportView],
      },
      {
        name: 'Knowledge Base',
        href: '/knowledge',
        icon: BookOpen,
        match: (p) => p === '/knowledge' || p.startsWith('/knowledge/'),
        permission: [PERMISSIONS.knowledgeView],
      },
    ],
  },
  {
    label: 'Directory',
    items: [
      {
        name: 'Contacts',
        href: '/contacts',
        icon: Users,
        match: (p) => p.startsWith('/contacts'),
        permission: [PERMISSIONS.contactView],
      },
      {
        name: 'Companies',
        href: '/companies',
        icon: Building2,
        match: (p) => p.startsWith('/companies'),
        permission: [PERMISSIONS.companyView],
      },
      {
        name: 'Employees',
        href: '/employees',
        icon: UserCircle,
        match: (p) => p.startsWith('/employees'),
        permission: [PERMISSIONS.employeeView],
      },
    ],
  },
];

function isItemActive(pathname: string, item: SidebarNavItem): boolean {
  if (item.match) return item.match(pathname);
  if (item.exact) return pathname === item.href;
  return pathname === item.href || pathname.startsWith(`${item.href}/`);
}

function filterVisibleItems(items: SidebarNavItem[]): SidebarNavItem[] {
  return items.filter(
    (item) => !item.permission || checkUserPermission(item.permission),
  );
}

export default function SideBar({ className }: { className?: string }) {
  const pathname = usePathname() || '/';
  const router = useRouter();
  const logout = useAuthStore((s) => s.logout);
  const user = useAuthStore((s) => s.userData ?? s.user);
  const sidebarCollapsed = useLayoutUiStore((s) => s.sidebarCollapsed);
  const toggleSidebarCollapsed = useLayoutUiStore(
    (s) => s.toggleSidebarCollapsed,
  );

  const displayName =
    user?.first_name || user?.last_name
      ? `${user?.first_name ?? ''} ${user?.last_name ?? ''}`.trim()
      : (user?.email ?? 'User');

  const initials = (displayName || 'U')
    .split(' ')
    .filter(Boolean)
    .slice(0, 2)
    .map((p) => p[0]?.toUpperCase())
    .join('');

  const roleLabel = getRoleDisplayName(user);

  const railW = sidebarCollapsed ? SIDEBAR_COLLAPSED_PX : SIDEBAR_EXPANDED_PX;

  /** Token colors from `app/redesign-tokens.css` — same as redesign `theme.css` sidebar vars */
  const linkClass = (active: boolean, collapsed: boolean) =>
    [
      'relative flex items-center gap-3 rounded-md px-2 py-2 transition-all duration-100 no-underline outline-none',
      collapsed ? 'justify-center' : '',
      active
        ? 'bg-white !text-primary dark:bg-sidebar-muted dark:!text-sidebar-foreground'
        : '!text-sidebar-foreground/80 hover:bg-sidebar-accent hover:!text-sidebar-accent-foreground',
    ].join(' ');

  const renderItem = (item: SidebarNavItem) => {
    const active = isItemActive(pathname, item);
    const Icon = item.icon;

  const inner = (
    <>
      {active && !sidebarCollapsed ? (
        <div className="bg-sidebar-accent absolute left-0 top-1/2 h-4 w-0.5 -translate-y-1/2 rounded-full" />
      ) : null}
      <Icon
        className={`h-4 w-4 flex-shrink-0 ${
          active
            ? '!text-primary dark:!text-sidebar-foreground'
            : '!text-sidebar-foreground/80'
        }`}
      />
      {!sidebarCollapsed ? (
        <span className="truncate text-[13px] font-medium">{item.name}</span>
      ) : null}
    </>
  );

  return (
    <Link
      key={item.href + item.name}
      href={item.href}
      className={linkClass(active, sidebarCollapsed)}
      data-cy={item.dataCy}
      title={sidebarCollapsed ? item.name : undefined}
    >
      {inner}
    </Link>
  );
};

const settingsActive =
  pathname === '/setting' || pathname.startsWith('/setting/');

return (
  <aside
    style={{ width: railW }}
    className={cn(
      "bg-sidebar antialiased text-sidebar-foreground [font-family:var(--font-family)] [font-size:var(--font-size)] flex h-full flex-col",
      className
    )}
    data-cy="sidebar"
  >
    {/* Brand — IE logo in secondary tile (redesign uses Ticket; we keep org mark per product) */}
    <div
      className={`border-sidebar-border h-[56px] flex items-center border-b flex-shrink-0 ${
        sidebarCollapsed ? 'px-4 justify-center' : 'px-5'
      }`}
    >
      <Link
        href="/dashboard"
        aria-label="Home"
        data-cy="sidebar-logo"
        className="flex items-center gap-2.5 min-w-0"
      >
        <div className="bg-secondary text-secondary-foreground flex size-7 items-center justify-center rounded-md flex-shrink-0 overflow-hidden ring-1 ring-white/10">
          <Image
            src="/ielogo.png"
            alt=""
            width={20}
            height={20}
            className="object-contain"
          />
        </div>
        {!sidebarCollapsed && (
          <div className="min-w-0">
            <div className="text-white text-sm font-semibold leading-tight truncate">
              Service Desk
            </div>
            <div className="text-sidebar-foreground/60 text-xs leading-tight truncate">
              Workspace
            </div>
          </div>
        )}
      </Link>
    </div>

    <nav
      className="flex flex-1 flex-col gap-4 overflow-y-auto px-2 py-3"
      data-cy="sidebar-navigation"
    >
      {NAV_GROUPS.map((group) => {

        {NAV_GROUPS.map((group) => {
          const visible = filterVisibleItems(group.items);
          if (visible.length === 0) return null;

          return (
            <div key={group.label}>
              {!sidebarCollapsed ? (
                <div className="mb-1 px-2">
                  <span className="text-[10px] font-semibold uppercase tracking-widest text-sidebar-foreground/60">
                    {group.label}
                  </span>
                </div>
              ) : null}
              <div className="flex flex-col gap-0.5">
                {visible.map(renderItem)}
              </div>
            </div>
          );
        })}
      </nav>

      {/* Bottom — MainLayout: border-t, Settings, user, collapse */}
      <div className="border-sidebar-border flex-shrink-0 border-t p-2">
        <Link
          href="/setting"
          className={linkClass(settingsActive, sidebarCollapsed)}
        >
          {settingsActive && !sidebarCollapsed && (
            <div className="bg-sidebar-accent absolute left-0 top-1/2 h-4 w-0.5 -translate-y-1/2 rounded-full" />
          )}
          <SettingsIcon className="w-4 h-4 flex-shrink-0" />
          {!sidebarCollapsed && (
            <span className="text-[13px] font-medium">Settings</span>
          )}
        </Link>

        {/* User */}
        {!sidebarCollapsed && (
          <div className="mt-1 px-2 py-2">
            <div className="flex items-center gap-2.5">
              <div className="bg-secondary text-secondary-foreground flex size-7 items-center justify-center rounded-full text-xs font-semibold flex-shrink-0">
                {initials || 'U'}
              </div>
              <div className="flex-1 min-w-0">
                <div className="text-white text-xs font-medium truncate">
                  {displayName}
                </div>
                <div className="text-sidebar-foreground/60 text-[11px] truncate">
                  {String(roleLabel)}
                </div>
              </div>
              <Button
                variant="ghost"
                size="icon"
                className="size-7 text-sidebar-foreground/60 hover:text-sidebar-foreground hover:bg-transparent"
                onClick={() => {
                  logout();
                  router.replace('/authentication/login');
                }}
              >
                <LogOut className="w-3.5 h-3.5" />
              </Button>
            </div>
          </div>
        )}

        <Button
          variant="ghost"
          onClick={toggleSidebarCollapsed}
          className={`text-sidebar-foreground/70 hover:text-sidebar-accent-foreground hover:bg-sidebar-accent h-auto w-full items-center gap-3 rounded-md px-2 py-2 ${sidebarCollapsed ? 'justify-center' : ''}`}
        >
          {sidebarCollapsed ? (
            <PanelLeftOpen className="w-4 h-4" />
          ) : (
            <>
              <PanelLeftClose className="w-4 h-4" />
              <span className="text-[13px]">Collapse</span>
            </>
          )}
        </Button>
      </div>
    </aside>
  );
}

