// Vendored copy of `service-desk-backend/src/permission/permissions.catalog.json` (Edge middleware
// does not apply webpack aliases; keep this file in sync when backend permissions change).
import permissionCatalog from './permissions.catalog.json';

const entries = permissionCatalog.permissions.map(
  (p: { key: string; slug: string }) => [p.key, p.slug] as const,
);

/** Slugs from `service-desk-backend/src/permission/permissions.catalog.json` (single source of truth). */
export const PERMISSIONS = Object.freeze(
  Object.fromEntries(entries),
) as Readonly<Record<string, string>>;

export type PermissionSlug =
  (typeof permissionCatalog.permissions)[number]['slug'];

export function isAdminRole(role?: string | null): boolean {
  return (role ?? '').trim().toLowerCase() === 'admin';
}

export function normalizePermissionSlugs(permissions: Array<string | null | undefined>) {
  return permissions
    .map((permission) => permission?.trim().toLowerCase() || '')
    .filter(Boolean);
}

export function hasRequiredPermissions(
  userPermissions: string[],
  requiredPermissions: string[] = [],
) {
  if (!requiredPermissions.length) return true;
  const normalizedUserPermissions = normalizePermissionSlugs(userPermissions);
  const required = normalizePermissionSlugs(requiredPermissions);
  return required.every((permission) =>
    normalizedUserPermissions.includes(permission),
  );
}

export const ROUTE_PERMISSION_RULES: Array<{
  match: (pathname: string) => boolean;
  permissions: string[];
}> = [
  { match: (p) => p === '/dashboard', permissions: [PERMISSIONS.dashboardView] },
  {
    match: (p) => p === '/createticket',
    permissions: [PERMISSIONS.ticketCreate],
  },
  {
    match: (p) => p === '/support/new',
    permissions: [PERMISSIONS.supportCreate],
  },
  {
    match: (p) => p.startsWith('/tickets'),
    permissions: [PERMISSIONS.ticketView],
  },
