    permissions: [PERMISSIONS.knowledgeView],
  },
  { match: (p) => p.startsWith('/contacts'), permissions: [PERMISSIONS.contactView] },
  {
    match: (p) => p.startsWith('/companies'),
    permissions: [PERMISSIONS.companyView],
  },
  {
    match: (p) => p.startsWith('/employees'),
    permissions: [PERMISSIONS.employeeView],
  },
  {
    match: (p) => p.startsWith('/setting/roles'),
    permissions: [PERMISSIONS.roleView],
  },
  {
    match: (p) => p.startsWith('/setting'),
    permissions: [],
  },
];

export function requiredPermissionsForPath(pathname: string): string[] {
  return ROUTE_PERMISSION_RULES.find((rule) => rule.match(pathname))?.permissions ?? [];
}

