                      <Textarea
                        value={escalationReason}
                        onChange={(e) => setEscalationReason(e.target.value)}
                        placeholder="Describe why this ticket should be escalated..."
                        rows={3}
                        className="min-h-[76px] text-[12px]"
                      />
                    </div>
                  </div>
                )}
