export class AppConfigService {
  constructor(private readonly config: ConfigService) {}

  get nodeEnv(): string {
    return this.config.get<string>('NODE_ENV', 'Development');
  }

  /** Port (Express: process.env.PORT with no default; 3003 fallback for Nest when unset) */
  get port(): number {
    return this.config.get<number>('PORT', 3003);
  }

  get db(): DatabaseConfig {
    return {
      host: this.config.get<string>('PG_HOST', ''),
      port: this.config.get<number>('PG_PORT', 5432),
      username: this.config.get<string>('PG_USER_NAME', ''),
      password: this.config.get<string>('PG_PASSWORD', ''),
      database: this.config.get<string>('PG_DATABASE', ''),
      idleTimeoutMillis: this.config.get<number>('PG_IDLE_TIMEOUT'),
      connectionTimeoutMillis: this.config.get<number>('PG_CONN_TIMEOUT'),
      maxConn: this.config.get<number>('PG_MAX_CONN'),
      url: this.config.get<string>('URL'),
    };
  }

  get jwt(): JwtConfig {
    return {
      secret: this.config.get<string>('JWT_SECRET', ''),
      expiresIn: this.config.get<string>('JWT_EXPIRES_IN', '7d'),
    };
  }

  get email(): EmailConfig {
    const port = this.config.get<number>('EMAIL_PORT', 587);
    return {
      host: this.config.get<string>('HOST_URL', 'smtp.office365.com'),
      port,
      secure: port === 465,
      user: this.config.get<string>('SYSTEM_EMAIL', ''),
      password: this.config.get<string>('SYSTEM_EMAIL_PASSWORD', ''),
    };
  }

  get backendDomainName(): string | undefined {
    return this.config.get<string>('BACKEND_DOMAIN_NAME');
  }

  get frontendUrl(): string | undefined {
    return this.config.get<string>('FRONTEND_URL');
  }

  get frontendProdDomainName(): string | undefined {
    return this.config.get<string>('FRONTEND_PROD_DOMAIN_NAME');
  }

  get frontendTestDomainName(): string | undefined {
    return this.config.get<string>('FRONTEND_TEST_DOMAIN_NAME');
  }

  get frontendDevDomainName(): string | undefined {
    return this.config.get<string>('FRONTEND_DEV_DOMAIN_NAME');
  }

  /** Express: log.logFilePath */
  get logFilePath(): string | undefined {
    return this.config.get<string>('LOG_FILE_PATH');
  }

  /** Express: company_email / COMP_EMAIL */
  get companyEmail(): string | undefined {
    return this.config.get<string>('COMP_EMAIL');
  }

  get publicVapidKey(): string | undefined {
    return this.config.get<string>('PUBLIC_VAPID_KEY');
  }

  get privateVapidKey(): string | undefined {
    return this.config.get<string>('PRIVATE_VAPID_KEY');
  }

  get webPushContact(): string | undefined {
    return this.config.get<string>('WEB_PUSH_CONTACT');
  }

  /** IMAP / support – sender email (from .env as senderEmail) */
  get senderEmail(): string | undefined {
    return this.config.get<string>('senderEmail');
  }

  /** IMAP / support – sender password (from .env as passwordEmail) */
  get passwordEmail(): string | undefined {
    return this.config.get<string>('passwordEmail');
  }

  get isDevelopment(): boolean {
    return this.nodeEnv === 'Development';
  }

  get isProduction(): boolean {
    return this.nodeEnv === 'Production';
  }

  get isTest(): boolean {
    return this.nodeEnv === 'Test';
  }

  get firebase(): FirebaseConfig {
    return {
      projectId: this.config.get<string>('FIREBASE_PROJECT_ID'),
      clientEmail: this.config.get<string>('FIREBASE_CLIENT_EMAIL'),
      privateKey: this.config.get<string>('FIREBASE_PRIVATE_KEY'),
      enableAuth: this.config.get<boolean>('ENABLE_FIREBASE_AUTH', true),
