import {
  ExceptionFilter,
  Catch,
  ArgumentsHost,
  HttpException,
  HttpStatus,
  Logger,
} from '@nestjs/common';
import { Request, Response } from 'express';

@Catch()

@Catch()
export class HttpExceptionFilter implements ExceptionFilter {
  private readonly logger = new Logger(HttpExceptionFilter.name);

  catch(exception: unknown, host: ArgumentsHost): void {
    const ctx = host.switchToHttp();
    const res = ctx.getResponse<Response>();
    const request = ctx.getRequest<Request>();

    const isDev = process.env.NODE_ENV === 'Development';
    const statusCode =
      exception instanceof HttpException
        ? exception.getStatus()
        : HttpStatus.INTERNAL_SERVER_ERROR;

    const status = `${statusCode}`.startsWith('4') ? 'FAIL' : 'ERROR';
    const exceptionResponse =
      exception instanceof HttpException ? exception.getResponse() : null;
    const message =
      typeof exceptionResponse === 'object' &&
      exceptionResponse &&
      'message' in exceptionResponse
        ? (exceptionResponse as { message?: string | string[] }).message
        : exception instanceof HttpException
          ? exception.message
          : 'Opps! Something Went wrong...';

    let msg = Array.isArray(message) ? message[0] : message;
    // Match Express catch-all: unknown routes (Nest "Cannot GET /path") return "Unknown URL - {fullUrl}"
    const msgStr = typeof msg === 'string' ? msg : '';
    if (
      statusCode === 404 &&
      request &&
      /^Cannot (GET|POST|PATCH|PUT|DELETE|HEAD|OPTIONS) /i.test(msgStr)
    ) {
      const host = typeof request.get === 'function' ? request.get('host') : '';
      const protocol = request.protocol || 'http';
      const fullUrl = `${protocol}://${host}${request.originalUrl || request.url}`;
      msg = `Unknown URL - ${fullUrl}`;
    }
    if (!isDev && statusCode >= 500) msg = 'Opps! Something Went wrong...';
    const body: Record<string, unknown> = {
      status,
      message: msg,
    };

    if (isDev && exception instanceof Error) {
      body.errorStack = exception.stack;
    }

    this.logger.error(
      `${request.method} ${request.url} ${statusCode} - ${JSON.stringify(body)}`,
    );

    res.status(statusCode).json(body);
  }
}

