import { Injectable } from '@nestjs/common';
import * as bcrypt from 'bcryptjs';

@Injectable()
export class CryptoService {
  private readonly saltRounds = 10;

  hash(plain: string): string {
    return bcrypt.hashSync(plain, this.saltRounds);
  }

  compare(plain: string, hashed: string): boolean {
    return bcrypt.compareSync(plain.toString(), hashed);
  }
}

import { Injectable } from '@nestjs/common';
import * as nodemailer from 'nodemailer';
import { AppConfigService } from '../config/app-config.service';

export interface SendEmailOptions {
  from?: string;
  to: string;
  subject: string;
  html: string;
  cc?: string;
  bcc?: string;
}

export interface SendEmailResult {
  error?: Error;
  success?: boolean;
  info?: unknown;
}

/** Transporter interface to avoid strict lint on nodemailer typings */
interface MailTransporter {
  sendMail(
    mailOptions: nodemailer.SendMailOptions,
    callback: (err: Error | null, info: unknown) => void,
  ): void;
}

@Injectable()
export class EmailService {
  private transporter: MailTransporter | null = null;

  constructor(private readonly config: AppConfigService) {}

  private getTransporter(): MailTransporter {
    if (!this.transporter) {
      const emailConfig = this.config.email;
      // eslint-disable-next-line @typescript-eslint/no-unsafe-call, @typescript-eslint/no-unsafe-member-access -- nodemailer typings
      this.transporter = nodemailer.createTransport({
        host: emailConfig.host,
        port: emailConfig.port,
        secure: emailConfig.secure,
        requireTLS: true,
        tls: { rejectUnauthorized: false },
        auth: {
          user: emailConfig.user,
          pass: emailConfig.password,
        },
      }) as MailTransporter;
    }
    return this.transporter;
  }

  async send(options: SendEmailOptions): Promise<SendEmailResult> {
    const from = options.from ?? this.config.email.user;
    return new Promise((resolve) => {
      this.getTransporter().sendMail(
        {
          from,
          to: options.to,
          subject: options.subject,
          html: options.html,
          cc: options.cc,
          bcc: options.bcc,
        },
        (err: Error | null, info: unknown) => {
          if (err) resolve({ error: err });
          else resolve({ success: true, info });
        },
      );
    });
  }

  /** Check if email is configured (user and password set) */
  isConfigured(): boolean {
    const { user, password } = this.config.email;
    return Boolean(user && password);
  }
}

import { Injectable } from '@nestjs/common';
import {
  getPagination,
  getPaginationMeta,
  type PaginationInput,
  type PaginationMeta,
} from '../utils/pagination.util';

export interface PaginatedResponse<T> {
  data: T[];
  meta: PaginationMeta;
}

@Injectable()
export class PaginationService {
  /**
   * Parse page and limit from query params (e.g. from @Query()).
   * Returns { take, skip, page, limit } for use with TypeORM.
   */
  getParams(params: PaginationInput) {
    return getPagination(params);
  }

  /**
   * Build a paginated API response with data and meta.
   */
  paginate<T>(
    items: T[],
    total: number,
    params: PaginationInput,
  ): PaginatedResponse<T> {
    const { page, limit } = getPagination(params);
    const meta = getPaginationMeta(page, limit, total);
    return { data: items, meta };
  }
}

