import { diskStorage } from 'multer';
import { existsSync, mkdirSync } from 'fs';
import { join } from 'path';
import { MulterOptions } from '@nestjs/platform-express/multer/interfaces/multer-options.interface';
import {
  IMAGE_MIME_TYPES,
  DOCUMENT_MIME_TYPES,
  UPLOADS_ROOT,
  UPLOADS_IMAGES,
  UPLOADS_DOCUMENTS,
  IMAGE_MAX_SIZE,
  DOCUMENT_MAX_SIZE,
} from './upload.constants';

function ensureDir(dir: string): void {
  if (!existsSync(dir)) {
    mkdirSync(dir, { recursive: true });
  }
}

/**
 * Multer options for image uploads (profile pics, company logos, etc.).
 * Use with FileInterceptor('fieldName', imageUploadOptions).
 */
export const imageUploadOptions: MulterOptions = {
  storage: diskStorage({
    destination: (_req, _file, cb) => {
      const dir = join(UPLOADS_ROOT, UPLOADS_IMAGES);
      ensureDir(dir);
      cb(null, dir);
    },
    filename: (_req, file, cb) => {
      const ext = IMAGE_MIME_TYPES[file.mimetype] || 'bin';
      const safeName = file.originalname.replace(/\s+/g, '-');
      cb(null, `${safeName}-${Date.now()}.${ext}`);
    },
  }),
  fileFilter: (_req, file, cb) => {
    if (IMAGE_MIME_TYPES[file.mimetype]) {
      cb(null, true);
    } else {
      cb(
        new Error('Invalid image type. Allowed: png, jpg, jpeg, gif, webp'),
        false,
      );
    }
  },
  limits: { fileSize: IMAGE_MAX_SIZE },
};

/**
 * Multer options for document uploads (PDF, Word, Excel, etc.).
 * Use with FileInterceptor('fieldName', documentUploadOptions).
 */
export const documentUploadOptions: MulterOptions = {
  storage: diskStorage({
    destination: (_req, _file, cb) => {
      const dir = join(UPLOADS_ROOT, UPLOADS_DOCUMENTS);
      ensureDir(dir);
      cb(null, dir);
    },
    filename: (_req, file, cb) => {
      const ext = file.originalname.split('.').pop() || 'bin';
      const unique = `${Date.now()}-${Math.round(Math.random() * 1e9)}`;
      cb(null, `doc-${unique}.${ext}`);
    },
  }),
  fileFilter: (_req, file, cb) => {
    if (
      DOCUMENT_MIME_TYPES.includes(
        file.mimetype as (typeof DOCUMENT_MIME_TYPES)[number],
      )
    ) {
      cb(null, true);
    } else {
      cb(
        new Error(
          'Invalid file type. Allowed: PDF, Word, Excel, images, text.',
        ),
        false,
      );
    }
  },
  limits: { fileSize: DOCUMENT_MAX_SIZE },
};

/** Allowed image MIME types for profile pics, logos, etc. */
export const IMAGE_MIME_TYPES: Record<string, string> = {
  'image/png': 'png',
  'image/jpg': 'jpg',
  'image/jpeg': 'jpeg',
  'image/gif': 'gif',
  'image/webp': 'webp',
};

/** Allowed document MIME types for knowledge base, attachments */
export const DOCUMENT_MIME_TYPES = [
  'application/pdf',
  'application/msword',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  'application/vnd.ms-excel',
  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
  'image/jpeg',
  'image/png',
  'image/gif',
  'text/plain',
] as const;

/** Max file size for images (bytes) */
export const IMAGE_MAX_SIZE = 5 * 1024 * 1024; // 5MB

/** Max file size for documents (bytes) */
export const DOCUMENT_MAX_SIZE = 10 * 1024 * 1024; // 10MB

/** Default uploads root (relative to project root) */
export const UPLOADS_ROOT = 'uploads/';

/** Subfolder for images (profile pics, logos) */
export const UPLOADS_IMAGES = 'images';

/** Subfolder for documents */
export const UPLOADS_DOCUMENTS = 'documents';

/**
 * Convert multer file.path (may have OS-specific separators) to a relative path
 * with forward slashes for storage and URLs (e.g. "images/file.jpeg").
 * Frontend can then use: `${baseUrl}/api/v1/uploads/${path}`
 */
export function toUploadRelativePath(fullPath: string): string {
  if (!fullPath?.trim()) return '';
  const normalized = fullPath.replace(/\\/g, '/');
  const match = normalized.match(/uploads\/?(.*)$/i);
  return match ? match[1] : normalized;
}

import { Injectable } from '@nestjs/common';
import { unlink } from 'fs/promises';
import { existsSync } from 'fs';
import { join } from 'path';
import {
  UPLOADS_ROOT,
  UPLOADS_IMAGES,
  UPLOADS_DOCUMENTS,
} from './upload.constants';

@Injectable()

@Injectable()
export class UploadService {
  /** Root directory for all uploads */
  get uploadsRoot(): string {
    return UPLOADS_ROOT;
  }

  /** Path for images subfolder */
  get imagesPath(): string {
    return join(UPLOADS_ROOT, UPLOADS_IMAGES);
  }

  /** Path for documents subfolder */
  get documentsPath(): string {
    return join(UPLOADS_ROOT, UPLOADS_DOCUMENTS);
  }

  /**
   * Get full path for a file under uploads (e.g. "images/foo.png").
   * Use for storing in DB or building URLs.
   */
  getPath(relativePath: string): string {
    return join(UPLOADS_ROOT, relativePath);
  }

  /**
   * Build public URL for an uploaded file (relative to uploads root).
   * Assumes static serve at /api/v1/uploads.
   */
  getPublicUrl(relativePath: string, backendDomain?: string): string {
    const base = backendDomain || '';
    const clean = relativePath.replace(/\\/g, '/');
    return `${base}/api/v1/uploads/${clean}`;
  }

  /**
   * Delete a file by path (relative to uploads root or absolute).
   * No-op if file does not exist.
   */
  async deleteFile(pathOrRelative: string): Promise<void> {
    const full = pathOrRelative.startsWith(UPLOADS_ROOT)
      ? pathOrRelative
      : join(UPLOADS_ROOT, pathOrRelative);
    if (existsSync(full)) {
      await unlink(full);
    }
  }

  /** Check if a file exists (relative to uploads root or absolute) */
  exists(pathOrRelative: string): boolean {
    const full = pathOrRelative.startsWith(UPLOADS_ROOT)
      ? pathOrRelative
      : join(UPLOADS_ROOT, pathOrRelative);
    return existsSync(full);
  }
}

