export {
  getPagination,
  getPaginationMeta,
  type PaginationInput,
  type PaginationResult,
  type PaginationMeta,
} from './pagination.util';

/**
 * Pagination helper for TypeORM find options.
 * Matches Express paginator: { take, skip } from limit & page.
 */
export interface PaginationInput {
  page?: number;
  limit?: number;
}

export interface PaginationResult {
  take: number;
  skip: number;
  page: number;
  limit: number;
}

export function getPagination(params: PaginationInput): PaginationResult {
  const page = Math.max(1, params.page ?? 1);
  const limit = Math.max(1, Math.min(100, params.limit ?? 10));
  return {
    take: limit,
    skip: (page - 1) * limit,
    page,
    limit,
  };
}

/** Build pagination meta for API responses */
export interface PaginationMeta {
  page: number;
  limit: number;
  total: number;
  totalPages: number;
  hasNext: boolean;
  hasPrev: boolean;
}

export function getPaginationMeta(
  page: number,
  limit: number,
  total: number,
): PaginationMeta {
  const totalPages = Math.ceil(total / limit) || 1;
  return {
    page,
    limit,
    total,
    totalPages,
    hasNext: page < totalPages,
    hasPrev: page > 1,
  };
}

/**
 * Generate a random password with optional character sets.
 */
export function generateRandomPassword(
  length = 8,
  includeUppercase = true,
  includeNumbers = true,
): string {
  const uppercase = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  const lowercase = 'abcdefghijklmnopqrstuvwxyz';
  const numbers = '0123456789';

  let chars = lowercase;
  if (includeUppercase) chars += uppercase;
  if (includeNumbers) chars += numbers;

  let password = '';
  for (let i = 0; i < length; i++) {
    password += chars[Math.floor(Math.random() * chars.length)];
  }
  return password;
}

/** Generate a 4-digit verification code and expiration (5 minutes from now). */
export function generateVerificationCode(): {
  code: number;
  expiresAt: number;
} {
  const expiresAt = Date.now() + 5 * 60 * 1000;
  const code = Math.floor(1000 + Math.random() * 9000);
  return { code, expiresAt };
}

/** Compare stored code with incoming code (string or number). */
export function checkVerificationCode(
  existingCode: string | number | null | undefined,
  incomingCode: string | number | null | undefined,
): boolean {
  if (existingCode == null || incomingCode == null) return false;
  return String(existingCode) === String(incomingCode);
}

