import {
  CanActivate,
  ExecutionContext,
  Injectable,
  UnauthorizedException,
} from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import * as admin from 'firebase-admin';
import { DataSource, Repository } from 'typeorm';
import { IS_PUBLIC_KEY } from '../../common/decorators/public.decorator';
import { AuthenticatedPrincipal } from '../authenticated-principal.interface';
import { EXCLUDE_AUTH_GUARD_KEY } from './exclud.guard';
import { User, UserType } from '../../user/user.entity';
import { Role } from '../../role/role.entity';

type RequestWithAuth = {
  headers?: Record<string, string | string[] | undefined>;
  user?: AuthenticatedPrincipal;
  authToken?: string;
};

@Injectable()
export class AuthGuard implements CanActivate {
  private readonly userRepository: Repository<User>;
  private readonly roleRepository: Repository<Role>;

  constructor(
    private readonly reflector: Reflector,
    dataSource: DataSource,
  ) {
    this.userRepository = dataSource.getRepository(User);
    this.roleRepository = dataSource.getRepository(Role);
  }

  async canActivate(context: ExecutionContext): Promise<boolean> {
    const isPublic = this.reflector.getAllAndOverride<boolean>(IS_PUBLIC_KEY, [
      context.getHandler(),
      context.getClass(),
    ]);
    if (isPublic) return true;

    const isExcluded = this.reflector.getAllAndOverride<boolean>(
      EXCLUDE_AUTH_GUARD_KEY,
      [context.getHandler(), context.getClass()],
    );
    if (isExcluded) return true;

    const request = context.switchToHttp().getRequest<RequestWithAuth>();

    if (request.user && request.authToken) return true;

    const token = this.getHeaderValue(request.headers, 'authorization');
    if (!token) {
      throw new UnauthorizedException('Missing Authorization header');
    }

    const match = token.trim().match(/^Bearer\s+(.+)$/i);
    if (!match) {
      throw new UnauthorizedException('Invalid Authorization header format');
    }

    const normalizedToken = match[1].trim();
    if (!normalizedToken) {
      throw new UnauthorizedException('Empty bearer token');
    }

    try {
      const decodedToken = await admin.auth().verifyIdToken(normalizedToken);
      const localId = decodedToken.uid;
      const tenantId =
        this.extractString(decodedToken['tenantId']) ??
        this.extractString(decodedToken['tenant_id']) ??
        this.getHeaderValue(request.headers, 'tenantid') ??
        this.getHeaderValue(request.headers, 'tenantId');
      const email = decodedToken.email?.trim().toLowerCase();

      const serviceDeskUser = await this.resolveOrCreateServiceDeskUser({
        localId,
        email,
        tenantId,
        decodedToken,
      });

      const permissionSlugs = (serviceDeskUser.role?.permissions ?? [])
        .map((permission) => permission.slug?.trim().toLowerCase() || '')
        .filter(Boolean);

      request.user = {
        uid: localId,
        email: serviceDeskUser.email,
        tenantId: serviceDeskUser.tenant_id ?? tenantId ?? undefined,
        userId: serviceDeskUser.id,
        role: serviceDeskUser.role?.roleName?.trim().toLowerCase() || undefined,
        userType: serviceDeskUser.user_type,
        permissions: permissionSlugs,
        id: serviceDeskUser.id,
        local_id: serviceDeskUser.local_id ?? localId,
        tenant_id: serviceDeskUser.tenant_id ?? tenantId ?? undefined,
        user_type: serviceDeskUser.user_type,
      };
      request.authToken = `Bearer ${normalizedToken}`;
      return true;
    } catch {
      throw new UnauthorizedException('Invalid or expired token');
    }
  }

  private async resolveOrCreateServiceDeskUser(params: {
    localId: string;
    email?: string;
    tenantId?: string | null;
    decodedToken: admin.auth.DecodedIdToken;
  }): Promise<User> {
    const { localId, email, tenantId, decodedToken } = params;

    let user = await this.findUserForIdentity(
      localId,
      email,
      tenantId ?? undefined,
    );

    if (user?.is_deleted) {
      throw new UnauthorizedException('User is deactivated');
    }

    if (user) {
      let updated = false;
      if (!user.local_id) {
        user.local_id = localId;
        updated = true;
      }
      if (!user.tenant_id && tenantId) {
        user.tenant_id = tenantId;
        updated = true;
      }
      if (!user.email && email) {
        user.email = email;
        updated = true;
      }
      if (updated) {
        await this.userRepository.save(user);
      }
      if (!user.role?.permissions) {
        user = await this.userRepository.findOneOrFail({
          where: { id: user.id },
          relations: ['role', 'role.permissions'],
        });
      }
      return user;
    }

    if (!email) {
      throw new UnauthorizedException(
        'Cannot auto-register user without email claim',
      );
    }

    const defaultRole = await this.roleRepository
      .createQueryBuilder('role')
      .where('LOWER(role.roleName) = :roleName', { roleName: 'user' })
      .getOne();

    if (!defaultRole) {
      throw new UnauthorizedException(
        'Default role "user" not configured in Service Desk',
      );
    }

    const displayName = this.extractString(decodedToken['name']) ?? '';
    const [firstName, ...rest] = displayName.split(' ').filter(Boolean);
    const lastName = rest.join(' ');

    const created = this.userRepository.create({
      email,
      local_id: localId,
      tenant_id: tenantId ?? null,
      role_id: defaultRole.id,
      role: defaultRole,
      user_type: UserType.Employee,
      first_name: firstName || email.split('@')[0],
      last_name: lastName || '',
      password: null as unknown as string,
      phone_number: null as unknown as string,
      profile_pic: null as unknown as string,
      manager_id: null as unknown as string,
      company_id: null as unknown as string,
      team_id: null as unknown as string,
      type_id: null as unknown as string,
      priority_id: null as unknown as string,
      status_id: null as unknown as string,
      created_by: null as unknown as string,
      password_changed: false,
      is_deleted: false,
      verificationCode: null,
      passwordChangeToken: null,
      tokenExpirationTime: null,
    });

    try {
      const saved = await this.userRepository.save(created);
      return this.userRepository.findOneOrFail({
        where: { id: saved.id },
        relations: ['role', 'role.permissions'],
      });
    } catch (error) {
      if (!this.isUniqueViolation(error)) {
        throw error;
      }

      const existing = await this.findUserForIdentity(
        localId,
        email,
        tenantId ?? undefined,
      );
      if (existing) {
        return existing;
      }
      throw error;
    }
  }

  private async findUserForIdentity(
    localId: string,
    email?: string,
    tenantId?: string,
  ): Promise<User | null> {
    if (tenantId) {
      const byLocalAndTenant = await this.userRepository.findOne({
        where: { local_id: localId, tenant_id: tenantId },
        relations: ['role', 'role.permissions'],
      });
      if (byLocalAndTenant) return byLocalAndTenant;

      if (!email) return null;

      return this.userRepository.findOne({
        where: { email, tenant_id: tenantId },
        relations: ['role', 'role.permissions'],
      });
    }

    const byLocal = await this.userRepository.findOne({
      where: { local_id: localId },
      relations: ['role', 'role.permissions'],
    });
    if (byLocal) return byLocal;

    if (!email) return null;

    return this.userRepository.findOne({
      where: { email },
      relations: ['role', 'role.permissions'],
    });
  }

  private isUniqueViolation(error: unknown): boolean {
    if (!error || typeof error !== 'object') return false;
    const maybeCode = (error as { code?: string }).code;
    return maybeCode === '23505';
  }

  private getHeaderValue(
    headers: Record<string, string | string[] | undefined> | undefined,
    key: string,
  ): string | null {
    if (!headers) return null;
    const value = headers[key];
    if (!value) return null;
    return Array.isArray(value) ? value[0] : value;
  }

  private extractString(value: unknown): string | undefined {
    return typeof value === 'string' && value.trim() ? value : undefined;
  }
}

import { SetMetadata } from '@nestjs/common';

export const EXCLUDE_AUTH_GUARD_KEY = 'hasExcludedToken';
export const EXCLUDE_TENANT_GUARD_KEY = 'hasExcludedTenantId';

export const ExcludeTenantGuard = () =>
  SetMetadata(EXCLUDE_TENANT_GUARD_KEY, true);
export const ExcludeAuthGuard = () => SetMetadata(EXCLUDE_AUTH_GUARD_KEY, true);

import {
  CanActivate,
  ExecutionContext,
  ForbiddenException,
  Injectable,
} from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { REQUIRE_PERMISSIONS_KEY } from '../../common/decorators/require-permissions.decorator';
import { AuthenticatedPrincipal } from '../authenticated-principal.interface';

@Injectable()
export class PermissionsGuard implements CanActivate {
  constructor(private reflector: Reflector) {}

  private isAdminRole(role?: string): boolean {
    return (role ?? '').trim().toLowerCase() === 'admin';
  }

  canActivate(context: ExecutionContext): boolean {
    const requiredPermissions = this.reflector.getAllAndOverride<string[]>(
      REQUIRE_PERMISSIONS_KEY,
      [context.getHandler(), context.getClass()],
    );
    if (!requiredPermissions?.length) return true;

    const { user } = context
      .switchToHttp()
      .getRequest<{ user: AuthenticatedPrincipal }>();
    if (!user) {
      throw new ForbiddenException("You don't have the required permission(s)");
    }

    if (this.isAdminRole(user.role)) return true;

    const rolePermissionSlugs = (
      Array.isArray(user.permissions) ? user.permissions : []
    )
      .map((slug) => (typeof slug === 'string' ? slug.toLowerCase() : ''))
      .filter(Boolean);

    if (!rolePermissionSlugs.length) {
      throw new ForbiddenException("You don't have the required permission(s)");
    }

    const hasRequired = requiredPermissions.every((p) =>
      rolePermissionSlugs.includes(p.toLowerCase()),
    );
    if (!hasRequired) {
      throw new ForbiddenException("You don't have the required permission(s)");
    }
    return true;
  }
}

import { BadRequestException, ExecutionContext } from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { TenantGuard } from './tenant.guard';

function makeContext(headers: Record<string, string> = {}): ExecutionContext {
  return {
    switchToHttp: () => ({
      getRequest: () => ({ headers }),
    }),
    getHandler: () => 'handler',
    getClass: () => class Test {},
  } as unknown as ExecutionContext;
}

describe('TenantGuard', () => {
  let guard: TenantGuard;
  let reflector: Reflector;

  beforeEach(() => {
    reflector = {
      getAllAndOverride: jest.fn().mockReturnValue(false),
    } as unknown as Reflector;
    guard = new TenantGuard(reflector);
  });

  it('returns true for excluded route', () => {
    (reflector.getAllAndOverride as jest.Mock)
      .mockReturnValueOnce(false)
      .mockReturnValueOnce(true);

    expect(guard.canActivate(makeContext())).toBe(true);
  });

  it('throws BadRequestException for missing tenant header', () => {
    expect(() => guard.canActivate(makeContext())).toThrow(BadRequestException);
  });

  it('sets request.tenantId for valid tenant header', () => {
    const request = { headers: { tenantid: 'tenant-1' } };
    const context = {
      switchToHttp: () => ({ getRequest: () => request }),
      getHandler: () => 'handler',
      getClass: () => class Test {},
    } as unknown as ExecutionContext;

    expect(guard.canActivate(context)).toBe(true);
    expect(request.tenantId).toBe('tenant-1');
  });
});

import {
  BadRequestException,
  CanActivate,
  ExecutionContext,
  Injectable,
} from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { IS_PUBLIC_KEY } from '../../common/decorators/public.decorator';
import { EXCLUDE_TENANT_GUARD_KEY } from './exclud.guard';

type RequestWithTenant = {
  headers?: Record<string, string | string[] | undefined>;
  tenantId?: string;
};

@Injectable()
export class TenantGuard implements CanActivate {
  constructor(private readonly reflector: Reflector) {}

  canActivate(context: ExecutionContext): boolean {
    const isPublic = this.reflector.getAllAndOverride<boolean>(IS_PUBLIC_KEY, [
      context.getHandler(),
      context.getClass(),
    ]);
    if (isPublic) return true;

    const isExcluded = this.reflector.getAllAndOverride<boolean>(
      EXCLUDE_TENANT_GUARD_KEY,
      [context.getHandler(), context.getClass()],
    );
    if (isExcluded) return true;

    const request = context.switchToHttp().getRequest<RequestWithTenant>();
    const tenantId =
      this.getHeaderValue(request.headers, 'tenantid') ??
      this.getHeaderValue(request.headers, 'tenantId') ??
      this.getHeaderValue(request.headers, 'x-tenant-id');

    if (!tenantId) {
      throw new BadRequestException('tenantId In header is missing');
    }

    request.tenantId = tenantId;
    return true;
  }

  private getHeaderValue(
    headers: Record<string, string | string[] | undefined> | undefined,
    key: string,
  ): string | null {
    if (!headers) return null;
    const value = headers[key];
    if (!value) return null;
    return Array.isArray(value) ? value[0] : value;
  }
}

