import {
  IsString,
  IsOptional,
  IsUUID,
  IsArray,
  IsEmail,
} from 'class-validator';
import { Transform } from 'class-transformer';

function toTeamArray(value: unknown): string[] {
  if (Array.isArray(value))
    return value.filter((id): id is string => typeof id === 'string');
  if (typeof value === 'string') {
    try {
      const parsed = JSON.parse(value) as unknown;
      return Array.isArray(parsed)
        ? parsed.filter((id): id is string => typeof id === 'string')
        : [];
    } catch {
      return value
        .split(',')
        .map((s) => s.trim())
        .filter(Boolean);
    }
  }
  return [];
}

export class CreateUserDto {
  @IsString()
  first_name: string;

  @IsString()
  last_name: string;

  @IsEmail()
  email: string;

  @IsOptional()
  @IsString()
  user_type?: string;

  @IsOptional()
  @IsString()
  phone_number?: string;

  @IsOptional()
  @IsString()
  local_id?: string;

  @IsOptional()
  @IsString()
  tenant_id?: string;

  @IsOptional()
  @IsUUID()
  role_id?: string;

  @IsOptional()
  @IsUUID()
  team_id?: string;

  @IsOptional()
  @Transform(({ value }) => toTeamArray(value))
  @IsArray()
  @IsUUID('4', { each: true })
  teams?: string[];

  /** Alias for teams (e.g. from form field team_id_list) */
  @IsOptional()
  @Transform(({ value }) => toTeamArray(value))
  @IsArray()
  @IsUUID('4', { each: true })
  team_id_list?: string[];
}

