function formatDate(dateString: string): string {
  try {
    return new Date(dateString).toLocaleDateString(undefined, {
      month: 'short',
      day: 'numeric',
      year:
        new Date(dateString).getFullYear() !== new Date().getFullYear()
          ? 'numeric'
          : undefined,
    });
  } catch {
    return dateString;
  }
}

