'use client';

import React, { useMemo, useState } from 'react';
import {
  Building2,
  Users,
  BarChart,
  AlertCircle,
  Search,
  Plus,
  ArrowUpDown,
  TrendingUp,
  Ticket,
} from 'lucide-react';
import { CompanyAlerts } from './_components/CompanyAlerts';
import { CompanyFilters } from './_components/CompanyFilters';
import { CompanyTable } from './_components/CompanyTable';
import { CompanyUpsertDrawer } from './_components/CompanyUpsertDrawer';
import { useCompanyUiStore } from './store/companyUi';
import {
  useCompaniesFilterQuery,
  useDeleteCompanyMutation,
  type Company,
} from './_hooks/useCompanyQueries';
import { Button } from '@/components/ui/button';
import { Card, CardContent } from '@/components/ui/card';
import { Skeleton } from '@/components/ui/skeleton';
import { Badge } from '@/components/ui/badge';
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog';
import { toast } from 'sonner';

export default function CompanyPage() {
  const [page, setPage] = useState(1);
  const [limit, setLimit] = useState(10);

  const search = useCompanyUiStore((s) => s.search);
  const accountTier = useCompanyUiStore((s) => s.accountTier);

  const companiesQ = useCompaniesFilterQuery({
    company_name: search || undefined,
    account_tier: accountTier || undefined,
    page: String(page),
    limit: String(limit),
  });
  const deleteM = useDeleteCompanyMutation();

  const setIsUpsertOpen = useCompanyUiStore((s) => s.setIsUpsertOpen);
  const setUpsertMode = useCompanyUiStore((s) => s.setUpsertMode);
  const setEditingCompanyId = useCompanyUiStore((s) => s.setEditingCompanyId);

  const [isDeleteDialogOpen, setIsDeleteDialogOpen] = useState(false);
  const [deletingId, setDeletingId] = useState<string | number | null>(null);

  const companiesData = companiesQ.data as
    | { data: Company[]; total: number }
    | undefined;
  const companies = (companiesData?.data ?? []) as Company[];
  const totalCompanies = companiesData?.total ?? companies.length;

  const totalContacts = useMemo(
    () =>
      companies.reduce(
        (sum, c) => sum + (Array.isArray(c.clients) ? c.clients.length : 0),
        0,
      ),
    [companies],
  );
  const totalTickets = useMemo(
    () =>
      companies.reduce(
        (sum, c) => sum + (Array.isArray(c.tickets) ? c.tickets.length : 0),
        0,
      ),
    [companies],
  );

  const stats = [
    {
      label: 'Total Companies',
      value: totalCompanies,
      icon: Building2,
      color: '#0b2235',
    },
    {
      label: 'Total Contacts',
      value: totalContacts,
      icon: Users,
      color: '#2563eb',
    },
    {
      label: 'Total Tickets',
      value: totalTickets,
      icon: Ticket,
      color: '#7c3aed',
    },
    { label: 'Avg Health', value: '88%', icon: TrendingUp, color: '#059669' },
  ];

  const openCreate = () => {
    setUpsertMode('create');
    setEditingCompanyId(null);
    setIsUpsertOpen(true);
  };
  const openEdit = (id: string | number) => {
    setUpsertMode('edit');
    setEditingCompanyId(id);
    setIsUpsertOpen(true);
  };

  const handleDeleteConfirm = async () => {
    if (!deletingId) return;
    try {
      await deleteM.mutateAsync(deletingId);
      toast.success('Company deleted successfully');
    } catch (e: any) {
      toast.error(e?.message || 'Failed to delete company');
    } finally {
      setDeletingId(null);
      setIsDeleteDialogOpen(false);
    }
  };

  const triggerDelete = (id: string | number) => {
    setDeletingId(id);
    setIsDeleteDialogOpen(true);
  };

  return (
    <div className="flex h-full flex-col bg-muted/30">
      {/* Header Area */}
      <div className="border-b bg-background px-6 py-4">
        <div className="flex items-center justify-between mb-5">
          <div>
            <h1 className="text-[20px] font-semibold tracking-tight text-foreground">
              Companies
            </h1>
            <p className="mt-0.5 text-[13px] text-muted-foreground">
              Manage client accounts and health scores
            </p>
          </div>
          <Button
            onClick={openCreate}
            size="sm"
            className="gap-2 text-[13px] h-8 px-4"
          >
            <Plus className="w-3.5 h-3.5" />
            New Company
          </Button>
        </div>

        {/* Stats Grid */}
        <div className="grid grid-cols-4 gap-3 mb-4">
          {stats.map((s) => (
            <Card
              key={s.label}
              className="p-3 border shadow-none bg-background"
            >
              <div className="flex items-center gap-3">
                <div className="flex size-8 items-center justify-center rounded-md bg-muted">
                  <s.icon className="w-4 h-4" style={{ color: s.color }} />
                </div>
                <div>
                  <div className="text-[18px] font-bold leading-none">
                    {companiesQ.isLoading ? (
                      <Skeleton className="h-5 w-8" />
                    ) : (
                      s.value
                    )}
                  </div>
                  <div className="text-[11px] text-muted-foreground mt-0.5">
                    {s.label}
                  </div>
                </div>
              </div>
            </Card>
          ))}
        </div>

        {/* Filters Area Integration */}
        <CompanyFilters
          loading={companiesQ.isLoading}
          onRefresh={() => companiesQ.refetch()}
          onCreate={openCreate}
        />

        {companiesQ.error && (
          <div className="mt-4 flex items-center gap-2 rounded-lg border border-red-100 bg-red-50/50 p-3 text-red-600 text-[13px] font-medium">
            <AlertCircle className="h-4 w-4" />
            {(companiesQ.error as any)?.message ?? 'Failed to load companies.'}
          </div>
        )}
      </div>

      {/* Table Content */}
      <div className="flex-1 overflow-auto bg-background">
        <CompanyTable
          rows={companies}
          loading={companiesQ.isLoading}
          deletingId={deletingId}
          onEdit={openEdit}
          onDelete={triggerDelete}
          currentPage={page}
          pageSize={limit}
          totalItems={totalCompanies}
          onPageChange={(nextPage, nextPageSize) => {
            setPage(nextPage);
            setLimit(nextPageSize);
          }}
        />
      </div>

      <CompanyUpsertDrawer companies={companies} />

      <AlertDialog
        open={isDeleteDialogOpen}
        onOpenChange={setIsDeleteDialogOpen}
      >
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete Company</AlertDialogTitle>
            <AlertDialogDescription>
              Are you sure you want to delete this company? This action cannot
              be undone and will remove all associated client and ticket
              records.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={handleDeleteConfirm}
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
            >
              Delete Company
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

