    if (!editingClientId) return null;
    return (
      clients.find((c) => String(c.id) === String(editingClientId)) ?? null
    );
  }, [clients, editingClientId]);

  const handleActivate = async (id: string | number) => {
    try {
      setActivateLoadingId(id);
      await activationMutation.mutateAsync(id);
      toast.success('Activation sent successfully');
    } catch (e: any) {
      toast.error(e?.message || 'Failed to send activation');
    } finally {
      setActivateLoadingId(null);
    }
  };

  const handleDelete = async (id: string | number) => {
    try {
      setDeleteLoadingId(id);
      await deleteMutation.mutateAsync(id);
      toast.success('Contact deleted successfully');
    } catch (e: any) {
      toast.error(e?.message || 'Failed to delete contact');
    } finally {
      setDeleteLoadingId(null);
    }
  };

  const anyLoading =
    clientsQ.isLoading || companiesQ.isLoading || teamsQ.isLoading;
  const anyError = clientsQ.error || companiesQ.error || teamsQ.error;

  const stats = [
    {
      label: 'Total Contacts',
      value: totalClients,
      icon: Users,
      color: '#0b2235',
    },
    {
      label: 'Total Companies',
      value: companies.length,
      icon: Building2,
      color: '#2563eb',
    },
    {
      label: 'Total Teams',
      value: teams.length,
      icon: TagIcon,
      color: '#7c3aed',
    },
  ];

  return (
    <div className="flex h-full flex-col bg-muted/30">
      {/* Header Area */}
      <div className="border-b bg-background px-6 py-4">
        <div className="flex items-center justify-between mb-5">
          <div>
            <h1 className="text-[20px] font-semibold tracking-tight text-foreground">
              Contacts
            </h1>
            <p className="mt-0.5 text-[13px] text-muted-foreground">
              Manage client contacts, companies, and team assignments
            </p>
          </div>
          <Button
            onClick={() => setIsCreateDrawerOpen(true)}
            size="sm"
            className="gap-2 text-[13px] h-8 px-4"
          >
            <Plus className="w-3.5 h-3.5" />
            New Contact
          </Button>
        </div>

        {/* Stats Grid */}
        <div className="grid grid-cols-3 gap-3 mb-4">
          {stats.map((s) => (
            <Card
              key={s.label}
              className="p-3 border shadow-none bg-background"
            >
              <div className="flex items-center gap-3">
                <div className="flex size-8 items-center justify-center rounded-md bg-muted">
                  <s.icon className="w-4 h-4" style={{ color: s.color }} />
                </div>
                <div>
                  <div className="text-[18px] font-bold leading-none">
                    {anyLoading ? <Skeleton className="h-5 w-8" /> : s.value}
                  </div>
                  <div className="text-[11px] text-muted-foreground mt-0.5">
                    {s.label}
                  </div>
                </div>
              </div>
            </Card>
          ))}
        </div>

        {/* Filters Area Integration */}
        <ContactsFilters
          companies={companies}
          teams={teams}
          loading={anyLoading}
        />

        {anyError && (
          <div className="mt-4 flex items-center gap-2 rounded-lg border border-red-100 bg-red-50/50 p-3 text-red-600 text-[13px] font-medium">
            <AlertCircle className="h-4 w-4" />
            {(anyError as any)?.message ?? 'Failed to load contacts.'}
          </div>
        )}
      </div>

      {/* Table Content */}
      <div className="flex-1 overflow-auto bg-background">
        <ContactsTable
          rows={filteredRows}
          loading={anyLoading}
          onActivate={handleActivate}
          onDelete={handleDelete}
          activateLoadingId={activateLoadingId}
          deleteLoadingId={deleteLoadingId}
          currentPage={page}
          pageSize={limit}
          totalItems={totalClients}
          onPageChange={(nextPage, nextPageSize) => {
            setPage(nextPage);
            setLimit(nextPageSize);
          }}
        />
      </div>

      <EditContactModal
        client={editingClient}
        companies={companies}
        teams={teams}
      />
      <CreateClientDrawer companies={companies} />
    </div>
  );
}

'use client';

import React, { useMemo, useState } from 'react';
import { useRouter } from 'next/navigation';
import {
  AlignLeft,
  ArrowLeft,
  Building2,
  ChevronRight,
  Info,
  Tag,
  Users,
} from 'lucide-react';
import { toast } from 'sonner';

import { checkUserPermission } from '@/utils/permissions';
import { useClientsQuery } from '@/app/(afterLogin)/contacts/_hooks/useContactsQueries';
import {
  useClientProjectsQuery,
  useCreateTicketMutation,
  useDepartmentsQuery,
  usePrioritiesQuery,
  useSupportsQuery,
  useTicketTypesQuery,
  useUsersQuery,
} from '@/app/(afterLogin)/tickets/_hooks/useTicketsQueries';

const steps = ['Basic Info', 'Assignment', 'Review'] as const;

const fieldClasses =
  'w-full h-9 px-3 border border-[#e1e4e8] rounded-md text-[13px] text-[#1a1d21] bg-white focus:outline-none focus:ring-2 focus:ring-[#0b2235]/20 focus:border-[#0b2235] transition-all placeholder-[#9ca3af]';

const selectClasses = `${fieldClasses} appearance-none`;
const labelClasses = 'block text-[12px] font-medium text-[#4b5563] mb-1.5';

const SUPPORT_TYPE_OPTIONS = [
  'Technical Support',
  'Network Support',
  'General Support',
  'Maintenance Support',
] as const;

const TICKET_TYPE_OPTIONS = [
  'Incident',
  'Request',
  'Problem',
  'Maintenance',
  'Change',
] as const;

const PRIORITY_OPTIONS = ['Critical', 'High', 'Medium', 'Low'] as const;

type FormState = {
  clientId: string;
  projectId: string;
  supportType: string;
  teamId: string;
  fieldEngineerId: string;
  assignmentAt: string;
  subject: string;
  typeId: string;
  priorityId: string;
  deadline: string;
  description: string;
};

export default function CreateTicketPage() {
  const router = useRouter();

  const clientsQ = useClientsQuery();
  const supportsQ = useSupportsQuery();
  const typesQ = useTicketTypesQuery();
  const departmentsQ = useDepartmentsQuery();
  const prioritiesQ = usePrioritiesQuery();
  const usersQ = useUsersQuery();

  const createTicketMut = useCreateTicketMutation();

  const [step, setStep] = useState(0);
  const [form, setForm] = useState<FormState>({
    clientId: '',
    projectId: '',
    supportType: '',
    teamId: '',
    fieldEngineerId: '',
    assignmentAt: '',
    subject: '',
    typeId: '',
    priorityId: '',
    deadline: '',
    description: '',
  });

  const clientProjectsQ = useClientProjectsQuery(form.clientId);

  const update = <K extends keyof FormState>(key: K, val: FormState[K]) =>
    setForm((prev) => ({ ...prev, [key]: val }));

  const clients = clientsQ.data ?? [];
  const clientProjects = clientProjectsQ.data ?? [];

  const selectedClient = clients.find(
    (c: any) => String(c.id) === String(form.clientId),
  );

  const selectedProject = clientProjects.find((p: any) => {
    const projectIdCandidate = p?.project?.id ?? p?.id;
    return String(projectIdCandidate ?? '') === String(form.projectId);
  });

  const projectLabel =
    (selectedProject?.project?.name as string | undefined) ??
    (selectedProject?.name as string | undefined) ??
    '';

  const selectedClientLabel = selectedClient
    ? `${selectedClient.first_name ?? ''} ${selectedClient.last_name ?? ''}`.trim() ||
      (selectedClient.name as string | undefined) ||
      ''
    : '';

  const selectedType = (typesQ.data ?? []).find(
    (t: any) => String(t.id) === String(form.typeId),
  );

  const selectedPriority = (prioritiesQ.data ?? []).find(
    (p: any) => String(p.id) === String(form.priorityId),
  );

  const engineers = usersQ.data ?? [];

  const engineerLabel = useMemo(() => {
    const engineer = engineers.find(
      (u: any) => String(u.id) === String(form.fieldEngineerId),
    );
    if (!engineer) return '';
    return (
      engineer.name ??
      `${engineer.first_name ?? ''} ${engineer.last_name ?? ''}`.trim() ??
      ''
    );
  }, [engineers, form.fieldEngineerId]);

  const supportsFlat = useMemo(() => {
    const data = supportsQ.data ?? [];
    return data.flatMap((node: any) => {
      const client = node?.client ?? node;
      return client?.supports ?? [];
    });
  }, [supportsQ.data]);

  const derivedSupportId = useMemo(() => {
    if (!form.projectId || !form.clientId) return null;

    // Primary: `GET /support/client_id/:clientId` returns Support records.
    // In production, these records often do NOT include a supportType label,
    // so use (clientId + projectId) to pick the correct support and return its `id`.
    const fromClientProjects = clientProjects.find((p: any) => {
      const pClientId = p?.client?.id ?? p?.clientId ?? p?.client_id ?? null;
      const pProjectId =
        p?.project?.id ?? p?.projectId ?? p?.project_id ?? null;
      return (
        String(pClientId ?? '') === String(form.clientId) &&
        String(pProjectId ?? '') === String(form.projectId)
      );
    });
    if (fromClientProjects?.id) return String(fromClientProjects.id);

    const matchWithClient = supportsFlat.find((s: any) => {
      const typeVal = String(
        s?.supportType ?? s?.type ?? s?.project?.supportType ?? '',
      );
      const supportProjectId =
        s?.project?.id ?? s?.project?.project_id ?? s?.project_id ?? null;

      s?.project?.id ?? s?.project?.project_id ?? s?.project_id ?? null;
    const supportClientId = s?.client?.id ?? s?.client_id ?? null;

    return (
      typeVal === form.supportType &&
      String(supportProjectId ?? '') === String(form.projectId) &&
      String(supportClientId ?? '') === String(form.clientId)
    );
  });

  if (matchWithClient?.id) return String(matchWithClient.id);

  const matchWithoutClient = supportsFlat.find((s: any) => {
    const typeVal = String(
      s?.supportType ?? s?.type ?? s?.project?.supportType ?? '',
    );
    const supportProjectId =
      s?.project?.id ?? s?.project?.project_id ?? s?.project_id ?? null;
    return (
      typeVal === form.supportType &&
      String(supportProjectId ?? '') === String(form.projectId)
    );
  });

  if (matchWithoutClient?.id) return String(matchWithoutClient.id);

  // Fallback: some environments store different supportType labels/casing.
  // If user already selected client + project, prefer any support that matches those.
  const fallbackByClientProject = supportsFlat.find((s: any) => {
    const supportProjectId =
      s?.project?.id ?? s?.project?.project_id ?? s?.project_id ?? null;
    const supportClientId = s?.client?.id ?? s?.client_id ?? null;
    return (
      String(supportProjectId ?? '') === String(form.projectId) &&
      String(supportClientId ?? '') === String(form.clientId)
    );
  });

  return fallbackByClientProject?.id
    ? String(fallbackByClientProject.id)
    : null;
}, [
  clientProjects,
  supportsFlat,
  form.supportType,
  form.projectId,
  form.clientId,
]);

const teamOptions = useMemo(() => {
  const projectTeams = (selectedProject?.project?.teams ??
    selectedProject?.teams ??
    []) as Array<any>;

  if (Array.isArray(projectTeams) && projectTeams.length > 0) {
    return projectTeams
      .map((t) => ({
        id: String(t?.id ?? ''),
        label: t?.name ?? t?.type ?? '',
      }))
      .filter((t) => t.id && t.label);
  }

  const departments = departmentsQ.data ?? [];
  return departments
    .map((d: any) => ({
      id: String(d?.id ?? ''),
      label: d?.type ?? d?.name ?? '',
    }))
    .filter((t: any) => t.id && t.label);
}, [departmentsQ.data, selectedProject]);

const fieldEngineerOptions = useMemo(() => {
  return engineers
    .map((u: any) => ({
      id: String(u?.id ?? ''),
      label:
        u?.name ??
        `${u?.first_name ?? ''} ${u?.last_name ?? ''}`.trim() ??
        u?.email ??
        '',
    }))
    .filter((x: any) => x.id && x.label);
}, [engineers]);

const selectedTeamLabel = useMemo(() => {
  const t = teamOptions.find((x) => x.id === String(form.teamId));
  return t?.label ?? '';
}, [form.teamId, teamOptions]);

const projectOptions = clientProjects.map((p: any) => {
  const pid = String(p?.project?.id ?? p?.id ?? '');
  const label = p?.project?.name ?? p?.name ?? '';
  return { id: pid, label };
});

const typeOptions = (typesQ.data ?? []).map((t: any) => ({
  id: String(t.id),
  label: t.type ?? t.name ?? '',
}));

const priorityOptions = (prioritiesQ.data ?? []).map((p: any) => ({
  id: String(p.id),
  label: p.type ?? p.name ?? '',
}));

const validateStep = () => {
  if (step === 0) {
    if (
      !form.clientId ||
      !form.projectId ||
      !form.supportType ||
      !form.typeId ||
      !form.subject ||
      !form.deadline
    ) {
      toast.warning('Please fill all required fields');
      return false;
    }
  }

  if (step === 1) {
    // Only team is required; agent and timestamp are optional.
    if (!form.teamId) {
      toast.warning('Please select a team');
      return false;
    }
  }

  return true;
};

const onFinish = async () => {
  // Guard: if something changed after step navigation, re-check required fields.
  if (!validateStep()) return;

  if (!checkUserPermission(['create-ticket'])) {
    toast.error('Permission denied');
    return;
  }

  if (!derivedSupportId) {
    toast.error(
      'Unable to resolve the selected Client/Project to an active Support record. Please re-check your selections.',
    );
    return;
  }

  if (!form.typeId) {
    toast.error('Ticket type is missing');
    return;
  }

  if (!form.teamId) {
    toast.error('Team is missing');
    return;
  }

  const issues = [
    {
      name: form.subject || 'Issue',
      description: form.description || '',
      expectedEndDate: form.deadline || undefined,
    },
  ];

  const body: Record<string, any> = {
    support_id: derivedSupportId,
    type_id: form.typeId,
    subject: form.subject.trim(),
    expectedEndDate: form.deadline || undefined,
    description: form.description,
    team_ids: [form.teamId],
    client_id: form.clientId || undefined,
    project_id: form.projectId || undefined,
  };

  try {
    const res = await createTicketMut.mutateAsync({ body, issues });
    const ticketId = (res as any)?.data?.id ?? (res as any)?.data?.[0]?.id;

    toast.success('Ticket created successfully');
    router.push(ticketId ? `/tickets/${ticketId}` : '/tickets');
  } catch (e: any) {
    toast.error(e?.message ?? 'Failed to create ticket');
  }
};

return (
  <div className="min-h-full bg-[#f8f9fa] p-6">
    <div className="mx-auto w-full max-w-6xl">
      {/* Header */}
      <div className="flex items-center gap-3 mb-6">
        <button
          onClick={() => router.push('/tickets')}
          className="w-8 h-8 flex items-center justify-center text-[#6c757d] hover:text-[#0b2235] hover:bg-white border border-[#e1e4e8] rounded-md transition-colors"
        >
          <ArrowLeft className="w-4 h-4" />
        </button>
        <div>
          <h1 className="text-[20px] font-semibold text-[#0b2235]">
            Create Ticket
          </h1>
          <p className="text-[13px] text-[#6c757d]">
            Capture a new support request
          </p>
        </div>
      </div>

      {/* Progress Steps */}
      <div className="mb-6 flex items-center gap-2">
        {steps.map((s, i) => (
          <div key={s} className="flex items-center gap-2">
            <div className="flex items-center gap-2">
              <div
                className={`flex size-6 items-center justify-center rounded-full text-[11px] font-semibold transition-all ${
                  i <= step
                    ? 'bg-primary text-primary-foreground'
                    : 'bg-muted text-muted-foreground'
                }`}
              >
                {i < step ? '✓' : i + 1}
              </div>
              <span
                className={`text-[12px] font-medium ${
                  i <= step ? 'text-primary' : 'text-muted-foreground'
                }`}
              >
                {s}
              </span>
            </div>
            {i < steps.length - 1 && (
              <div
                className={`h-px w-12 ${
                  i < step ? 'bg-primary/70' : 'bg-border'
                }`}
              />
            )}
          </div>
        ))}
      </div>

      <div className="grid gap-4 lg:grid-cols-4">
        {/* Form */}
        <div className="flex flex-col gap-4 lg:col-span-3">
          {step === 0 && (
            <>
              <div className="bg-white border border-[#e1e4e8] rounded-lg p-5">
                <div className="flex items-center gap-2 mb-4">
                  <Building2 className="w-4 h-4 text-[#9ca3af]" />
                  <h3 className="text-[14px] font-semibold text-[#0b2235]">
                    Client & Support
                  </h3>
                </div>
                <div className="space-y-4">
                  <div>
                    <label className={labelClasses}>
                      Client <span className="text-red-500 ml-0.5">*</span>
                    </label>
                    <select
                      value={form.clientId}
                      onChange={(e) => {
                        const nextClientId = e.target.value;
                        update('clientId', nextClientId);
                        update('projectId', '');
                      }}
                      className={selectClasses}
                    >
                      <option value="">Select client</option>
                      {clients.map((c: any) => {

            {clients.map((c: any) => {
              const label =
                `${c.first_name ?? ''} ${c.last_name ?? ''}`.trim();
              return (
                <option key={String(c.id)} value={String(c.id)}>
                  {label || c.name || 'Client'}
                </option>
              );
            })}
          </select>
        </div>

        <div>
          <label className={labelClasses}>
            Project <span className="text-red-500 ml-0.5">*</span>
          </label>
          <select
            value={form.projectId}
            onChange={(e) => update('projectId', e.target.value)}
            className={selectClasses}
          >
            <option value="">
              {form.clientId
                ? 'Select project'
                : 'Select client first'}
            </option>
            {projectOptions.map((p) => (
              <option key={p.id} value={p.id}>
                {p.label}
              </option>
            ))}
          </select>
        </div>

        <div>
          <label className={labelClasses}>
            Support Type{' '}
            <span className="text-red-500 ml-0.5">*</span>
          </label>
          <select
            value={form.supportType}
            onChange={(e) => update('supportType', e.target.value)}
            className={selectClasses}
          >
            <option value="">Select support type</option>
            {SUPPORT_TYPE_OPTIONS.map((s) => (
              <option key={s} value={s}>
                {s}
              </option>
            ))}
          </select>
        </div>
      </div>
    </div>

    <div className="bg-white border border-[#e1e4e8] rounded-lg p-5">
      <div className="flex items-center gap-2 mb-4">
        <Tag className="w-4 h-4 text-[#9ca3af]" />
        <h3 className="text-[14px] font-semibold text-[#0b2235]">
          Ticket Details
        </h3>
      </div>
      <div className="space-y-4">
        <div>
          <label className={labelClasses}>
            Subject <span className="text-red-500 ml-0.5">*</span>
          </label>
          <input
            value={form.subject}
            onChange={(e) => update('subject', e.target.value)}
            placeholder="Brief description of the issue"
            className={fieldClasses}
          />
        </div>

        <div className="grid grid-cols-2 gap-4">
          <div>
            <label className={labelClasses}>
              Type <span className="text-red-500 ml-0.5">*</span>
            </label>
            <select
              value={form.typeId}
              onChange={(e) => update('typeId', e.target.value)}
              className={selectClasses}
            >
              <option value="">Select type</option>
              {typeOptions
                .filter((t) =>
                  (
                    TICKET_TYPE_OPTIONS as unknown as string[]
                  ).includes(t.label),
                )
                .map((t) => (
                  <option key={t.id} value={t.id}>
                    {t.label}
                  </option>
                ))}
            </select>
          </div>

          <div>
            <label className={labelClasses}>Priority</label>
            <select
              value={form.priorityId}
              onChange={(e) => update('priorityId', e.target.value)}
              className={selectClasses}
            >
              <option value="">No priority</option>
              {priorityOptions
                .filter((p) =>
                  (
                    PRIORITY_OPTIONS as unknown as string[]
                  ).includes(p.label),
                )
                .map((p) => (
                  <option key={p.id} value={p.id}>
                    {p.label}
                  </option>
                ))}
            </select>
          </div>
        </div>

        <div>
          <label className={labelClasses}>
            Expected End Date{' '}
            <span className="text-red-500 ml-0.5">*</span>
          </label>
          <input
            type="date"
            value={form.deadline}
            onChange={(e) => update('deadline', e.target.value)}
            className={fieldClasses}
          />
        </div>
      </div>
    </div>

    <div className="bg-white border border-[#e1e4e8] rounded-lg p-5">
      <div className="flex items-center gap-2 mb-4">
        <AlignLeft className="w-4 h-4 text-[#9ca3af]" />
        <h3 className="text-[14px] font-semibold text-[#0b2235]">
          Description
        </h3>
      </div>
      <textarea
        value={form.description}
        onChange={(e) => update('description', e.target.value)}
        placeholder="Describe the issue in detail — include error messages, affected systems, and steps taken..."
        rows={5}
        className="w-full px-3 py-2.5 border border-[#e1e4e8] rounded-md text-[13px] text-[#1a1d21] bg-white focus:outline-none focus:ring-2 focus:ring-[#0b2235]/20 focus:border-[#0b2235] resize-none placeholder-[#9ca3af]"
      />
    </div>
  </>
)}

{step === 1 && (
  <div className="bg-white border border-[#e1e4e8] rounded-lg p-5">
    <div className="flex items-center gap-2 mb-4">
      <Users className="w-4 h-4 text-[#9ca3af]" />
      <h3 className="text-[14px] font-semibold text-[#0b2235]">

