        className={`h-4 w-4 ${refresh.isPending ? 'animate-spin' : ''}`}
      />
      <span>Refresh</span>
    </Button>
  );
}

function useRoleAndTeamIds() {
  const role =
    (typeof window !== 'undefined' && localStorage.getItem('role')) || '';
  const teamIdRaw =
    (typeof window !== 'undefined' && localStorage.getItem('teamId')) || '';
  const teamIds = teamIdRaw
    .split(',')
    .map((t) => t.trim())
    .filter(Boolean);
  return { role, teamIds };
}

function aggregateTicketStatus(rows: TicketStatusRow[]) {
  const byStatus = new Map<string, number>();
  for (const r of rows) {
    const status = r.statustype;
    if (!status) continue;
    byStatus.set(status, (byStatus.get(status) ?? 0) + 1);
  }
  const agg: TicketStatusAgg[] = Array.from(byStatus.entries()).map(
    ([statustype, ticketcount]) => ({ statustype, ticketcount }),
  );
  agg.sort((a, b) => a.statustype.localeCompare(b.statustype));
  return agg;
}

