  const allTickets = junkTicketsQuery.data || [];

  const filteredTickets = useMemo(() => {
    return allTickets.filter((ticket) => {
      // Folder logic
      if (folder === 'Inbox' && ticket.isTransfered) return false;
      if (folder === 'Transferred' && !ticket.isTransfered) return false;

      return true;
    });
  }, [allTickets, folder]);

  const folderCounts = {
    All: allTickets.length,
    Inbox: allTickets.filter((e) => !e.isTransfered).length,
    Transferred: allTickets.filter((e) => e.isTransfered).length,
  };

  const getTicketColor = (ticket: JunkTicket) => {
    const CARD_COLORS = [
      '#7c3aed',
      '#6d28d9',
      '#1e5a8a',
      '#0e7490',
      '#0f766e',
      '#4338ca',
      '#a855f7',
    ];
    const idx =
      (ticket.subject || ticket.senderEmail || '').length % CARD_COLORS.length;
    return CARD_COLORS[idx];
  };

  const getInitials = (ticket: JunkTicket) => {
    if (ticket.first_name) {
      return `${ticket.first_name.charAt(0)}${ticket.last_name ? ticket.last_name.charAt(0) : ''}`.toUpperCase();
    }
    return (ticket.senderEmail || ticket.subject || '?')
      .charAt(0)
      .toUpperCase();
  };

  const formatEmailDate = (dateStr?: string) => {
    if (!dateStr) return '';
    const d = new Date(dateStr);
    const isToday = new Date().toDateString() === d.toDateString();
    if (isToday) {
      return d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    }
    return d.toLocaleDateString(undefined, { month: 'short', day: 'numeric' });
  };

