  const handleRestore = (ticket: JunkTicket) => {
    setTicketToTransfer(ticket);
    setIsTransferModalOpen(true);
  };

  const handleDelete = (ticket: JunkTicket) => {
    setTicketsToDelete([ticket]);
    setDeleteConfirmOpen(true);
  };

  const handleCreateTicket = (ticket: JunkTicket) => {
    setTicketForCreate(ticket);
    setCreateTicketOpen(true);
  };

  const handleViewDetails = (ticket: JunkTicket) => {
    setTicketForDetails(ticket);
    setSelectedTicketId(ticket.id);
    setIsDetailsDrawerOpen(true);
  };

const handleTransferSubmit = async (values: any) => {
  if (!ticketToTransfer) {
    // Check if bulk
    if (selectedTicketIds.length > 0) {
      try {
        await bulkActionMutation.mutateAsync({
          ticketIds: selectedTicketIds,
          action: 'restore',
          transferData: values,
        });
        toast.success(
          `${selectedTicketIds.length} tickets transferred successfully`,
        );
        setIsTransferModalOpen(false);
        clearSelection();
      } catch (error: any) {
        toast.error(error?.message || 'Failed to transfer tickets');
      }
    }
    return;
  }
  try {
    await transferMutation.mutateAsync({
      ticketId: ticketToTransfer.id,
      ...values,
    });
    toast.success('Ticket transferred successfully');
    setIsTransferModalOpen(false);
    setTicketToTransfer(null);
  } catch (error: any) {
    toast.error(error?.message || 'Failed to transfer ticket');
  }
};

const handleDeleteConfirm = async () => {
  if (ticketsToDelete.length === 0) return;
  try {
    const ids = ticketsToDelete.map((t) => t.id);
    setDeletingId(ids[0]);
    if (ids.length === 1) {
      await deleteMutation.mutateAsync(ids[0]);
      toast.success('Ticket deleted successfully');
    } else {
      await bulkActionMutation.mutateAsync({
        ticketIds: ids,
        action: 'delete',
      });
      toast.success(`${ids.length} tickets deleted successfully`);
    }
    setDeleteConfirmOpen(false);
    setTicketsToDelete([]);
    clearSelection();
  } catch (error: any) {
    toast.error(error?.message || 'Failed to delete ticket(s)');
  } finally {
    setDeletingId(null);
  }
};

