  const employees = (employeesQ.data?.rows ?? []) as Employee[];
  const total = employeesQ.data?.total ?? employees.length;

  const filteredRows = useMemo(() => {
    const s = search.trim().toLowerCase();
    return employees.filter((e) => {
      const matchesSearch =
        !s ||
        `${e.first_name ?? ''} ${e.last_name ?? ''}`
          .toLowerCase()
          .includes(s) ||
        (e.email ?? '').toLowerCase().includes(s);
      const companyId = (e.company as any)?.id ?? e.company_id ?? null;
      const matchesCompany =
        !selectedCompanyId ||
        String(companyId ?? '') === String(selectedCompanyId);
      const matchesTeam =
        !selectedTeamId ||
        (e.teams_access ?? []).some(
          (t) => String(t.id) === String(selectedTeamId),
        );
      const roleId = (e.role as any)?.id ?? e.role_id ?? null;
      const matchesRole =
        !selectedRoleId || String(roleId ?? '') === String(selectedRoleId);
      return matchesSearch && matchesCompany && matchesTeam && matchesRole;
    });
  }, [employees, search, selectedCompanyId, selectedTeamId, selectedRoleId]);

  const openCreate = () => {
    setUpsertMode('create');
    setEditingEmployeeId(null);
    setIsUpsertOpen(true);
  };
  const openEdit = (id: string | number) => {
    setUpsertMode('edit');
    setEditingEmployeeId(id);
    setIsUpsertOpen(true);
  };

  const handleDelete = async (id: string | number) => {
    try {
      setDeletingId(id);
      await deleteM.mutateAsync(id);
      toast.success('Employee deleted successfully');
