'use client';

import React, { useMemo, useState } from 'react';
import { Activity, CheckCircle2, LifeBuoy, TrendingUp } from 'lucide-react';

import { useSupportsTreeQuery } from './_hooks/useSupportListQueries';
import SupportFeatureLayer from './_feature-layer/SupportFeatureLayer';
import { openTicket } from './_feature-layer/supportFeatureEvents';
import SupportPageLayout from './_components/SupportPageLayout';
import type { SupportEngagementRow } from './_components/SupportEngagementCard';

const FEATURE_LAYER_ENABLED = false;

const TYPE_OPTIONS = [
  'Technical Support',
  'Maintenance',
  'Network Support',
  'General Support',
] as const;

const STATUS_OPTIONS = ['Active', 'Completed', 'Paused'] as const;

export default function SupportListPage() {
  const supportsQ = useSupportsTreeQuery();

  const [search, setSearch] = useState('');
  const [typeFilter, setTypeFilter] = useState<string>('all');
  const [statusFilter, setStatusFilter] = useState<string>('all');

  const engagements = useMemo<SupportEngagementRow[]>(() => {
    const tree = supportsQ.data ?? [];
    const rows: SupportEngagementRow[] = [];

    for (const node of tree) {
      const client = node?.client ?? node;
      const supports = Array.isArray(client?.supports) ? client.supports : [];

      for (const support of supports) {
        const tickets = support?.project?.tickets || support?.tickets || [];
        const resolved = tickets.filter((ticket: any) => {
          const raw =
            ticket?.ticket_status?.type ??
            ticket?.ticket_status?.name ??
            ticket?.status ??
            '';
          const normalized = String(raw).toLowerCase();
          return (
            normalized.includes('resolved') ||
            normalized.includes('closed') ||
            normalized.includes('done') ||
            ticket?.closed === true
          );
        }).length;

        const clientName =
          [client?.first_name, client?.last_name].filter(Boolean).join(' ') ||
          client?.name ||
          'Client';
        const teams = support?.project?.teams || support?.teams || [];
        const team =
          Array.isArray(teams) && teams.length > 0
            ? teams
                .map((item: any) => item?.name)
                .filter(Boolean)
                .join(', ')
            : '—';
        const type =
          support?.supportType ??
          support?.type ??
          support?.project?.supportType ??
          (support?.isCSAT ? 'CSAT Support' : 'Support');
        const status = support?.approvalStatus?.status ?? 'Active';
        const csat =
          typeof support?.csat === 'number'
            ? support.csat
            : typeof support?.csatScore === 'number'
              ? support.csatScore
              : support?.isCSAT
                ? 72
                : null;
        const id = `SUP-${support?.id ?? '—'}`;

        rows.push({
          id,
          name: support?.name ?? 'Support',
          client: clientName,
          type,
          team,
          startDate: support?.supportStartDate ?? '—',
          endDate: support?.supportEndDate ?? '—',
          csat,
          tickets: tickets.length,
          resolved,
          status,
          initials: clientName
            .split(' ')
            .filter(Boolean)
            .slice(0, 2)
            .map((part: string) => part[0]?.toUpperCase())
            .join(''),
          color: '#7c3aed',
        });
      }
    }

    rows.sort((a, b) => a.name.localeCompare(b.name));
    return rows;
  }, [supportsQ.data]);

  const filteredEngagements = useMemo(() => {
    const q = search.trim().toLowerCase();

    return engagements.filter((eng) => {
      if (q) {
        const inName = eng.name.toLowerCase().includes(q);
        const inClient = eng.client.toLowerCase().includes(q);
        if (!inName && !inClient) return false;
      }

      if (typeFilter !== 'all' && eng.type !== typeFilter) return false;
      if (statusFilter !== 'all' && eng.status !== statusFilter) return false;

      return true;
    });
  }, [engagements, search, typeFilter, statusFilter]);

  const avgCsat = useMemo(() => {
    const withCsat = filteredEngagements.filter(
      (engagement) => engagement.csat != null,
    );
    if (withCsat.length === 0) {
      return 0;
    }
    return Math.round(
      withCsat.reduce((sum, engagement) => sum + (engagement.csat ?? 0), 0) /
        withCsat.length,
    );
  }, [filteredEngagements]);

  const activeCount = filteredEngagements.filter(
    (engagement) => engagement.status === 'Active',
  ).length;

  const totalTickets = filteredEngagements.reduce(
    (sum, engagement) => sum + engagement.tickets,
    0,
  );

  const totalResolved = filteredEngagements.reduce(
    (sum, engagement) => sum + engagement.resolved,
    0,
  );

  const statItems = [
    {
      label: 'Total Engagements',
      value: filteredEngagements.length,
      icon: LifeBuoy,
      color: '#0b2235',
    },
    {
      label: 'Active',
      value: activeCount,
      icon: Activity,
      color: '#059669',
    },
    {
      label: 'Avg. CSAT',
      value: `${avgCsat}%`,
      icon: TrendingUp,
      color: '#2563eb',
    },
    {
      label: 'Resolution Rate',
      value: `${totalTickets > 0 ? Math.round((totalResolved / totalTickets) * 100) : 0}%`,
      icon: CheckCircle2,
      color: '#d97706',
    },
  ];

  return (
    <>
      <SupportPageLayout
        stats={statItems}
        engagements={filteredEngagements}
        loading={supportsQ.isLoading}
        onOpenTicket={(ticketId) => {
          if (FEATURE_LAYER_ENABLED) openTicket(ticketId);
        }}
        search={search}
        typeFilter={typeFilter}
        statusFilter={statusFilter}
        onSearchChange={setSearch}
        onTypeFilterChange={setTypeFilter}
        onStatusFilterChange={setStatusFilter}
        typeOptions={[...TYPE_OPTIONS]}
        statusOptions={[...STATUS_OPTIONS]}
      />
      <SupportFeatureLayer enabled={FEATURE_LAYER_ENABLED} />
    </>
  );
}

