'use client';

import { useMutation } from '@tanstack/react-query';
import { sendPasswordResetEmail } from 'firebase/auth';
import { getFirebaseAuth } from '@/utils/firebaseConfig';
import { ORG_AND_EMP_URL } from '@/utils/constants';
import { requestPasswordReset } from '@/api/services/orgEmp.service';
import type { ApiError } from '@/api/core/errors';
import {
  domainLabelFromHostname,
  fetchTenantClientByDomain,
} from '../authentication/login/_components/tenantChecker';

export type ForgotPasswordValues = {
  email: string;
};

type ForgotPasswordResponse = {
  message?: string;
};

async function resolveLoginTenantId(): Promise<string> {
  if (typeof window === 'undefined') return '';
  const domain = domainLabelFromHostname(window.location.hostname);
  if (domain) {
    const tenant = await fetchTenantClientByDomain(domain);
    if (tenant?.id) return tenant.id;
  }
  return process.env.NEXT_PUBLIC_DEFAULT_TENANT_ID?.trim() || '';
}

export function useForgotPasswordMutation() {
  return useMutation({
    mutationFn: async (
      values: ForgotPasswordValues,
    ): Promise<ForgotPasswordResponse> => {
      const email = values.email.trim();
      const origin =
        typeof window !== 'undefined' ? window.location.origin : '';
      const loginTenantId = await resolveLoginTenantId();

      if (ORG_AND_EMP_URL?.trim()) {
        try {
          const payload = await requestPasswordReset({
            email,
            redirectUrl: `${origin}/authentication/reset-password`,
            loginTenantId: loginTenantId || undefined,
          });
          return {
            message:
              payload?.message ||
              'If an account exists, password reset instructions have been sent.',
          };
        } catch (error) {
          const e = error as ApiError;
          throw new Error(
            e?.status === 404
              ? 'Password reset is not available for this deployment.'
