import { useClientPortalUiStore } from '../store/clientPortalUi';
import {
  useNotificationsQuery,
  useClientProfileQuery,
} from '../_hooks/useClientPortalQueries';
import { useAuthStore } from '@/store/auth';
import { URL } from '@/utils/constants';
import { CreateTicketModal } from './CreateTicketModal';

const BRAND = 'IE Network Solutions';

const pathTitles: Record<string, string> = {
  '/client-portal': 'Dashboard',
  '/client-portal/submit-ticket': 'Submit Ticket',
  '/client-portal/tickets': 'My Tickets',
  '/client-portal/knowledge-base': 'Knowledge Base',
  '/client-portal/notifications': 'Notifications',
  '/client-portal/profile': 'Profile',
};

function getPageTitle(pathname: string): string {
  if (pathTitles[pathname]) return pathTitles[pathname];
  if (pathname.match(/^\/client-portal\/tickets\/[^/]+$/))
    return 'Ticket details';
  if (pathname.startsWith('/client-portal/tickets')) return 'My Tickets';
  if (pathname.startsWith('/client-portal/knowledge-base'))
    return 'Knowledge Base';
  return 'Client Portal';
}

export function ClientPortalNavbar() {
  const pathname = usePathname() || '';
  const router = useRouter();
  const { setSidebarMobileOpen } = useClientPortalUiStore();
  const { data: notifications = [] } = useNotificationsQuery();
  const { data: profile } = useClientProfileQuery();
  const { user, logout } = useAuthStore();
  const unreadCount = notifications.filter((n) => !n.read).length;

  const title = useMemo(() => getPageTitle(pathname), [pathname]);

  const displayName =
    user?.first_name || user?.last_name
      ? `${user?.first_name ?? ''} ${user?.last_name ?? ''}`.trim()
