'use client';

import React from 'react';
import { Avatar, Typography, Spin } from 'antd';
import { UserOutlined } from '@ant-design/icons';
import { ClientProfile } from '../_hooks/useClientPortalQueries';
import { URL } from '@/utils/constants';

const { Text } = Typography;

interface ClientProfileCardProps {
  profile: ClientProfile | undefined;
  loading?: boolean;
  onEdit?: () => void;
}

export function ClientProfileCard({
  profile,
  loading,
  onEdit,
}: ClientProfileCardProps) {
  if (loading) {
    return (
      <div className="flex justify-center items-center py-8">
        <Spin size="large" />
      </div>
    );
  }

  if (!profile) {
    return (
      <div className="text-center py-8">
        <Text type="secondary">No profile data available</Text>
      </div>
    );
  }

  const getInitials = () => {
    const first = profile.first_name?.[0]?.toUpperCase() || '';
    const last = profile.last_name?.[0]?.toUpperCase() || '';
    return first + last || 'U';
  };

  const getAvatarSrc = () => {
    if (!profile.profile_pic) return undefined;
    if (profile.profile_pic.startsWith('http')) {
      return profile.profile_pic;
    }
    return URL
      ? `${URL}/${profile.profile_pic.replace(/^\//, '')}`
      : profile.profile_pic;
  };

  return (
    <div className="flex flex-col items-center" data-cy="client-profile-card">
      <Avatar
        size={120}
        src={getAvatarSrc()}
        icon={!profile.profile_pic ? <UserOutlined /> : undefined}
        style={{
          border: '4px solid var(--primary)',
          boxShadow: '0 4px 12px rgba(0,0,0,0.15)',
        }}
      >
        {!profile.profile_pic && getInitials()}
      </Avatar>
      <div className="mt-4 text-center">
        <Text
          strong
          style={{
            fontSize: '18px',
            color: 'var(--primary)',
            display: 'block',
            marginBottom: '4px',
          }}
        >
          {profile.first_name} {profile.last_name}
        </Text>
        <Text type="secondary" style={{ fontSize: '14px', display: 'block' }}>
          {profile.email}
        </Text>
      </div>
    </div>
  );
}

