import { useClientPortalUiStore } from '../store/clientPortalUi';

const { TextArea } = Input;

interface Issue {
  name: string;
  description: string;
}

export function CreateTicketModal() {
  const { isCreateTicketModalOpen, setIsCreateTicketModalOpen } =
    useClientPortalUiStore();
  const [form] = Form.useForm();
  const [issues, setIssues] = useState<Issue[]>([]);

  const createMutation = useCreateClientTicketMutation();
  const { data: projects = [], isLoading: projectsLoading } =
    useClientProjectsQuery();
  console.log(projects, 'dfdfdfd');
  const { data: types = [], isLoading: typesLoading } = useTicketTypesQuery();

  const handleSubmit = async (values: any) => {
    try {
      await createMutation.mutateAsync({
        supportId: values.supportId,
        subject: values.subject,
        type_id: values.type_id,
        description: values.description || '',
        issues: issues.length > 0 ? issues : undefined,
      });
      message.success('Ticket created successfully');
      form.resetFields();
      setIssues([]);
      setIsCreateTicketModalOpen(false);
    } catch (error: any) {
      message.error(error?.message || 'Failed to create ticket');
    }
  };

  const addIssue = () => {
    setIssues([...issues, { name: '', description: '' }]);
  };

  const removeIssue = (index: number) => {
    setIssues(issues.filter((_, i) => i !== index));
  };

  const updateIssue = (index: number, field: keyof Issue, value: string) => {

  const updateIssue = (index: number, field: keyof Issue, value: string) => {
    const updated = [...issues];
    updated[index] = { ...updated[index], [field]: value };
    setIssues(updated);
  };

  return (
    <Modal
      title={
        <span className="text-foreground font-semibold">Create New Ticket</span>
      }
      open={isCreateTicketModalOpen}
      onCancel={() => {
        setIsCreateTicketModalOpen(false);
        form.resetFields();
        setIssues([]);
      }}
      footer={null}
      width={800}
      data-cy="create-ticket-modal"
    >
      <Form
        form={form}
        layout="vertical"
        onFinish={handleSubmit}
        className="mt-4 [&_.ant-form-item-label>label]:!text-foreground"
      >
        <Form.Item
          name="supportId"
          label="Support/Project"
          rules={[{ required: true, message: 'Please select a project' }]}
        >
          <Select
            placeholder="Select a project"
            loading={projectsLoading}
            data-cy="project-select"
          >
            {projects?.map((project) => (
              <Select.Option key={project.id} value={project.id}>
                {project.name || project.project?.name}
              </Select.Option>
            ))}
          </Select>
        </Form.Item>

        <Form.Item
          name="subject"
          label="Subject"
          rules={[{ required: true, message: 'Please enter a subject' }]}
        >
          <Input placeholder="Enter ticket subject" data-cy="subject-input" />
        </Form.Item>

        <Form.Item
          name="type_id"
          label="Type"
          rules={[{ required: true, message: 'Please select a type' }]}
        >
          <Select
            placeholder="Select ticket type"
            loading={typesLoading}
            data-cy="type-select"
          >
            {types.map((type) => (
              <Select.Option key={type.id} value={type.id}>
                {type.type}
              </Select.Option>
            ))}
          </Select>
        </Form.Item>

        <Form.Item name="description" label="Description">
          <TextArea
            rows={4}
            placeholder="Enter ticket description"
            data-cy="description-textarea"
          />
        </Form.Item>

        <div className="mb-4">
          <div className="flex justify-between items-center mb-2">
            <span className="text-foreground font-medium">
              Issues (Optional)
            </span>
            <Button
              type="dashed"
              icon={<PlusOutlined />}
              onClick={addIssue}
              size="small"
            >
              Add Issue
            </Button>
          </div>

          {issues.map((issue, index) => (
            <Card
              key={index}
              className="border-border bg-muted/30 mb-2 border shadow-sm"
              size="small"
            >
              <Space direction="vertical" className="w-full">
                <Input
                  placeholder="Issue name"
                  value={issue.name}
                  onChange={(e) => updateIssue(index, 'name', e.target.value)}
                />
                <TextArea
                  rows={2}
                  placeholder="Issue description"
                  value={issue.description}
                  onChange={(e) =>
                    updateIssue(index, 'description', e.target.value)
                  }
                />
                <Button
                  type="text"
                  danger
                  icon={<MinusCircleOutlined />}
                  onClick={() => removeIssue(index)}
                  size="small"
                >
                  Remove
                </Button>
              </Space>
            </Card>
          ))}
        </div>

        <Form.Item className="mb-0">
          <Space>
            <Button
              type="primary"
              htmlType="submit"
              loading={createMutation.isPending}
              className="shadow-sm"
              data-cy="submit-ticket-button"
            >
              Create Ticket
            </Button>
            <Button
              onClick={() => {
                setIsCreateTicketModalOpen(false);
                form.resetFields();
                setIssues([]);
              }}
            >
              Cancel
            </Button>
          </Space>
        </Form.Item>
      </Form>
    </Modal>
  );
}

'use client';

import React from 'react';
import { Card, List, Typography, Badge, Empty, Spin, Button } from 'antd';
import { BellOutlined, CheckOutlined } from '@ant-design/icons';
import { Notification } from '../_hooks/useClientPortalQueries';
import { useMarkNotificationReadMutation } from '../_hooks/useClientPortalQueries';

const { Text } = Typography;

interface NotificationsListProps {
  notifications: Notification[];
  loading?: boolean;
}

export function NotificationsList({
  notifications,
  loading,
}: NotificationsListProps) {
  const markReadMutation = useMarkNotificationReadMutation();

  const handleMarkAsRead = (notificationId: string | number) => {
    markReadMutation.mutate(notificationId);
  };

  if (loading) {
    return (
      <div className="flex justify-center py-8">
        <Spin size="large" />
      </div>
    );
  }

  const unreadCount = notifications.filter((n) => !n.read).length;

  if (notifications.length === 0) {
    return (
      <Card className="border-border rounded-md border bg-card shadow-sm">
        <Empty
          description="No notifications"
          image={Empty.PRESENTED_IMAGE_SIMPLE}
        />
      </Card>
    );
  }

  return (
    <Card
      title={
        <div className="flex items-center gap-2">
          <BellOutlined className="text-primary" />
          <span className="text-foreground">Notifications</span>
          {unreadCount > 0 && <Badge count={unreadCount} showZero={false} />}
        </div>
      }
      className="border-border rounded-md border bg-card shadow-sm"
      data-cy="notifications-list"
    >
      <List
        dataSource={notifications}
        renderItem={(notification) => (
          <List.Item
            className={`border-border border-b last:border-b-0 ${
              !notification.read ? 'bg-primary/5' : ''
            }`}
          >
            <List.Item.Meta
              title={
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    <Text strong={!notification.read}>
                      {notification.title}
                    </Text>
                    {!notification.read && (
                      <span
                        className="bg-primary inline-block h-2 w-2 shrink-0 rounded-full"
                        aria-hidden
                      />
                    )}
                  </div>
                  {!notification.read && (
                    <Button
                      type="text"
                      size="small"
                      icon={<CheckOutlined />}
                      onClick={() => handleMarkAsRead(notification.id)}
                      loading={markReadMutation.isPending}
                      data-cy={`mark-read-${notification.id}`}
                    >
                      Mark as read
                    </Button>
                  )}
                </div>
              }
              description={
                <div className="space-y-1">
                  <Text type="secondary" className="text-sm">
                    {notification.message}
                  </Text>
                  <Text type="secondary" className="text-xs">
                    {new Date(notification.created_at).toLocaleString()}
                  </Text>
                </div>
              }
            />
          </List.Item>
        )}
      />
    </Card>
  );
}

'use client';

import React from 'react';
import { Card, List, Tag, Typography, Empty, Spin } from 'antd';
import { ProjectOutlined, TeamOutlined } from '@ant-design/icons';
import { ClientProject } from '../_hooks/useClientPortalQueries';

const { Text } = Typography;

interface ProjectListProps {
  projects: ClientProject[];
  loading?: boolean;
  onProjectSelect?: (projectId: string | number) => void;
  selectedProjectId?: string | number | null;
}

export function ProjectList({
  projects,
  loading,
  onProjectSelect,
  selectedProjectId,
}: ProjectListProps) {
  if (loading) {
    return (
      <div className="flex justify-center py-8">
        <Spin size="large" />
      </div>
    );
  }

  if (!projects || projects.length === 0) {
    return (
      <Card className="border-border rounded-md border bg-card shadow-sm">
        <Empty
          description="No projects available"
          image={Empty.PRESENTED_IMAGE_SIMPLE}
        />
      </Card>
    );
  }

  return (
    <Card
      title={<span className="text-foreground font-semibold">My Projects</span>}
      className="border-border rounded-md border bg-card shadow-sm"
      data-cy="project-list"
    >
      <List
        dataSource={projects}
        renderItem={(project) => {
          const projectData = project.project || project;
          const isSelected = selectedProjectId === project.id;

          return (
            <List.Item
              className={`cursor-pointer rounded-md p-3 transition-colors ${
                isSelected
                  ? 'border-primary/40 bg-primary/10 border'
                  : 'hover:bg-muted/50'
              }`}
              onClick={() => onProjectSelect?.(project.id)}
              data-cy={`project-item-${project.id}`}
            >
              <List.Item.Meta
                avatar={<ProjectOutlined className="text-primary text-2xl" />}
                title={
                  <div className="flex items-center gap-2">
                    <Text strong>{projectData.name || project.name}</Text>
                    {isSelected && (
                      <Tag className="!m-0 !border-0 !bg-primary/15 !font-medium !text-primary">
                        Selected
