import React, { useRef, useState, useEffect } from 'react';
import { useEditor, EditorContent } from '@tiptap/react';
import StarterKit from '@tiptap/starter-kit';
import TextAlign from '@tiptap/extension-text-align';
import TextStyle from '@tiptap/extension-text-style';
import Color from '@tiptap/extension-color';
import Code from '@tiptap/extension-code';
import Heading from '@tiptap/extension-heading';
import Highlight from '@tiptap/extension-highlight';
import Image from '@tiptap/extension-image';
import {
  BoldOutlined,
  ItalicOutlined,
  StrikethroughOutlined,
  OrderedListOutlined,
  UnorderedListOutlined,
  AlignLeftOutlined,
  AlignCenterOutlined,
  AlignRightOutlined,
  LinkOutlined,
  PictureOutlined,
  CodeOutlined,
  FontColorsOutlined,
  HighlightOutlined,
} from '@ant-design/icons';

interface RichTextEditorProps {
  value?: string;
  onChange?: (value: string) => void;
  placeholder?: string;
}

export function RichTextEditor({
  value = '',
  onChange,
  placeholder = 'Write something',
}: RichTextEditorProps) {
  const imageInputRef = useRef<HTMLInputElement>(null);
  const isInsertingImagesRef = useRef(false);
  const [, setHeadingUpdate] = useState({});

  const editor = useEditor({
    extensions: [
      StarterKit.configure({
        heading: false,
      }),
      Heading.configure({ levels: [1, 2, 3] }),
      TextAlign.configure({
        types: ['heading', 'paragraph'],
      }),
      TextStyle,
      Color,
      Code,
      Highlight.configure({ multicolor: true }),
      Image.configure({
        allowBase64: true,
        HTMLAttributes: {
          width: 300,
          height: 300,
          style: 'object-fit: cover;',
        },
      }),
    ],
    content: value,
    onUpdate: ({ editor }) => {
      onChange?.(editor.getHTML());
    },
    editorProps: {
      attributes: {
        class:
          'prose prose-sm sm:prose lg:prose-lg xl:prose-2xl mx-auto focus:outline-none min-h-[200px] px-4 py-2 [&_img]:max-w-full [&_img]:h-auto [&_img]:block [&_img]:rounded',
      },
    },
  });

  React.useEffect(() => {
    if (editor && !isInsertingImagesRef.current && value !== editor.getHTML()) {
      editor.commands.setContent(value);
    }
  }, [value, editor]);

  useEffect(() => {
    if (!editor) return;

  if (!editor) return;
  const onUpdate = () => setHeadingUpdate({});
  editor.on('selectionUpdate', onUpdate);
  editor.on('transaction', onUpdate);
  return () => {
    editor.off('selectionUpdate', onUpdate);
    editor.off('transaction', onUpdate);
  };
}, [editor]);

if (!editor) {
  return (
    <div className="border-border bg-card text-muted-foreground flex min-h-[220px] items-center justify-center rounded-md border text-sm">
      Loading editor…
    </div>
  );
}

return (
