'use client';

import React, { useMemo } from 'react';
import {
  Tag,
  Typography,
  Button,
  Empty,
  Spin,
  Card,
  Space,
  Avatar,
  Row,
  Col,
} from 'antd';
import { EyeOutlined, UserOutlined, CalendarOutlined } from '@ant-design/icons';
import { ClientTicket } from '../_hooks/useClientPortalQueries';
import { useClientPortalUiStore } from '../store/clientPortalUi';
import { getUserExternalId } from '@/utils/externalIdentity';
import {
  hasResolvedAssignees,
  resolveTicketAssigneeRows,
} from '@/utils/ticketAssignees';

const { Text, Title } = Typography;

interface TicketListProps {
  tickets: ClientTicket[];
  loading?: boolean;
  onTicketClick?: (ticket: ClientTicket) => void;
}

export function TicketList({
  tickets,
  loading,
  onTicketClick,
}: TicketListProps) {
  const { ticketsPagination, setTicketsPagination, ticketFilters } =
    useClientPortalUiStore();

  // Filter tickets based on UI state
  const filteredTickets = useMemo(() => {
    let filtered = [...tickets];

    if (ticketFilters.search) {
      const searchLower = ticketFilters.search.toLowerCase();
      filtered = filtered.filter(
        (t) =>
          t.subject?.toLowerCase().includes(searchLower) ||
          t.description?.toLowerCase().includes(searchLower),
      );
    }

    if (ticketFilters.status) {
      filtered = filtered.filter(
        (t) =>
          (typeof t.ticket_status === 'object'
            ? t.ticket_status?.type
            : t.ticket_status) === ticketFilters.status,
      );
    }

    if (ticketFilters.priority) {
      filtered = filtered.filter(
        (t) => t.ticket_priority?.id === ticketFilters.priority,
      );
    }

    return filtered;
  }, [tickets, ticketFilters]);

  const getStatusColor = (status: any) => {
    if (typeof status === 'object' && status?.status_color) {
      return status.status_color;
    }
    const statusType = typeof status === 'object' ? status?.type : status;
    const colorMap: Record<string, string> = {
      Open: 'blue',
      Pending: 'orange',
      Closed: 'green',
      Escalated: 'red',
    };
    return colorMap[statusType] || 'default';
  };

  const getPriorityColor = (priority: any) => {
    if (!priority) return 'default';
    const priorityType =
      typeof priority === 'object' ? priority?.type : priority;
    const colorMap: Record<string, string> = {
      High: 'red',
      Medium: 'orange',
      Low: 'blue',
    };
    return colorMap[priorityType] || 'default';
  };

  const formatDate = (dateString: string) => {
    const date = new Date(dateString);
    const now = new Date();
    const diffTime = Math.abs(now.getTime() - date.getTime());
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

    if (diffDays === 0) {
      return 'Today';
    } else if (diffDays === 1) {
      return 'Yesterday';
    } else if (diffDays < 7) {
      return `${diffDays} days ago`;
    } else {
      return date.toLocaleDateString('en-US', {
        month: 'short',
        day: 'numeric',
        year: date.getFullYear() !== now.getFullYear() ? 'numeric' : undefined,
      });
    }
  };

  if (loading) {
    return (
      <div className="flex justify-center items-center py-16">
        <Spin size="large" />
      </div>
    );
  }

  if (filteredTickets.length === 0) {
    return (
      <div className="py-16">
        <Empty
          description={
            tickets.length === 0
              ? 'No tickets found'
              : 'No tickets match your filters'
          }
          image={Empty.PRESENTED_IMAGE_SIMPLE}
        />
      </div>
    );
  }

  // Pagination logic
  const startIndex =
    (ticketsPagination.current - 1) * ticketsPagination.pageSize;
  const endIndex = startIndex + ticketsPagination.pageSize;
  const paginatedTickets = filteredTickets.slice(startIndex, endIndex);

  return (
    <div style={{ padding: '24px' }}>
      <div className="space-y-4">
        {paginatedTickets.map((ticket) => {
          const status =
            typeof ticket.ticket_status === 'object'
              ? ticket.ticket_status?.type
              : ticket.ticket_status;

        : ticket.ticket_status;
    const priority =
      typeof ticket.ticket_priority === 'object'
        ? ticket.ticket_priority?.type
        : ticket.ticket_priority;

    return (
      <Card
        key={ticket.id}
        className="rounded-lg shadow-sm hover:shadow-md transition-all cursor-pointer"
        style={{
          borderLeft: `4px solid ${getStatusColor(ticket.ticket_status)}`,
          background: 'white',
        }}
        onClick={() => onTicketClick?.(ticket)}
        data-cy={`ticket-card-${ticket.id}`}
      >
        <Row gutter={[16, 16]} align="middle">
          <Col xs={24} md={16}>
            <Space
              direction="vertical"
              size={8}
              style={{ width: '100%' }}
            >
              <div className="flex items-start justify-between gap-4">
                <Title
                  level={5}
                  style={{
                    margin: 0,
                    color: 'var(--primary)',
                    fontSize: '16px',
                    fontWeight: 600,
                    flex: 1,
                  }}
                  ellipsis={{ tooltip: ticket.subject }}
                >
                  {ticket.subject}
                </Title>
              </div>

              {ticket.description && (
                <Text
                  type="secondary"
                  ellipsis={{ tooltip: ticket.description }}
                  style={{
                    display: 'block',
                    fontSize: '14px',
                    lineHeight: '1.5',
                  }}
                >
                  {ticket.description}
                </Text>
              )}

              <Space size="middle" wrap>
                <Tag
                  color={getStatusColor(ticket.ticket_status)}
                  style={{
                    borderRadius: '4px',
                    padding: '2px 8px',
                    fontSize: '12px',
                    fontWeight: 500,
                  }}
                >
                  {status || 'N/A'}
                </Tag>
                {priority && (
                  <Tag
                    color={getPriorityColor(ticket.ticket_priority)}
                    style={{
                      borderRadius: '4px',
                      padding: '2px 8px',
                      fontSize: '12px',
                      fontWeight: 500,
                    }}
                  >
                    {priority}
                  </Tag>
                )}
                <Space size={4}>
                  <CalendarOutlined
                    style={{ fontSize: '12px', color: '#8c8c8c' }}
                  />
                  <Text type="secondary" style={{ fontSize: '12px' }}>
                    {formatDate(ticket.created_at)}
                  </Text>
                </Space>
              </Space>
            </Space>
          </Col>

          <Col xs={24} md={8}>
            <div className="flex items-center justify-end gap-4">
              {hasResolvedAssignees(ticket) && (
                <Space>
                  <Avatar.Group
                    maxCount={2}
                    size="small"
                    maxStyle={{
                      color: '#f56a00',
                      backgroundColor: '#fde3cf',
                    }}
                  >
                    {resolveTicketAssigneeRows(ticket)
                      .slice(0, 3)
                      .map((user: any) => (
                        <Avatar
                          key={String(getUserExternalId(user) ?? user.id)}
                          icon={<UserOutlined />}
                          src={user.avatar}
                        >
                          {user.name?.[0]?.toUpperCase()}
                        </Avatar>
                      ))}
                  </Avatar.Group>
                </Space>
              )}
              <Button
                type="primary"
                icon={<EyeOutlined />}
                onClick={(e) => {
                  e.stopPropagation();
                  onTicketClick?.(ticket);
                }}
                className="shadow-sm"
                data-cy={`view-ticket-${ticket.id}`}
              >
                View
              </Button>
            </div>
          </Col>
        </Row>
      </Card>
    );
  })}
</div>

{/* Pagination */}
{filteredTickets.length > ticketsPagination.pageSize && (
  <div className="flex justify-center items-center mt-6">
    <Space>
      <Button
        disabled={ticketsPagination.current === 1}
        onClick={() =>
          setTicketsPagination({
            ...ticketsPagination,
            current: ticketsPagination.current - 1,
          })
        }
      >
        Previous
      </Button>
      <Text>
        Page {ticketsPagination.current} of{' '}
        {Math.ceil(filteredTickets.length / ticketsPagination.pageSize)}
      </Text>
      <Button
        disabled={
          ticketsPagination.current >=
          Math.ceil(filteredTickets.length / ticketsPagination.pageSize)
        }

