function getCategoryName(
  categoryId: string | number | null | undefined,
  categories: KnowledgeBaseCategory[],
): string {
  if (!categoryId) return 'No Category';
  const category = categories.find((cat) => cat.id === categoryId);
  return category ? category.name : 'Unknown Category';
}

function getAuthorName(article: KnowledgeBaseArticle): string {
  const createdBy = article.createdBy;
  if (typeof createdBy === 'object' && createdBy) {
    const creator = createdBy as {
      first_name?: string;
      last_name?: string;
      email?: string;
    };
    if (creator.first_name && creator.last_name) {
      return `${creator.first_name} ${creator.last_name}`;
    }
    return creator.email || 'Unknown';
  }
  return 'Unknown';
}

function formatDate(dateString: string): string {
  return new Date(dateString).toLocaleDateString('en-US', {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
  });
}

function exportArticleAsDoc(article: KnowledgeBaseArticle) {
  const docContent = `
    <html xmlns:o='urn:schemas-microsoft-com:office:office'
          xmlns:w='urn:schemas-microsoft-com:office:word'
          xmlns='http://www.w3.org/TR/REC-html40'>
      <head>
        <meta charset='utf-8'>
        <title>${article.title}</title>
        <style>
          body { font-family: Arial, sans-serif; margin: 0; padding: 0; line-height: 1.6; }
          .header { background-color: #f8f9fa; padding: 20px; border-bottom: 2px solid #7c3aed; }
          .header-title { color: #7c3aed; font-size: 24px; font-weight: bold; margin: 0; }
          .content { padding: 40px; font-size: 16px; }
        </style>
      </head>
      <body>
        <div class="header">
          <h1 class="header-title">${article.title}</h1>
        </div>
        <div class="content">
          ${article.description ?? ''}
        </div>
      </body>
    </html>
  `;
  const blob = new Blob([docContent], {
    type: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `${article.title.replace(/[^a-z0-9]/gi, '_').toLowerCase()}.doc`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

