export type BannerState =
  | { type: 'success'; message: string }
  | { type: 'error'; message: string }
  | null;

type TicketFilterState = {
  status: string | null;
  priority: string | number | null;
  projectId: string | number | null;
  search: string;
};

type ClientPortalUiState = {
  // Selected client/project/ticket (UI state)
  selectedProjectId: string | number | null;
  setSelectedProjectId: (v: string | number | null) => void;

  selectedTicketId: string | number | null;
  setSelectedTicketId: (v: string | number | null) => void;

  // Ticket filters (UI state)
  ticketFilters: TicketFilterState;
  setTicketFilter: <K extends keyof TicketFilterState>(
    key: K,
    value: TicketFilterState[K],
  ) => void;
  resetTicketFilters: () => void;

  // Table state (pagination, sorting, etc.)
  ticketsPagination: {
    current: number;
    pageSize: number;
  };
  setTicketsPagination: (pagination: {
    current: number;
    pageSize: number;
  }) => void;

  // Modal/Drawer visibility
  isCreateTicketModalOpen: boolean;
  setIsCreateTicketModalOpen: (open: boolean) => void;

  isTicketDetailDrawerOpen: boolean;
  setIsTicketDetailDrawerOpen: (open: boolean) => void;

  isProfileEditModalOpen: boolean;
  setIsProfileEditModalOpen: (open: boolean) => void;

  // View modes
  ticketsViewMode: 'list' | 'table';
  setTicketsViewMode: (mode: 'list' | 'table') => void;

  // Global banners
  banner: BannerState;
  setBanner: (b: BannerState) => void;
  clearBanner: () => void;

  // Activity log filters
  activityLogFilters: {
    dateRange: [string, string] | null;
    actionType: string | null;
  };
  setActivityLogFilter: <
    K extends keyof ClientPortalUiState['activityLogFilters'],
  >(
    key: K,
    value: ClientPortalUiState['activityLogFilters'][K],
  ) => void;

  // Layout: sidebar (desktop collapsible, mobile overlay)
  sidebarCollapsed: boolean;
  setSidebarCollapsed: (collapsed: boolean) => void;
  toggleSidebarCollapsed: () => void;
  sidebarMobileOpen: boolean;
  setSidebarMobileOpen: (open: boolean) => void;
};

const initialState = {
  selectedProjectId: null as string | number | null,
  selectedTicketId: null as string | number | null,
  ticketFilters: {
    status: null,
    priority: null,
    projectId: null,
    search: '',
  } as TicketFilterState,
  ticketsPagination: {
    current: 1,
    pageSize: 10,
  },
  isCreateTicketModalOpen: false,
  isTicketDetailDrawerOpen: false,
  isProfileEditModalOpen: false,
  ticketsViewMode: 'table' as 'list' | 'table',
  banner: null as BannerState,
  activityLogFilters: {
    dateRange: null,
    actionType: null,
  },
  sidebarCollapsed: false,
  sidebarMobileOpen: false,
};

export const useClientPortalUiStore = create<ClientPortalUiState>((set) => ({
  ...initialState,

  setSelectedProjectId: (v) => set({ selectedProjectId: v }),
  setSelectedTicketId: (v) => set({ selectedTicketId: v }),

  setTicketFilter: (key, value) =>
    set((state) => ({
      ticketFilters: { ...state.ticketFilters, [key]: value },
    })),

  resetTicketFilters: () =>
    set({
      ticketFilters: initialState.ticketFilters,
      ticketsPagination: initialState.ticketsPagination,
    }),

  setTicketsPagination: (pagination) => set({ ticketsPagination: pagination }),

  setIsCreateTicketModalOpen: (open) => set({ isCreateTicketModalOpen: open }),
  setIsTicketDetailDrawerOpen: (open) =>
    set({ isTicketDetailDrawerOpen: open }),
  setIsProfileEditModalOpen: (open) => set({ isProfileEditModalOpen: open }),

  setTicketsViewMode: (mode) => set({ ticketsViewMode: mode }),

  setBanner: (b) => set({ banner: b }),
  clearBanner: () => set({ banner: null }),

  setActivityLogFilter: (key, value) =>
    set((state) => ({
      activityLogFilters: { ...state.activityLogFilters, [key]: value },
    })),

  setSidebarCollapsed: (collapsed) => set({ sidebarCollapsed: collapsed }),
  toggleSidebarCollapsed: () =>
    set((s) => ({ sidebarCollapsed: !s.sidebarCollapsed })),
  setSidebarMobileOpen: (open) => set({ sidebarMobileOpen: open }),
}));

