export default function SubmitTicketPage() {
  const router = useRouter();
  const [form] = Form.useForm();
  const [issues, setIssues] = useState<Issue[]>([]);
  const [description, setDescription] = useState('');
  const editorRef = useRef<{ getContent: () => string } | null>(null);
  const [editorMounted, setEditorMounted] = useState(false);

  const createMutation = useCreateClientTicketMutation();
  const { data: projects = [], isLoading: projectsLoading } =
    useClientProjectsQuery();
  const { data: types = [], isLoading: typesLoading } = useTicketTypesQuery();

  useEffect(() => {
    const t = setTimeout(() => setEditorMounted(true), 100);
    return () => clearTimeout(t);
  }, []);

  const handleSubmit = async (values: Record<string, any>) => {
    try {
      await createMutation.mutateAsync({
        supportId: values.supportId,
        subject: values.subject,
        type_id: values.type_id,
        description: description || '',
        issues: issues.length > 0 ? issues : undefined,
      });
      message.success('Ticket created successfully');
      form.resetFields();
      setIssues([]);
      setDescription('');
      router.push('/client-portal/tickets');
    } catch (error: unknown) {
      const msg =
        error && typeof error === 'object' && 'message' in error
          ? String((error as { message: string }).message)
          : 'Failed to create ticket';
      message.error(msg);
    }
  };

  const addIssue = () => {
    setIssues([...issues, { name: '', description: '' }]);
  };

  const removeIssue = (index: number) => {
    setIssues(issues.filter((_, i) => i !== index));
  };

  const updateIssue = (index: number, field: keyof Issue, value: string) => {
    const updated = [...issues];
    updated[index] = { ...updated[index], [field]: value };
    setIssues(updated);
  };

const handleCancel = () => {
  form.resetFields();
  setIssues([]);
  setDescription('');
  router.push('/client-portal');
};

