  useEffect(() => {
    if (!banner) return;
    const t = setTimeout(() => clearBanner(), 4000);
    return () => clearTimeout(t);
  }, [banner, clearBanner]);

  if (!banner) return null;

  return (
    <Alert
      type={banner.type}
      message={banner.message}
      closable
      onClose={() => clearBanner()}
      showIcon
    />
  );
