function companyLogoSrc(company: Company): string | null {
  const v = company.company_logo;
  if (!v || typeof v !== 'string') return null;
  if (v.startsWith('http://') || v.startsWith('https://')) return v;
  if (!URL) return null;
  const trimmed = v.startsWith('/') ? v : `/${v}`;
  return `${URL}${trimmed}`;
}

