import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { fetchJson, fetchMultipart } from '@/utils/api';
import { unwrapData, unwrapRowsAndTotal } from '@/api/core/envelopes';
import type { ApiEnvelope } from '@/api/types/envelopes';
import { useAuthStore } from '@/store/auth';

export type Company = {
  id: string | number;
  company_name?: string;
  description?: string;
  notes?: string;
  health_score?: number | string;
  account_tier?: string | number;
  company_logo?: string | null;
  clients?: any[];
  tickets?: any[];
  [k: string]: any;
};

export type CompanyUpsertInput = {
  company_name: string;
  description?: string;
  notes?: string;
  health_score?: number | string;
  account_tier?: string | number;
  company_logo?: File | null;
};

export type CompanyUpdateInput = Partial<CompanyUpsertInput> & {
  id: string | number;
};

function useToken() {
  const token = useAuthStore((s) => s.token);
  return (
    token ??
    (typeof window !== 'undefined' ? localStorage.getItem('token') : null)
  );
}

export type CompaniesFilterQuery = {
  company_name?: string;
  account_tier?: string;
  page?: string;
  limit?: string;
};

export function useCompaniesQuery() {
  const token = useToken();
  return useQuery({
    queryKey: ['companies'],
    queryFn: async () => {
      const res = await fetchJson<ApiEnvelope<Company[]>>('/company', {
        token,
      });
      return unwrapData<Company[]>(res, []);
    },
    enabled: !!token,
    staleTime: 60 * 1000,
  });
}

export function useCompaniesFilterQuery(filters: CompaniesFilterQuery) {
  const token = useToken();
  return useQuery({
    queryKey: ['companies-filter', filters],
    queryFn: async () => {
      const params = new URLSearchParams();
      (
        Object.entries(filters) as [
          keyof CompaniesFilterQuery,
          string | undefined,
        ][]
      ).forEach(([key, value]) => {
        if (value != null && value !== '') {
          params.append(key, value);
        }
      });
      const queryString = params.toString();
      const path = queryString ? `/company?${queryString}` : '/company';
      const res = await fetchJson<unknown>(path, { token });
      const { rows: data, total } = unwrapRowsAndTotal<Company>(res);
      return { data, total } as { data: Company[]; total: number };
    },
    enabled: !!token,
    staleTime: 60 * 1000,
  });
}

export function useCompanyQuery(companyId: string | number | null) {
  const token = useToken();
  return useQuery({
    queryKey: ['company', companyId],
    queryFn: async () => {
      const res = await fetchJson<ApiEnvelope<Company>>(
        `/company/${companyId}`,
        { token },
      );
      const d = unwrapData<Company | Company[] | null>(res, null);
      if (Array.isArray(d)) return (d[0] ?? null) as Company | null;
      return (d ?? null) as Company | null;
    },
    enabled: !!token && !!companyId,
    staleTime: 30 * 1000,
  });
}

export function useCreateCompanyMutation() {
  const token = useToken();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (input: CompanyUpsertInput) => {
      const form = new FormData();
      form.append('company_name', input.company_name);
      if (input.company_logo instanceof File)
        form.append('company_logo', input.company_logo);
      if (input.health_score !== undefined)
        form.append('health_score', String(input.health_score));
      if (input.description !== undefined)
        form.append('description', String(input.description ?? ''));
      if (input.account_tier !== undefined)
        form.append('account_tier', String(input.account_tier ?? ''));
      if (input.notes !== undefined)
        form.append('notes', String(input.notes ?? ''));

      return fetchMultipart<ApiEnvelope<Company>>('/company', {
        token,
        method: 'POST',
        form,
      });
    },
    meta: { successMessage: 'Company created successfully' },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['companies'] });
    },
  });
}

export function useUpdateCompanyMutation() {
  const token = useToken();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (input: CompanyUpdateInput) => {
      const { id, ...rest } = input;

      if (rest.company_logo instanceof File) {

      if (rest.company_logo instanceof File) {
        const form = new FormData();
        if (rest.company_name !== undefined)
          form.append('company_name', rest.company_name);
        if (rest.company_logo) form.append('company_logo', rest.company_logo);
        if (rest.health_score !== undefined)
          form.append('health_score', String(rest.health_score ?? ''));
        if (rest.description !== undefined)
          form.append('description', String(rest.description ?? ''));
        if (rest.account_tier !== undefined)
          form.append('account_tier', String(rest.account_tier ?? ''));
        if (rest.notes !== undefined)
          form.append('notes', String(rest.notes ?? ''));

        return fetchMultipart<ApiEnvelope<Company>>(`/company/${id}`, {
          token,
          method: 'PATCH',
          form,
        });
      }

      return fetchJson<ApiEnvelope<Company>>(`/company/${id}`, {
        token,
        method: 'PATCH',
        body: rest,
      });
    },
    meta: { successMessage: 'Company updated successfully' },
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({ queryKey: ['companies'] });
      queryClient.invalidateQueries({ queryKey: ['company', variables.id] });
    },
  });
}

export function useDeleteCompanyMutation() {
  const token = useToken();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (companyId: string | number) => {
      return fetchJson(`/company/${companyId}`, { token, method: 'DELETE' });
    },
    meta: { successMessage: 'Company deleted successfully' },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['companies'] });
    },
  });
}

