          onChange={(e) => setSearch(e.target.value)}
          className="h-8 bg-muted pl-9 pr-3 text-[13px] border-none shadow-none focus-visible:ring-1"
        />
      </div>

      <Select
        value={selectedCompanyId ? String(selectedCompanyId) : 'all'}
        onValueChange={(v) => setSelectedCompanyId(v === 'all' ? null : v)}
      >
        <SelectTrigger className="h-8 w-[170px] text-[13px]">
          <div className="flex items-center gap-2">
            <Building2 className="w-3.5 h-3.5 text-muted-foreground" />
