  'bg-rose-600',
];

function profilePicSrc(profile_pic?: string | null): string | undefined {
  if (!profile_pic) return undefined;
  if (profile_pic.startsWith('http://') || profile_pic.startsWith('https://'))
    return profile_pic;
  if (!URL) return undefined;
  const trimmed = profile_pic.startsWith('/') ? profile_pic : `/${profile_pic}`;
  return `${URL}${trimmed}`;
}

type ContactsTableProps = {
  rows: ClientContact[];
  loading?: boolean;
