    string | number | null
  >(null);

  const total = typeof totalItems === 'number' ? totalItems : rows.length;

  const handleDeleteTrigger = (id: string | number) => {
    setTargetDeleteId(id);
    setIsDeleteDialogOpen(true);
  };

  const confirmDelete = () => {
    if (targetDeleteId) {
