'use client';

import React, { useEffect, useState } from 'react';
import { Avatar, Form, Input, Modal, Select, Typography, Upload } from 'antd';
import type { UploadFile } from 'antd';
import {
  EditOutlined,
  UserOutlined,
  MailOutlined,
  PhoneOutlined,
  BankOutlined,
  TeamOutlined,
  PictureOutlined,
} from '@ant-design/icons';
import { useContactsUiStore } from '../store/contactsUi';
import { checkUserPermission, PERMISSIONS } from '@/utils/permissions';
import type {
  ClientContact,
  Company,
  Team,
} from '../_hooks/useContactsQueries';
import { useUpdateClientMutation } from '../_hooks/useContactsQueries';

type FormValues = {
  first_name: string;
  last_name: string;
  email?: string;
  phone_number?: string;
  companyId?: string | number;
  user_type?: string;
  team_id?: Array<string | number>;
};

export function EditContactModal({
  client,
  companies,
  teams,
}: {
  client: ClientContact | null;
  companies: Company[];
  teams: Team[];
}) {
  const [form] = Form.useForm<FormValues>();
  const isOpen = useContactsUiStore((s) => s.isEditModalOpen);
  const setIsOpen = useContactsUiStore((s) => s.setIsEditModalOpen);
  const setEditingClientId = useContactsUiStore((s) => s.setEditingClientId);
  const setBanner = useContactsUiStore((s) => s.setBanner);
  const updateMutation = useUpdateClientMutation();
  const canUpdateContact = checkUserPermission([PERMISSIONS.updateClient]);

  const [profileFile, setProfileFile] = useState<File | null>(null);
  const [profileFileList, setProfileFileList] = useState<UploadFile[]>([]);

  useEffect(() => {
    if (!client || !isOpen) return;
    form.setFieldsValue({
      first_name: client.first_name,
      last_name: client.last_name,
      email: client.email,
      phone_number: client.phone_number ?? undefined,
      companyId: (client.company as any)?.id ?? undefined,
      user_type: client.user_type,
      team_id: (client.teams_access ?? []).map((t) => t.id),
    });

    setProfileFile(null);

    if (client.profile_pic) {
      const initialFile: UploadFile = {
        uid: String(client.id),
        name: 'profile-picture',
        status: 'done',
        url: client.profile_pic,
      };
      setProfileFileList([initialFile]);
    } else {
      setProfileFileList([]);
    }
  }, [client, isOpen, form]);

  const close = () => {
    setIsOpen(false);
    setEditingClientId(null);
    form.resetFields();
    setProfileFile(null);
    setProfileFileList([]);
  };

  const onOk = async () => {
    if (!canUpdateContact) return;
    if (!client) return;
    const values = await form.validateFields();
    await updateMutation.mutateAsync({
      id: client.id,
      first_name: values.first_name,
      last_name: values.last_name,
      email: values.email,
      phone_number: values.phone_number ?? null,
      companyId: values.companyId ?? null,
      user_type: values.user_type,
      team_id: values.team_id ?? [],
      profile_pic: profileFile ?? null,
    });
    setBanner({ type: 'success', message: 'Contact updated successfully.' });
    close();
  };

  return (
    <Modal
      title={
        <div className="flex items-center gap-2.5 py-1">
          <div className="bg-primary/10 flex h-8 w-8 items-center justify-center rounded-lg">
            <EditOutlined className="text-primary text-sm" />
          </div>
          <div>
            <Typography.Text strong style={{ fontSize: 15 }}>
              Edit Contact
            </Typography.Text>
            <Typography.Text
              type="secondary"
              className="block"
              style={{ fontSize: 12 }}
            >
              Update contact information
            </Typography.Text>
          </div>
        </div>
      }
      open={isOpen}
      onCancel={close}
      onOk={onOk}
      okText="Save"
      confirmLoading={updateMutation.isPending}
      okButtonProps={{
        className: '!rounded-lg shadow-sm',
        disabled: !canUpdateContact,
      }}
      destroyOnClose
      cancelButtonProps={{ className: '!rounded-lg' }}
      styles={{ content: { borderRadius: 16 } }}
    >
      <Form
        form={form}
        layout="vertical"
        requiredMark="optional"
        className="mt-4"
      >
        <Form.Item
          label={
            <span className="flex items-center gap-1.5 text-sm">
              <PictureOutlined className="text-primary" /> Profile picture
            </span>
          }
        >
          <div className="flex items-center gap-4">
            <Avatar
              size={48}
              src={
                (profileFileList[0]?.url as string | undefined) ??
                (profileFileList[0]?.thumbUrl as string | undefined) ??
                client?.profile_pic ??
                undefined
              }
            >
              {client?.first_name?.[0]}
            </Avatar>
            <Upload
              accept="image/*"
              maxCount={1}
              listType="picture-card"
              fileList={profileFileList}
              beforeUpload={(file) => {

              beforeUpload={(file) => {
                const nextList: UploadFile[] = [
                  {
                    uid: '-1',
                    name: file.name,
                    status: 'done',
                    originFileObj: file,
                  },
                ];
                setProfileFileList(nextList);
                setProfileFile(file as File);
                return false;
              }}
              onRemove={() => {
                setProfileFileList([]);
                setProfileFile(null);
                return true;
              }}
              showUploadList={{ showPreviewIcon: false }}
            >
              {profileFileList.length === 0 && <div>Change</div>}
            </Upload>
          </div>
        </Form.Item>
        <div className="grid grid-cols-1 gap-3 md:grid-cols-2">
          <Form.Item
            name="first_name"
            label={
              <span className="flex items-center gap-1.5 text-sm">
                <UserOutlined className="text-primary" /> First name
              </span>
            }
            rules={[{ required: true, message: 'Required' }]}
          >
            <Input className="!rounded-lg" />
          </Form.Item>
          <Form.Item
