function useToken() {
  const token = useAuthStore((s) => s.token);
  return (
    token ??
    (typeof window !== 'undefined' ? localStorage.getItem('token') : null)
  );
}

export type ClientsFilterQuery = {
  email?: string;
  phone_number?: string;
  company_id?: string;
  page?: string;
  limit?: string;
};

export function useClientsQuery() {
  const token = useToken();
  return useQuery({
    queryKey: ['clients'],
    queryFn: async () => {
      const res = await fetchJson<any>('/client', { token });
      return unwrapData<ClientContact[]>(res, []);
    },
    enabled: !!token,
    staleTime: 60 * 1000,
  });
}

export function useClientsFilterQuery(filters: ClientsFilterQuery) {
  const token = useToken();
  return useQuery({
    queryKey: ['clients-filter', filters],
    queryFn: async () => {
      const params = new URLSearchParams();
      (
        Object.entries(filters) as [
          keyof ClientsFilterQuery,
          string | undefined,
        ][]
      ).forEach(([key, value]) => {
        if (value != null && value !== '') {
          params.append(key, value);
        }
      });
      const queryString = params.toString();
      const path = queryString ? `/client?${queryString}` : '/client';
      const res = await fetchJson<unknown>(path, { token });
      const { rows: data, total } = unwrapRowsAndTotal<ClientContact>(res);
      return { data, total } as { data: ClientContact[]; total: number };
    },
    enabled: !!token,
    staleTime: 60 * 1000,
  });
}

