export type CreateClientInput = {
  first_name: string;
  last_name: string;
  email: string;
  password?: string;
  phone_number?: string | null;
  company_id?: string | number | null;
  companyId?: string | number | null;
  profile_pic?: File | null;
};

export function useCreateClientMutation() {
  const token = useToken();
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: async (input: CreateClientInput) => {
      const { profile_pic, company_id, companyId, ...rest } = input;
      const finalCompanyId = company_id ?? companyId;

      // If a file is present, send multipart form-data
      if (profile_pic instanceof File) {
        const form = new FormData();
        form.append('first_name', rest.first_name);
        form.append('last_name', rest.last_name);
        form.append('email', rest.email);
        if (rest.password != null) form.append('password', rest.password);
        if (rest.phone_number !== undefined)
          form.append('phone_number', String(rest.phone_number ?? ''));
        if (finalCompanyId) form.append('company_id', String(finalCompanyId));
        if (profile_pic) form.append('profile_pic', profile_pic);

        return fetchMultipart('/client', { token, method: 'POST', form });
      }

      // Otherwise, send JSON
      return fetchJson('/client', {
        token,
        method: 'POST',
        body: {
          ...rest,
          company_id: finalCompanyId ?? undefined,
        },
      });
    },
    meta: { successMessage: 'Contact created successfully' },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['clients'] });
    },
  });
}

export function useUpdateClientMutation() {
  const token = useToken();
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: async (input: UpdateClientInput) => {
      const { id, profile_pic, ...rest } = input;

      // If a file is present, send multipart form-data (backend legacy behavior).
      if (profile_pic instanceof File) {
        const form = new FormData();
        if (profile_pic) form.append('profile_pic', profile_pic);
        if (rest.first_name) form.append('first_name', rest.first_name);
        if (rest.last_name) form.append('last_name', rest.last_name);
        if (rest.email) form.append('email', rest.email);
        if (rest.phone_number !== undefined)
          form.append('phone_number', String(rest.phone_number ?? ''));
        if (rest.user_type) form.append('user_type', rest.user_type);
        if (rest.companyId !== undefined)
          form.append('companyId', String(rest.companyId ?? ''));
        if (rest.team_id?.length) {
          rest.team_id.forEach((t, idx) =>
            form.append(`team_id[${idx}]`, String(t)),
          );
        }

        return fetchMultipart(`/client/${id}`, {
          token,
          method: 'PATCH',
          form,
        });
      }

      // Otherwise, prefer JSON for simplicity.
      return fetchJson(`/client/${id}`, { token, method: 'PATCH', body: rest });
    },
    meta: { successMessage: 'Contact updated successfully' },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['clients'] });
    },
  });
}

