  '#7c3aed',
  '#1d4ed8',
  '#0891b2',
  '#059669',
  '#dc2626',
];

function stablePaletteHex(seed: string): string {
  let h = 0;
  for (let i = 0; i < seed.length; i++) {
    h = Math.imul(31, h) + seed.charCodeAt(i);
  }
  const idx = Math.abs(h) % DESIGN_AVATAR_PALETTE_HEX.length;
  return DESIGN_AVATAR_PALETTE_HEX[idx] ?? '#7c3aed';
}

