function MultiSelect({
  title,
  options,
  selectedValues,
  onChange,
  icon: Icon,
}: {
  title: string;
  options: { value: string | number; label: string }[];
  selectedValues: (string | number)[];
  onChange: (vals: (string | number)[]) => void;
  icon: any;
}) {
  return (
    <Popover>
      <PopoverTrigger asChild>
        <Button
          variant="outline"
          size="sm"
          className="h-10 border-border/60 px-3 bg-background hover:bg-muted/50 justify-between min-w-[180px] rounded-lg shadow-sm"
        >
          <div className="flex items-center gap-2">
            <Icon className="size-4 text-primary/60" />
            <span className="text-[13px] font-bold text-foreground/80">
              {title}
            </span>
            {selectedValues.length > 0 && (
              <>
                <Separator
                  orientation="vertical"
                  className="mx-1 h-4 bg-border/60"
                />
                <Badge
                  variant="secondary"
                  className="rounded-md px-1 font-bold text-[10px] bg-primary/5 text-primary border-primary/20"
                >
                  {selectedValues.length}
                </Badge>
              </>
            )}
          </div>
          <ChevronDown className="size-3.5 text-muted-foreground opacity-50 ml-2" />
        </Button>
      </PopoverTrigger>
      <PopoverContent
        className="w-[220px] p-0 shadow-xl border-border/60"
        align="start"
      >
        <Command>
          <CommandInput
            placeholder={`Search ${title.toLowerCase()}...`}
            className="h-9 text-[13px]"
          />
          <CommandList className="max-h-[220px]">
            <CommandEmpty className="py-4 text-[12px] text-muted-foreground text-center">
              No results found.
            </CommandEmpty>
            <CommandGroup className="p-1">
              {options.map((option) => {
                const isSelected = selectedValues.includes(option.value);
                return (
                  <CommandItem
                    key={option.value}
                    onSelect={() => {
                      const newValues = isSelected
                        ? selectedValues.filter((v) => v !== option.value)
                        : [...selectedValues, option.value];
                      onChange(newValues);
                    }}
                    className="gap-2 px-2 py-1.5 cursor-pointer text-[13px] font-medium rounded-md"
                  >
                    <div
                      className={`size-4 border rounded-sm flex items-center justify-center transition-colors ${isSelected ? 'bg-primary border-primary text-primary-foreground font-bold' : 'bg-transparent border-border/60'}`}
                    >
                      {isSelected && <Check className="size-3 stroke-[3]" />}
                    </div>
                    {option.label}
                  </CommandItem>
                );
              })}
            </CommandGroup>
            {selectedValues.length > 0 && (
              <>
                <CommandSeparator />
                <CommandGroup>
                  <CommandItem
                    onSelect={() => onChange([])}
                    className="justify-center text-center font-bold text-[12px] text-primary/80 py-2 cursor-pointer hover:text-primary"
                  >
                    Clear Filters
                  </CommandItem>
                </CommandGroup>
              </>
            )}
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  );
}

