  '#059669',
  '#dc2626',
  '#0891b2',
];

/** Canonical 8-4-4-4-12 hex IDs — never shown as ticket subtitle labels */
const UUID_RE =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const NUMERIC_CODE_RE = /^[0-9]{4,}$/;
const DATE_PART_RE = /^[0-9]{1,4}$/;

type ParsedTicketSubject = {
  cleanTitle: string;
  parsedCode?: string;
  siteToken?: string;
};

function isUuidLike(s: string): boolean {
  return UUID_RE.test(s.trim());
}

/**
 * Parses structured subjects like:
 * 000131/02/05/2026/INTERNAL/MOTI Virtual machine access issue
 * into clean title + optional code and site token.
 */
function parseTicketSubject(rawSubject: string): ParsedTicketSubject {
  const subject = rawSubject.trim();
  if (!subject.includes('/')) return { cleanTitle: subject };

  const parts = subject
    .split('/')
    .map((p) => p.trim())
    .filter(Boolean);
  if (parts.length < 4) return { cleanTitle: subject };

  const maybeCode = parts[0] ?? '';
  if (!NUMERIC_CODE_RE.test(maybeCode)) return { cleanTitle: subject };

  let index = 1;
  const dateParts: string[] = [];
  while (index < parts.length && DATE_PART_RE.test(parts[index] ?? '')) {
    dateParts.push(parts[index] as string);
    index += 1;
    if (dateParts.length >= 3) break;
  }

  if (dateParts.length < 2 || index >= parts.length - 1) {
    return { cleanTitle: subject };
  }

  // Category segment exists but is intentionally omitted from display.
  index += 1;
  if (index >= parts.length) return { cleanTitle: subject };

  const cleanTitle = parts.slice(index).join('/').trim();
  if (!cleanTitle) return { cleanTitle: subject };

  const siteToken = cleanTitle.split(/\s+/).find(Boolean);
  return {
    cleanTitle,
    parsedCode: maybeCode,
    siteToken,
  };
}

function subtitleCodePart(
  ticketCode: string | undefined,
  parsedCode: string | undefined,
  fallbackId: string,
): string | null {
  const explicit = ticketCode?.trim().replace(/^#/, '');
  if (explicit && !isUuidLike(explicit)) return `#${explicit}`;
  if (parsedCode) return `#${parsedCode}`;

  const id = fallbackId.trim();
  if (!id || isUuidLike(id) || id.length > 16) return null;
  return `#${id.replace(/^#/, '')}`;
}

function buildTicketSubtitleMeta(
  codePart: string | null,
  companyName: string | undefined,
  siteToken: string | undefined,
): string | null {
  const company = companyName?.trim();
  const site = siteToken?.trim();
  const orgLabel = company || site;
  if (codePart && orgLabel) return `${codePart} · ${orgLabel}`;
  if (codePart) return codePart;
  if (orgLabel) return orgLabel;
  return null;
}

function initialsFromToken(token: string | undefined): string | null {
  const value = token?.trim();
  if (!value) return null;

  const words = value.split(/\s+/).filter(Boolean);
  if (words.length >= 2) {
    return `${words[0]![0] ?? ''}${words[1]![0] ?? ''}`.toUpperCase();
  }

  const alnum = value.replace(/[^a-zA-Z0-9]/g, '');
  if (alnum.length >= 2) return alnum.slice(0, 2).toUpperCase();
  if (alnum.length === 1) return `${alnum[0]}${alnum[0]}`.toUpperCase();
  return null;
}

function ticketRowInitials(
  companyName: string | undefined,
  siteToken: string | undefined,
  ticketCode: string | undefined,
  cleanTitle: string,
): string {
  const companyInitials = initialsFromToken(companyName);
  if (companyInitials) return companyInitials;

  const siteInitials = initialsFromToken(siteToken);
  if (siteInitials) return siteInitials;

  const code = ticketCode?.trim().replace(/^#/, '') ?? '';
  if (code && !/^0+$/.test(code)) {
    const digits = code.replace(/[^0-9]/g, '');
    if (digits.length >= 2) return digits.slice(-2);
    const codeInitials = initialsFromToken(code);
    if (codeInitials) return codeInitials;
  }

  const titleInitials = initialsFromToken(cleanTitle);
  if (titleInitials) return titleInitials;
  return 'TK';
}

