const PERIODS = ['7d', '30d', '90d'] as const;

const trendChartConfig = {
  created: {
    label: 'Created',
    color: 'var(--chart-3)',
  },
  resolved: {
    label: 'Resolved',
    color: 'var(--chart-4)',
  },
} satisfies ChartConfig;

export function TicketActivityChart() {
  const [period, setPeriod] = useState<'7d' | '30d' | '90d'>('7d');
  const activityQ = useTicketActivityQuery(period);

  const trendData = useMemo(() => {
    const data = activityQ.data ?? [];
    return data.map((p) => ({
      date: p.date,
      created: Number(p.created ?? 0),
      resolved: Number(p.resolved ?? 0),
    }));
  }, [activityQ.data]);

  const maxY = useMemo(() => {
    let m = 0;
    for (const p of trendData) {
      m = Math.max(m, p.created ?? 0, p.resolved ?? 0);
    }
    return m;
  }, [trendData]);

  return (
    <Card className="w-full lg:col-span-2 gap-0 p-0 shadow-none border-border">
      <CardHeader className="flex flex-row items-center justify-between">
        <div>
          <CardTitle className="text-[14px] font-semibold">
            Ticket Activity
          </CardTitle>
          <CardDescription className="mt-0.5 text-[12px]">
            Created vs. Resolved
          </CardDescription>
        </div>
        <div className="flex items-center gap-1 rounded-md border border-border bg-muted p-0.5">
          {PERIODS.map((p) => (
            <Button
              key={p}
              onClick={() => setPeriod(p)}
              variant={period === p ? 'secondary' : 'ghost'}
              size="sm"
              className="h-7 px-2.5 text-[12px] font-medium"
            >
              {p}
            </Button>
          ))}
        </div>
      </CardHeader>
      <CardContent className="pb-5">
        {activityQ.isLoading ? (
          <div className="h-[220px] w-full">
            <Skeleton className="h-full w-full" />
          </div>
        ) : (
          <ChartContainer config={trendChartConfig} className="h-[220px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart
                data={trendData}
                margin={{ top: 4, right: 4, left: -20, bottom: 0 }}
              >
                <defs>
                  <linearGradient id="gCreated" x1="0" y1="0" x2="0" y2="1">
                    <stop
                      offset="0%"
                      stopColor="var(--chart-3)"
                      stopOpacity={0.12}
                    />
                    <stop
                      offset="100%"
                      stopColor="var(--chart-3)"
                      stopOpacity={0}
                    />
                  </linearGradient>
                  <linearGradient id="gResolved" x1="0" y1="0" x2="0" y2="1">
                    <stop
                      offset="0%"
                      stopColor="var(--chart-4)"
                      stopOpacity={0.12}
                    />
                    <stop
                      offset="100%"
                      stopColor="var(--chart-4)"
                      stopOpacity={0}
                    />
                  </linearGradient>
                </defs>
                <CartesianGrid
                  strokeDasharray="3 3"
                  stroke="var(--border)"
                  vertical={false}
                />
                <XAxis
                  dataKey="date"
                  tick={{ fill: 'var(--muted-foreground)', fontSize: 11 }}
                  axisLine={false}
                  tickLine={false}
                  tickFormatter={(v) => String(v).slice(5)} // MM-DD
                />
                <YAxis
                  tick={{ fill: 'var(--muted-foreground)', fontSize: 11 }}
                  axisLine={false}
                  tickLine={false}
                  domain={[0, Math.max(3, maxY)]}
                  allowDecimals={false}
                />
                <ChartTooltip content={<ChartTooltipContent indicator="dot" />} />
                <ChartLegend content={<ChartLegendContent />} />
                <Area
                  type="monotone"
                  dataKey="created"
                  stroke="var(--chart-3)"
                  strokeWidth={2}
                  fill="url(#gCreated)"
                  name="Created"
                  dot={false}
                />
                <Area
                  type="monotone"
                  dataKey="resolved"
                  stroke="var(--chart-4)"
                  strokeWidth={2}
                  fill="url(#gResolved)"
                  name="Resolved"
                  dot={false}
                />
              </AreaChart>
            </ResponsiveContainer>
          </ChartContainer>
        )}
      </CardContent>
    </Card>
