  ChartTooltipContent,
  type ChartConfig,
} from '@/components/ui/chart';
import { Skeleton } from '@/components/ui/skeleton';

const STATUS_COLORS: Record<string, string> = {
  Open: 'var(--status-open)',
  Pending: 'var(--status-pending)',
  Escalated: 'var(--status-escalated)',
  Closed: 'var(--status-closed)',
  Resolved: 'var(--status-resolved)',
};

const PRIORITY_COLORS: Record<string, string> = {
  Critical: 'var(--error)',
  High: 'var(--warning)',
  Medium: 'var(--info)',
  Low: 'var(--primary)',
  Unassigned: 'var(--border)',
};

const DEFAULT_COLORS = [
  'var(--chart-1)',
  'var(--chart-5)',
  'var(--error)',
  'var(--status-closed)',
  'var(--chart-4)',
  'var(--chart-3)',
  'var(--info)',
];

const statusChartConfig = {
  count: { label: 'Tickets', color: 'var(--chart-1)' },
} satisfies ChartConfig;

const priorityChartConfig = {
  value: { label: 'Tickets', color: 'var(--foreground)' },
} satisfies ChartConfig;

export function TicketsByStatusChart() {
  const statusQ = useTicketsByStatusDashboardQuery();
  const priorityQ = useTicketsByPriorityDashboardQuery();

  const isLoading = statusQ.isLoading || priorityQ.isLoading;
  const isError = statusQ.isError || priorityQ.isError;

  if (isLoading)
    return (
      <Card className="h-[400px] w-full p-6">
        <Skeleton className="h-full w-full" />
      </Card>
    );
  if (isError || !statusQ.data) return null;

  const totalTickets = statusQ.data.reduce((acc, curr) => acc + curr.count, 0);
  const statusData = statusQ.data.map((d, i) => ({
    name: d.statusType,
    count: d.count,
    fill:
      STATUS_COLORS[d.statusType] || DEFAULT_COLORS[i % DEFAULT_COLORS.length],
  }));

  const priorityChartData = (priorityQ.data ?? []).map((d) => ({
    name: d.priorityType || 'Unassigned',
    value: d.count,
    fill: PRIORITY_COLORS[d.priorityType] || PRIORITY_COLORS.Unassigned,
  }));

  return (
    <Card className="w-full gap-0 p-0 shadow-none border-border overflow-hidden bg-background">
      <CardHeader>
        <CardTitle className="text-[14px] font-semibold">
          Status Distribution
        </CardTitle>
        <CardDescription className="text-[12px]">
          {totalTickets} total tickets
        </CardDescription>
      </CardHeader>
      <CardContent>
        <ChartContainer config={statusChartConfig} className="h-[170px] w-full">
          <BarChart
            data={statusData}
            margin={{ top: 4, right: 4, left: -16, bottom: 0 }}
          >
            <CartesianGrid
              vertical={false}
              strokeDasharray="3 3"
              stroke="var(--border)"
            />
            <XAxis
              dataKey="name"
              tickLine={false}
              axisLine={false}
              tick={{ fontSize: 11, fill: 'var(--muted-foreground)' }}
            />
            <YAxis
              allowDecimals={false}
              tickLine={false}
              axisLine={false}
              tick={{ fontSize: 11, fill: 'var(--muted-foreground)' }}
            />
            <ChartTooltip
              content={
                <ChartTooltipContent
                  formatter={(value) => (
                    <span className="font-medium">{value} tickets</span>
                  )}
                />
              }
            />
            <Bar dataKey="count" radius={4}>
              {statusData.map((entry, index) => (
                <Cell key={`cell-${index}`} fill={entry.fill} />
              ))}
            </Bar>
          </BarChart>
        </ChartContainer>

        <div className="mt-5 border-t pt-4">
          <h4 className="mb-3 text-[13px] font-semibold">Priority Breakdown</h4>
          <ChartContainer
            config={priorityChartConfig}
            className="h-[140px] w-full"
          >
            <BarChart
              data={priorityChartData}
              layout="vertical"
              margin={{ top: 0, right: 8, left: 8, bottom: 0 }}
            >
              <CartesianGrid
                horizontal={false}
                strokeDasharray="3 3"
                stroke="var(--border)"
              />
              <XAxis type="number" hide />
              <YAxis
                type="category"
                dataKey="name"
                tickLine={false}
                axisLine={false}
                tick={{ fontSize: 11, fill: 'var(--muted-foreground)' }}
                width={72}
              />
              <ChartTooltip
                content={
                  <ChartTooltipContent
                    formatter={(value) => (
                      <span className="font-medium">{value} tickets</span>
                    )}
                  />
                }
              />
              <Bar dataKey="value" radius={4}>
                {priorityChartData.map((entry) => (
                  <Cell key={entry.name} fill={entry.fill} />
                ))}
              </Bar>
            </BarChart>
          </ChartContainer>
        </div>
      </CardContent>
    </Card>
  );
}

'use client';

import React from 'react';
