export type TicketStatusAgg = {
  statustype: string;
  ticketcount: number;
};

const STATUS_PALETTE: Record<
  string,
  { bg: string; text: string; accent: string }
> = {
  open: {
    bg: 'bg-blue-50/50',
    text: 'text-blue-700',
    accent: 'border-blue-500',
  },
  'in progress': {
    bg: 'bg-emerald-50/50',
    text: 'text-emerald-700',
    accent: 'border-emerald-500',
  },
  pending: {
    bg: 'bg-amber-50/50',
    text: 'text-amber-700',
    accent: 'border-amber-500',
  },
  closed: {
    bg: 'bg-slate-50/50',
    text: 'text-slate-700',
    accent: 'border-slate-500',
  },
  resolved: {
    bg: 'bg-teal-50/50',
    text: 'text-teal-700',
    accent: 'border-teal-500',
  },
  escalated: {
    bg: 'bg-rose-50/50',
    text: 'text-rose-700',
    accent: 'border-rose-500',
  },
};

function getStatusColors(status: string) {
  const key = status.toLowerCase().trim();
  return (
    STATUS_PALETTE[key] ?? {
      bg: 'bg-muted/10',
      text: 'text-foreground',
      accent: 'border-primary',
    }
  );
}

export function TicketStatusCards({
  items,
  rawRows,
}: {
  items: TicketStatusAgg[];
  rawRows: TicketStatusRow[];
}) {
  if (!items.length) {
    return (
      <div className="flex flex-col items-center justify-center py-10 border border-dashed rounded-xl bg-muted/5">
        <Inbox className="size-10 text-muted-foreground/30 mb-3" />
        <p className="text-muted-foreground text-[13px] font-medium">
          No ticket activities found for this status.
        </p>
      </div>
    );
  }

  return (
    <div
      className="grid grid-cols-2 lg:grid-cols-4 gap-4"
      data-cy="dashboard-ticket-status-cards"
    >
      {items.map((item) => {
        const colors = getStatusColors(item.statustype);
        return (
          <Card
            key={item.statustype}
            className={`relative overflow-hidden border-border/40 transition-all duration-300 hover:shadow-md cursor-default group ${colors.bg}`}
          >
            <div
              className={`absolute top-0 left-0 w-1 h-full opacity-70 ${colors.accent.replace('border-', 'bg-')}`}
            />
            <CardContent className="p-4 flex flex-col justify-between h-full">
              <div>
                <p
                  className={`text-[10px] font-bold uppercase tracking-widest opacity-80 ${colors.text}`}
                >
                  {item.statustype}
                </p>
                <p
                  className={`mt-1 text-3xl font-bold tabular-nums tracking-tight ${colors.text}`}
                >
                  {item.ticketcount}
                </p>
              </div>
              <div className="mt-3 flex items-center justify-between">
                <p className="text-[11px] font-medium text-muted-foreground/70">
                  Total Distribution
                </p>
                <div className="text-[11px] font-bold px-1.5 py-0.5 rounded-md bg-white/50 border border-black/5">
                  {Math.round((item.ticketcount / (rawRows.length || 1)) * 100)}
                  %
                </div>
              </div>
            </CardContent>
          </Card>
        );
      })}
    </div>
  );
}

