'use client';

import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { useAuthStore } from '@/store/auth';
import {
  getDashboardSummary,
  getTicketsByStatus,
  getTicketsByPriority,
  getRecentTickets,
  getAgentPerformance,
  getTicketActivity,
} from '@/utils/dashboard.service';
import type { TicketActivityPoint } from '@/types/dashboard';

function useToken() {
  const token = useAuthStore((s) => s.token);
  return (
    token ??
    (typeof window !== 'undefined' ? localStorage.getItem('token') : null)
  );
}

export const DASHBOARD_QUERY_KEY = 'dashboard';

export function useDashboardSummaryQuery() {
  const token = useToken();
  return useQuery({
    queryKey: [DASHBOARD_QUERY_KEY, 'summary'],
    queryFn: () => getDashboardSummary(token),
    enabled: !!token,
    staleTime: 60 * 1000,
  });
}

export function useTicketsByStatusDashboardQuery() {
  const token = useToken();
  return useQuery({
    queryKey: [DASHBOARD_QUERY_KEY, 'tickets-by-status'],
    queryFn: () => getTicketsByStatus(token),
    enabled: !!token,
    staleTime: 60 * 1000,
  });
}

export function useTicketsByPriorityDashboardQuery() {
  const token = useToken();
  return useQuery({
    queryKey: [DASHBOARD_QUERY_KEY, 'tickets-by-priority'],
    queryFn: () => getTicketsByPriority(token),
    enabled: !!token,
    staleTime: 60 * 1000,
  });
}

export function useRecentTicketsQuery(limit = 10) {
  const token = useToken();
  return useQuery({
    queryKey: [DASHBOARD_QUERY_KEY, 'recent-tickets', limit],
    queryFn: () => getRecentTickets(token, limit),
    enabled: !!token,
    staleTime: 30 * 1000,
  });
}

export function useAgentPerformanceQuery() {
  const token = useToken();
  return useQuery({
    queryKey: [DASHBOARD_QUERY_KEY, 'agent-performance'],
    queryFn: () => getAgentPerformance(token),
    enabled: !!token,
    staleTime: 60 * 1000,
  });
}

export function useTicketActivityQuery(period: '7d' | '30d' | '90d' = '7d') {
  const token = useToken();
  return useQuery({
    queryKey: [DASHBOARD_QUERY_KEY, 'ticket-activity', period],
    queryFn: () => getTicketActivity(token, period),
    enabled: !!token,
    staleTime: 30 * 1000,
    select: (data) => (Array.isArray(data) ? data : ([] as TicketActivityPoint[])),
  });
}

/** Mutation: invalidates all dashboard queries (refresh). Use with Zustand or buttons. */
export function useRefreshDashboardMutation() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: async () => {
      await queryClient.invalidateQueries({ queryKey: [DASHBOARD_QUERY_KEY] });
    },
    meta: { successMessage: 'Dashboard refreshed successfully' },
  });
}

