'use client';

import React from 'react';
import { Button, Space, Typography } from 'antd';
import { DeleteOutlined, UndoOutlined, CloseOutlined } from '@ant-design/icons';
import { useJunkTicketUiStore } from '../store/junkTicketUi';

const { Text } = Typography;

type BulkActionsBarProps = {
  selectedCount: number;
  onRestore?: () => void;
  onDelete?: () => void;
  onClearSelection?: () => void;
};

export function BulkActionsBar({
  selectedCount,
  onRestore,
  onDelete,
  onClearSelection,
}: BulkActionsBarProps) {
  const clearSelection = useJunkTicketUiStore((s) => s.clearSelection);

  if (selectedCount === 0) return null;

  const handleClear = () => {
    clearSelection();
    onClearSelection?.();
  };

  return (
    <div className="border-primary/20 bg-primary/5 flex flex-wrap items-center justify-between gap-3 rounded-xl border px-5 py-3.5">
      <Text strong className="text-foreground text-[13px]">
        {selectedCount} ticket{selectedCount !== 1 ? 's' : ''} selected
      </Text>
      <Space size="middle" wrap>
        {onRestore && (
          <Button
            type="primary"
            icon={<UndoOutlined />}
            onClick={onRestore}
            className="!rounded-lg shadow-sm"
          >
            Restore selected
          </Button>
        )}
        {onDelete && (
          <Button
            danger
            icon={<DeleteOutlined />}
            onClick={onDelete}
            className="!rounded-lg"
          >
            Delete selected
          </Button>
        )}
        <Button
          type="default"
          icon={<CloseOutlined />}
          onClick={handleClear}
          className="!rounded-lg !border-border"
        >
          Clear selection
        </Button>
      </Space>
    </div>
  );
}

