  ticket: JunkTicket | null;
  onCancel: () => void;
};

export function CreateTicketFromEmailModal({
  open,
  ticket,
  onCancel,
}: CreateTicketFromEmailModalProps) {
  const router = useRouter();
  const userRole =
    typeof window !== 'undefined' ? localStorage.getItem('role') : null;
  const isAdmin = userRole === 'Admin';

  const clientsQ = useClientsQuery();
  const [clientId, setClientId] = useState<string | number | null>(null);
  const clientProjectsQ = useClientProjectsQuery(clientId);
  const supportsQ = useSupportsQuery();
  const typesQ = useTicketTypesQuery();
  const teamsQ = useDepartmentsQuery();
  const createTicketMut = useCreateTicketMutation();

  const clientProjects = clientProjectsQ.data ?? [];
  const supportsFlat = useMemo(() => {
    const data = supportsQ.data ?? [];
    return data.flatMap((node: any) => {
      const client = node?.client ?? node;
      return client?.supports ?? [];
    });
  }, [supportsQ.data]);

  const supportOptions = isAdmin
    ? clientProjects.map((e) => ({ label: e.name, value: e.id }))
    : supportsFlat.map((s: any) => ({
        label: s?.name ?? 'Support',
        value: s?.id,
      }));

  const [supportIdForm, setSupportIdForm] = useState<string | number | null>(
    null,
  );
  const selectedProject = useMemo(() => {
    if (isAdmin) return clientProjects.find((p) => p.id === supportIdForm);
    const sup = supportsFlat.find((s: any) => s?.id === supportIdForm);
    return sup?.project
      ? { project: sup.project }
      : sup
        ? { project: sup.project }
        : null;
  }, [isAdmin, clientProjects, supportsFlat, supportIdForm]);

  const teamsForProject = selectedProject?.project?.teams ?? [];
  const teamOptions = (
    isAdmin && teamsForProject.length > 0
      ? teamsForProject
      : (teamsQ.data ?? [])
  ).map((t: any) => ({ label: t.name ?? t.type, value: t.id }));

  const [form] = Form.useForm();
  const descriptionValue = Form.useWatch('description', form) ?? '';
  const [issueList, setIssueList] = useState<IssueItem[]>([]);
  const [issueDescriptions, setIssueDescriptions] = useState<
    Record<number, string>
  >({});

  useEffect(() => {
    if (open && ticket) {
      form.setFieldsValue({
        subject: ticket.subject ?? '',
        description: ticket.body ?? '',
      });
    }
  }, [open, ticket, form]);

  const checkSupportDuration = (projectId: string | number) => {
    const item = clientProjects.find((c) => c.project?.id === projectId);
    if (!item?.supportEndDate) return true;
    return new Date() < new Date(item.supportEndDate);
  };

  const onFinish = async (values: any) => {
    if (!checkUserPermission([PERMISSIONS.ticketCreate])) {
      message.error('You do not have permission to create tickets');
      return;
    }
    const supportIdVal = values.support_id ?? supportIdForm;
    const projectId = selectedProject?.project?.id;

    if (projectId && !checkSupportDuration(projectId)) {
      message.error('Support end date has passed.');
      return;
    }
    if (issueList.length === 0) {
      message.error('At least one issue is required.');
      return;
    }

    const issuesValid = issueList.every((issue, i) => {
      const name = issue.name?.trim();
      const desc = stripHtml(issueDescriptions[i] ?? issue.description ?? '');
      return name && issue.expectedEndDate && desc;
    });
    if (!issuesValid) {
      message.error(
        'Each issue must have name, expected end date, and description.',
      );
      return;
    }

    const issues = issueList.map((issue, i) => ({
      name: issue.name?.trim(),
      expectedEndDate:
        typeof issue.expectedEndDate === 'string'
          ? issue.expectedEndDate
          : issue.expectedEndDate
            ? dayjs(issue.expectedEndDate).format('YYYY-MM-DD')
            : '',
      description: issueDescriptions[i] ?? issue.description ?? '',
    }));

    const expectedEndDateStr = values.expectedEndDate
      ? dayjs.isDayjs(values.expectedEndDate)
        ? values.expectedEndDate.format('YYYY-MM-DD')
        : String(values.expectedEndDate)
      : '';
    const body: Record<string, any> = {
      support_id: supportIdVal,
      type_id: values.type_id,
      subject: values.subject?.trim(),
      expectedEndDate: expectedEndDateStr,
      description: values.description ?? '',
    };
    if (isAdmin) {
      body.client_id = values.client_id ?? clientId;
      body.team_ids = Array.isArray(values.team_ids)
        ? values.team_ids
        : values.team_ids
          ? [values.team_ids]
          : [];
    }

    try {

  try {
    const res = await createTicketMut.mutateAsync({ body, issues });
    const data = (res as any)?.data;
    const ticketId = Array.isArray(data) ? data[0]?.id : data?.id;
    message.success('Ticket created successfully');
    onCancel();
    if (ticketId) router.push(`/tickets/${ticketId}`);
    else router.push('/tickets');
  } catch (e: any) {
    message.error(e?.message ?? 'Failed to create ticket');
  }
};

const handleCancel = () => {
  form.resetFields();
  setIssueList([]);
  setIssueDescriptions({});
  setSupportIdForm(null);
  setClientId(null);
  onCancel();
};

return (
  <Drawer
    title={null}
    open={open}
    onClose={handleCancel}
    width="50%"
    placement="right"
    destroyOnClose
    closable={false}
    styles={{ body: { padding: 0 }, header: { display: 'none' } }}
  >
    <div className="border-border bg-card border-b px-6 py-5">
      <div className="flex items-center gap-3">
        <div className="bg-primary/10 flex h-9 w-9 items-center justify-center rounded-lg">
          <PlusOutlined className="text-primary text-base" />
        </div>
        <div>
          <Typography.Title level={4} className="!m-0 !text-foreground">
            Create Ticket from Email
          </Typography.Title>
          <Typography.Text className="text-muted-foreground text-xs">
            Convert this email into a support ticket
          </Typography.Text>
        </div>
      </div>
    </div>

    <div className="p-6">
      <Form
        form={form}
        layout="vertical"
        onFinish={onFinish}
        initialValues={{
          subject: ticket?.subject ?? '',
          description: ticket?.body ?? '',
        }}
      >
        {isAdmin && (
          <Form.Item
            name="client_id"
            label={
              <span className="flex items-center gap-1.5">
                <UserOutlined className="text-primary" /> Client
              </span>
            }
            rules={[{ required: true, message: 'Client is required' }]}
          >
            <Select
              allowClear
              placeholder="Select Client"
              loading={clientsQ.isLoading}
              showSearch
              optionFilterProp="label"
              className="!rounded-lg"
              options={(clientsQ.data ?? []).map((c: any) => ({
                label: `${c.first_name ?? ''} ${c.last_name ?? ''}`.trim(),
                value: c.id,
              }))}
              onChange={(v) => {
                setClientId(v ?? null);
                setSupportIdForm(null);
                form.setFieldValue('support_id', null);
                form.setFieldValue('team_ids', undefined);
              }}
            />
          </Form.Item>
        )}

        {isAdmin &&
          clientId &&
          clientProjects.length === 0 &&
          !clientProjectsQ.isLoading && (
            <p className="text-red-500 text-sm mb-2">
              No active support projects for this client.
            </p>
          )}

        <Form.Item
          name="support_id"
          label={
            <span className="flex items-center gap-1.5">
              <ProjectOutlined className="text-primary" /> Support
            </span>
          }
          rules={[{ required: true, message: 'Support is required' }]}
        >
          <Select
            allowClear
            placeholder="Select Support"
            loading={
              isAdmin ? clientProjectsQ.isLoading : supportsQ.isLoading
            }
            showSearch
            optionFilterProp="label"
            className="!rounded-lg"
            options={supportOptions}
            onChange={(v) => {
              setSupportIdForm(v ?? null);
              form.setFieldValue('team_ids', undefined);
            }}
          />
        </Form.Item>

        {selectedProject?.project &&
          !checkSupportDuration(selectedProject.project.id) && (
            <p className="text-red-500 text-sm mb-2">
              Support end date passed.
            </p>
          )}

        {isAdmin && (
          <Form.Item
            name="team_ids"
            label={
              <span className="flex items-center gap-1.5">
                <TeamOutlined className="text-primary" /> Team
              </span>
            }
            rules={[{ required: true, message: 'Team is required' }]}
          >
            <Select
              mode="multiple"
              allowClear
              placeholder="Select Team(s)"
              loading={teamsQ.isLoading}
              options={teamOptions}
              className="!rounded-lg"
            />
          </Form.Item>
        )}

        <Form.Item
          name="subject"
          label={
            <span className="flex items-center gap-1.5">
              <FileTextOutlined className="text-primary" /> Subject
            </span>
          }
          rules={[{ required: true, message: 'Subject is required' }]}
        >
          <Input placeholder="Ticket subject" className="!rounded-lg" />
        </Form.Item>

        <Form.Item
          name="type_id"
          label={
            <span className="flex items-center gap-1.5">
              <FileTextOutlined className="text-primary" /> Type
            </span>
          }
          rules={[{ required: true, message: 'Type is required' }]}

                    setIssueList((p) => p.filter((_, i) => i !== index));
                    const next: Record<number, string> = {};
                    Object.entries(issueDescriptions).forEach(([k, v]) => {
                      const i = Number(k);
                      if (i > index) next[i - 1] = v;
                      else if (i < index) next[i] = v;
                    });
                    setIssueDescriptions(next);
                  }}
                >
                  Remove
                </Button>
              </div>
              <Form.Item
                label={<span className="text-sm">Issue name</span>}
                required
              >
                <Input
                  value={issue.name}
                  onChange={(e) =>
                    setIssueList((p) => {
                      const n = [...p];
                      n[index] = { ...n[index], name: e.target.value };
                      return n;
                    })
                  }
                  placeholder="Issue name"
                  className="!rounded-lg"
                />
              </Form.Item>
              <Form.Item
                label={<span className="text-sm">Expected end date</span>}
                required
              >
                <DatePicker
                  className="w-full !rounded-lg"
                  value={
                    issue.expectedEndDate
                      ? dayjs(issue.expectedEndDate)
                      : undefined
                  }
                  onChange={(_, dateStr) =>
                    setIssueList((p) => {
                      const n = [...p];
                      n[index] = {
                        ...n[index],
                        expectedEndDate: Array.isArray(dateStr)
                          ? dateStr[0]
                          : dateStr,
                      };
                      return n;
                    })
                  }
                  format="YYYY-MM-DD"
                />
              </Form.Item>
              <Form.Item
                label={<span className="text-sm">Description</span>}
                required
              >
                <div className="border-border overflow-hidden rounded-lg border">
                  <RichTextEditor
                    value={
                      typeof issueDescriptions[index] === 'string'
                        ? issueDescriptions[index]
                        : (issue.description ?? '')
                    }
                    onChange={(v) =>
                      setIssueDescriptions((prev) => ({ ...prev, [index]: v }))
                    }
                    placeholder="Issue description"
                  />
                </div>
              </Form.Item>
            </div>
          ))}

          <div className="flex justify-end gap-2 mb-6">
            <Button
              type="dashed"
