'use client';

import React from 'react';
import { Button, Space, Popconfirm, Tooltip } from 'antd';
import {
  SwapOutlined,
  DeleteOutlined,
  EyeOutlined,
  PlusCircleOutlined,
  ExclamationCircleOutlined,
} from '@ant-design/icons';
import type { JunkTicket } from '../_hooks/useJunkTicketQueries';
import { checkUserPermission, PERMISSIONS } from '@/utils/permissions';

type JunkTicketActionsProps = {
  ticket: JunkTicket;
  onRestore?: (ticket: JunkTicket) => void;
  onDelete?: (ticket: JunkTicket) => void;
  onViewDetails?: (ticket: JunkTicket) => void;
  onCreateTicket?: (ticket: JunkTicket) => void;
  deletingId?: string | number | null;
  restoringId?: string | number | null;
};

export function JunkTicketActions({
  ticket,
  onRestore,
  onDelete,
  onViewDetails,
  onCreateTicket,
  deletingId,
  restoringId,
}: JunkTicketActionsProps) {
  const isDeleting = deletingId === ticket.id;
  const isRestoring = restoringId === ticket.id;
  const canCreateTicket = checkUserPermission([PERMISSIONS.ticketCreate]);

  return (
    <Space
      className="border-border bg-muted/50 rounded-lg border px-2 py-1"
      size={2}
      wrap
    >
      {onViewDetails && (
        <Tooltip title="View details" placement="top">
          <Button
            type="text"
            size="small"
            icon={<EyeOutlined />}
            onClick={() => onViewDetails(ticket)}
            className="!text-muted-foreground hover:!bg-primary/5 hover:!text-primary !rounded-lg"
          />
        </Tooltip>
      )}
      {onRestore && !ticket.isTransfered && (
        <Tooltip title="Transfer to support" placement="top">
          <span>
            <Button
              type="text"
              size="small"
              icon={<SwapOutlined />}
              onClick={() => onRestore(ticket)}
              loading={isRestoring}
              className="!text-primary hover:!bg-primary/5 !rounded-lg"
            />
          </span>
        </Tooltip>
      )}
      {onCreateTicket && canCreateTicket && (
        <Tooltip title="Create ticket" placement="top">
          <Button
            type="text"
            size="small"
            icon={<PlusCircleOutlined />}
            onClick={() => onCreateTicket(ticket)}
            className="!rounded-lg !text-emerald-600 hover:!bg-emerald-50"
          />
        </Tooltip>
      )}
      {onDelete && (
        <Popconfirm
          title="Delete ticket?"
          description="This cannot be undone."
          icon={<ExclamationCircleOutlined style={{ color: '#ef4444' }} />}
          onConfirm={() => onDelete(ticket)}
          okText="Delete"
          okButtonProps={{ danger: true, className: '!rounded-lg' }}
          cancelButtonProps={{ className: '!rounded-lg' }}
          cancelText="Cancel"
        >
          <Tooltip title="Delete permanently" placement="top">
            <span>
              <Button
                type="text"
                size="small"
                danger
                icon={<DeleteOutlined />}
                loading={isDeleting}
                className="!rounded-lg"
              />
            </span>
          </Tooltip>
        </Popconfirm>
      )}
    </Space>
  );
}

