'use client';

import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { fetchJson } from '@/utils/api';
import { unwrapData } from '@/api/core/envelopes';
import { useAuthStore } from '@/store/auth';
import type { ApiEnvelope } from '@/api/types/envelopes';

export type JunkTicket = {
  id: string | number;
  subject?: string;
  body?: string;
  senderEmail?: string;
  first_name?: string;
  last_name?: string;
  created_at?: string;
  isTransfered?: boolean;
  [k: string]: any;
};

export type JunkTicketListParams = {
  page?: number;
  limit?: number;
  search?: string;
};

export type TransferJunkTicketInput = {
  ticketId: string | number;
  team_id?: string | number | null;
  priority_id?: string | number | null;
  client_id?: string | number | null;
  type_id?: string | number | null;
  [k: string]: any;
};

export type BulkActionInput = {
  ticketIds: Array<string | number>;
  action: 'restore' | 'delete';
  transferData?: TransferJunkTicketInput;
};

function useToken() {
  const token = useAuthStore((s) => s.token);
  return (
    token ??
    (typeof window !== 'undefined' ? localStorage.getItem('token') : null)
  );
}

function toQueryString(params: Record<string, any>) {
  const sp = new URLSearchParams();
  Object.entries(params).forEach(([k, v]) => {
    if (v === undefined || v === null || v === '') return;
    sp.set(k, String(v));
  });
  const qs = sp.toString();
  return qs ? `?${qs}` : '';
}

// Junk Tickets Query
export function useJunkTicketsQuery(params?: JunkTicketListParams) {
  const token = useToken();
  const qs = params ? toQueryString(params) : '';

  return useQuery({
    queryKey: ['junkTickets', params?.page, params?.limit, params?.search],
    queryFn: async () => {
      const res = await fetchJson<any>(`/support/junk/get-all/support${qs}`, {
        token,
      });
      // Legacy response shape: { data: [...] }
      const tickets = unwrapData<JunkTicket[]>(
        { data: (res as Record<string, unknown>)?.data ?? res?.junkTickets },
        [],
      );
      return Array.isArray(tickets) ? tickets : [];
    },
    enabled: !!token,
    staleTime: 30 * 1000, // 30 seconds
  });
}

// Single Junk Ticket Query
export function useJunkTicketQuery(
  ticketId: string | number | null,
  tickets?: JunkTicket[],
) {
  const token = useToken();

  return useQuery({
    queryKey: ['junkTicket', ticketId, tickets?.length ?? 0],
    queryFn: async () => {
      // Try to fetch single ticket from API first
      try {
        const res = await fetchJson<any>(`/support/junk/${ticketId}`, {
          token,
        });
        const raw = unwrapData<any>(
          {
            data: (res as Record<string, unknown>)?.data ?? res?.ticket ?? res,
          },
          null,
        );
        if (
          raw &&
          typeof raw === 'object' &&
          (raw.id !== undefined || raw.subject !== undefined)
        ) {
          return {
            id: raw.id,
            subject: raw.subject,
            body: raw.body,
            senderEmail: raw.senderEmail,
            first_name: raw.first_name,
            last_name: raw.last_name,
            created_at: raw.created_at,
            isTransfered: raw.isTransfered,
            ...raw,
          } as JunkTicket;
        }
      } catch {
        // Fall back to finding in provided list
      }

      // Fallback: find ticket in the provided list (e.g. when list has loaded)
      if (tickets && tickets.length > 0) {
        const found = tickets.find((t) => String(t.id) === String(ticketId));
        return found ?? null;
      }

      return null;
    },
    enabled: !!token && !!ticketId,
    staleTime: 30 * 1000,
  });
}

// Transfer/Restore Junk Ticket Mutation
export function useTransferJunkTicketMutation() {
  const token = useToken();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (input: TransferJunkTicketInput) => {
      const { ticketId, ...rest } = input;
      return fetchJson<ApiEnvelope<JunkTicket>>(`/support/junk/${ticketId}`, {
        token,
        method: 'POST',
        body: rest,
      });
    },
    meta: { successMessage: 'Ticket transferred successfully' },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['junkTickets'] });
    },
  });
}

// Delete Junk Ticket Mutation
export function useDeleteJunkTicketMutation() {
  const token = useToken();

  const token = useToken();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (ticketId: string | number) => {
      return fetchJson(`/support/junk/${ticketId}`, {
        token,
        method: 'DELETE',
      });
    },
    meta: { successMessage: 'Junk ticket deleted successfully' },
    onSuccess: (_, ticketId) => {
      queryClient.invalidateQueries({ queryKey: ['junkTickets'] });
      queryClient.invalidateQueries({ queryKey: ['junkTicket', ticketId] });
    },
  });
}

// Bulk Actions Mutation
export function useBulkActionJunkTicketsMutation() {
  const token = useToken();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async ({
      ticketIds,
      action,
      transferData,
    }: BulkActionInput) => {
      if (action === 'delete') {
        // Delete all tickets
        const deletePromises = ticketIds.map((id) =>
          fetchJson(`/support/junk/${id}`, { token, method: 'DELETE' }),
        );
        await Promise.all(deletePromises);
      } else if (action === 'restore' && transferData) {
        // Transfer all tickets with the same transfer data
        const { ticketId, ...rest } = transferData;
        const transferPromises = ticketIds.map((id) =>
          fetchJson(`/support/junk/${id}`, {
            token,
            method: 'POST',
            body: rest,
          }),
        );
        await Promise.all(transferPromises);
      }
    },
    meta: { successMessage: 'Bulk action completed successfully' },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['junkTickets'] });
    },
  });
}

