export default function EmailSupportDetailPage() {
  const params = useParams();
  const id = params?.id as string | undefined;
  const ticketId = id ? (isNaN(Number(id)) ? id : Number(id)) : null;

  const listQuery = useJunkTicketsQuery({});
  const tickets = listQuery.data ?? [];
  const ticketFromList = ticketId
    ? tickets.find((t) => String(t.id) === String(ticketId))
    : null;

  const singleQuery = useJunkTicketQuery(ticketId, tickets);
  const ticket: JunkTicket | null = singleQuery.data ?? ticketFromList ?? null;
  const loading = !ticket && (singleQuery.isLoading || listQuery.isLoading);
  const error = singleQuery.error || listQuery.error;

  const [transferOpen, setTransferOpen] = useState(false);
  const [createTicketOpen, setCreateTicketOpen] = useState(false);
  const canTransferJunk = checkUserPermission([PERMISSIONS.supportCreate]);
  const transferMutation = useTransferJunkTicketMutation();

  const handleTransferSubmit = async (values: any) => {
    if (!canTransferJunk) {
      message.error('You do not have permission to transfer junk tickets');
      return;
    }
    if (!ticket) return;
    try {
      await transferMutation.mutateAsync({ ticketId: ticket.id, ...values });
      message.success('Ticket transferred successfully');
      setTransferOpen(false);
      singleQuery.refetch();
