type JunkTicketUiState = {
  // Search filter
  search: string;
  setSearch: (search: string) => void;

  // Pagination
  currentPage: number;
  pageSize: number;
  setCurrentPage: (page: number) => void;
  setPageSize: (size: number) => void;

  // Selected tickets (for bulk actions)
  selectedTicketIds: Array<string | number>;
  setSelectedTicketIds: (ids: Array<string | number>) => void;
  toggleTicketSelection: (id: string | number) => void;
  clearSelection: () => void;
  selectAll: (ids: Array<string | number>) => void;

  // Bulk action state
  isBulkActionMode: boolean;
  setIsBulkActionMode: (mode: boolean) => void;

  // Modal visibility
  isTransferModalOpen: boolean;
  setIsTransferModalOpen: (open: boolean) => void;
  isDeleteConfirmModalOpen: boolean;
  setIsDeleteConfirmModalOpen: (open: boolean) => void;
  isBulkActionModalOpen: boolean;
  setIsBulkActionModalOpen: (open: boolean) => void;

  // Drawer visibility
  isDetailsDrawerOpen: boolean;
  setIsDetailsDrawerOpen: (open: boolean) => void;

  // Selected ticket for viewing/editing
  selectedTicketId: string | number | null;
  setSelectedTicketId: (id: string | number | null) => void;

  // Table state
  expandedRowKeys: Array<string | number>;
  setExpandedRowKeys: (keys: Array<string | number>) => void;

  // View mode
  viewMode: 'list' | 'grid';
  setViewMode: (mode: 'list' | 'grid') => void;

  // Reset filters
  resetFilters: () => void;
};

const initialState = {
  search: '',
  currentPage: 1,
  pageSize: 12,
  selectedTicketIds: [],
  isBulkActionMode: false,
  isTransferModalOpen: false,
  isDeleteConfirmModalOpen: false,
  isBulkActionModalOpen: false,
  isDetailsDrawerOpen: false,
  selectedTicketId: null,
  expandedRowKeys: [],
  viewMode: 'list' as const,
};

export const useJunkTicketUiStore = create<JunkTicketUiState>((set) => ({
  ...initialState,

  setSearch: (search) => set({ search }),

  setCurrentPage: (page) => set({ currentPage: page }),

  setPageSize: (size) => set({ pageSize: size, currentPage: 1 }),

  setSelectedTicketIds: (ids) => set({ selectedTicketIds: ids }),

  toggleTicketSelection: (id) =>
    set((state) => {
      const isSelected = state.selectedTicketIds.includes(id);
      return {
        selectedTicketIds: isSelected
          ? state.selectedTicketIds.filter((selectedId) => selectedId !== id)
          : [...state.selectedTicketIds, id],
      };
    }),

  clearSelection: () => set({ selectedTicketIds: [], isBulkActionMode: false }),

  selectAll: (ids) => set({ selectedTicketIds: ids }),

  setIsBulkActionMode: (mode) => set({ isBulkActionMode: mode }),

  setIsTransferModalOpen: (open) => set({ isTransferModalOpen: open }),

  setIsDeleteConfirmModalOpen: (open) =>
    set({ isDeleteConfirmModalOpen: open }),

  setIsBulkActionModalOpen: (open) => set({ isBulkActionModalOpen: open }),

  setIsDetailsDrawerOpen: (open) => set({ isDetailsDrawerOpen: open }),

  setSelectedTicketId: (id) => set({ selectedTicketId: id }),

  setExpandedRowKeys: (keys) => set({ expandedRowKeys: keys }),

  setViewMode: (mode) => set({ viewMode: mode }),

  resetFilters: () => set(initialState),
}));

