];

function fullName(e: Employee) {
  const fn = (e.first_name ?? '').trim();
  const ln = (e.last_name ?? '').trim();
  return `${fn} ${ln}`.trim() || `Employee ${e.id}`;
}

function roleLabel(role: Role | null | undefined) {
  return role?.roleName ?? role?.rolename ?? role?.name ?? '—';
}

function getEmployeeAvatarSrc(profile_pic: string | null | undefined) {
  if (!profile_pic) return undefined;
  if (profile_pic.startsWith('http')) return profile_pic;
  return URL ? `${URL}/${profile_pic.replace(/^\//, '')}` : profile_pic;
}

function employeeInitials(e: Employee) {
  const fn = (e.first_name ?? '').trim()[0]?.toUpperCase() ?? '';
  const ln = (e.last_name ?? '').trim()[0]?.toUpperCase() ?? '';
  return fn + ln || '?';
}

