                  </TableCell>
                </TableRow>
              );
            })
          )}
        </TableBody>
      </Table>

      <div className="border-t px-6 py-3 flex items-center justify-between text-muted-foreground text-[12px] bg-muted/5">
        <span>
          Showing {rows.length} of {total} employees
        </span>
        <Pagination
          current={page}
          pageSize={pageSize}
          total={total}
          onChange={(p, ps) => {
            if (ps !== pageSize) setPageSize(ps);
            else setPage(p);
          }}
        />
      </div>
    </div>
  );
}

