};

export type EmployeeUpdateInput = {
  id: string | number;
  first_name?: string;
  last_name?: string;
  email?: string;
  phone_number?: string | null;
  user_type?: string;
  role_id?: string | number | null;
  companyId?: string | number | null;
  team_id?: Array<string | number>;
  is_deleted?: boolean;
  profile_pic?: File | null;
};

export type AssignTeamsInput = {
  id: string | number;
  payload: Record<string, any>;
};

function useToken() {
  const token = useAuthStore((s) => s.token);
  return (
    token ??
    (typeof window !== 'undefined' ? localStorage.getItem('token') : null)
  );
}

function toQueryString(params: Record<string, any>) {
  const sp = new URLSearchParams();
  Object.entries(params).forEach(([k, v]) => {
    if (v === undefined || v === null || v === '') return;
    sp.set(k, String(v));
  });
  const qs = sp.toString();
  return qs ? `?${qs}` : '';
}

function normalizeEmployeesList(payload: any): EmployeesListResponse {
  const { rows, total } = unwrapRowsAndTotal<Employee>(payload);
  return { rows, total };
}

export function useEmployeesQuery(params: EmployeesListParams) {
  const token = useToken();
  const qs = toQueryString({
    page: params.page,
    limit: params.limit,
    search: params.search,
    companyId: params.companyId,
    teamId: params.teamId,
    roleId: params.roleId,
  });

  return useQuery({
    queryKey: [
      'employees',
      params.page,
      params.limit,
      params.search,
      params.companyId,
      params.teamId,
      params.roleId,
    ],
    queryFn: async () => {
      const res = await fetchJson<any>(`${EMPLOYEES_API_BASE}${qs}`, { token });
      return normalizeEmployeesList(res);
    },
    enabled: !!token,
    staleTime: 30 * 1000,
  });
}

export function useEmployeeQuery(employeeId: string | number | null) {
  const token = useToken();
  return useQuery({
    queryKey: ['employee', employeeId],
    queryFn: async () => {
      const res = await fetchJson<any>(
        `${EMPLOYEES_API_BASE.replace(/\/$/, '')}/${employeeId}`,
        { token },
      );
      const d = unwrapData<Employee | Employee[] | null>(res, null);
      if (Array.isArray(d)) return (d[0] ?? null) as Employee | null;
      return (d ?? null) as Employee | null;
    },
    enabled: !!token && !!employeeId,
    staleTime: 30 * 1000,
  });
}

export function useRolesQuery() {

export function useRolesQuery() {
  const token = useToken();
  return useQuery({
    queryKey: ['roles'],
    queryFn: async () => {
      const res = await fetchJson<any>('/role', { token });
      // legacy: roleFetch dispatches allRoleSuccess(res.data) where res.data has .data
      const roles = (res?.data ?? res?.roles ?? []) as Role[];
      return Array.isArray(roles) ? roles : [];
    },
    enabled: !!token,
    staleTime: 5 * 60 * 1000,
  });
}

export function useCreateEmployeeMutation() {
  const token = useToken();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (input: EmployeeCreateInput) => {
      const form = new FormData();
      form.append('first_name', input.first_name);
      form.append('last_name', input.last_name);
      form.append('email', input.email);
      if (input.phone_number !== undefined)
        form.append('phone_number', String(input.phone_number ?? ''));
      if (input.role_id !== undefined && input.role_id !== null)
        form.append('role_id', String(input.role_id));
      if (input.companyId !== undefined && input.companyId !== null)
        form.append('companyId', String(input.companyId));
      if (input.profile_pic instanceof File)
        form.append('profile_pic', input.profile_pic);
      if (Array.isArray(input.teams)) {
        input.teams.forEach((t, idx) =>
          form.append(`teams[${idx}]`, String(t)),
        );
      }

      return fetchMultipart<ApiEnvelope<Employee>>(EMPLOYEES_API_BASE, {
        token,
        method: 'POST',
        form,
      });
    },
    meta: { successMessage: 'Employee created successfully' },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['employees'] });
    },
  });
}

export function useUpdateEmployeeMutation() {
  const token = useToken();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (input: EmployeeUpdateInput) => {
      const { id, profile_pic, team_id, ...rest } = input;

      // Prefer multipart if a file is present OR team arrays must use legacy indexed keys.
      if (profile_pic instanceof File || Array.isArray(team_id)) {
        const form = new FormData();
        if (rest.first_name !== undefined)
          form.append('first_name', String(rest.first_name ?? ''));
        if (rest.last_name !== undefined)
          form.append('last_name', String(rest.last_name ?? ''));
        if (rest.email !== undefined)
          form.append('email', String(rest.email ?? ''));
        if (rest.phone_number !== undefined)
          form.append('phone_number', String(rest.phone_number ?? ''));
        if (rest.user_type !== undefined)
          form.append('user_type', String(rest.user_type ?? ''));
        if (rest.role_id !== undefined && rest.role_id !== null)
          form.append('role_id', String(rest.role_id));
        if (rest.companyId !== undefined)
          form.append('companyId', String(rest.companyId ?? ''));
        if (rest.is_deleted !== undefined)
          form.append('is_deleted', String(!!rest.is_deleted));
        if (profile_pic instanceof File)
          form.append('profile_pic', profile_pic);
        if (Array.isArray(team_id))
          team_id.forEach((t, idx) =>
            form.append(`team_id[${idx}]`, String(t)),
          );

        return fetchMultipart<ApiEnvelope<Employee>>(
          `${EMPLOYEES_API_BASE.replace(/\/$/, '')}/${id}`,
          {
            token,
            method: 'PATCH',
            form,
          },
        );
      }

      return fetchJson<ApiEnvelope<Employee>>(
        `${EMPLOYEES_API_BASE.replace(/\/$/, '')}/${id}`,
        {
          token,
          method: 'PATCH',
          body: rest,
        },
      );
    },
    meta: { successMessage: 'Employee updated successfully' },
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({ queryKey: ['employees'] });
      queryClient.invalidateQueries({ queryKey: ['employee', variables.id] });
    },
  });
}

export function useDeleteEmployeeMutation() {
  const token = useToken();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (employeeId: string | number) => {
      return fetchJson(
        `${EMPLOYEES_API_BASE.replace(/\/$/, '')}/${employeeId}`,
        { token, method: 'DELETE' },
      );
    },
    meta: { successMessage: 'Employee deleted successfully' },
    onSuccess: (_, employeeId) => {
      queryClient.invalidateQueries({ queryKey: ['employees'] });
      queryClient.invalidateQueries({ queryKey: ['employee', employeeId] });
    },
  });
}

export function useAssignTeamsMutation() {
  const token = useToken();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async ({ id, payload }: AssignTeamsInput) => {
      return fetchJson(
        `${EMPLOYEES_API_BASE.replace(/\/$/, '')}/team-access/${id}`,
        {
          token,
          method: 'POST',
