      last_name: employee.last_name ?? '',
      email: employee.email ?? '',
      phone_number: employee.phone_number ?? undefined,
      companyId:
        employee.company_id ?? (employee.company as any)?.id ?? undefined,
      role_id: employee.role_id ?? (employee.role as any)?.id ?? undefined,
      team_id: (employee.teams_access ?? []).map((t) => t.id),
      is_deleted: !!employee.is_deleted,
    });
  }, [employee, form]);

  const anyLoading =
    employeeQ.isLoading ||
    companiesQ.isLoading ||
    teamsQ.isLoading ||
    rolesQ.isLoading;
  const anyError =
    employeeQ.error || companiesQ.error || teamsQ.error || rolesQ.error;

  const onSave = async (values: any) => {
    if (!canUpdateEmployee) return;
    try {
      if (!employeeId) throw new Error('Missing employee id');
      await updateM.mutateAsync({
        id: employeeId,
        first_name: values.first_name,
        last_name: values.last_name,
        email: values.email,
        phone_number: values.phone_number ?? null,
        companyId: values.companyId ?? null,
        role_id: values.role_id ?? null,
        team_id: Array.isArray(values.team_id) ? values.team_id : [],
        is_deleted: !!values.is_deleted,
      });
      setBanner({ type: 'success', message: 'Employee saved.' });
    } catch (e: any) {
      setBanner({
        type: 'error',
        message: e?.message || 'Failed to save employee.',
      });
    }
  };

  const companies = (companiesQ.data ?? []) as any[];
  const teams = (teamsQ.data ?? []) as any[];
  const roles = (rolesQ.data ?? []) as any[];

  const getEmployeeAvatarSrc = (e: Employee | null) => {
    if (!e?.profile_pic) return undefined;
    const pic = e.profile_pic;
    if (pic.startsWith('http')) return pic;
    return URL ? `${URL}/${pic.replace(/^\//, '')}` : pic;
  };
  const employeeInitials = (e: Employee | null) => {
    if (!e) return '?';
    const fn = (e.first_name ?? '').trim()[0]?.toUpperCase() ?? '';
    const ln = (e.last_name ?? '').trim()[0]?.toUpperCase() ?? '';
    return fn + ln || '?';
  };

  const fullName = employee
    ? `${employee.first_name ?? ''} ${employee.last_name ?? ''}`.trim() ||
      'Employee'
    : 'Employee';
  const roleName =
    (employee?.role as any)?.roleName ??
    (employee?.role as any)?.rolename ??
    (employee?.role as any)?.name ??
    '—';
  const companyName =
    (employee?.company as any)?.company_name ??
    (employee?.company as any)?.name ??
    '—';

