  return (
    <Card
      className="group relative flex flex-col h-full overflow-hidden border-border/50 bg-background transition-all hover:shadow-md hover:border-primary/20 cursor-pointer"
      onClick={() => router.push(`/knowledge/${article.id}`)}
    >
      <CardHeader className="p-4 pb-2">
        <div className="flex items-start justify-between mb-3">
          <Avatar className="size-10 rounded-xl shadow-sm">
            <AvatarFallback
              className={`${colorClass} rounded-xl text-[14px] font-bold text-white uppercase`}
            >
              {initial}
            </AvatarFallback>
          </Avatar>
          <div onClick={(e) => e.stopPropagation()}>
            <DropdownMenu>
              <DropdownMenuTrigger asChild>
                <Button
                  variant="ghost"
                  size="icon"
                  className="size-8 text-muted-foreground hover:text-foreground"
                >
                  <MoreVertical className="h-4 w-4" />
                </Button>
              </DropdownMenuTrigger>
              <DropdownMenuContent align="end" className="w-40">
                <DropdownMenuItem
                  className="gap-2 text-[12px] font-medium"
                  onClick={() => onEdit(article)}
                >
                  <Edit className="h-3.5 w-3.5" /> Edit
                </DropdownMenuItem>
                <DropdownMenuItem
                  className="gap-2 text-[12px] font-medium"
                  onClick={() => handleExport()}
                >
                  <Download className="h-3.5 w-3.5" /> Download
                </DropdownMenuItem>
                {checkUserPermission(['delete-knowledge-base']) && (
                  <DropdownMenuItem
                    className="gap-2 text-[12px] font-medium text-destructive focus:text-destructive"
                    onClick={handleDelete}
                    disabled={deleteMutation.isPending}
                  >
                    <Trash className="h-3.5 w-3.5" />
                    {deleteMutation.isPending ? 'Deleting...' : 'Delete'}
                  </DropdownMenuItem>
                )}
              </DropdownMenuContent>
            </DropdownMenu>
          </div>
        </div>
        <h3 className="line-clamp-2 text-[14px] font-bold leading-snug tracking-tight text-foreground group-hover:text-primary transition-colors">
          {article.title}
