      </CardHeader>

      <CardContent className="flex flex-col flex-1 p-4 pt-0">
        <div className="mt-2 mb-4">
          <Badge
            variant="outline"
            className="text-[10px] font-bold px-2 py-0 h-5 bg-muted/40 border-transparent text-muted-foreground uppercase tracking-wider"
