export function ArticleDetails() {
  const {
    isArticleDetailsDrawerOpen,
    setIsArticleDetailsDrawerOpen,
    selectedArticleId,
  } = useKnowledgeBaseUiStore();

  const { data: article, isLoading } = useArticleQuery(selectedArticleId);
  const {
    data: comments = [],
    isLoading: commentsLoading,
    refetch: refetchComments,
  } = useArticleCommentsQuery(selectedArticleId);
  const { data: documents = [], refetch: refetchDocuments } =
    useArticleDocumentsQuery(selectedArticleId);
  const { data: categories = [] } = useCategoriesQuery();

  const createCommentMutation = useCreateCommentMutation();
  const deleteDocumentMutation = useDeleteDocumentMutation();

  const canDeleteKnowledge = checkUserPermission([PERMISSIONS.knowledgeDelete]);

  const [commentText, setCommentText] = useState('');

  const getCategoryName = (categoryId?: string | number | null) => {
    if (!categoryId) return 'No Category';
    const category = categories.find((cat) => cat.id === categoryId);
    return category ? category.name : 'Unknown Category';
  };

  const getAuthorName = (createdBy: any): string => {
    if (createdBy == null) return '—';
    if (typeof createdBy === 'object') {
      if (createdBy.first_name != null && createdBy.last_name != null)
        return `${createdBy.first_name} ${createdBy.last_name}`.trim() || '—';
      if (createdBy.name && typeof createdBy.name === 'string')
        return createdBy.name.trim();
      if (createdBy.email && typeof createdBy.email === 'string')
        return createdBy.email.trim();
    }
    if (typeof createdBy === 'string' && createdBy.trim())
      return createdBy.trim();
    return '—';
  };

  const formatDate = (dateString: string | null | undefined): string => {
    if (dateString == null || String(dateString).trim() === '') return '—';
    const d = new Date(dateString);
    return Number.isNaN(d.getTime())
      ? '—'
      : d.toLocaleDateString('en-US', {
          year: 'numeric',
          month: 'long',
          day: 'numeric',
        });
  };

  const formatDateTime = (dateString: string | null | undefined): string => {
    if (dateString == null || String(dateString).trim() === '') return '—';
    const d = new Date(dateString);
    return Number.isNaN(d.getTime())
      ? '—'
      : d.toLocaleString('en-US', {
          year: 'numeric',
          month: 'short',
          day: 'numeric',
          hour: '2-digit',
          minute: '2-digit',
        });
  };

  const handleCommentSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedArticleId || !commentText.trim()) return;
    createCommentMutation.mutate(
      { articleId: selectedArticleId, comment: commentText },
      {
        onSuccess: () => {
          setCommentText('');
          refetchComments();
          toast.success('Comment added successfully');
        },
      },
    );
  };

  const handleDownloadDocument = (
    documentId: string | number,
    fileName: string,
  ) => {
    const token =
      typeof window !== 'undefined' ? localStorage.getItem('token') : null;
    if (!token) return;
    fetchBlob(`/knowledgebase/documents/download/${documentId}`, { token })
      .then((blob) => {
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = fileName;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        window.URL.revokeObjectURL(url);
      })
      .catch((error) => {
        console.error('Failed to download document:', error);
        toast.error('Failed to download document');
      });
  };

  const handleDeleteDocument = (documentId: string | number) => {
    if (!canDeleteKnowledge) return;
    if (!selectedArticleId) return;
    deleteDocumentMutation.mutate(
      { documentId, articleId: selectedArticleId },
      { onSuccess: () => refetchDocuments() },
    );
  };

