export function ArticleFormModal() {
  const {
    isCreateArticleModalOpen,
    isEditArticleModalOpen,
    setIsCreateArticleModalOpen,
    setIsEditArticleModalOpen,
    setIsCreateCategoryModalOpen,
    selectedArticleId,
    ticketIdForArticle,
    setTicketIdForArticle,
  } = useKnowledgeBaseUiStore();

  const editorRef = useRef<{ getContent: () => string } | null>(null);
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [selectedCategoryId, setSelectedCategoryId] = useState<
    string | number | null
  >(null);
  const [editorMounted, setEditorMounted] = useState(false);

  const createMutation = useCreateArticleMutation();
  const updateMutation = useUpdateArticleMutation();
  const { data: categories = [] } = useCategoriesQuery();
  const { data: article, isLoading: isLoadingArticle } = useArticleQuery(
    isEditArticleModalOpen ? selectedArticleId : null,
  );

  const isOpen = isCreateArticleModalOpen || isEditArticleModalOpen;
  const isEdit = isEditArticleModalOpen;

  useEffect(() => {
    if (isOpen) {
      const t = setTimeout(() => setEditorMounted(true), 100);
      return () => clearTimeout(t);
    } else {
      setEditorMounted(false);
    }
  }, [isOpen]);

  useEffect(() => {
    if (isOpen && !isEdit) {
      setTitle('');
      setDescription('');
      setSelectedCategoryId(null);
    } else if (isOpen && isEdit && article) {
      setTitle(article.title || '');
      setDescription(article.description || '');
      setSelectedCategoryId(article.catagoryId || null);
    }
  }, [isOpen, isEdit, article]);

  const handleSubmit = async () => {
    if (!title?.trim() || !description?.trim()) {
      toast.error('Title and content are required');
      return;
    }
    const userId =
      typeof window !== 'undefined' ? localStorage.getItem('id') : null;
    if (!userId) {
      toast.error('User ID not found');
      return;
    }

    if (isEdit && selectedArticleId) {
      if (!checkUserPermission([PERMISSIONS.knowledgeUpdate])) {
        toast.error('You do not have permission to update knowledge base articles');
        return;
      }
      updateMutation.mutate(
        {
          id: selectedArticleId,
          title: title.trim(),
          description: description.trim(),
          createdBy: userId,
          catagoryId: selectedCategoryId || null,
        },
        { onSuccess: handleClose },
      );
    } else {
      if (!checkUserPermission([PERMISSIONS.knowledgeCreate])) {
        toast.error('You do not have permission to create knowledge base articles');
        return;
      }
      createMutation.mutate(
        {
          title: title.trim(),
          description: description.trim(),
          createdBy: userId,
          catagoryId: selectedCategoryId || null,
          ticketId: ticketIdForArticle ?? null,
        },
        { onSuccess: handleClose },
      );
    }
  };

  const handleClose = () => {
    setTitle('');
    setDescription('');
    setSelectedCategoryId(null);
    setTicketIdForArticle(null);
    setIsCreateArticleModalOpen(false);
    setIsEditArticleModalOpen(false);
  };

  const isLoading =
    createMutation.isPending || updateMutation.isPending || isLoadingArticle;

  return (
    <>
      <Sheet open={isOpen} onOpenChange={(open) => !open && handleClose()}>
        <SheetContent className="sm:max-w-[800px] p-0 flex flex-col gap-0 border-l shadow-2xl">
