            <div className="flex items-center gap-3">
              <div className="bg-primary/10 flex h-10 w-10 items-center justify-center rounded-lg">
                {isEdit ? (
                  <Edit className="text-primary size-5" />
                ) : (
                  <Plus className="text-primary size-5" />
                )}
              </div>
              <div className="text-left">
                <SheetTitle className="text-lg font-semibold leading-none mb-1.5">
                  {isEdit ? 'Edit Article' : 'Create New Article'}
                </SheetTitle>
                <SheetDescription className="text-xs text-muted-foreground">
                  {isEdit
                    ? 'Update the article details below'
                    : 'Fill in the details to publish a new article'}
                </SheetDescription>
              </div>
            </div>
          </SheetHeader>

          <div className="flex-1 overflow-y-auto">
            <div className="p-6 space-y-8">
              {/* Article Title */}
              <div className="space-y-2.5">
                <Label htmlFor="title" className="flex items-center gap-2 text-[13px] font-medium text-foreground">
