type ArticleListProps = {
  articles: KnowledgeBaseArticle[];
  getCategoryName: (categoryId?: string | number | null) => string;
  onEdit: (article: KnowledgeBaseArticle) => void;
};

const AUTHOR_COLORS = [
  'bg-violet-600',
  'bg-blue-600',
  'bg-emerald-600',
  'bg-amber-600',
  'bg-rose-600',
];

export function ArticleList({
  articles,
  getCategoryName,
  onEdit,
}: ArticleListProps) {
  const router = useRouter();
  const deleteMutation = useDeleteArticleMutation();

  const formatDate = (dateString: string) =>
    new Date(dateString).toLocaleDateString();

  const getAuthorName = (article: KnowledgeBaseArticle) => {
    if (typeof article.createdBy === 'object' && article.createdBy) {
      const creator = article.createdBy as any;
      if (creator.first_name && creator.last_name)
        return `${creator.first_name} ${creator.last_name}`;
      return creator.email || 'Unknown';
    }
    return 'Unknown';
  };

  const handleExport = (article: KnowledgeBaseArticle) => {
    const docContent = `
      <html>
        <head><meta charset='utf-8'><title>${article.title}</title></head>
        <body style="font-family: sans-serif; padding: 40px;">
          <h1 style="color: #7c3aed;">${article.title}</h1>
          <hr />
          <div>${article.description}</div>
        </body>
      </html>`;
    const blob = new Blob([docContent], { type: 'application/msword' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${article.title.replace(/[^a-z0-9]/gi, '_').toLowerCase()}.doc`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const handleDelete = async (id: string | number) => {
    try {
      await deleteMutation.mutateAsync(id);
      toast.success('Article deleted');
    } catch (e: any) {
      toast.error(e?.message || 'Delete failed');
    }
  };

  return (
    <Table className="w-full">
      <TableHeader>
        <TableRow className="hover:bg-transparent">
          <TableHead className="px-5 py-3 h-11 text-[11px] font-bold uppercase tracking-widest text-muted-foreground">
            Article
          </TableHead>
          <TableHead className="px-5 py-3 h-11 text-[11px] font-bold uppercase tracking-widest text-muted-foreground">
            Category
          </TableHead>
          <TableHead className="px-5 py-3 h-11 text-[11px] font-bold uppercase tracking-widest text-muted-foreground">
            Views
          </TableHead>
          <TableHead className="px-5 py-3 h-11 text-[11px] font-bold uppercase tracking-widest text-muted-foreground">
            Author
          </TableHead>
          <TableHead className="px-5 py-3 h-11 text-[11px] font-bold uppercase tracking-widest text-muted-foreground">
            Date
          </TableHead>
          <TableHead className="w-10 pr-4" />
        </TableRow>
      </TableHeader>
      <TableBody>
        {articles.map((article) => {
          const authorName = getAuthorName(article);
          const initial = authorName.charAt(0).toUpperCase();

          const initial = authorName.charAt(0).toUpperCase();
          const colorClass =
            AUTHOR_COLORS[authorName.length % AUTHOR_COLORS.length];

          return (
            <TableRow
              key={article.id}
              className="group cursor-pointer border-border/50"
              onClick={() => router.push(`/knowledge/${article.id}`)}
            >
              <TableCell className="px-5 py-3.5">
                <div className="flex items-center gap-3">
                  <Avatar className="size-8 rounded-lg shadow-sm">
                    <AvatarFallback
                      className={`${colorClass} rounded-lg text-[11px] font-bold text-white`}
                    >
                      {initial}
                    </AvatarFallback>
                  </Avatar>
                  <div className="flex flex-col min-w-0">
                    <span className="line-clamp-1 text-[13px] font-bold text-foreground group-hover:text-primary transition-colors">
                      {article.title}
                    </span>
                    <span className="text-[11px] text-muted-foreground font-mono">
                      ID: {String(article.id).slice(0, 8)}
                    </span>
                  </div>
                </div>
              </TableCell>
              <TableCell className="px-5 py-3.5">
                <Badge
                  variant="outline"
                  className="text-[11px] font-medium px-2 py-0 h-5 bg-muted/40 border-transparent"
                >
                  {getCategoryName(article.catagoryId)}
                </Badge>
              </TableCell>
              <TableCell className="px-5 py-3.5">
                <div className="flex items-center gap-1.5 text-[12px] text-muted-foreground font-medium">
                  <Eye className="w-3.5 h-3.5" />
                  {article.views || 0}
                </div>
              </TableCell>
              <TableCell className="px-5 py-3.5 text-[13px] font-medium text-foreground/80">
                {authorName}
              </TableCell>
              <TableCell className="px-5 py-3.5 text-[12px] text-muted-foreground font-medium">
                {formatDate(article.created_at)}
              </TableCell>
              <TableCell
                className="pr-4 py-3.5"
                onClick={(e) => e.stopPropagation()}
              >
                <DropdownMenu>
                  <DropdownMenuTrigger asChild>
                    <Button
                      variant="ghost"
                      size="icon"
                      className="size-8 text-muted-foreground hover:text-foreground"
                    >
                      <MoreVertical className="h-4 w-4" />
                    </Button>
                  </DropdownMenuTrigger>
                  <DropdownMenuContent align="end" className="w-40">
                    <DropdownMenuItem
                      className="gap-2 text-[12px] font-medium"
                      onClick={() => onEdit(article)}
                    >
                      <Edit className="h-3.5 w-3.5" /> Edit
                    </DropdownMenuItem>
                    <DropdownMenuItem
                      className="gap-2 text-[12px] font-medium"
                      onClick={() => handleExport(article)}
                    >
                      <Download className="h-3.5 w-3.5" /> Download
                    </DropdownMenuItem>
                    {checkUserPermission(['delete-knowledge-base']) && (
                      <DropdownMenuItem
                        className="gap-2 text-[12px] font-medium text-destructive focus:text-destructive"
                        onClick={() => handleDelete(article.id)}
                        disabled={deleteMutation.isPending}
