'use client';

import React, { useEffect, useState } from 'react';
import {
  Folder,
  Edit,
  FileText,
} from 'lucide-react';
import {
  useCreateCategoryMutation,
  useUpdateCategoryMutation,
  useCategoryQuery,
} from '../_hooks/useKnowledgeBaseQueries';
import { useKnowledgeBaseUiStore } from '../store/knowledgeBaseUi';
import { checkUserPermission, PERMISSIONS } from '@/utils/permissions';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Label } from '@/components/ui/label';

export function CategoryFormModal() {
  const {
    isCreateCategoryModalOpen,
    isEditCategoryModalOpen,
    setIsCreateCategoryModalOpen,
    setIsEditCategoryModalOpen,
    selectedCategoryIdForEdit,
  } = useKnowledgeBaseUiStore();

  const [name, setName] = useState('');
  const [description, setDescription] = useState('');

  const createMutation = useCreateCategoryMutation();
  const updateMutation = useUpdateCategoryMutation();
  const { data: category, isLoading } = useCategoryQuery(
    isEditCategoryModalOpen ? selectedCategoryIdForEdit : null,
  );

  const isOpen = isCreateCategoryModalOpen || isEditCategoryModalOpen;
  const isEdit = isEditCategoryModalOpen;
  const canCreateCategory = checkUserPermission([PERMISSIONS.categoryCreate]);
  const canUpdateCategory = checkUserPermission([PERMISSIONS.updateCategory]);

  useEffect(() => {
    if (isOpen && !isEdit) {
      setName('');
      setDescription('');
    } else if (isOpen && isEdit && category) {
      setName(category.name);
      setDescription(category.description || '');
    }
  }, [isOpen, isEdit, category]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!name.trim()) return;

    if (isEdit && selectedCategoryIdForEdit) {
      updateMutation.mutate({
        id: selectedCategoryIdForEdit,
        name: name.trim(),
        description: description.trim(),
      }, { onSuccess: handleClose });
    } else {
      createMutation.mutate({
        name: name.trim(),
        description: description.trim(),
      }, { onSuccess: handleClose });
    }
  };

  const handleClose = () => {
    setName('');
    setDescription('');
    setIsCreateCategoryModalOpen(false);
    setIsEditCategoryModalOpen(false);
  };

  const isPending = createMutation.isPending || updateMutation.isPending || isLoading;

  return (
    <Dialog open={isOpen} onOpenChange={(open) => !open && handleClose()}>
      <DialogContent className="sm:max-w-[520px] p-0 overflow-hidden rounded-xl border-none">
        <DialogHeader className="px-6 pt-6 pb-4 border-b bg-muted/30">
          <div className="flex items-center gap-3">
            <div className="bg-primary/10 flex h-10 w-10 items-center justify-center rounded-lg">
              {isEdit ? (
                <Edit className="text-primary size-5" />
              ) : (
                <Folder className="text-primary size-5" />
              )}
            </div>
            <div className="flex flex-col text-left">
              <DialogTitle className="text-lg font-semibold leading-none mb-1.5">
                {isEdit ? 'Edit Category' : 'Create New Category'}
              </DialogTitle>
              <DialogDescription className="text-xs text-muted-foreground">
                {isEdit
                  ? 'Update category details'
                  : 'Add a new category to organize articles'}
              </DialogDescription>
            </div>
          </div>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="px-6 py-6 space-y-6">
          <div className="space-y-2">
            <Label htmlFor="name" className="flex items-center gap-2 text-sm font-medium">
              <Folder className="size-3.5 text-primary" />
              Category Name <span className="text-destructive">*</span>
            </Label>
            <Input
              id="name"
              placeholder="Enter category name"
              value={name}
              onChange={(e) => setName(e.target.value)}
              required
              className="h-10 rounded-lg"
              disabled={isPending}
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="description" className="flex items-center gap-2 text-sm font-medium">
              <FileText className="size-3.5 text-primary" />
              Description
            </Label>
            <Textarea
              id="description"
              placeholder="Enter category description (optional)"
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              rows={4}
              className="rounded-lg resize-none"
              disabled={isPending}
            />
          </div>

          <DialogFooter className="pt-2">
            <Button
              type="button"
              variant="outline"
              onClick={handleClose}
              disabled={isPending}
              className="rounded-lg h-10"
            >
              Cancel
            </Button>
            <Button
              type="submit"
              disabled={isPending || !name.trim()}
              className="rounded-lg h-10 px-6"
            >
              {isEdit ? 'Update Category' : 'Create Category'}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

