'use client';

import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { fetchJson, fetchMultipart } from '@/utils/api';
import { unwrapData } from '@/api/core/envelopes';
import { useAuthStore } from '@/store/auth';
import type { ApiEnvelope } from '@/api/types/envelopes';

export type KnowledgeBaseArticle = {
  id: string | number;
  title: string;
  description: string;
  catagoryId?: string | number | null;
  createdBy?:
    | {
        id: string | number;
        first_name?: string;
        last_name?: string;
        email?: string;
        [k: string]: any;
      }
    | string
    | number;
  created_at: string;
  updated_at?: string;
  views?: number;
  documents?: Array<{
    id: string | number;
    name: string;
    url?: string;
    [k: string]: any;
  }>;
  [k: string]: any;
};

export type KnowledgeBaseCategory = {
  id: string | number;
  name: string;
  description?: string;
  [k: string]: any;
};

export type KnowledgeBaseComment = {
  id: string | number;
  comment: string;
  knowledgeBaseId: string | number;
  createdBy?: {
    id: string | number;
    first_name?: string;
    last_name?: string;
    email?: string;
    [k: string]: any;
  };
  created_at: string;
  [k: string]: any;
};

export type KnowledgeBaseDocument = {
  id: string | number;
  name: string;
  url?: string;
  knowledgeBaseId: string | number;
  created_at?: string;
  [k: string]: any;
};

export type CreateArticlePayload = {
  title: string;
  description: string;
  createdBy: string | number;
  catagoryId?: string | number | null;
  ticketId?: string | number | null;
};

export type UpdateArticlePayload = {
  id: string | number;
  title: string;
  description: string;
  createdBy: string | number;
  catagoryId?: string | number | null;
};

export type CreateCategoryPayload = {
  name: string;
  description?: string;
};

export type UpdateCategoryPayload = {
  id: string | number;
  name: string;
  description?: string;
};

function useToken() {
  const token = useAuthStore((s) => s.token);
  return (
    token ??
    (typeof window !== 'undefined' ? localStorage.getItem('token') : null)
  );
}

// Articles Queries
export function useArticlesQuery(ticketId?: string | number | null) {
  const token = useToken();
  return useQuery({
    queryKey: ['knowledgebase', 'articles', ticketId],
    queryFn: async () => {
      const endpoint = ticketId
        ? `/knowledgebase/ticket/${ticketId}`
        : '/knowledgebase';
      const res = await fetchJson<ApiEnvelope<KnowledgeBaseArticle[]>>(
        endpoint,
        { token },
      );
      const data = unwrapData<KnowledgeBaseArticle[] | KnowledgeBaseArticle>(
        res,
        [],
      );
      return Array.isArray(data) ? data : [data];
    },
    enabled: !!token,
    staleTime: 30 * 1000,
  });
}

export function useArticleQuery(articleId: string | number | null) {
  const token = useToken();
  return useQuery({
    queryKey: ['knowledgebase', 'article', articleId],
    queryFn: async () => {
      const res = await fetchJson<ApiEnvelope<KnowledgeBaseArticle>>(
        `/knowledgebase/${articleId}`,
        { token },
      );
      return unwrapData<KnowledgeBaseArticle>(res, {} as KnowledgeBaseArticle);
    },
    enabled: !!token && !!articleId,
    staleTime: 30 * 1000,
  });
}

// Categories Queries
export function useCategoriesQuery() {
  const token = useToken();
  return useQuery({
    queryKey: ['knowledgebase', 'categories'],
    queryFn: async () => {
      const res = await fetchJson<ApiEnvelope<KnowledgeBaseCategory[]>>(
        '/catagory',
        { token },
      );
      return unwrapData<KnowledgeBaseCategory[]>(res, []);
    },
    enabled: !!token,
    staleTime: 5 * 60 * 1000,
  });
}

export function useCategoryQuery(categoryId: string | number | null) {
  const token = useToken();
  return useQuery({
    queryKey: ['knowledgebase', 'category', categoryId],
    queryFn: async () => {

    queryFn: async () => {
      const res = await fetchJson<ApiEnvelope<KnowledgeBaseCategory>>(
        `/catagory/${categoryId}`,
        { token },
      );
      return unwrapData<KnowledgeBaseCategory>(
        res,
        {} as KnowledgeBaseCategory,
      );
    },
    enabled: !!token && !!categoryId,
    staleTime: 5 * 60 * 1000,
  });
}

// Comments Queries
export function useArticleCommentsQuery(articleId: string | number | null) {
  const token = useToken();
  return useQuery({
    queryKey: ['knowledgebase', 'comments', articleId],
    queryFn: async () => {
      const res = await fetchJson<ApiEnvelope<KnowledgeBaseComment[]>>(
        `/knowledgeBaseComments/knowledge-base/${articleId}`,
        { token },
      );
      return unwrapData<KnowledgeBaseComment[]>(res, []);
    },
    enabled: !!token && !!articleId,
    staleTime: 10 * 1000,
  });
}

// Documents Queries
export function useArticleDocumentsQuery(articleId: string | number | null) {
  const token = useToken();
  return useQuery({
    queryKey: ['knowledgebase', 'documents', articleId],
    queryFn: async () => {
      const res = await fetchJson<ApiEnvelope<KnowledgeBaseDocument[]>>(
        `/knowledgebase/documents/knowledgebase/${articleId}`,
        { token },
      );
      return unwrapData<KnowledgeBaseDocument[]>(res, []);
    },
    enabled: !!token && !!articleId,
    staleTime: 5 * 60 * 1000,
  });
}

// Article Mutations
export function useCreateArticleMutation() {
  const token = useToken();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (payload: CreateArticlePayload) => {
      const res = await fetchJson<ApiEnvelope<KnowledgeBaseArticle>>(
        '/knowledgebase',
        {
          token,
          method: 'POST',
          body: payload,
        },
      );
      return unwrapData<KnowledgeBaseArticle>(res, {} as KnowledgeBaseArticle);
    },
    meta: { successMessage: 'Article created successfully' },
    onSuccess: () => {
      queryClient.invalidateQueries({
        queryKey: ['knowledgebase', 'articles'],
      });
    },
  });
}

export function useUpdateArticleMutation() {
  const token = useToken();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (payload: UpdateArticlePayload) => {
      const { id, ...data } = payload;
      const res = await fetchJson<ApiEnvelope<KnowledgeBaseArticle>>(
        `/knowledgebase/${id}`,
        {
          token,
          method: 'PATCH',
          body: data,
        },
      );
      return unwrapData<KnowledgeBaseArticle>(res, {} as KnowledgeBaseArticle);
    },
    meta: { successMessage: 'Article updated successfully' },
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({
        queryKey: ['knowledgebase', 'articles'],
      });
      queryClient.invalidateQueries({
        queryKey: ['knowledgebase', 'article', variables.id],
      });
    },
  });
}

export function useDeleteArticleMutation() {
  const token = useToken();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (articleId: string | number) => {
      await fetchJson(`/knowledgebase/${articleId}`, {
        token,
        method: 'DELETE',
      });
      return articleId;
    },
    meta: { successMessage: 'Article deleted successfully' },
    onSuccess: () => {
      queryClient.invalidateQueries({
        queryKey: ['knowledgebase', 'articles'],
      });
    },
  });
}

// Category Mutations
export function useCreateCategoryMutation() {
  const token = useToken();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (payload: CreateCategoryPayload) => {
      const res = await fetchJson<ApiEnvelope<KnowledgeBaseCategory>>(
        '/catagory',
        {
