import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { fetchJson, fetchMultipart } from '@/utils/api';
import { useAuthStore } from '@/store/auth';
import type { AuthUser } from '@/store/auth';

type ApiEnvelope<T> = { data: T };

type NotificationPreference = { email?: boolean; push?: boolean };
export type NotificationPreferences = Record<string, NotificationPreference>;

type MySettings = {
  profile?: {
    first_name?: string | null;
    last_name?: string | null;
    email?: string | null;
    phone_number?: string | null;
    profile_pic?: string | null;
  };
};

type UpdateMyProfileInput = {
  first_name?: string;
  last_name?: string;
  phone_number?: string;
  profile_pic?: File | null;
};

function useToken() {
  const token = useAuthStore((s) => s.token);
  return (
    token ??
    (typeof window !== 'undefined' ? localStorage.getItem('token') : null)
  );
}

export function useMySettingsQuery() {
  const token = useToken();
  return useQuery({
    queryKey: ['my-settings'],
    queryFn: async () => {
      const res = await fetchJson<ApiEnvelope<MySettings>>('/users/me/settings', {
        token,
      });
      return res.data ?? {};
    },
    enabled: !!token,
    staleTime: 60 * 1000,
  });
}

export function useUpdateMyProfileMutation() {
  const token = useToken();
  const queryClient = useQueryClient();
  const setUserData = useAuthStore((s) => s.setUserData);
  const user = useAuthStore((s) => s.userData ?? s.user);

  return useMutation({
    mutationFn: async (input: UpdateMyProfileInput) => {
      const { profile_pic, ...rest } = input;
      const res =
        profile_pic instanceof File
          ? await fetchMultipart<ApiEnvelope<AuthUser>>('/users/me/profile', {
              token,
              method: 'PATCH',
              form: (() => {
                const form = new FormData();
                if (rest.first_name !== undefined)
                  form.append('first_name', rest.first_name);
                if (rest.last_name !== undefined)
                  form.append('last_name', rest.last_name);
                if (rest.phone_number !== undefined)
                  form.append('phone_number', rest.phone_number);
                form.append('profile_pic', profile_pic);
                return form;
              })(),
            })
          : await fetchJson<ApiEnvelope<AuthUser>>('/users/me/profile', {
              token,
              method: 'PATCH',
              body: rest,
            });
      return res.data;
    },
    onSuccess: (next) => {
      queryClient.invalidateQueries({ queryKey: ['my-settings'] });
      if (next) {
        setUserData({
          ...(user ?? {}),
          ...next,
        });
