export function useUpdatePasswordMutation() {
  const token = useToken();
  const user = useAuthStore((s) => s.userData ?? s.user);
  const userId = user?.id;
  return useMutation({
    mutationFn: async (input: { old_password: string; password: string }) => {
      if (!userId) throw new Error('User not found');
      return fetchJson(`/users/change-password/${userId}`, {
        token,
        method: 'PATCH',
        body: input,
      });
    },
  });
}

