import React from 'react';
import { Button, Flex, Input, Tooltip, Typography } from 'antd';
import {
  DeleteOutlined,
  LinkOutlined,
  PaperClipOutlined,
  PlusOutlined,
} from '@ant-design/icons';

type Props = {
  value?: string[];
  onChange?: (next: string[]) => void;
  label?: string;
};

export default function AttachmentLinks({
  value,
  onChange,
  label = 'Attachments',
}: Props) {
  const links = value ?? [];

  return (
    <div>
      <Flex align="center" gap={6} style={{ marginBottom: 8 }}>
        <PaperClipOutlined style={{ color: '#8c8c8c', fontSize: 13 }} />
        <Typography.Text type="secondary" style={{ fontSize: 13 }}>
          {label}
        </Typography.Text>
        {links.length > 0 && (
          <Typography.Text
            type="secondary"
            style={{
              fontSize: 11,
              background: '#f0f0f0',
              padding: '0 6px',
              borderRadius: 8,
              lineHeight: '18px',
            }}
          >
            {links.length}
          </Typography.Text>
        )}
      </Flex>

      <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
        {links.map((v, idx) => (
          <Flex key={idx} align="center" gap={8}>
            <Input
              value={v}
              onChange={(e) => {
                const next = [...links];
                next[idx] = e.target.value;
                onChange?.(next);
              }}
              placeholder="https://example.com/attachment..."
              prefix={<LinkOutlined style={{ color: '#bfbfbf' }} />}
              style={{
                borderRadius: 8,
                flex: 1,
              }}
            />
            <Tooltip title="Remove">
              <Button
                type="text"
                danger
                icon={<DeleteOutlined />}
                onClick={() => {
                  const next = links.filter((_, i) => i !== idx);
                  onChange?.(next);
                }}
                style={{ borderRadius: 8, flexShrink: 0 }}
              />
            </Tooltip>
          </Flex>
        ))}

        <Button
          type="dashed"
          icon={<PlusOutlined />}
          onClick={() => onChange?.([...links, ''])}
          className="rounded-lg !text-primary"
          style={{ borderColor: 'var(--border)' }}
          block
        >
          Add attachment link
        </Button>
      </div>
    </div>
  );
}

