      token,
      method: 'POST',
      body: payload,
    });
  },
  meta: { successMessage: 'Ticket created successfully' },
  onSuccess: async () => {
    await qc.invalidateQueries({ queryKey: ['tickets'] });
    closeCreateTicketModal();
    form.resetFields();
  },
