import { useEffect } from 'react';

import { useUpdateSupportApprovalMutation } from '../_hooks/useSupportListQueries';
import { onChangeApproval } from './supportFeatureEvents';

export default function SupportApprovalController() {
  const approvalMutation = useUpdateSupportApprovalMutation();

  useEffect(() => {
    return onChangeApproval((supportId, statusId) => {
