type TicketListener = (ticketId: string | number) => void;
type SupportListener = (supportId: string | number | null) => void;
type ApprovalListener = (
  supportId: string | number,
  statusId: string | number,
) => void;

const ticketListeners = new Set<TicketListener>();
const createTicketListeners = new Set<SupportListener>();
const approvalListeners = new Set<ApprovalListener>();

export function openTicket(ticketId: string | number) {
  ticketListeners.forEach((listener) => listener(ticketId));
}

export function onOpenTicket(listener: TicketListener) {
  ticketListeners.add(listener);
  return () => {
    ticketListeners.delete(listener);
  };
}

export function openCreateTicket(supportId: string | number | null) {
  createTicketListeners.forEach((listener) => listener(supportId));
}

export function onOpenCreateTicket(listener: SupportListener) {
  createTicketListeners.add(listener);
  return () => {
    createTicketListeners.delete(listener);
  };
}

export function changeApproval(
  supportId: string | number,
  statusId: string | number,
) {
  approvalListeners.forEach((listener) => listener(supportId, statusId));
}

export function onChangeApproval(listener: ApprovalListener) {
  approvalListeners.add(listener);
  return () => {
    approvalListeners.delete(listener);
  };
}

