'use client';

import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { fetchJson } from '@/utils/api';
import { unwrapData } from '@/api/core/envelopes';
import { useAuthStore } from '@/store/auth';
import type { ApiEnvelope } from '@/api/types/envelopes';

function useToken() {
  const token = useAuthStore((s) => s.token);
  return (
    token ??
    (typeof window !== 'undefined' ? localStorage.getItem('token') : null)
  );
}

export type SupportStatus = {
  id: string | number;
  status: string;
  [k: string]: any;
};

// NOTE: backend returns a "legacy tree" for /support (client -> supports -> project -> tickets -> issues)
export type SupportsTreeNode = any;

export function useSupportsTreeQuery() {
  const token = useToken();
  return useQuery({
    queryKey: ['supportsTree'],
    queryFn: async () => {
      const res = await fetchJson<ApiEnvelope<SupportsTreeNode[]>>('/support', {
        token,
      });
      return unwrapData<SupportsTreeNode[]>(res, []);
    },
    enabled: !!token,
    staleTime: 60 * 1000,
  });
}

export function useSupportStatusesQuery() {
  const token = useToken();
  return useQuery({
    queryKey: ['supportStatuses'],
    queryFn: async () => {
      const res = await fetchJson<ApiEnvelope<SupportStatus[]>>(
        '/support/status',
        { token },
      );
      return unwrapData<SupportStatus[]>(res, []);
    },
    enabled: !!token,
    staleTime: 10 * 60 * 1000,
  });
}

export function useUpdateSupportApprovalMutation() {
  const token = useToken();
  const qc = useQueryClient();
  return useMutation({
    mutationFn: async (vars: {
      supportId: string | number;
      supportStatusId: string | number;
    }) => {
      return fetchJson<ApiEnvelope<any>>('/support/approval/status', {
        token,
        method: 'PATCH',
        body: {
          supportStatusId: vars.supportStatusId,
          supportId: vars.supportId,
        },
      });
    },
    meta: { successMessage: 'Support approval updated successfully' },
    onSuccess: async () => {
      await qc.invalidateQueries({ queryKey: ['supportsTree'] });
      await qc.invalidateQueries({ queryKey: ['supportStatuses'] });
    },
  });
}

