import React, { useState, useMemo } from 'react';
import { Dropdown, Button, Spin, Input } from 'antd';
import { UserOutlined, CheckOutlined, SearchOutlined } from '@ant-design/icons';
import {
  useUsersQuery,
  useAssignTicketUsersMutation,
} from '../_hooks/useTicketsQueries';
import { getUserExternalId } from '@/utils/externalIdentity';
import { getTicketAssigneeExternalIds } from '@/utils/ticketAssignees';

type AssignDropdownProps = {
  ticket: any;
  trigger?: React.ReactNode;
  placement?:
    | 'bottomLeft'
    | 'bottom'
    | 'bottomRight'
    | 'topLeft'
    | 'top'
    | 'topRight';
};

export function AssignDropdown({
  ticket,
  trigger,
  placement = 'bottomLeft',
}: AssignDropdownProps) {
  const [open, setOpen] = useState(false);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [search, setSearch] = useState('');

  const { data: users = [], isLoading } = useUsersQuery();
  const assignMutation = useAssignTicketUsersMutation();

  const currentAgentIds = useMemo(
    () => getTicketAssigneeExternalIds(ticket),
    [ticket],
  );

  const filteredUsers = useMemo(() => {
    if (!search.trim()) return users;
    const q = search.trim().toLowerCase();
    return (users as any[]).filter((u: any) => {
      const label =
        [u?.first_name, u?.last_name].filter(Boolean).join(' ') ||
        u?.email ||
        '';
      return (
        label.toLowerCase().includes(q) ||
        (u?.email ?? '').toLowerCase().includes(q)
      );
    });
  }, [users, search]);

  const toggleUser = (id: string) => {
    setSelectedIds((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  };

  const handleApply = () => {
    if (!ticket?.id || selectedIds.size === 0) {
      setOpen(false);
      return;
    }
    assignMutation.mutate(
      { ticketId: ticket.id, userExternalIds: Array.from(selectedIds) },
      { onSettled: () => setOpen(false) },
    );
  };

  const listContent = (
    <div className="border-border bg-card flex max-h-[320px] min-w-[260px] flex-col rounded-lg border shadow-lg">
      <div className="border-border flex items-center justify-between border-b px-3 py-2">
        <span className="text-foreground text-sm font-semibold">
          Assign agents
        </span>
        <Button type="text" size="small" onClick={() => setOpen(false)}>
          ✕
        </Button>
      </div>
      <div className="border-border border-b px-2 pt-2">
        <Input
          placeholder="Search users..."
          prefix={<SearchOutlined className="text-muted-foreground" />}
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          allowClear
          size="small"
          className="rounded-md"
          onClick={(e) => e.stopPropagation()}
        />
      </div>
      <div className="flex-1 overflow-y-auto p-2 min-h-[120px] max-h-[240px]">
        {isLoading ? (
          <div className="flex justify-center py-6">
            <Spin size="small" />
          </div>
        ) : filteredUsers.length === 0 ? (
          <p className="text-muted-foreground py-4 text-center text-xs">
            {search.trim()
              ? 'No users match your search'
              : 'No users available'}
          </p>
        ) : (
          <ul className="space-y-0.5">
            {filteredUsers.map((u: any) => {
              const id = getUserExternalId(u) ?? String(u?.id ?? '');
              const label =
                [u?.first_name, u?.last_name].filter(Boolean).join(' ') ||
                u?.email ||
                id;
              const isSelected =
                (id && selectedIds.has(id)) || (id && currentAgentIds.has(id));
              return (
                <li
                  key={id || String(u?.id)}
                  role="button"
                  onClick={() => id && toggleUser(id)}
                  className={`flex cursor-pointer items-center justify-between rounded-md px-3 py-2 text-sm transition-colors ${
                    isSelected
                      ? 'bg-primary/10 text-primary font-medium'
                      : 'text-foreground hover:bg-muted/50'
                  }`}
                >
                  <span>{label}</span>
                  {isSelected && <CheckOutlined style={{ fontSize: 12 }} />}
                </li>
              );
            })}
          </ul>
        )}
      </div>
      <div className="border-border flex justify-end gap-2 border-t px-3 py-2">
        <Button size="small" onClick={() => setOpen(false)}>
          Cancel
        </Button>
        <Button
          type="primary"
          size="small"
          icon={<CheckOutlined />}
          loading={assignMutation.isPending}
          onClick={handleApply}
        >
          Apply
        </Button>
      </div>
    </div>
  );

  const triggerNode = trigger ?? (
    <Button type="default" size="small" icon={<UserOutlined />}>
      Assign
    </Button>
  );

  return (
    <Dropdown
      open={open}
      onOpenChange={(v) => {
        setOpen(v);
        if (v) {
          setSelectedIds(new Set<string>(currentAgentIds));
          setSearch('');
        } else {
          setSelectedIds(new Set());
        }
      }}
      trigger={['click']}
      placement={placement}
      dropdownRender={() => listContent}
    >
      <span className="inline-block">{triggerNode}</span>
    </Dropdown>
  );
}

