'use client';

import React from 'react';
import { Ticket } from '../_hooks/useTicketsQueries';

type ChipProps = {
  ticket: Ticket;
  tag: string;
  color?: string;
};

const statusColors: Record<
  string,
  { bg: string; text: string; border: string }
> = {
  open: {
    bg: 'bg-emerald-50',
    text: 'text-emerald-700',
    border: 'border-emerald-200',
  },
  'in progress': {
    bg: 'bg-blue-50',
    text: 'text-blue-700',
    border: 'border-blue-200',
  },
  pending: {
    bg: 'bg-amber-50',
    text: 'text-amber-700',
    border: 'border-amber-200',
  },
  closed: {
    bg: 'bg-muted',
    text: 'text-muted-foreground',
    border: 'border-border',
  },
  resolved: {
    bg: 'bg-green-50',
    text: 'text-green-700',
    border: 'border-green-200',
  },
};

export function Chip({ ticket, tag, color }: ChipProps) {
  const lowerTag = tag.toLowerCase();
  const preset = statusColors[lowerTag];

  if (preset && !color) {
    return (
      <span
        className={`${preset.bg} ${preset.text} ${preset.border} border px-3 py-0.5 rounded-full text-xs font-semibold`}
      >
        {tag}
      </span>
    );
  }

  return (
    <span
      className="text-white px-3 py-0.5 rounded-full text-xs font-semibold"
      style={{ backgroundColor: color || '#8c8c8c' }}
    >
      {tag}
    </span>
  );
}

'use client';

import React, { useState, useEffect, useRef } from 'react';
import { IoMdClose } from 'react-icons/io';
import {
  useReplyCommentMutation,
  useAddNoteMutation,
  useEscalateCommentMutation,
  type CommentPayload,
} from '../_hooks/useTicketsQueries';
import { UserEmailSelect } from './UserEmailSelect';
import { RichTextEditor } from '@/app/(afterLogin)/client-portal/_components/RichTextEditor';
import { checkUserPermission, PERMISSIONS } from '@/utils/permissions';

export type FormMode = 'reply' | 'note' | 'escalation';

type CommentNoteEscalationFormProps = {
  ticket: any;
  label: string;
  mail: FormMode;
  onClose: () => void;
  users?: any[];
  assigned_users?: any[];
};

export function CommentNoteEscalationForm({
  ticket,
  label,
  mail,
  onClose,
  users = [],
  assigned_users = [],
}: CommentNoteEscalationFormProps) {
  const [subject, setSubject] = useState('');
  const [description, setDescription] = useState('');
  const [emailTo, setEmailTo] = useState<string[]>([]);
  const [emailCc, setEmailCc] = useState<string[]>([]);
  const [validationErrors, setValidationErrors] = useState<{
    emailTo: string;
    subject: string;
    description: string;
  }>({
    emailTo: '',
    subject: '',
    description: '',
  });

  const replyMutation = useReplyCommentMutation();
  const noteMutation = useAddNoteMutation();
  const escalateMutation = useEscalateCommentMutation();
  const prevLoadingRef = useRef(false);

  const loading =
    replyMutation.isPending ||
    noteMutation.isPending ||
    escalateMutation.isPending;
  const error =
    replyMutation.error || noteMutation.error || escalateMutation.error;

  function getTicketInfoHTML(): string {
    if (!ticket?.id) return '';
    if (mail !== 'escalation') return '';
    return `
      <div style="margin-top: 25px; padding-top: 10px; border-top: 1px solid #e5e7eb; font-family: Arial, sans-serif; font-size: 13px; color: #4b5563; line-height: 1.6;">
       <br><br>
        <p style="margin: 0; color: #1f2937; font-weight: 600;">—</p>
        <p style="margin: 2px 0 0 0;"><strong>Ticket ID:</strong> ${ticket.id}</p>
        <p style="margin: 2px 0 0 0;"><strong>Subject:</strong> ${ticket.subject || ticket.description || 'N/A'}</p>
        <p style="margin: 8px 0 0 0; color: #6b7280; font-style: italic;">Sent via Support Desk</p>
      </div>
    `;
  }

  const initialDescription = getTicketInfoHTML();
  const [initialized, setInitialized] = useState(false);

  useEffect(() => {
    if (!initialized && ticket?.id && mail === 'escalation') {
      setDescription(initialDescription);
      setInitialized(true);
    }
  }, [ticket?.id, mail, initialized, initialDescription]);

  useEffect(() => {
    if (mail !== 'reply' || emailTo.length > 0) return;
    if (assigned_users?.length > 0) {
      const emails = assigned_users
        .map((u: any) => u?.email)
        .filter(Boolean) as string[];
      if (emails.length) setEmailTo(emails);
    } else if (ticket?.client?.email) {
      setEmailTo([ticket.client.email]);
    }
  }, [assigned_users, mail, ticket?.client?.email, emailTo.length]);

  function appendTicketInfo(htmlContent: string): string {
    if (!ticket?.id) return htmlContent;
    const ticketInfoHTML = getTicketInfoHTML();
    if (!ticketInfoHTML) return htmlContent;
    if (htmlContent.includes(`Ticket ID:</strong> ${ticket.id}`))
      return htmlContent;
    const trimmed = htmlContent
      .replace(/<[^>]*>/g, '')
      .replace(/&nbsp;/g, ' ')
      .trim();
    if (!trimmed) return ticketInfoHTML;
    return htmlContent + ticketInfoHTML;
  }

  function validateForm(): boolean {
    const errors = { emailTo: '', subject: '', description: '' };
    let valid = true;

    if (!emailTo?.length) {
      errors.emailTo = 'At least one recipient is required';
      valid = false;
    }
    if (!subject.trim()) {
      errors.subject = 'Subject is required';
      valid = false;
    }
    const descText = description
      .replace(/<[^>]*>/g, '')
      .replace(/&nbsp;/g, ' ')
      .trim();
    const ticketInfoText = getTicketInfoHTML()
      .replace(/<[^>]*>/g, '')
      .replace(/&nbsp;/g, ' ')
      .trim();
    let actualContent = descText;
    if (ticketInfoText && descText.includes(ticketInfoText)) {
      actualContent = descText.replace(ticketInfoText, '').trim();
    }
    if (!actualContent) {
      errors.description = 'Description is required';
      valid = false;
    }
    setValidationErrors(errors);
    return valid;
  }

  useEffect(() => {
    const loadingJustFinished = prevLoadingRef.current === true && !loading;
    if (loadingJustFinished && !error) {
      onClose();
    }
    prevLoadingRef.current = loading;
  }, [loading, error, onClose]);

  const handleSubmit = () => {
    if (!validateForm() || !ticket?.id) return;
    if (mail === 'reply' && !checkUserPermission([PERMISSIONS.commentCreate])) {
      return;
    }
    if (mail === 'note' && !checkUserPermission([PERMISSIONS.noteCreate])) {
      return;
    }
    if (mail === 'escalation' && !checkUserPermission([PERMISSIONS.ticketReplay])) {
      return;
    }
    const finalDescription =
      mail === 'escalation' ? appendTicketInfo(description) : description;

      mail === 'escalation' ? appendTicketInfo(description) : description;
    const payload: CommentPayload = {
      ticket_id: ticket.id,
      title: subject.trim(),
      description: finalDescription,
      emailTo,
      emailCc: emailCc.length ? emailCc : undefined,
    };
    if (mail === 'reply') {
      replyMutation.mutate(payload);
    } else if (mail === 'note') {
      noteMutation.mutate(payload);
    } else if (mail === 'escalation') {
      escalateMutation.mutate(payload);
    }
  };

  const submitLabel = mail ? 'Send' : 'Submit';

  return (
    <div className="border-border bg-card overflow-hidden rounded-md border shadow-sm">
      <div className="border-border bg-muted/60 flex h-12 items-center justify-between border-b px-4 sm:px-6">
        <span className="text-foreground text-sm font-semibold">{label}</span>
        <button
          type="button"
          onClick={onClose}
          className="text-muted-foreground hover:text-foreground rounded-lg p-1.5 transition-colors hover:bg-muted"
          aria-label="Close"
        >
          <IoMdClose className="w-5 h-5" />
        </button>
      </div>

      <div className="p-4 sm:p-6 space-y-4">
        <div className="grid gap-1">
          <div className="flex flex-col gap-1">
            <div className="flex gap-2 items-center">
              <span className="text-foreground w-8 text-sm font-semibold">
                To:
              </span>
              <div className="flex-1 min-w-0">
                <UserEmailSelect
                  users={users}
                  value={emailTo}
                  onChange={setEmailTo}
                  ticket={mail === 'reply' ? ticket : undefined}
                  defaultEmails={assigned_users
                    ?.map((u: any) => u?.email)
                    .filter(Boolean)}
                  placeholder="Search users or type email"
                />
              </div>
            </div>
            {validationErrors.emailTo && (
              <p className="text-xs text-red-500 ml-10">
                {validationErrors.emailTo}
              </p>
            )}
          </div>
          <div className="flex gap-2 items-center">
            <span className="text-foreground w-8 text-sm font-semibold">
              Cc:
            </span>
            <div className="flex-1 min-w-0">
              <UserEmailSelect
                users={users}
                value={emailCc}
                onChange={setEmailCc}
                placeholder="Search users or type email"
              />
            </div>
          </div>
        </div>

        <div className="flex flex-col gap-1">
          <input
            value={subject}
            onChange={(e) => {
              setSubject(e.target.value);
              if (validationErrors.subject) {
                setValidationErrors((prev) => ({ ...prev, subject: '' }));
              }
            }}
            type="text"
            className={`focus:ring-primary/30 w-full rounded-lg border bg-card px-4 py-2 text-sm focus:outline-none focus:ring-2 ${
              validationErrors.subject ? 'border-red-400' : 'border-border'
            }`}
            placeholder="Subject"
          />
          {validationErrors.subject && (
            <p className="text-xs text-red-500 mt-0.5">
              {validationErrors.subject}
            </p>
          )}
        </div>

        <div className="flex flex-col gap-1">
          <RichTextEditor
            value={description}
            onChange={(html) => {
              const next =
                mail === 'escalation' ? appendTicketInfo(html) : html;
              setDescription(next);
              if (validationErrors.description) {
                setValidationErrors((prev) => ({ ...prev, description: '' }));
              }
            }}
            placeholder="Write something..."
          />
          {validationErrors.description && (
            <p className="text-xs text-red-500 mt-0.5">
              {validationErrors.description}
            </p>
          )}
        </div>

        {error && (
          <p className="text-sm text-red-500">
            {mail === 'note' &&
            /unauthorized|private/i.test((error as Error).message)
              ? "You don't have permission to add a private note on this ticket. Your role may need the add-private-note permission."
              : (error as Error).message ||
                'Something went wrong. Please try again.'}
          </p>
        )}

        <div className="flex gap-2 justify-end pt-2">
          <button
            type="button"
            onClick={handleSubmit}
            disabled={loading}
            className="bg-primary text-primary-foreground h-9 rounded-md border border-transparent px-4 text-sm font-semibold shadow-sm hover:opacity-90 disabled:opacity-60"
          >
            {loading ? 'Sending…' : submitLabel}
          </button>
          <button
            type="button"
            onClick={onClose}
            className="border-border bg-card text-muted-foreground hover:bg-muted/60 h-9 rounded-md border px-4 text-sm font-medium"
          >
            Cancel
          </button>
        </div>
      </div>
    </div>
  );
}

