import React, { useState, useRef, useEffect } from 'react';
import {
  CheckOutlined,
  DownOutlined,
  LoadingOutlined,
} from '@ant-design/icons';

const NO_PRIORITY_VALUE = '__none__';

const PRIORITY_COLOR_MAP: Record<string, string> = {
  High: 'bg-red-400',
  Medium: 'bg-amber-400',
  Low: 'bg-emerald-400',
  Urgent: 'bg-blue-400',
};

function getPriorityColor(name: string): string {
  return PRIORITY_COLOR_MAP[name] ?? 'bg-muted';
}

type PrioritySelectorProps = {
  bgColor?: string;
  menu: Array<{
    name: string;
    value: string | number;
    priority_color?: string;
  }>;
  text: string;
  onPrioritySelect: (value: string | number) => void;
  placeholder?: string;
  loading?: boolean;
};

export function PrioritySelector({
  bgColor = 'bg-card',
  menu,
  text,
  onPrioritySelect,
  placeholder = 'No priority',
  loading = false,
}: PrioritySelectorProps) {
  const [isOpen, setIsOpen] = useState(false);
  const [pendingValue, setPendingValue] = useState<string | number | null>(
    null,
  );
  const containerRef = useRef<HTMLDivElement>(null);

  const currentValue =
    text &&
    menu.some((m) => String(m.value) === String(text) || m.name === text)
      ? (menu.find((m) => m.name === text)?.value ?? NO_PRIORITY_VALUE)
      : NO_PRIORITY_VALUE;
  const effectivePending = pendingValue ?? currentValue;

  const displayText =
    effectivePending === NO_PRIORITY_VALUE
      ? placeholder
      : (menu.find((m) => String(m.value) === String(effectivePending))?.name ??
        text ??
        placeholder);

  const displayColor =
    effectivePending === NO_PRIORITY_VALUE
      ? 'bg-muted'
      : (menu.find((m) => String(m.value) === String(effectivePending))
          ?.priority_color ?? 'bg-muted');

  useEffect(() => {
    if (!isOpen) setPendingValue(null);
  }, [isOpen]);

  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (
        containerRef.current &&
        !containerRef.current.contains(e.target as Node)
      ) {
        setIsOpen(false);
      }
    };
    if (isOpen) {
      document.addEventListener('mousedown', handleClickOutside);
      return () =>
        document.removeEventListener('mousedown', handleClickOutside);
    }
  }, [isOpen]);

  const handleApply = () => {

  const handleApply = () => {
    const valueToApply = pendingValue ?? currentValue;
    if (
      String(valueToApply) === String(currentValue) &&
      pendingValue === null
    ) {
      setIsOpen(false);
      return;
    }
    onPrioritySelect(valueToApply);
    setIsOpen(false);
    setPendingValue(null);
  };

  const options: Array<{
    name: string;
    value: string | number;
    priority_color?: string;
  }> = [
    {
      name: placeholder,
      value: NO_PRIORITY_VALUE as string,
      priority_color: undefined,
    },
    ...menu.map((item) => ({
      name: item.name,
      value: item.value,
      priority_color: item.priority_color,
    })),
  ];
  return (
    <div className="relative" ref={containerRef}>
      <div
        role="combobox"
        aria-expanded={isOpen}
        aria-haspopup="listbox"
        aria-label="Priority"
        aria-busy={loading}
        className={`
          inline-flex min-w-[88px] max-w-[200px] items-center overflow-hidden rounded-lg border
          border-border bg-card transition-colors
          ${loading ? 'cursor-wait opacity-70' : 'hover:border-primary/30 hover:bg-muted/50 cursor-pointer'}
        `}
        onClick={() => !loading && setIsOpen((o) => !o)}
      >
        <span className="text-foreground flex items-center gap-1.5 py-1.5 pl-2.5">
          {loading ? (
            <LoadingOutlined
              style={{ fontSize: 12 }}
              className="text-muted-foreground"
            />
          ) : (
            <span
              style={{
                backgroundColor:
                  displayText == 'No priority' ? '#bfbfbf' : displayColor,
              }}
              className={`h-2.5 w-2.5 shrink-0 rounded-sm ${NO_PRIORITY_VALUE}`}
              aria-hidden
            />
          )}
          <span className="text-xs font-medium">{displayText}</span>
        </span>
        <span className="text-muted-foreground ml-auto flex h-full items-center py-1 pr-1.5">
          {loading ? (
            <LoadingOutlined style={{ fontSize: 10 }} />
          ) : (
            <DownOutlined
              style={{ fontSize: 10 }}
              className={`transition-transform ${isOpen ? 'rotate-180' : ''}`}
            />
          )}
        </span>
      </div>

      {isOpen && (
        <div
          role="listbox"
          className="border-border bg-card absolute end-0 z-[100] mt-1 w-40 rounded-md border py-1.5 shadow-lg"
          aria-label="Priority options"
        >
          <div className="max-h-56 overflow-y-auto">
            {options.map((item) => {
              const isSelected =
                String(item.value) === String(effectivePending);
              const dotColor =
                item.value === NO_PRIORITY_VALUE
                  ? 'bg-muted'
                  : (item.priority_color ?? 'bg-muted');
              return (
                <div
                  key={String(item.value)}
                  role="option"
                  aria-selected={isSelected}
                  className={`
                    flex cursor-pointer items-center gap-2 px-3 py-2 text-xs transition-colors
                    ${
                      isSelected
                        ? 'bg-primary/10 text-primary font-medium'
                        : 'text-foreground hover:bg-muted/60 hover:text-foreground'
                    }
                  `}
                  onClick={() => setPendingValue(item.value)}
                >
                  <span
                    style={{
                      backgroundColor:
                        item.value === NO_PRIORITY_VALUE ? '#bfbfbf' : dotColor,
                    }}
                    className={`h-2 w-2 shrink-0 rounded-sm`}
                    aria-hidden
                  />
                  <span>{item.name}</span>
                </div>
              );
            })}
          </div>
          <div className="border-border mt-1 flex justify-end border-t px-2 pt-2">
            <button
              type="button"
              onClick={handleApply}
              disabled={loading}
              className="bg-muted text-foreground hover:bg-primary/15 hover:text-primary flex h-8 w-8 items-center justify-center rounded-full transition-colors disabled:cursor-wait disabled:opacity-50"
              aria-label="Apply priority"
            >
              {loading ? (
                <LoadingOutlined style={{ fontSize: 14 }} />
              ) : (
                <CheckOutlined style={{ fontSize: 14 }} />
              )}
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

