import React from 'react';
import { MailOutlined, LockOutlined, AlertOutlined } from '@ant-design/icons';

function formatDistanceToNow(date: Date): string {
  const now = new Date();
  const diffInSeconds = Math.floor((now.getTime() - date.getTime()) / 1000);
  const diffInMinutes = Math.floor(diffInSeconds / 60);
  const diffInHours = Math.floor(diffInMinutes / 60);
  const diffInDays = Math.floor(diffInHours / 24);

  if (diffInDays > 0) return `${diffInDays}d ago`;
  if (diffInHours > 0) return `${diffInHours}h ago`;
  if (diffInMinutes > 0) return `${diffInMinutes}m ago`;
  return diffInSeconds <= 5 ? 'Just now' : `${diffInSeconds}s ago`;
}

function getAuthorName(m: any): string {
  const by = m?.created_by ?? m?.user;
  if (!by) return 'Unknown';
  if (typeof by === 'string') return by;
  return (
    [by?.first_name, by?.last_name].filter(Boolean).join(' ') ||
    by?.email ||
    'Unknown'
  );
}

function getAuthorInitials(m: any): string {
  const by = m?.created_by ?? m?.user;
  if (!by || typeof by === 'string') return '?';
  const f = (by?.first_name ?? '')?.[0] ?? '';
  const l = (by?.last_name ?? '')?.[0] ?? '';
  if (f || l) return `${f}${l}`.toUpperCase();
  return (by?.email ?? '?')?.[0]?.toUpperCase() ?? '?';
}

type MessageType = 'reply' | 'note' | 'escalation';

function getMessageType(m: any): MessageType {
  if (m?.is_escalation) return 'escalation';
  if (m?.is_private) return 'note';
  return 'reply';
}

const typeStyles: Record<
  MessageType,
  {
    badge: string;
    card: string;
    accent: string;
    avatar: string;
    icon: React.ReactNode;
  }
> = {
  reply: {
    badge: 'border-primary/20 bg-primary/10 text-primary',
    card: 'border-border bg-muted/50',
    accent: 'bg-primary',
    avatar: 'from-violet-600 to-violet-800 bg-gradient-to-br text-white',
    icon: <MailOutlined style={{ fontSize: 9 }} />,
  },
  note: {
    badge: 'bg-amber-50 text-amber-700 border-amber-100',
    card: 'bg-amber-50/40 border-amber-200/60',
    accent: 'bg-amber-400',
    avatar: 'bg-gradient-to-br from-amber-500 to-amber-600 text-white',
    icon: <LockOutlined style={{ fontSize: 9 }} />,
  },
  escalation: {
    badge: 'bg-rose-50 text-rose-700 border-rose-100',
    card: 'bg-rose-50/40 border-rose-200/60',
    accent: 'bg-rose-400',
    avatar: 'bg-gradient-to-br from-rose-500 to-rose-600 text-white',
    icon: <AlertOutlined style={{ fontSize: 9 }} />,
  },
};

const typeLabels: Record<MessageType, string> = {
  reply: 'Reply',
  note: 'Note',
  escalation: 'Escalation',
};

type RepliedMessageProps = {
  replied_mail: any;
  replied?: boolean;
  users?: any[];
};

export function RepliedMessage({
  replied_mail,
  replied,
  users,
}: RepliedMessageProps) {
  const m = replied_mail;
  if (!m) return null;

  const type = getMessageType(m);
  const styles = typeStyles[type];
  const authorName = getAuthorName(m);
  const initials = getAuthorInitials(m);
  const timeStr = m?.created_at
    ? formatDistanceToNow(new Date(m.created_at))
    : '';
  const toList = Array.isArray(m?.emailTo) ? m.emailTo : [];
  const ccList = Array.isArray(m?.emailCc) ? m.emailCc : [];

  const ccList = Array.isArray(m?.emailCc) ? m.emailCc : [];
  const body = m?.description ?? m?.comment ?? m?.body ?? '';

  return (
    <div
      className={`relative rounded-xl border ${styles.card} overflow-hidden transition-all hover:shadow-sm mb-3 last:mb-0`}
    >
      {/* Accent bar */}
      <div
        className={`absolute left-0 top-0 bottom-0 w-1 ${styles.accent} rounded-l-xl`}
      />

      <div className="pl-5 pr-5 pt-4 pb-4">
        {/* Header: avatar, author, badge, time */}
        <div className="flex items-start gap-3">
          <div
            className={`flex h-10 w-10 shrink-0 items-center justify-center rounded-xl text-sm font-semibold shadow-sm ${styles.avatar}`}
          >
            {initials}
          </div>
          <div className="min-w-0 flex-1">
            <div className="flex flex-wrap items-center gap-2">
              <span className="text-foreground text-sm font-semibold">
                {authorName}
              </span>
              <span
                className={`inline-flex items-center gap-1 rounded-full border px-2 py-0.5 text-xs font-medium ${styles.badge}`}
              >
                {styles.icon}
                {typeLabels[type]}
              </span>
              {timeStr && (
                <span className="text-muted-foreground text-xs tabular-nums">
                  {timeStr}
                </span>
              )}
            </div>

            {/* Subject */}
            {m?.title && (
              <p className="text-foreground mt-1.5 text-sm">
                <span className="text-muted-foreground text-xs font-medium uppercase tracking-wider">
                  Subject:
                </span>{' '}
                <span className="font-medium">{m.title}</span>
              </p>
            )}

            {/* To / Cc */}
            {(toList.length > 0 || ccList.length > 0) && (
              <div className="text-muted-foreground mt-2 flex flex-wrap items-center gap-x-4 gap-y-1 text-xs">
                <span className="flex items-center gap-1.5">
                  <MailOutlined
                    className="text-muted-foreground"
                    style={{ fontSize: 11 }}
                  />
                  <span className="font-medium">To:</span>
                  <span>{toList.join(', ') || '—'}</span>
                </span>
                <span className="flex items-center gap-1.5">
                  <span className="font-medium">Cc:</span>
                  <span>{ccList.join(', ') || '—'}</span>
                </span>
              </div>
            )}
          </div>
        </div>

        {/* Body */}
        {body && (
          <div className="border-border mt-4 rounded-lg border bg-background/90 px-4 py-3">
            <div
              className="prose prose-slate prose-sm text-foreground prose-headings:my-2 prose-p:my-1 prose-a:text-primary max-w-none prose-img:rounded-lg"
              dangerouslySetInnerHTML={{ __html: body }}
            />
          </div>
        )}
      </div>
    </div>
  );
}

