'use client';

import React, { useState, useRef, useEffect } from 'react';
import {
  CheckOutlined,
  DownOutlined,
  LoadingOutlined,
} from '@ant-design/icons';
import { message } from 'antd';
import { useUpdateTicketMutation } from '../_hooks/useTicketsQueries';
import type { Ticket } from '../_hooks/useTicketsQueries';
import { checkUserPermission, PERMISSIONS } from '@/utils/permissions';

export type StatusOption = {
  id: string | number;
  type: string;
  status_color?: string;
};

type TagSelectProps = {
  ticket: Ticket;
  menu: StatusOption[];
  text: string;
  id: string | number;
};

export function TagSelect({ ticket, menu, text, id }: TagSelectProps) {
  const [isOpen, setIsOpen] = useState(false);
  const [pendingStatusId, setPendingStatusId] = useState<
    string | number | null
  >(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const updateTicket = useUpdateTicketMutation();
  const canUpdateTicket = checkUserPermission([PERMISSIONS.ticketUpdate]);

  const currentId =
    id != null && id !== ''
      ? id
      : (menu.find((m) => m.type === text)?.id ??
        menu.find((m) => m.type?.toLowerCase() === text?.toLowerCase())?.id ??
        null);
  const effectivePending = pendingStatusId ?? currentId;
  const displayText = menu.find((m) => m.id === effectivePending)?.type ?? text;
  const statusColor =
    typeof ticket.ticket_status === 'object' && ticket.ticket_status != null
      ? (ticket.ticket_status as { status_color?: string }).status_color
      : menu.find((m) => m.id === effectivePending)?.status_color;

  useEffect(() => {
    if (!isOpen) setPendingStatusId(null);
  }, [isOpen]);

  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (
        containerRef.current &&
        !containerRef.current.contains(e.target as Node)
      ) {
        setIsOpen(false);
      }
    };
    if (isOpen) {
      document.addEventListener('mousedown', handleClickOutside);
      return () =>
        document.removeEventListener('mousedown', handleClickOutside);
    }
  }, [isOpen]);

  const buildPayload = (): Record<string, string | number> => {
    const tid = pendingStatusId ?? currentId;
    const payload: Record<string, string | number> = {};
    if (tid != null) payload.status_id = tid;
    const priorityId = (ticket as any)?.ticket_priority?.id;
    const teamId = (ticket as any)?.team?.id ?? (ticket as any)?.department?.id;
    const typeId = (ticket as any)?.ticket_type?.id;
    if (priorityId != null) payload.priority_id = priorityId;
    if (teamId != null) payload.team_id = teamId;
    if (typeId != null) payload.type_id = typeId;
    return payload;
  };

  const handleApply = () => {
    if (!canUpdateTicket) {
      message.error('You do not have permission to update tickets');
      return;
    }
    const payload = buildPayload();
    const statusId = payload.status_id;
    if (statusId == null) return;
    if (String(statusId) === String(currentId) && !pendingStatusId) {
      setIsOpen(false);
      return;
    }
    updateTicket.mutate(
      {
        ticketId: ticket.id,
        data: payload,
      },
      {
        onSuccess: () => {
          message.success('Status updated');
          setIsOpen(false);
          setPendingStatusId(null);
        },
        onError: (err: Error) => {
          message.error(err?.message ?? 'Failed to update status');
        },
      },
    );
  };

  const disabled = ticket?.closed === true || !canUpdateTicket;
  const loading = updateTicket.isPending;

  return (
    <div className="relative" ref={containerRef}>
      <div
        role="combobox"
        aria-expanded={isOpen}
        aria-haspopup="listbox"
        aria-label="Ticket status"
        aria-busy={loading}
        className={`
          inline-flex min-w-[88px] max-w-[100px] items-center overflow-hidden rounded-lg border
          bg-card transition-colors
          ${disabled ? 'border-border bg-muted/60 cursor-not-allowed opacity-70' : loading ? 'border-border cursor-wait opacity-70' : 'border-border hover:border-primary/30 hover:bg-muted/50 cursor-pointer'}
        `}
        onClick={() => !disabled && !loading && setIsOpen((o) => !o)}
      >
        <span className="text-foreground flex items-center gap-1.5 py-1.5 pl-2.5">
          {loading ? (
            <LoadingOutlined
              style={{ fontSize: 12 }}
              className="text-muted-foreground"
            />
          ) : (
            <span
