            return (
              <div
                className="w-full space-y-2"
                key={teamIndex}
                data-cy={`team-section-${team.teamName?.toLowerCase().replace(/\s+/g, '-')}`}
              >
                <div
                  className="font-semibold text-text"
                  data-cy={`team-name-${team.teamName?.toLowerCase().replace(/\s+/g, '-')}`}
                >
                  Team : {team.teamName}
