                <div>
                  {team.tickets.map((ticket) => {
                    const currentIndex = ticketIndex++;
                    return (
                      <TicketCard
                        key={ticket.id}
                        ticket={ticket}
                        active={activeTicketIndex === currentIndex}
                        onClick={() => onTicketClick(currentIndex)}
                        letter="A"
                        allGroups={allGroups}
                        allAgents={allAgents}
                        allStatus={allStatus}
                        allPriority={allPriority}
                        onPrioritySelectValue={onPrioritySelectValue}
                      />
                    );
                  })}
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

'use client';

import React from 'react';
import {
  TeamOutlined,
  UserOutlined,
  DownOutlined,
  FlagOutlined,
} from '@ant-design/icons';
import { PrioritySelector } from './PrioritySelector';
import { AssignDropdown } from './AssignDropdown';
import {
  usePrioritiesQuery,
  useUpdatePriorityMutation,
} from '../_hooks/useTicketsQueries';
import { checkUserPermission, PERMISSIONS } from '@/utils/permissions';
import { resolveTicketAssigneeRows } from '@/utils/ticketAssignees';

type TicketAssignmentBarProps = {
  ticket: any;
};

export function TicketAssignmentBar({ ticket }: TicketAssignmentBarProps) {
  const userType =
    typeof window !== 'undefined' ? localStorage.getItem('user_type') : null;
  const canUpdate =
    userType === 'employee' && checkUserPermission([PERMISSIONS.ticketUpdate]);

  const { data: priorities = [] } = usePrioritiesQuery();
  const updatePriority = useUpdatePriorityMutation();

  const teamList = ticket?.ticket_teams ?? ticket?.teams ?? [];
  const teamLabels = teamList.map(
    (t: any) => t?.team?.name ?? t?.type ?? String(t),
  );
  const agentList = resolveTicketAssigneeRows(ticket);
  const agentLabels = agentList.map((a: any) => {
    if (typeof a === 'string') return a;
    return (
      [a?.first_name, a?.last_name].filter(Boolean).join(' ') || a?.email || '—'
    );
  });
  const priorityType =
    ticket?.ticket_priority?.type ?? ticket?.ticket_priority ?? '';

  const priorityMenu = priorities.map((p: any) => ({
    name: p?.type ?? String(p),
    value: p?.id ?? p,
  }));

  const handlePriorityChange = (value: string | number) => {
    if (!ticket?.id || String(value) === '__none__') return;
    updatePriority.mutate({
      priorityId: value as string | number,
      ticketId: ticket.id,
    });
  };

  if (
    !canUpdate &&
    teamLabels.length === 0 &&
    agentLabels.length === 0 &&
    !priorityType
  ) {
    return null;
  }

  return (
    <div className="border-border bg-muted/30 mt-6 rounded-md border p-4">
      <div className="flex flex-wrap items-center gap-x-6 gap-y-4">
        {/* Teams */}
        <div className="flex items-center gap-2">
          <TeamOutlined className="text-primary" style={{ fontSize: 14 }} />
          <span className="text-muted-foreground text-xs font-semibold uppercase tracking-wider">
            Teams ({teamLabels.length || 0})
          </span>
          {teamLabels.length > 0 ? (
            <div className="flex flex-wrap gap-1.5">
              {teamLabels.map((t: any) => (
                <span
                  key={t}
                  className="border-primary/20 bg-primary/10 text-primary inline-flex rounded-full border px-2.5 py-0.5 text-xs font-medium"
                >
                  {t}
                </span>
              ))}
            </div>
          ) : (
            <span className="text-muted-foreground/60 text-xs">None</span>
          )}
        </div>

        {/* Agents */}
        <div className="flex items-center gap-2">
          <UserOutlined className="text-emerald-500" style={{ fontSize: 14 }} />
          <span className="text-muted-foreground text-xs font-semibold uppercase tracking-wider">
            Agents ({agentLabels.length || 0})
          </span>
          {agentLabels.length > 0 ? (
            <div className="flex flex-wrap gap-1.5">
              {agentLabels.map((a: string) => (
                <span
                  key={a}
                  className="inline-flex rounded-full border border-emerald-100 bg-emerald-50 px-2.5 py-0.5 text-xs font-medium text-emerald-700"
                >
                  {a}
                </span>
              ))}
            </div>
          ) : (
            <span className="text-muted-foreground/60 text-xs">None</span>
          )}
        </div>

        {/* Assign */}
        {canUpdate && (
          <div className="flex items-center gap-2">
            <AssignDropdown
              ticket={ticket}
              placement="bottomLeft"
              trigger={
                <button
                  type="button"
                  className="border-border bg-card text-foreground hover:border-primary/25 hover:bg-primary/10 hover:text-primary inline-flex items-center gap-1.5 rounded-lg border px-3 py-1.5 text-xs font-medium shadow-sm transition-colors"
                >
                  <UserOutlined style={{ fontSize: 12 }} />
                  Assign
                  <DownOutlined style={{ fontSize: 10 }} />
                </button>
              }
            />
          </div>
        )}

        {/* Priority */}
        {canUpdate && priorityMenu.length > 0 && (
          <div className="flex items-center gap-2">
            <FlagOutlined className="text-amber-400" style={{ fontSize: 14 }} />
            <span className="text-muted-foreground text-xs font-semibold uppercase tracking-wider">
              Priority
            </span>
            <PrioritySelector
              menu={priorityMenu}
              text={priorityType}
              onPrioritySelect={handlePriorityChange}
              placeholder="Select priority"
            />
          </div>
        )}
        {!canUpdate && priorityType && (
          <div className="flex items-center gap-2">
            <FlagOutlined className="text-amber-400" style={{ fontSize: 14 }} />
            <span className="text-muted-foreground text-xs font-semibold uppercase tracking-wider">
              Priority
            </span>
            <span className="rounded-full border border-amber-100 bg-amber-50 px-2.5 py-0.5 text-xs font-medium text-amber-700">
              {priorityType}
            </span>
          </div>
        )}
      </div>
    </div>
  );
}

