const AVATAR_COLORS = [
  '#7c3aed',
  '#2563eb',
  '#0891b2',
  '#059669',
  '#d97706',
  '#dc2626',
  '#64748b',
  '#6d28d9',
];

function formatDistanceToNow(date: Date): string {
  const now = new Date();
  const diffMs = now.getTime() - date.getTime();
  const diffSeconds = Math.floor(Math.abs(diffMs) / 1000);
  const diffMinutes = Math.floor(diffSeconds / 60);
  const diffHours = Math.floor(diffMinutes / 60);
  const diffDays = Math.floor(diffHours / 24);

  if (diffDays > 0) return `${diffDays}d ago`;
  if (diffHours > 0) return `${diffHours}h ago`;
  if (diffMinutes > 0) return `${diffMinutes}m ago`;
  return 'Just now';
}

function formatDueRelative(dueDate: Date): { text: string; overdue: boolean } {
  const now = new Date();
  const diffMs = dueDate.getTime() - now.getTime();
  const diffMinutes = Math.floor(Math.abs(diffMs) / (1000 * 60));
  const diffHours = Math.floor(diffMinutes / 60);
  const diffDays = Math.floor(diffHours / 24);
  const overdue = diffMs < 0;

  if (overdue) {
    if (diffDays !== 0)
      return { text: `${Math.abs(diffDays)}d overdue`, overdue: true };
    if (diffHours !== 0)
      return { text: `${Math.abs(diffHours)}h overdue`, overdue: true };
    return { text: `${Math.abs(diffMinutes)}m overdue`, overdue: true };
  }
  if (diffDays > 0) return { text: `Due in ${diffDays}d`, overdue: false };
  if (diffHours > 0) return { text: `Due in ${diffHours}h`, overdue: false };
  return { text: 'Due soon', overdue: false };
}

function DueDateBadge({
  dueDate,
  className = '',
}: {
  dueDate: Date;
  className?: string;
}) {
  const { text, overdue } = formatDueRelative(dueDate);
  return (
    <span
      className={`inline-flex items-center gap-1 rounded-full px-2.5 py-0.5 text-xs font-medium border ${className}`}
      style={{
        backgroundColor: overdue
          ? 'rgba(239, 68, 68, 0.08)'
          : 'rgba(34, 197, 94, 0.08)',
        color: overdue ? '#dc2626' : '#16a34a',
        borderColor: overdue
          ? 'rgba(239, 68, 68, 0.2)'
          : 'rgba(34, 197, 94, 0.2)',
      }}
    >
      <CalendarOutlined style={{ fontSize: 10 }} />
      {text}
    </span>
  );
}

type TicketCardProps = {
