  const displayStatusType = toDisplayStatusLabel(statusType);
  const statusColor =
    typeof ticket.ticket_status === 'object'
      ? ticket.ticket_status?.status_color
      : undefined;
  const priorityType = ticket.ticket_priority?.type || '';
  const createdAt = new Date(ticket.created_at);
  const dueDate = ticket.due_date ? new Date(ticket.due_date) : null;

  const dueDate = ticket.due_date ? new Date(ticket.due_date) : null;
  const avatarColor =
    AVATAR_COLORS[letter.charCodeAt(0) % AVATAR_COLORS.length];

  return (
    <div
      role="button"
      tabIndex={0}
      onClick={onClick}
      onKeyDown={(e) => (e.key === 'Enter' || e.key === ' ') && onClick?.()}
      className={`
        group bg-card mb-2.5 flex w-full items-center gap-4 rounded-md border px-5 py-4
        transition-all duration-200 ease-out
        hover:border-border hover:-translate-y-[1px] hover:shadow-md
        focus:outline-none focus-visible:ring-2 focus-visible:ring-primary focus-visible:ring-offset-2
        ${
          active
            ? 'border border-border border-l-4 border-l-primary bg-primary/10 shadow-sm'
            : 'border border-border'
        }
      `}
    >
      {/* Selection + avatar block */}
      <div className="flex shrink-0 items-center gap-3">
        <label
          className="border-border hover:border-primary/40 focus-within:ring-primary flex h-5 w-5 shrink-0 cursor-pointer items-center justify-center rounded-md border transition-colors focus-within:ring-2"
          onClick={(e) => e.stopPropagation()}
        >
          <input
            type="checkbox"
            className="border-border text-primary focus:ring-primary h-3.5 w-3.5 rounded"
            aria-label="Select ticket"
          />
        </label>
        <div
          className="hidden h-10 w-10 shrink-0 items-center justify-center rounded-xl text-sm font-semibold text-white xl:flex shadow-sm"
          style={{
            background: `linear-gradient(135deg, ${avatarColor}, ${avatarColor}dd)`,
          }}
          aria-hidden
        >
          {letter}
        </div>
