              />
              {dueDate && <DueDateBadge dueDate={dueDate} />}
              {ticket.issues && ticket.issues.length > 0 && (
                <span className="border-primary/20 bg-primary/10 text-primary inline-flex items-center gap-1 rounded-full border px-2.5 py-0.5 text-xs font-medium">
                  <MessageOutlined style={{ fontSize: 10 }} />
                  {ticket.issues.length} issue
                  {ticket.issues.length !== 1 ? 's' : ''}
                </span>
              )}
            </div>
            <Link
              href={`/tickets/${ticket.id}`}
              className="text-foreground hover:text-primary block font-semibold transition-colors"
              onClick={(e) => e.stopPropagation()}
            >
              <span className="line-clamp-2 break-words">{ticket.subject}</span>
            </Link>
          </div>
          {/* Employee actions */}
          {userType === 'employee' && (
            <div className="border-border flex shrink-0 flex-wrap items-center gap-2 border-t pt-3 sm:border-t-0 sm:pt-0">
              {checkUserPermission([PERMISSIONS.ticketPriorityUpdate]) &&
