                    bgColor="bg-card"
                    menu={allPriority.map((p) => ({
                      name: p.type,
                      value: p.id,
                    }))}
                    text={priorityType}
                    onPrioritySelect={(val) =>
                      onPrioritySelectValue?.(val, ticket.id)
                    }
                  />
                )}
              {(checkUserPermission([PERMISSIONS.ticketAssignUser]) ||
                checkUserPermission([PERMISSIONS.ticketAssignTeam])) && (
                <AssignSelector
                  ticket={ticket}
                  id={ticket.id}
                  bgColor="bg-card"
                  agents={allAgents}
                  groups={allGroups}
