  onStatusChange,
  departmentId,
  onDepartmentChange,
  supports = [],
  selectedSupportIds = [],
  onSupportChange,
  priorities = [],
  statuses = [],
  departments = [],
  createdFrom = '',
  onCreatedFromChange,
  createdTo = '',
  onCreatedToChange,
  onReset,
}: TicketFiltersProps) {
