function getIssueTeams(issue: any): { id: string | number; name: string }[] {
  const raw = issue?.issue_teams ?? issue?.teams ?? [];
  return raw
    .map((t: any) => {
      const team = t?.team ?? t?.linked_team ?? t;
      return {
        id: team?.id ?? t,
        name: team?.name ?? team?.type ?? String(team?.id ?? t),
      };
    })
    .filter((x: { id: any }) => x.id != null);
}

function getIssueAgents(issue: any): { id: string | number; label: string }[] {
  const raw = issue?.issue_agents ?? issue?.agents ?? [];
  return raw
    .map((a: any) => {
      const agent = a?.agent ?? a;
      if (typeof agent === 'string') return { id: agent, label: agent };
      const label =
        [agent?.first_name, agent?.last_name].filter(Boolean).join(' ') ||
        agent?.email ||
        String(agent?.id ?? '');
      return { id: agent?.id ?? agent, label };
    })
    .filter((x: { id: any }) => x.id != null);
}

