type IssueNameEditProps = {
  value: string;
  issueId: string | number;
  ticketId?: string | number;
  updateMutation: ReturnType<typeof useUpdateIssueMutation>;
  isSaving?: boolean;
};

function IssueNameEdit({
  value,
  issueId,
  ticketId,
  updateMutation,
  isSaving = false,
}: IssueNameEditProps) {
  const [editing, setEditing] = useState(false);
  const [localValue, setLocalValue] = useState(value);
  React.useEffect(() => {
    setLocalValue(value);
  }, [value]);

  const handleSave = () => {
    const trimmed = localValue.trim();
    if (trimmed && trimmed !== value) {
      updateMutation.mutate(
        { issueId, ticketId, name: trimmed },
        { onSettled: () => setEditing(false) },
      );
    } else {
      setLocalValue(value);
      setEditing(false);
    }
  };

  if (editing) {
    return (
      <div className="mt-0.5 flex items-center gap-2">
        <Input
          value={localValue}
          onChange={(e) => setLocalValue(e.target.value)}
          onPressEnter={handleSave}
          size="small"
          className="flex-1 rounded-lg"
          autoFocus
          disabled={isSaving}
        />
        <Button
          type="primary"
          size="small"
          icon={<CheckOutlined />}
          onClick={handleSave}
          loading={isSaving}
        />
        <Button
          size="small"
          onClick={() => {
            setEditing(false);
            setLocalValue(value);
          }}
          disabled={isSaving}
        >
          Cancel
        </Button>
      </div>
    );
  }

  return (
    <div className="mt-0.5 flex items-center gap-2">
      {isSaving ? (
        <Skeleton.Input active size="small" className="!min-w-[120px] !w-32" />
      ) : (
        <p className="text-foreground font-medium">{value}</p>
      )}
      {isSaving ? null : (
        <button
          type="button"
          onClick={() => setEditing(true)}
          disabled={isSaving}
          className="p-0.5 text-[#4a90d9] hover:text-[#2563eb] rounded disabled:opacity-50"
          aria-label="Edit issue name"
        >
          <EditOutlined className="text-sm" />
        </button>
      )}
    </div>
  );
}

