import React, { useMemo } from 'react';
import { Empty, Spin, Pagination } from 'antd';
import { Ticket } from '../_hooks/useTicketsQueries';
import { TicketCard } from './TicketCard';

type TicketListProps = {
  tickets: Ticket[];
  loading?: boolean;
  activeTicketIndex: number | null;
  onTicketClick: (index: number) => void;
  allGroups?: Array<{ id: string | number; type: string }>;
  allAgents?: Array<{ id: string | number; name?: string; email?: string }>;
  allStatus?: Array<{
    id: string | number;
    type: string;
    status_color?: string;
  }>;
  allPriority?: Array<{ id: string | number; type: string }>;
  onPrioritySelectValue?: (
    priorityId: string | number,
    ticketId: string | number,
  ) => void;
  ticketAssignedToMe?: boolean;
  perPage?: number;
  'data-cy'?: string;
};

function usePagination<T>(data: T[], perPage: number) {
  const [currentPage, setCurrentPage] = React.useState(1);

  const totalPages = Math.ceil(data.length / perPage);
  const startIndex = (currentPage - 1) * perPage;
  const endIndex = startIndex + perPage;
  const currentData = data.slice(startIndex, endIndex);

  const jump = (page: number) => {
    setCurrentPage(page);
  };

  React.useEffect(() => {
    setCurrentPage(1);
  }, [data.length]);

  return {
    currentData: () => currentData,
    currentPage,
    maxPage: totalPages,
    jump,
  };
}

export function TicketList({
  tickets,
  loading = false,
  activeTicketIndex,
  onTicketClick,
  allGroups = [],
  allAgents = [],
  allStatus = [],
  allPriority = [],
  onPrioritySelectValue,
  ticketAssignedToMe = false,
  perPage = 10,
  'data-cy': dataCy,
}: TicketListProps) {
  const pagination = usePagination(tickets, perPage);

  if (loading) {
    return <Spin size="large" data-cy={`${dataCy}-loading-spinner`} />;
  }

  if (tickets.length < 1) {
    return <Empty data-cy={`${dataCy}-empty`} />;
  }

  return (
    <div className="col-span-12" data-cy={dataCy}>
      <div className="grid gap-2">
        <div className="flex flex-col justify-start items-start w-full mx-auto py-2 overflow-y-auto max-h-full p-5">
          {pagination.currentData().map((ticket, index) => {
            const globalIndex = (pagination.currentPage - 1) * perPage + index;
            return (
              <TicketCard
                key={ticket.id}
                ticket={ticket}
                active={activeTicketIndex === globalIndex}
                onClick={() => onTicketClick(globalIndex)}
                letter={ticket.subject?.[0] || 'A'}
                allGroups={allGroups}
                allAgents={allAgents}
                allStatus={allStatus}
                allPriority={allPriority}
                onPrioritySelectValue={onPrioritySelectValue}
                ticketAssignedToMe={ticketAssignedToMe}
              />
            );
          })}
        </div>
      </div>
      {pagination.maxPage > 1 && (
        <div className="mt-3 px-0">
          <Pagination
            total={tickets.length}
            pageSize={perPage}
            current={pagination.currentPage}
            onChange={(page) => pagination.jump(page)}
            showSizeChanger={false}
            showQuickJumper={false}
            className="flex justify-start"
          />
        </div>
      )}
    </div>
  );
}

