  const normalizedStatusId = useMemo(() => {
    if (!statusIdFilter) return undefined;
    const match = statuses.find(
      (status: { id: string | number; type?: string }) =>
        (status?.type || '').toLowerCase() === statusIdFilter.toLowerCase(),
    );
    return match ? String(match.id) : statusIdFilter;
  }, [statusIdFilter, statuses]);

  const ticketsFilterQuery = useTicketsFilterQuery({
    ticket_name: search || undefined,
    priority: priorityFilter ?? undefined,
    status: normalizedStatusId,
    status_id: normalizedStatusId,
    type: typeFilter ?? undefined,
    department: departmentFilter ?? undefined,
    support_id: supportIdParam,
    view_type: viewTypeParam,
    page: String(page),
    limit: String(limit),
  });

  const loading = ticketsFilterQuery.isLoading;
  const apiResponse = ticketsFilterQuery.data as any;
  const apiTickets = (apiResponse?.data ?? []) as Ticket[];
  const totalItems =
    typeof apiResponse?.total === 'number'
      ? apiResponse.total
      : typeof apiResponse?.meta?.total === 'number'
        ? apiResponse.meta.total
        : apiTickets.length;

  const tickets = useMemo(() => {
    return apiTickets.filter((ticket) => {
      const created = String(ticket.created_at ?? '').slice(0, 10);
      if (createdFrom && created < createdFrom) return false;
      if (createdTo && created > createdTo) return false;
      return true;
    });
  }, [apiTickets, createdFrom, createdTo]);

  const handlePageChange = (nextPage: number, nextPageSize: number) => {
    setPage(nextPage);
    setLimit(nextPageSize);
  };

  const tableProps = {
    loading,
    activeTicketIndex: selectedTicketIndex,
    onTicketClick: setSelectedTicketIndex,
    allGroups: departments,
    allAgents: users,
    allStatus: statuses,
    allPriority: priorities,
    onPrioritySelectValue: updatePriority,
    updatingPriority,
    currentPage: page,
    pageSize: limit,
    onPageChange: handlePageChange,
    totalItems,
  };

  if (ticketTypeFilter === 'assigned' && role !== 'Admin') {
    return (
      <Alert
        type="warning"
        showIcon
        message="You do not have access to this page."
      />
    );
  }
  if (ticketTypeFilter === 'unassigned' && role !== 'Admin') {
    return (
      <Alert
        type="warning"
        showIcon
        message="You do not have access to this page."
      />
    );
  }
  if (ticketTypeFilter === 'unassigned-agent' && role !== 'team-lead') {
    return (
      <Alert
        type="warning"
        showIcon
        message="You do not have access to this page."
      />
    );
  }

  return (
    <div className="h-full min-h-0">
      <TicketTable
        tickets={tickets}
        data-cy="tickets-all-list"
        {...tableProps}
      />
    </div>
  );
}

