};

const TicketsDataContext = createContext<TicketsData | null>(null);

function filterTickets(
  tickets: Ticket[] | undefined,
  searchTerm: string,
): Ticket[] {
  if (!tickets) return [];
  if (!searchTerm || searchTerm.trim() === '') return tickets;
  const searchLower = searchTerm.toLowerCase();
  return tickets.filter((ticket) => {
    const subject = ticket?.subject?.toLowerCase() || '';
    const description = ticket?.description?.toLowerCase() || '';
    const status =
      typeof ticket?.ticket_status === 'string'
        ? ticket?.ticket_status
        : ticket?.ticket_status?.type || '';
    const priority = ticket?.ticket_priority?.type?.toLowerCase() || '';
    const department = ticket?.department?.type?.toLowerCase() || '';
    return (
      subject.includes(searchLower) ||
      description.includes(searchLower) ||
      status.toLowerCase().includes(searchLower) ||
      priority.includes(searchLower) ||
      department.includes(searchLower)
    );
  });
}

function filterGroupedTeamTickets(
  groupedTickets: Array<{ teamName: string; tickets: Ticket[] }> | undefined,
  searchTerm: string,
): Array<{ teamName: string; tickets: Ticket[] }> {
  if (!groupedTickets) return [];
  if (!searchTerm || searchTerm.trim() === '') return groupedTickets;
  return groupedTickets
    .map((team) => ({
      ...team,
      tickets: filterTickets(team.tickets, searchTerm),
    }))
    .filter((team) => team.tickets.length > 0);
}

const CLOSED_STATUS_VALUES = [
  'closed',
  'resolved',
  'done',
  'completed',
  'cancelled',
];

function filterTicketsByStatus(
  tickets: Ticket[],
  statusFilter: 'all' | 'open' | 'closed',
): Ticket[] {
  if (statusFilter === 'all') return tickets;
  if (!tickets?.length) return tickets;
  return tickets.filter((ticket) => {
    const statusType =
      typeof ticket?.ticket_status === 'string'
        ? ticket.ticket_status
        : (ticket?.ticket_status?.type ?? '');
    const statusLower = (statusType && String(statusType).toLowerCase()) || '';
    const isClosed =
      ticket?.closed === true ||
      CLOSED_STATUS_VALUES.some((v) => statusLower === v);
    if (statusFilter === 'closed') return isClosed;
    if (statusFilter === 'open') return !isClosed;
    return true;
  });
}

// Support PascalCase, snake_case, and wrapped { data } API response
function getAssignedTickets(ticketData: any): Ticket[] | undefined {
  const list =
    ticketData?.AssignedTickets ??
    ticketData?.assigned_tickets ??
    ticketData?.data?.AssignedTickets ??
    ticketData?.data?.assigned_tickets;
  return Array.isArray(list) ? list : undefined;
}
function getUnassignedTickets(
  ticketData: any,
): { teamAssigned?: Ticket[]; unAssigned?: Ticket[] } | undefined {
  const u =
    ticketData?.unAssignedTickets ??
    ticketData?.unassigned_tickets ??
    ticketData?.data?.unAssignedTickets ??
    ticketData?.data?.unassigned_tickets;
  if (!u) return undefined;
  const teamAssigned = u.teamAssigned ?? u.team_assigned;
  const unAssigned = u.unAssigned ?? u.unassigned;
  if (!Array.isArray(teamAssigned) && !Array.isArray(unAssigned))
    return undefined;
  return {
    teamAssigned: Array.isArray(teamAssigned) ? teamAssigned : undefined,
    unAssigned: Array.isArray(unAssigned) ? unAssigned : undefined,
  };
}

function getAllTickets(ticketData: any): Ticket[] {
  const allTickets: Ticket[] = [];

  // Handle direct data array response (e.g., { data: [...] })
  if (ticketData?.data && Array.isArray(ticketData.data)) {
    allTickets.push(...ticketData.data);
  }

  // Handle nested structure responses
  if (ticketData?.listOfTicketsByAgent)
    allTickets.push(...ticketData.listOfTicketsByAgent);
  const assigned = getAssignedTickets(ticketData);
  if (assigned?.length) allTickets.push(...assigned);

  if (assigned?.length) allTickets.push(...assigned);
  const unassigned = getUnassignedTickets(ticketData);
  if (unassigned?.teamAssigned?.length)
    allTickets.push(...unassigned.teamAssigned);
  if (unassigned?.unAssigned?.length) allTickets.push(...unassigned.unAssigned);
  if (ticketData?.groupedTeam) {
    ticketData.groupedTeam.forEach((team: { tickets: Ticket[] }) => {
      if (team?.tickets) allTickets.push(...team.tickets);
    });
  }

  // Remove duplicates based on ticket ID
  return allTickets.filter(
    (ticket, index, self) =>
      index === self.findIndex((t) => t?.id === ticket?.id),
  );
}

export function TicketsDataProvider({
  children,
}: {
  children: React.ReactNode;
}) {
  const { search, selectedProjectIds, selectedSupportIds, allTicketsSubTab } =
    useTicketsUiStore();
  const debouncedSearch = useDeferredValue(search);

  const role =
    typeof window !== 'undefined' ? localStorage.getItem('role') : null;

  const projectIdForQuery = selectedProjectIds[0] ?? null;
  const supportIdForQuery = selectedSupportIds[0] ?? null;

  const ticketsQ = useTicketsQuery(projectIdForQuery, supportIdForQuery);
  const departmentsQ = useDepartmentsQuery();
  const prioritiesQ = usePrioritiesQuery();
  const statusesQ = useStatusesQuery();
  const usersQ = useUsersQuery();
  const projectsQ = useProjectsQuery();
  const supportsQ = useSupportsQuery();
  const ticketTypesQ = useTicketTypesQuery();

  const updatePriorityM = useUpdatePriorityMutation();
  const canUpdateTicket = checkUserPermission([PERMISSIONS.ticketUpdate]);

  const ticketData = ticketsQ.data;
  const rawTicketData = ticketData?.data != null ? ticketData.data : ticketData;

  const getListOfTicketsByAgent = (data: any) => {
    if (!data || Array.isArray(data)) return undefined;
    return (
      data.listOfTicketsByAgent ??
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      (data as any).list_of_tickets_by_agent
    );
  };

  const getGroupedTeam = (data: any) => {
    if (!data || Array.isArray(data)) return undefined;
    return data.groupedTeam;
  };

  const statusFilter = allTicketsSubTab;

  const teamTicketsDataRaw = useMemo(
    () => filterGroupedTeamTickets(ticketData?.groupedTeam, debouncedSearch),
    [ticketData?.groupedTeam, debouncedSearch],
  );
  const teamTicketsData = useMemo(
    () =>
      teamTicketsDataRaw.map((team) => ({
        teamName: team.teamName,
        tickets: filterTicketsByStatus(team.tickets, statusFilter),
      })),
    [teamTicketsDataRaw, statusFilter],
  );

  const listOfTicketsByAgentFromApi =
    getListOfTicketsByAgent(rawTicketData) ??
    getListOfTicketsByAgent(ticketData);

  const listOfTicketsByAgent = useMemo(() => {
    if (
      listOfTicketsByAgentFromApi &&
      Array.isArray(listOfTicketsByAgentFromApi) &&
      listOfTicketsByAgentFromApi.length > 0
    ) {
      return listOfTicketsByAgentFromApi;
    }
    const groupedTeam =
      getGroupedTeam(rawTicketData) ?? getGroupedTeam(ticketData);
    if (!groupedTeam || !Array.isArray(groupedTeam)) return [];
    const directlyAssigned = groupedTeam.find(
      (g: any) =>
        g?.teamName === 'Directly Assigned' && Array.isArray(g?.tickets),
    );
    if (!directlyAssigned?.tickets?.length) return [];
    const byId = new Map<string | number, any>();
    for (const item of directlyAssigned.tickets) {
      const tid = item?.id;
      if (tid == null || byId.has(tid)) continue;
      const issue = item?.issue ?? item?.issues?.[0];
      const ticketCopy = { ...item };
      delete ticketCopy.issue;
      byId.set(tid, { ...ticketCopy, issues: issue ? [issue] : [] });
    }
    return Array.from(byId.values());
  }, [listOfTicketsByAgentFromApi, rawTicketData, ticketData]);

  const filteredAssignedToMeRaw = useMemo(
    () => filterTickets(listOfTicketsByAgent, debouncedSearch),
    [listOfTicketsByAgent, debouncedSearch],
  );
  const filteredAssignedToMe = useMemo(
    () => filterTicketsByStatus(filteredAssignedToMeRaw, statusFilter),
    [filteredAssignedToMeRaw, statusFilter],
  );

  const assignedTickets = useMemo(
    () => getAssignedTickets(ticketData),
    [ticketData],
  );
  const unassignedTickets = useMemo(
    () => getUnassignedTickets(ticketData),
    [ticketData],
  );

  const filteredUserTicketsRaw = useMemo(
    () => filterTickets(assignedTickets, debouncedSearch),
    [assignedTickets, debouncedSearch],
  );
  const filteredUserTickets = useMemo(
    () => filterTicketsByStatus(filteredUserTicketsRaw, statusFilter),
    [filteredUserTicketsRaw, statusFilter],
  );

  const filteredUnAssignedAgentRaw = useMemo(
    () => filterTickets(unassignedTickets?.teamAssigned, debouncedSearch),
    [unassignedTickets?.teamAssigned, debouncedSearch],
  );
  const filteredUnAssignedAgent = useMemo(
    () => filterTicketsByStatus(filteredUnAssignedAgentRaw, statusFilter),
    [filteredUnAssignedAgentRaw, statusFilter],
  );

  const filteredFullyUnassignedTicketsRaw = useMemo(
    () => filterTickets(unassignedTickets?.unAssigned, debouncedSearch),
    [unassignedTickets?.unAssigned, debouncedSearch],
  );
  const filteredFullyUnassignedTickets = useMemo(
    () =>
      filterTicketsByStatus(filteredFullyUnassignedTicketsRaw, statusFilter),
    [filteredFullyUnassignedTicketsRaw, statusFilter],
  );

  const filteredTeamAssignedOnlyTicketsRaw = useMemo(
    () => filterTickets(unassignedTickets?.teamAssigned, debouncedSearch),
    [unassignedTickets?.teamAssigned, debouncedSearch],
  );
  const filteredTeamAssignedOnlyTickets = useMemo(
    () =>
      filterTicketsByStatus(filteredTeamAssignedOnlyTicketsRaw, statusFilter),
    [filteredTeamAssignedOnlyTicketsRaw, statusFilter],
  );

  const allTickets = useMemo(() => getAllTickets(ticketData), [ticketData]);
  const filteredAllTickets = useMemo(
    () => filterTickets(allTickets, debouncedSearch),
    [allTickets, debouncedSearch],
  );
  const filteredAllTicketsByStatus = useMemo(
    () => filterTicketsByStatus(filteredAllTickets, statusFilter),
    [filteredAllTickets, statusFilter],
  );

  const reducedSupports = useMemo(() => {
    const supports = supportsQ.data || [];
    return supports.flatMap((client: any) => client?.client?.supports || []);
  }, [supportsQ.data]);

  const value: TicketsData = {
    role,
    loading: ticketsQ.isLoading,
    error: (ticketsQ.error as Error) ?? null,
    refetch: () => ticketsQ.refetch(),

    departments: departmentsQ.data ?? [],
    priorities: prioritiesQ.data ?? [],
    statuses: statusesQ.data ?? [],
    users: usersQ.data ?? [],
    projects: projectsQ.data ?? [],
    supports: supportsQ.data ?? [],
    reducedSupports,
    ticketTypes: ticketTypesQ.data ?? [],

    teamTicketsData,
    filteredAssignedToMe,
    filteredUserTickets,
    filteredUnAssignedAgent,
    filteredFullyUnassignedTickets,
    filteredTeamAssignedOnlyTickets,
    filteredAllTicketsByStatus,

    updatePriority: (priorityId, ticketId) => {
      if (!canUpdateTicket) return;
      if (priorityId === '__none__') return;
      updatePriorityM.mutate({ priorityId, ticketId });
    },
    updatingPriority: updatePriorityM.isPending,
  };

  return (
    <TicketsDataContext.Provider value={value}>
      {children}
    </TicketsDataContext.Provider>
  );
}

export function useTicketsData() {
  const ctx = useContext(TicketsDataContext);
  if (!ctx)
    throw new Error('useTicketsData must be used within TicketsDataProvider');
  return ctx;
}

