type TabProps = {
  label: string;
  children: ReactNode;
  'data-cy'?: string;
};

type TicketTabsProps = {
  children: React.ReactElement<TabProps>[];
  activeTab: string;
  onTabChange: (tab: string) => void;
  initialTab?: string;
};

export function Tab({ children }: TabProps) {
  return <>{children}</>;
}

export function TicketTabs({
  children,
  activeTab,
  onTabChange,
  initialTab,
}: TicketTabsProps) {
  const tabs = React.Children.toArray(
    children,
  ) as React.ReactElement<TabProps>[];

  return (
    <div className="w-full">
      <div className="flex border-b border-gray-300 w-full">
        {tabs.map((tab) => {
          const label = tab.props.label;
          const isActive = activeTab === label;
          return (
            <button
              key={label}
              className={`${
                isActive ? 'border-b-2 border-black' : ''
              } flex justify-start items-center text-gray-700 font-medium py-2 px-2`}
              onClick={() => onTabChange(label)}
              data-cy={tab.props['data-cy']}
            >
              {label}
            </button>
          );
        })}
      </div>
      <div className="py-4">
        {tabs.map((tab) => {
          if (tab.props.label === activeTab) {
            return (
              <div
                key={tab.props.label}
                className="grid grid-cols-12 gap-5 mt-[35px] w-full"
              >
                {tab.props.children}
              </div>
            );
          }
          return null;
        })}
      </div>
    </div>
  );
}

