const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const isValidEmail = (email: string) => emailRegex.test(email);

type UserLike = {
  id?: string | number;
  email?: string;
  first_name?: string;
  last_name?: string;
  isCustom?: boolean;
};

type UserEmailSelectProps = {
  users?: UserLike[];
  value?: string[];
  onChange: (emails: string[]) => void;
  placeholder?: string;
  ticket?: { client?: { email?: string } } | null;
  defaultEmails?: string[];
  disabled?: boolean;
  'data-testid'?: string;
};

export function UserEmailSelect({
  users = [],
  value = [],
  onChange,
  placeholder = 'Search users or type email',
  ticket,
  defaultEmails,
  disabled,
}: UserEmailSelectProps) {
  const [selectedEmails, setSelectedEmails] = useState<string[]>(
    value.length > 0 ? value : (defaultEmails ?? []),
  );
  const [searchQuery, setSearchQuery] = useState('');
  const [results, setResults] = useState<UserLike[]>([]);
  const [focused, setFocused] = useState(false);
  const [emailError, setEmailError] = useState('');

  const syncFromValue = useCallback(() => {
    if (value.length > 0) setSelectedEmails(value);
  }, [value]);

  useEffect(() => {
    syncFromValue();
  }, [syncFromValue]);

  useEffect(() => {
    if (
      ticket?.client?.email &&
      selectedEmails.length === 0 &&
      !defaultEmails?.length &&
      value.length === 0
    ) {
      setSelectedEmails([ticket.client.email]);
      onChange([ticket.client.email]);
    }
  }, [
    ticket?.client?.email,
    defaultEmails,
    value.length,
    selectedEmails.length,
    onChange,
  ]);

  useEffect(() => {
    if (!searchQuery.trim()) {
      setResults([]);
      return;
    }
    const q = searchQuery.toLowerCase().trim();
    const filtered =
      users.filter(
        (u) =>
          u.email?.toLowerCase().includes(q) ||
          u.first_name?.toLowerCase().includes(q) ||
          u.last_name?.toLowerCase().includes(q),
      ) ?? [];
    if (isValidEmail(searchQuery.trim())) {
      const email = searchQuery.trim().toLowerCase();
      const exists =
        filtered.some((x) => x.email?.toLowerCase() === email) ||
        selectedEmails.some((e) => e.toLowerCase() === email);
      if (!exists) {
        setResults([
          {
            id: `custom-${email}`,
            email,
            first_name: email.split('@')[0],
            isCustom: true,
          },
          ...filtered,
        ]);
        return;
      }
    }
    setResults(filtered);
  }, [searchQuery, users, selectedEmails]);

  const add = (email: string) => {
    const e = email?.trim?.() ?? '';
    if (!e) return;
    const normalized = e.toLowerCase();
    if (selectedEmails.map((x) => x.toLowerCase()).includes(normalized)) return;
    const next = [...selectedEmails, normalized];
    setSelectedEmails(next);
    onChange(next);
    setSearchQuery('');
    setResults([]);
    setEmailError('');
  };

  const remove = (email: string) => {
    const next = selectedEmails.filter(
      (x) => x.toLowerCase() !== email.toLowerCase(),
    );
    setSelectedEmails(next);
    onChange(next);
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter' && searchQuery.trim()) {
      e.preventDefault();

      e.preventDefault();
      const s = searchQuery.trim();
      if (isValidEmail(s)) {
        if (selectedEmails.some((x) => x.toLowerCase() === s.toLowerCase())) {
          setEmailError('This email is already added');
        } else {
          add(s);
        }
      } else {
        setEmailError('Please enter a valid email address');
      }
    }
  };

  return (
    <div className="relative w-full">
      <div className="border-border bg-card focus-within:border-primary flex min-h-[40px] w-full flex-wrap gap-2 rounded-lg border px-3 py-2 focus-within:ring-2 focus-within:ring-primary/30">
        {selectedEmails.map((email) => (
          <span
            key={email}
            className="inline-flex items-center gap-1 rounded-md bg-primary/10 px-2 py-0.5 text-xs font-medium text-primary"
          >
            <span className="truncate max-w-[180px]">{email}</span>
            {!disabled && (
              <button
                type="button"
                onClick={() => remove(email)}
                className="hover:bg-primary/20 rounded-full p-0.5"
                aria-label={`Remove ${email}`}
              >
                ×
              </button>
            )}
          </span>
        ))}
        {!disabled && (
          <input
            type="text"
            autoComplete="off"
            value={searchQuery}
            onChange={(e) => {
              setSearchQuery(e.target.value);
              setEmailError('');
            }}
            onKeyDown={handleKeyDown}
            onFocus={() => setFocused(true)}
            onBlur={() => setTimeout(() => setFocused(false), 180)}
            placeholder={selectedEmails.length ? 'Add more…' : placeholder}
            className={`min-w-[120px] flex-1 border-0 bg-transparent px-1 py-0.5 text-sm outline-none placeholder:text-muted-foreground ${emailError ? 'text-red-500' : ''}`}
          />
        )}
      </div>
      {emailError && <p className="mt-1 text-xs text-red-500">{emailError}</p>}
      {focused && (searchQuery.trim() || results.length > 0) && (
        <ul className="border-border bg-card absolute z-50 mt-1 max-h-56 w-full overflow-auto rounded-lg border shadow-lg">
          {results.length > 0
            ? results.map((opt) => {
                const em = opt.email ?? '';
                const sel = selectedEmails.some(
                  (x) => x.toLowerCase() === em.toLowerCase(),
                );
                return (
                  <li
                    key={opt.id ?? em}
                    onMouseDown={(ev) => {
                      ev.preventDefault();
                      add(em);
                    }}
                    className={`cursor-pointer px-3 py-2 text-sm ${sel ? 'bg-primary/10 text-primary' : 'text-foreground hover:bg-muted/50'}`}
                  >
                    <div>
                      <span className="font-medium">{em}</span>
                      {!opt.isCustom && (opt.first_name || opt.last_name) && (
                        <span className="text-muted-foreground ml-2 text-xs">
                          {[opt.first_name, opt.last_name]
                            .filter(Boolean)
                            .join(' ')}
                        </span>
                      )}
                    </div>
                  </li>
                );
              })
            : searchQuery.trim() &&
              !isValidEmail(searchQuery.trim()) && (
                <li className="text-muted-foreground px-3 py-2 text-sm">
                  {searchQuery.trim().length < 3
                    ? 'Type at least 3 characters to search'
                    : 'No results. Type a valid email to add it.'}
                </li>
              )}
        </ul>
      )}
    </div>
  );
}

