// Tickets Filter Query - new API: GET /api/v1/tickets/filter
export function useTicketsFilterQuery(
  filters: TicketsFilterQuery,
  options?: { enabled?: boolean },
) {
  const token = useToken();

  return useQuery({
    queryKey: ['tickets-filter', filters],
    queryFn: async () => {
      const params = new URLSearchParams();
      (
        Object.entries(filters) as [
          keyof TicketsFilterQuery,
          string | undefined,
        ][]
      ).forEach(([key, value]) => {
        if (value != null && value !== '') {
          params.append(key, value);
        }
      });

      const queryString = params.toString();
      const path = queryString
        ? `/tickets/filter?${queryString}`
        : '/tickets/filter';

      const res = await fetchJson<{ data?: Ticket[]; [k: string]: any }>(path, {
        token,
      });
      return res;
    },
    enabled: !!token && (options?.enabled ?? true),
    staleTime: 30 * 1000,
  });
}

