'use client';

import React, { useMemo } from 'react';
import { useRouter } from 'next/navigation';
import { Plus, RefreshCw } from 'lucide-react';
import { useTicketsUiStore } from '../store/ticketsUi';
import { TicketFilters } from '../_components/TicketFilters';
import {
  TicketsDataProvider,
  useTicketsData,
} from '../_components/TicketsDataProvider';
import { useTicketsFilterQuery } from '../_hooks/useTicketsQueries';
import { Button } from '@/components/ui/button';
import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';
import { checkUserPermission, PERMISSIONS } from '@/utils/permissions';

function TicketsChrome({ children }: { children: React.ReactNode }) {
  const router = useRouter();
  const {
    search,
    ticketTypeFilter,
    setSearch,
    priorityFilter,
    setPriorityFilter,
    statusIdFilter,
    setStatusIdFilter,
    typeFilter,
    setTypeFilter,
    departmentFilter,
    setDepartmentFilter,
    createdFrom,
    setCreatedFrom,
    createdTo,
    setCreatedTo,
    selectedSupportIds,
    setSelectedSupportIds,
    resetFilters,
  } = useTicketsUiStore();

  const {
    role,
    error,
    refetch,
    reducedSupports,
    priorities,
    statuses,
    departments,
  } = useTicketsData();

  const canCreateTicket = checkUserPermission([PERMISSIONS.ticketCreate]);

  const viewTypeParam = useMemo(() => {
    switch (ticketTypeFilter) {
      case 'team':
        return '1';
      case 'assigned-to-me':
        return '2';
      case 'assigned':
        return '3';
      case 'unassigned':
      case 'unassigned-agent':
        return '4';
      case 'all':
      default:
        return '0';
    }
  }, [ticketTypeFilter]);

  const supportIdParam =
    selectedSupportIds && selectedSupportIds.length > 0
      ? String(selectedSupportIds[0])
      : undefined;

  const countBaseFilters = useMemo(
    () => ({
      ticket_name: search || undefined,
      priority: priorityFilter ?? undefined,
      type: typeFilter ?? undefined,
      department: departmentFilter ?? undefined,
      support_id: supportIdParam,
      view_type: viewTypeParam,
      page: '1',
      limit: '1',
    }),
    [
      search,
      priorityFilter,
      typeFilter,
      departmentFilter,
      supportIdParam,
      viewTypeParam,
    ],
  );

  const normalizedStatusIds = useMemo(() => {
    const byKey: Record<string, string> = {};
    for (const s of statuses ?? []) {
      const id = s?.id != null ? String(s.id) : '';
      const raw = String(s?.type ?? s?.name ?? '')
        .trim()
        .toLowerCase();
      if (!id || !raw) continue;
      byKey[raw] = id;
    }
    return {
      open: byKey['open'] ?? null,
      escalated:
        byKey['escalated'] ?? byKey['escalate'] ?? byKey['escalet'] ?? null,
      pending: byKey['pending'] ?? byKey['in progress'] ?? null,
      closedPrimary:
        byKey['closed'] ??
        byKey['resolved'] ??
        byKey['done'] ??
        byKey['completed'] ??
        null,
    } as const;
  }, [statuses]);

  const totalCountQ = useTicketsFilterQuery(countBaseFilters);
  const openCountQ = useTicketsFilterQuery(
    {
      ...countBaseFilters,
      status: normalizedStatusIds.open ?? undefined,
      status_id: normalizedStatusIds.open ?? undefined,
    },
    { enabled: !!normalizedStatusIds.open },
  );
  const escalatedCountQ = useTicketsFilterQuery(
    {
      ...countBaseFilters,
      status: normalizedStatusIds.escalated ?? undefined,
      status_id: normalizedStatusIds.escalated ?? undefined,
    },
    { enabled: !!normalizedStatusIds.escalated },
  );
  const pendingCountQ = useTicketsFilterQuery(
    {
      ...countBaseFilters,
      status: normalizedStatusIds.pending ?? undefined,
      status_id: normalizedStatusIds.pending ?? undefined,
    },
    { enabled: !!normalizedStatusIds.pending },
  );
  const closedCountQ = useTicketsFilterQuery(
    {
      ...countBaseFilters,
      status: normalizedStatusIds.closedPrimary ?? undefined,
      status_id: normalizedStatusIds.closedPrimary ?? undefined,
    },
    { enabled: !!normalizedStatusIds.closedPrimary },
  );

  const readCount = (q: any): number => {
    const payload = q?.data as any;
    if (typeof payload?.meta?.total === 'number') return payload.meta.total;
    if (typeof payload?.total === 'number') return payload.total;
    if (Array.isArray(payload?.data)) return payload.data.length;
    return 0;
  };

  const totalCount = readCount(totalCountQ);
  const openCount = readCount(openCountQ);
  const escalatedCount = readCount(escalatedCountQ);
  const pendingCount = readCount(pendingCountQ);
  const closedCount = readCount(closedCountQ);

  const quickStats = useMemo(
    () => [
      { label: 'Total', value: totalCount, color: '#0b2235', id: null },
      {
        label: 'Open',
        value: openCount,
        color: '#2563eb',
        id: normalizedStatusIds.open,
      },
      {
        label: 'Escalated',
        value: escalatedCount,
        color: '#dc2626',
        id: normalizedStatusIds.escalated,
      },
      {
        label: 'Pending',
        value: pendingCount,
        color: '#d97706',
        id: normalizedStatusIds.pending,
      },
      {
        label: 'Closed',
        value: closedCount,
        color: '#6c757d',
        id: normalizedStatusIds.closedPrimary,
      },
    ],
    [
      totalCount,
