/** Same-origin app paths only (blocks `//evil.com`). */
function isInternalAppPath(path: string): boolean {
  return Boolean(path.startsWith('/') && !path.startsWith('//'));
}

/**
 * Preview/production deployments sometimes see client `router.replace` stall for a long time
 * while "Taking you to your Service Desk…" stays up. A full document load reliably sends the
 * `token` cookie to middleware on the next request (`hydrateFromDeskLogin` sets it synchronously).
 */
function navigateAfterLogin(
  router: ReturnType<typeof useRouter>,
  path: string,
) {
  if (
    typeof window !== 'undefined' &&
    process.env.NODE_ENV === 'production' &&
    isInternalAppPath(path)
  ) {
    window.location.assign(path);
    return;
  }
  router.replace(path);
}

function applyPostLoginNavigation(
  router: ReturnType<typeof useRouter>,
  user: Record<string, unknown>,
  setUserIdForPasswordChange: (id: string) => void,
) {
  if (typeof window !== 'undefined') {
    const redir = sessionStorage.getItem('redirectAfterLogin');
    if (redir) {
      sessionStorage.removeItem('redirectAfterLogin');
      if (isInternalAppPath(redir)) {
        navigateAfterLogin(router, redir);
      } else {
        router.replace('/dashboard');
      }
      return;
    }
  }

  if (user?.password_changed === true) {
    const user_type =
      (user.user_type as string) ||
      (typeof window !== 'undefined'
        ? localStorage.getItem('user_type')
        : '') ||
      '';
    if (user_type === 'client')
      navigateAfterLogin(router, '/client-portal');
    else navigateAfterLogin(router, '/dashboard');
    return;
  }

  setUserIdForPasswordChange(String(user.id));
  navigateAfterLogin(router, '/confirmpassword');
}

export default function AuthenticationLoginPage() {
  const router = useRouter();
  const hydrateFromDeskLogin = useAuthStore((s) => s.hydrateFromDeskLogin);
  const setUserIdForPasswordChange = useAuthStore(
    (s) => s.setUserIdForPasswordChange,
  );

  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [remember, setRemember] = useState(false);

  const [socialBusy, setSocialBusy] = useState<'google' | 'microsoft' | null>(null);
  const [socialError, setSocialError] = useState<string | null>(null);
  const [isNavigatingAfterLogin, setIsNavigatingAfterLogin] = useState(false);
  const postLoginNavigationRef = useRef(false);

  useEffect(() => {
    router.prefetch('/dashboard');
    router.prefetch('/client-portal');
    router.prefetch('/confirmpassword');
  }, [router]);

  const mutation = useMutation({
    mutationFn: (vals: LoginValues) =>
      signInWithDeskCredentials(vals.email, vals.password),
    meta: {
      // Avoid a global toast: we already show full-screen loading + post-login copy;
      // a "Login successful" toast reads as finished while `/dashboard` is still loading.
      skipSuccessNotification: true,
    },
    onSuccess: (result) => {
      setIsNavigatingAfterLogin(true);
      postLoginNavigationRef.current = true;
      const { token, user, activeCalendar } = result;
      hydrateFromDeskLogin({
        token,
        localId: String(user.localId ?? ''),
        tenantId: String(user.tenantId ?? ''),
        userId: String(user.id ?? ''),
        userData: user as AuthUser,
        activeCalendar,
      });
      if (user?.user_type) {
        localStorage.setItem('user_type', String(user.user_type));
      }
      applyPostLoginNavigation(router, user, setUserIdForPasswordChange);
    },
  });

  const authInFlight =
    mutation.isPending ||
    socialBusy !== null ||
    isNavigatingAfterLogin;

  useLayoutEffect(() => {
    if (typeof window === 'undefined') return;
    const storeState = useAuthStore.getState();
    storeState.setHostname(window.location.hostname);

    // If user is already authenticated, redirect them away from the login page
    if (storeState.token && storeState.user && Object.keys(storeState.user).length > 0) {
      // Middleware only trusts the `token` cookie. If cookies are blocked (Firefox strict
      // mode, etc.), persisted Zustand still has a token → we'd send users to /dashboard,
      // middleware sends them back here → infinite redirect. Clear stale client state.

    // middleware sends them back here → infinite redirect. Clear stale client state.
    const hasTokenCookie = document.cookie
      .split(';')
      .some((c) => c.trim().startsWith('token='));
    if (!hasTokenCookie) {
      storeState.logout();
      return;
    }
    setIsNavigatingAfterLogin(true);
    postLoginNavigationRef.current = true;
    applyPostLoginNavigation(router, storeState.user, setUserIdForPasswordChange);
  }
}, [router, setUserIdForPasswordChange]);

async function runSocial(
  mode: 'google' | 'microsoft',
  fn: () => Promise<Awaited<ReturnType<typeof signInWithGoogleForDesk>>>,
) {
  setSocialBusy(mode);
  setSocialError(null);
  try {
    const result = await fn();
    setIsNavigatingAfterLogin(true);
    postLoginNavigationRef.current = true;
    const { token, user, activeCalendar } = result;
    hydrateFromDeskLogin({
      token,
      localId: String(user.localId ?? ''),
      tenantId: String(user.tenantId ?? ''),
      userId: String(user.id ?? ''),
      userData: user as AuthUser,
      activeCalendar,
    });
    if (user?.user_type) {
      localStorage.setItem('user_type', String(user.user_type));
    }
    applyPostLoginNavigation(router, user, setUserIdForPasswordChange);
  } catch (e) {
    setSocialError((e as Error)?.message || 'Sign-in failed');
  } finally {
    if (!postLoginNavigationRef.current) setSocialBusy(null);
  }
}

