'use client';

import React from 'react';
import { Input, Space, Button, Typography, List } from 'antd';
import { PlusOutlined, LinkOutlined } from '@ant-design/icons';

export type AttachmentsMode = 'edit' | 'view';

export interface AttachmentsProps {
  value?: string[];
  onChange?: (urls: string[]) => void;
  disabled?: boolean;
  mode?: AttachmentsMode;
}

export function Attachments({
  value = [],
  onChange,
  disabled = false,
  mode = 'view',
}: AttachmentsProps) {
  if (mode === 'view') {
    if (!value?.length)
      return <Typography.Text type="secondary">No attachments</Typography.Text>;
    return (
      <List
        size="small"
        dataSource={value}
        renderItem={(url) => (
          <List.Item>
            <a
              href={url}
              target="_blank"
              rel="noopener noreferrer"
              className="flex items-center gap-2"
            >
              <LinkOutlined />
              <Typography.Link ellipsis style={{ maxWidth: 320 }}>
                {url}
              </Typography.Link>
            </a>
          </List.Item>
        )}
      />
    );
  }

  const next = [...value];
  const add = () => onChange?.([...next, '']);
  const update = (index: number, v: string) => {
    const u = [...next];
    u[index] = v;
    onChange?.(u);
  };
  const remove = (index: number) => {
    onChange?.(next.filter((_, i) => i !== index));
  };

  return (
    <Space direction="vertical" style={{ width: '100%' }}>
      {next.map((url, i) => (
        <Space key={i} style={{ width: '100%' }} align="center">
          <Input
            placeholder="https://…"
            value={url}
            onChange={(e) => update(i, e.target.value)}
            disabled={disabled}
            style={{ flex: 1, maxWidth: 400 }}
          />
          <Button
            type="text"
            danger
            disabled={disabled}
            onClick={() => remove(i)}
          >
            Remove
          </Button>
        </Space>
      ))}
      <Button
        type="dashed"
        icon={<PlusOutlined />}
        onClick={add}
        disabled={disabled}
      >
        Add link
      </Button>
    </Space>
  );
}

