export function ReplyEditor({
  ticketId,
  onSuccess,
  disabled,
}: ReplyEditorProps) {
  const [body, setBody] = useState('');
  const [attachmentLinks, setAttachmentLinks] = useState<string[]>([]);
  const createReply = useCreateClientReplyMutation();

  const handleSubmit = async () => {
    const trimmed = body.trim();
    if (!trimmed) {
      message.warning('Please enter a message.');
      return;
    }
    try {
      await createReply.mutateAsync({
        ticketId,
        comment: trimmed,
        attachments: attachmentLinks.filter(Boolean),
      });
      message.success('Reply sent.');
      setBody('');
      setAttachmentLinks([]);
      onSuccess?.();
    } catch (e: any) {
      message.error(e?.message ?? 'Failed to send reply.');
    }
  };

  return (
    <Form layout="vertical" onFinish={handleSubmit}>
      <Form.Item
        label="Your reply"
        help="Add a comment to this ticket. Only plain text is sent to the team."
      >
        <TextArea
          rows={4}
          value={body}
          onChange={(e) => setBody(e.target.value)}
          placeholder="Type your message…"
