'use client';

import React from 'react';
import { Tag } from 'antd';

export type StatusSource =
  | { id?: string | number; type?: string; status_color?: string }
  | string
  | null
  | undefined;

const DEFAULT_STATUS_COLORS: Record<string, string> = {
  Open: 'blue',
  Pending: 'orange',
  Closed: 'green',
  Escalated: 'red',
  New: 'default',
};

function getStatusDisplay(status: StatusSource): {
  label: string;
  color: string;
} {
  if (status == null) return { label: 'N/A', color: 'default' };
  const type = typeof status === 'object' ? status?.type : status;
  const label = type ?? 'N/A';
  const color =
    (typeof status === 'object' && status?.status_color) ||
    DEFAULT_STATUS_COLORS[label] ||
    'default';
  return {
    label,
    color:
      typeof color === 'string' && color.startsWith('#')
        ? color
        : (color as string),
  };
}

export interface StatusBadgeProps {
  status: StatusSource;
  size?: 'default' | 'small';
}

export function StatusBadge({ status, size = 'default' }: StatusBadgeProps) {
  const { label, color } = getStatusDisplay(status);
  return (
    <Tag
      color={color}
      className="!rounded !font-medium !m-0"
      style={{
        padding: size === 'small' ? '1px 6px' : '4px 12px',
        fontSize: size === 'small' ? 10 : 14,
        lineHeight: size === 'small' ? '1.2' : undefined,
      }}
    >
      {label}
    </Tag>
  );
}

