function formatDate(dateString: string): string {
  try {
    return new Date(dateString).toLocaleString(undefined, {
      dateStyle: 'medium',
      timeStyle: 'short',
    });
  } catch {
    return dateString;
  }
}

const PRIORITY_COLORS: Record<string, string> = {
  High: 'red',
  Medium: 'orange',
  Low: 'blue',
};

export interface TicketDetailsProps {
  ticket: ClientTicket | null | undefined;
  loading?: boolean;
}

export function TicketDetails({ ticket, loading }: TicketDetailsProps) {
  if (loading || !ticket) {
    return (
      <div className="animate-pulse space-y-4">
        <div className="bg-muted h-6 w-3/4 rounded" />
        <div className="bg-muted/70 h-20 w-full rounded" />
      </div>
    );
  }

  const priority =
    typeof ticket.ticket_priority === 'object'
      ? ticket.ticket_priority?.type
      : ticket.ticket_priority;
  const priorityColor = priority
    ? (PRIORITY_COLORS[priority] ?? 'default')
    : undefined;

  return (
    <div className="space-y-5">
      <div className="flex flex-wrap items-start justify-between gap-4">
        <span className="text-foreground !text-md m-0 font-semibold leading-tight">
          {ticket.subject}
        </span>
        <Space wrap>
          <StatusBadge status={ticket.ticket_status} />
          {priority && (
            <Tag color={priorityColor} className="!rounded-lg">
              {priority}
            </Tag>
          )}
        </Space>
      </div>

      <Descriptions
        column={{ xs: 1, sm: 2 }}
        size="small"
        bordered
        className="[&_.ant-descriptions-view]:!rounded-xl [&_td]:!py-2.5 [&_.ant-descriptions-item-label]:text-muted-foreground"
        style={{ marginBottom: 0 }}
      >
        <Descriptions.Item
          label={
            <Space size={4}>
              <CalendarOutlined className="text-muted-foreground" />
              <span>Created</span>
            </Space>
          }
        >
          <span className="text-foreground">
            {formatDate(ticket.created_at)}
          </span>
        </Descriptions.Item>
        {hasResolvedAssignees(ticket) && (
          <Descriptions.Item
            label={
              <Space size={4}>
                <UserOutlined className="text-muted-foreground" />
                <span>Assigned to</span>
              </Space>
            }
          >
            <Avatar.Group
              maxCount={4}
              size="default"
              maxStyle={{
                color: 'var(--primary)',
                backgroundColor: 'var(--accent)',
                fontSize: 12,
              }}
            >
              {resolveTicketAssigneeRows(ticket).map(
                (u: {
                  id: string | number;
                  name?: string;
                  first_name?: string;
                  last_name?: string;
                  profile_pic?: string;
                }) => {
                  const name =
                    u.name ??
                    ([u.first_name, u.last_name]
                      .filter(Boolean)
                      .join(' ')
                      .trim() ||
                      '—');
                  const src = u.profile_pic?.startsWith('http')
                    ? u.profile_pic
                    : URL && u.profile_pic
                      ? `${URL}/${String(u.profile_pic).replace(/^\//, '')}`
                      : undefined;
                  const initials =
                    u.first_name || u.last_name
                      ? [u.first_name?.charAt(0), u.last_name?.charAt(0)]
                          .filter(Boolean)
                          .join('')
                          .toUpperCase()
                      : name !== '—'
                        ? name.charAt(0).toUpperCase()
                        : '?';
                  return (
                    <Tooltip
                      key={String(getUserExternalId(u as any) ?? u.id)}
                      title={name}
                      placement="top"
                    >
                      <Avatar
                        src={src}
                        className="!bg-primary !text-primary-foreground"
                      >
                        {!src ? initials : null}
                      </Avatar>
                    </Tooltip>
                  );
                },
              )}
            </Avatar.Group>
          </Descriptions.Item>
        )}
      </Descriptions>

      <Divider orientation="left" plain className="!border-border !mt-5">
        <Space size={4}>
          <FlagOutlined className="text-muted-foreground" />
          <span className="text-muted-foreground font-medium">Description</span>
        </Space>
      </Divider>
      <div dangerouslySetInnerHTML={{ __html: ticket.description || '—' }} />
    </div>
  );
}

