function formatRelativeDate(dateString: string): string {
  const date = new Date(dateString);
  const now = new Date();
  const diffTime = Math.abs(now.getTime() - date.getTime());
  const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
  if (diffDays === 0) return 'Today';
  if (diffDays === 1) return 'Yesterday';
  if (diffDays < 7) return `${diffDays} days ago`;
  return date.toLocaleDateString('en-US', {
    month: 'short',
    day: 'numeric',
    year: date.getFullYear() !== now.getFullYear() ? 'numeric' : undefined,
  });
}

export interface TicketListProps {
  tickets: ClientTicket[];
  loading?: boolean;
  onTicketClick?: (ticket: ClientTicket) => void;
}

export function TicketList({
  tickets,
  loading,
  onTicketClick,
}: TicketListProps) {
  console.log(tickets, 'tisssckets');
  const {
    ticketsViewMode,
    ticketsPagination,
    setTicketsPagination,
    ticketFilters,
  } = useClientPortalUiStore();

  const filteredTickets = useMemo(() => {
    let out = [...tickets];
    const search = (ticketFilters.search ?? '').toLowerCase();

    if (search) {
      out = out.filter(
        (t) =>
          t.subject?.toLowerCase().includes(search) ||
          t.description?.toLowerCase().includes(search),
      );
    }

    if (ticketFilters.status) {
      out = out.filter((t) => {
        const statusId =
          (typeof t.ticket_status === 'object' && t.ticket_status?.id) ||
          // some APIs may also expose a top-level status_id
          (t as any).status_id ||
          null;
        return String(statusId) === String(ticketFilters.status);
      });
    }

    if (ticketFilters.priority != null && ticketFilters.priority !== '') {
      out = out.filter((t) => t.ticket_priority?.id === ticketFilters.priority);
    }

    return out;
  }, [tickets, ticketFilters]);

  const paginatedTickets = useMemo(() => {
    const { current, pageSize } = ticketsPagination;
    const start = (current - 1) * pageSize;
    return filteredTickets.slice(start, start + pageSize);
  }, [filteredTickets, ticketsPagination]);
  console.log(filteredTickets, 'filteredTickets');

  if (loading) {
    return (
      <div className="flex justify-center items-center py-20">
        <Spin size="large" tip="Loading tickets…" />
      </div>
    );
  }

  if (filteredTickets.length === 0) {
    return (
      <div className="py-16 px-4">
        <Empty
          description={
            <span className="text-muted-foreground text-sm">
              {tickets.length === 0
                ? 'No tickets yet'
                : 'No tickets match your filters'}
            </span>
          }
          image={Empty.PRESENTED_IMAGE_SIMPLE}
          className="[&_.ant-empty-image]:opacity-80"
        />
      </div>
    );
  }

  if (ticketsViewMode === 'list') {
    return (
      <div className="p-5">
        <Space direction="vertical" size={10} style={{ width: '100%' }}>
          {paginatedTickets.map((ticket) => (
            <TicketCard
              key={String(ticket.id)}
              ticket={ticket}
              onView={onTicketClick}
            />
          ))}
        </Space>
        {filteredTickets.length > ticketsPagination.pageSize && (
          <div className="flex justify-center items-center mt-8 gap-3 flex-wrap">
            <Button
              disabled={ticketsPagination.current <= 1}
              onClick={() =>
                setTicketsPagination({
                  ...ticketsPagination,
                  current: ticketsPagination.current - 1,
                })
              }
              size="middle"
              className="!rounded-lg"
            >
              Previous
            </Button>
            <span className="text-muted-foreground text-sm">
              Page {ticketsPagination.current} of{' '}
              {Math.ceil(filteredTickets.length / ticketsPagination.pageSize)}
            </span>
            <Button
              disabled={
                ticketsPagination.current >=
                Math.ceil(filteredTickets.length / ticketsPagination.pageSize)
              }
              onClick={() =>
                setTicketsPagination({
                  ...ticketsPagination,
                  current: ticketsPagination.current + 1,
                })
              }
              size="middle"
              className="!rounded-lg"
            >
              Next
            </Button>
          </div>
        )}
      </div>
    );
  }

  const columns: ColumnsType<ClientTicket> = [
    {
      title: 'Subject',
      dataIndex: 'subject',
      key: 'subject',
      ellipsis: true,
      render: (_, record) => (
        <button
          type="button"
          className="text-foreground hover:text-primary cursor-pointer text-left font-medium transition-colors hover:underline"
          onClick={() => onTicketClick?.(record)}
        >
          {record.subject}
        </button>
      ),
    },
    {
      title: 'Status',
      key: 'status',
      width: 120,
      render: (_, r) => <StatusBadge status={r.ticket_status} size="small" />,
    },
    {
      title: 'Priority',
      key: 'priority',
      width: 100,
      render: (_, r) =>
        typeof r.ticket_priority === 'object'
          ? r.ticket_priority?.type
          : (r.ticket_priority ?? '—'),
    },
    {
      title: 'Created',
      dataIndex: 'created_at',
      key: 'created_at',
      width: 120,
      render: (v: string) => (
        <span className="text-muted-foreground text-xs">
          {formatRelativeDate(v)}
        </span>
      ),
    },
  ];

  return (
    <div className="p-6 [&_.ant-table]:!rounded-xl [&_.ant-table-container]:!rounded-xl overflow-hidden">
      <Table<ClientTicket>
        rowKey={(r) => String(r.id)}
        columns={columns}
        dataSource={paginatedTickets}
        pagination={{
          current: ticketsPagination.current,
          pageSize: ticketsPagination.pageSize,
          total: filteredTickets.length,
          showSizeChanger: true,
          showTotal: (total) => (
            <span className="text-muted-foreground text-sm">
              Total {total} tickets
            </span>
          ),
          onChange: (page, pageSize) =>
            setTicketsPagination({ current: page, pageSize: pageSize ?? 10 }),
        }}
        size="middle"
        loading={false}
        className="client-tickets-table"
      />
    </div>
  );
}

'use client';

import React, { useMemo } from 'react';
import { Timeline, Typography, Empty, Spin } from 'antd';
import type { TicketReply } from '../../_hooks/useClientPortalQueries';

const { Text } = Typography;

function formatWhen(v?: string): string {
  if (!v) return '';
  try {
    const d = new Date(v);
    if (Number.isNaN(d.getTime())) return '';
    return d.toLocaleString(undefined, {
      dateStyle: 'medium',
      timeStyle: 'short',
    });
  } catch {
    return '';
  }
}

function getReplyAuthor(r: TicketReply): string {
  const byUser = r?.created_by ?? r?.createdByUser ?? r?.user;
  if (byUser) {
    const name =
      (byUser as any).name ??
      [(byUser as any).first_name, (byUser as any).last_name]
        .filter(Boolean)
        .join(' ')
        .trim();
    if (name) return name;
    if ((byUser as any).email) return (byUser as any).email;
  }
  return r?.senderEmail ?? 'Support';
}

function getReplyBody(r: TicketReply): string {
  return r?.description ?? r?.comment ?? r?.body ?? r?.message ?? '';
}

export interface TicketTimelineProps {
  replies: TicketReply[] | undefined;
  loading?: boolean;
}

export function TicketTimeline({ replies, loading }: TicketTimelineProps) {
  const items = useMemo(() => {
    const list = replies ?? [];
    return list.map((r) => ({
      children: (
        <div>
          <Text strong>{getReplyAuthor(r)}</Text>
          {formatWhen(r?.created_at ?? (r as any)?.createdAt) ? (
            <Text type="secondary" style={{ marginLeft: 8 }}>
              {formatWhen(r?.created_at ?? (r as any)?.createdAt)}
            </Text>
          ) : null}
          <div
            dangerouslySetInnerHTML={{ __html: getReplyBody(r) }}
            style={{ marginTop: 6, whiteSpace: 'pre-wrap' }}
            className="tiptap-content"
          />
        </div>
      ),
    }));
  }, [replies]);

  if (loading) {
    return (
      <div className="flex justify-center py-8">
        <Spin tip="Loading replies…" />
      </div>
    );
  }

  if (!items.length) {
    return (
      <Empty
        image={Empty.PRESENTED_IMAGE_SIMPLE}
        description="No replies yet. Add a comment below."
      />
    );
  }

  return <Timeline items={items} />;
}

