const { Text } = Typography;

export function PermissionPanel() {
  const permissionListSearch = useRoleUiStore((s) => s.permissionListSearch);
  const setPermissionListSearch = useRoleUiStore(
    (s) => s.setPermissionListSearch,
  );
  const showAssignToRole = useRoleUiStore((s) => s.showAssignToRole);
  const setShowAssignToRole = useRoleUiStore((s) => s.setShowAssignToRole);
  const selectedRoleIdForAssign = useRoleUiStore(
    (s) => s.selectedRoleIdForAssign,
  );
  const setSelectedRoleIdForAssign = useRoleUiStore(
    (s) => s.setSelectedRoleIdForAssign,
  );
  const selectedPermissionIdsForAssign = useRoleUiStore(
    (s) => s.selectedPermissionIdsForAssign,
  );
  const setSelectedPermissionIdsForAssign = useRoleUiStore(
    (s) => s.setSelectedPermissionIdsForAssign,
  );
  const permissionAssignSearch = useRoleUiStore(
    (s) => s.permissionAssignSearch,
  );
  const setPermissionAssignSearch = useRoleUiStore(
    (s) => s.setPermissionAssignSearch,
  );

  const rolesQuery = useRolesQuery();
  const permissionsQuery = usePermissionsQuery();
  const assignPermissionsMutation = useAssignPermissionsMutation();
  const canUpdateRole = checkUserPermission([PERMISSIONS.roleUpdate]);

  const roles = rolesQuery.data ?? [];
  const permissions = permissionsQuery.data ?? [];

  const handleRoleSelectForAssign = useCallback(
    (roleId: string | number | null) => {
      setSelectedRoleIdForAssign(roleId);
      if (roleId == null) {
        setSelectedPermissionIdsForAssign([]);
        return;
      }
      const role = roles.find((r) => String(r.id) === String(roleId));
      setSelectedPermissionIdsForAssign(
        (role?.permissions ?? []).map((p) => p.id),
      );
    },
    [roles, setSelectedRoleIdForAssign, setSelectedPermissionIdsForAssign],
  );

  const handleAssignToRoleSubmit = useCallback(async () => {
    if (!canUpdateRole) return;
    if (selectedRoleIdForAssign == null) return;
    try {
      await assignPermissionsMutation.mutateAsync({
        roleId: selectedRoleIdForAssign,
        permissions: selectedPermissionIdsForAssign,
      });
      message.success('Permissions assigned to role');
      setShowAssignToRole(false);
      setSelectedRoleIdForAssign(null);
      setSelectedPermissionIdsForAssign([]);
      setPermissionAssignSearch('');
    } catch (e: any) {
      message.error(e?.message ?? 'Failed to assign permissions');
    }
  }, [
    selectedRoleIdForAssign,
    selectedPermissionIdsForAssign,
    assignPermissionsMutation,
    setShowAssignToRole,
    setSelectedRoleIdForAssign,
    setSelectedPermissionIdsForAssign,
    setPermissionAssignSearch,
    canUpdateRole,
  ]);

  const filteredPermissions = useMemo(() => {
    if (!permissionListSearch.trim()) return permissions;
    const q = permissionListSearch.trim().toLowerCase();
    return permissions.filter(
      (p) =>
        (p.name ?? '').toLowerCase().includes(q) ||
        (p.slug ?? '').toLowerCase().includes(q),
    );
  }, [permissions, permissionListSearch]);

  const roleOptions = roles.map((r) => ({
    label: r.roleName ?? r.name ?? r.rolename ?? String(r.id),
    value: String(r.id),
  }));

  return (
    <Card
