            value={
              selectedRoleIdForAssign != null
                ? String(selectedRoleIdForAssign)
                : undefined
            }
            onChange={(v) => handleRoleSelectForAssign(v ? v : null)}
            options={roleOptions}
            style={{ width: '100%' }}
            allowClear
            className="!rounded-lg"
          />
          {selectedRoleIdForAssign != null && (
            <>
              <div className="border-border mt-2 max-h-40 overflow-y-auto rounded-lg border p-2">
                <PermissionTree
                  permissions={permissions}
                  selectedPermissionIds={selectedPermissionIdsForAssign}
                  onSelectionChange={setSelectedPermissionIdsForAssign}
