                  onSearchChange={setPermissionAssignSearch}
                  showSearch={false}
                  height={160}
                />
              </div>
              <Space className="mt-2">
                <Button
                  type="primary"
                  size="small"
                  onClick={handleAssignToRoleSubmit}
