    </Card>
  );
}

'use client';

import React, { useMemo } from 'react';
import { Input, Checkbox, Typography, List, Space } from 'antd';
import { SearchOutlined, KeyOutlined } from '@ant-design/icons';
import type { Permission } from '../_hooks/useRoleQueries';

const { Text } = Typography;

type PermissionTreeProps = {
  permissions: Permission[];
  selectedPermissionIds: Array<string | number>;
  onSelectionChange: (selectedIds: Array<string | number>) => void;
  searchValue?: string;
  onSearchChange?: (value: string) => void;
  showSearch?: boolean;
  height?: number;
};

export function PermissionTree({
  permissions,
  selectedPermissionIds,
  onSelectionChange,
  searchValue,
  onSearchChange,
  showSearch = true,
  height = 400,
}: PermissionTreeProps) {
  const filteredPermissions = useMemo(() => {
    if (!searchValue?.trim()) return permissions;
    const search = searchValue.trim().toLowerCase();
    return permissions.filter(
      (p) =>
        (p.name ?? '').toLowerCase().includes(search) ||
        (p.slug ?? '').toLowerCase().includes(search),
    );
  }, [permissions, searchValue]);

  const handleSelectAll = (checked: boolean) => {
    if (checked) {
      const allIds = filteredPermissions.map((p) => p.id);
      const merged = [...selectedPermissionIds, ...allIds];
      const unique = merged.filter((id, index) => merged.indexOf(id) === index);
      onSelectionChange(unique);
    } else {
      const filteredIds = filteredPermissions.map((p) => p.id);
      onSelectionChange(
        selectedPermissionIds.filter((id) => !filteredIds.includes(id)),
      );
    }
  };

  const handleTogglePermission = (
    permissionId: string | number,
    checked: boolean,
  ) => {
    if (checked) {
      onSelectionChange([...selectedPermissionIds, permissionId]);
    } else {
      onSelectionChange(
        selectedPermissionIds.filter((id) => id !== permissionId),
      );
    }
  };

  const allFilteredSelected =
    filteredPermissions.length > 0 &&
    filteredPermissions.every((p) => selectedPermissionIds.includes(p.id));
  const someFilteredSelected =
    filteredPermissions.some((p) => selectedPermissionIds.includes(p.id)) &&
    !allFilteredSelected;

  return (
    <div className="space-y-2">
      {showSearch && (
        <Input
          placeholder="Search permissions..."
          prefix={
            <SearchOutlined style={{ color: 'var(--primary)', opacity: 0.5 }} />
          }
          value={searchValue}
          onChange={(e) => onSearchChange?.(e.target.value)}
          allowClear
          className="!rounded-lg"
        />
      )}

      {filteredPermissions.length > 0 && (
        <div className="border-border rounded-md border p-4">
          <Checkbox
            checked={allFilteredSelected}
            indeterminate={someFilteredSelected}
            onChange={(e) => handleSelectAll(e.target.checked)}
            className="mb-3"
          >
            <Text strong className="!text-sm">
              Select All ({filteredPermissions.length})
            </Text>
          </Checkbox>

          <div style={{ maxHeight: height, overflowY: 'auto' }}>
            <List
              dataSource={filteredPermissions}
              renderItem={(permission) => {
                const permissionId = permission.id;
                const isSelected = selectedPermissionIds.includes(permissionId);

                const isSelected = selectedPermissionIds.includes(permissionId);
                const displayName =
                  permission.name || permission.slug || String(permission.id);

                return (
                  <List.Item
                    key={String(permissionId)}
                    className="hover:!bg-muted/60 !cursor-pointer rounded-lg !px-2.5 !py-2 transition-colors"
                    onClick={() =>
                      handleTogglePermission(permissionId, !isSelected)
                    }
                  >
                    <Space>
                      <Checkbox
                        checked={isSelected}
                        onChange={(e) => {
                          e.stopPropagation();
                          handleTogglePermission(
                            permissionId,
                            e.target.checked,
                          );
                        }}
                        onClick={(e) => e.stopPropagation()}
                      />
                      <div className="flex items-center gap-1.5">
                        <KeyOutlined
                          style={{
                            color: 'var(--primary)',
                            fontSize: 11,
                            opacity: 0.4,
                          }}
                        />
                        <Text className="!text-sm">{displayName}</Text>
                      </div>
                    </Space>
                  </List.Item>
                );
              }}
            />
          </div>
        </div>
      )}

      {filteredPermissions.length === 0 && searchValue && (
        <div className="text-center py-8">
          <Text type="secondary" className="!text-sm">
            No permissions found matching &quot;{searchValue}&quot;
          </Text>
        </div>
      )}

      {permissions.length === 0 && (
        <div className="text-center py-8">
          <Text type="secondary" className="!text-sm">
            No permissions available
          </Text>
        </div>
      )}
    </div>
  );
}

