};

export function RoleActions({
  role,
  onEdit,
  onDelete,
  onAssignPermissions,
  onViewDetails,
  deletingId,
}: RoleActionsProps) {
  const isDeleting = deletingId === role.id;

  return (
    <Space
      size={2}
