            onClick={() => onViewDetails(role)}
            className="!text-muted-foreground hover:!text-primary hover:!bg-primary/5 !rounded-lg"
          />
        </Tooltip>
      )}
      {onEdit && (
        <Tooltip title="Edit Role">
          <Button
            type="text"
            size="small"
            icon={<EditOutlined />}
            onClick={() => onEdit(role)}
            className="!text-muted-foreground hover:!text-primary hover:!bg-primary/5 !rounded-lg"
          />
        </Tooltip>
      )}
      {onAssignPermissions && (
        <Tooltip title="Assign Permissions">
          <Button
            type="text"
            size="small"
            icon={<KeyOutlined />}
            onClick={() => onAssignPermissions(role)}
            className="!rounded-lg !text-amber-500 hover:!bg-amber-50"
          />
        </Tooltip>
      )}
      {onDelete && (
        <Popconfirm
          title="Delete role?"
          description={`Delete "${role.roleName || role.name || role.rolename}"? This cannot be undone.`}
          icon={<ExclamationCircleOutlined style={{ color: '#ef4444' }} />}
          onConfirm={() => onDelete(role)}
          okText="Delete"
          okButtonProps={{ danger: true, className: '!rounded-lg' }}
          cancelButtonProps={{ className: '!rounded-lg' }}
          cancelText="Cancel"
        >
          <Tooltip title="Delete Role">
            <Button
              type="text"
              size="small"
              danger
              icon={<DeleteOutlined />}
              loading={isDeleting}
              className="!rounded-lg"
            />
          </Tooltip>
        </Popconfirm>
      )}
    </Space>
  );
}

