'use client';

import React, { useEffect } from 'react';
import { Form, Input, Button, Space } from 'antd';
import { SafetyOutlined } from '@ant-design/icons';
import type {
  Role,
  RoleCreateInput,
  RoleUpdateInput,
} from '../_hooks/useRoleQueries';

type RoleFormProps = {
  role?: Role | null;
  onSubmit: (values: RoleCreateInput | RoleUpdateInput) => void | Promise<void>;
  onCancel?: () => void;
  loading?: boolean;
  submitText?: string;
};

export function RoleForm({
  role,
  onSubmit,
  onCancel,
  loading,
  submitText = 'Submit',
}: RoleFormProps) {
  const [form] = Form.useForm();

  useEffect(() => {
    if (role) {
      form.setFieldsValue({
        roleName: role.roleName || role.name || role.rolename || '',
      });
    } else {
      form.resetFields();
    }
  }, [role, form]);

  const handleSubmit = async (values: any) => {
    if (role) {
      await onSubmit({ id: role.id, ...values });
    } else {
      await onSubmit(values);
    }
  };

  return (
    <Form
      form={form}
      layout="vertical"
      onFinish={handleSubmit}
      initialValues={{
        roleName: role?.roleName || role?.name || role?.rolename || '',
      }}
    >
      <Form.Item
        name="roleName"
        label={
          <span className="flex items-center gap-1.5 text-sm">
            <SafetyOutlined style={{ color: 'var(--primary)' }} /> Role Name
          </span>
        }
        rules={[
          { required: true, message: 'Please enter a role name' },
          { min: 2, message: 'Role name must be at least 2 characters' },
          { max: 100, message: 'Role name must not exceed 100 characters' },
        ]}
      >
        <Input
          placeholder="Enter role name"
          className="!rounded-lg"
          style={{ height: 42 }}
        />
      </Form.Item>

      <Form.Item className="mb-0">
        <Space className="w-full justify-end">
          {onCancel && (
            <Button
              onClick={onCancel}
              className="!rounded-lg"
              style={{ height: 42 }}
            >
              Cancel
            </Button>
          )}
          <Button
            type="primary"
            htmlType="submit"
            loading={loading}
            className="!rounded-lg shadow-sm"
            style={{ height: 42 }}
          >
            {submitText}
          </Button>
        </Space>
      </Form.Item>
    </Form>
  );
}

