'use client';

import React, { useMemo } from 'react';
import { Table, Tag, Typography, Empty, Avatar, Badge } from 'antd';
import type { ColumnsType } from 'antd/es/table';
import type { Role } from '../_hooks/useRoleQueries';
import { RoleActions } from './RoleActions';
import { SafetyOutlined, KeyOutlined } from '@ant-design/icons';

const { Text } = Typography;

const ROLE_COLORS = [
  '#7c3aed',
  '#6d28d9',
  '#1e5a8a',
  '#0e7490',
  '#0f766e',
  '#4338ca',
  '#0d9488',
];

type RoleTableProps = {
  roles: Role[];
  loading?: boolean;
  total?: number;
  currentPage?: number;
  pageSize?: number;
  onPageChange?: (page: number, size: number) => void;
  onEdit?: (role: Role) => void;
  onDelete?: (role: Role) => void;
  onAssignPermissions?: (role: Role) => void;
  onViewDetails?: (role: Role) => void;
  deletingId?: string | number | null;
};

export function RoleTable({
  roles,
  loading,
  total,
  currentPage = 1,
  pageSize = 10,
  onPageChange,
  onEdit,
  onDelete,
  onAssignPermissions,
  onViewDetails,
  deletingId,
}: RoleTableProps) {
  const columns: ColumnsType<Role> = useMemo(
    () => [
      {
        title: (
          <span className="flex items-center gap-1.5">
            <SafetyOutlined style={{ color: 'var(--primary)' }} /> Role Name
          </span>
        ),
        dataIndex: 'roleName',
        key: 'roleName',
        render: (text: string, record: Role) => {
          const roleName = text || record.name || record.rolename || 'N/A';
          const colorIdx = roleName.charCodeAt(0) % ROLE_COLORS.length;
          return (
            <div className="flex items-center gap-2.5">
              <Avatar
                size={30}
                style={{
                  background: ROLE_COLORS[colorIdx],
                  color: '#fff',
                  fontSize: 12,
                  fontWeight: 600,
                }}
              >
                {roleName.charAt(0).toUpperCase()}
              </Avatar>
              <Text strong className="!text-sm">
                {roleName}
              </Text>
            </div>
          );
        },
        sorter: (a: Role, b: Role) => {
          const nameA = (
            a.roleName ||
            a.name ||
            a.rolename ||
            ''
          ).toLowerCase();
          const nameB = (
            b.roleName ||
            b.name ||
            b.rolename ||
            ''
          ).toLowerCase();
          return nameA.localeCompare(nameB);
        },
      },
      {
        title: (
          <span className="flex items-center gap-1.5">
            <KeyOutlined style={{ color: 'var(--primary)' }} /> Permissions
          </span>
        ),
        key: 'permissions',
        render: (_: any, record: Role) => {

        render: (_: any, record: Role) => {
          const permissions = record.permissions || [];
          if (permissions.length === 0) {
            return (
              <Text type="secondary" className="!text-xs">
                No permissions
              </Text>
            );
          }
          return (
            <div className="flex flex-wrap gap-1">
              {permissions.slice(0, 3).map((perm) => (
                <Tag
                  key={perm.id}
                  className="!rounded-full !border-0 !text-xs"
                  style={{ background: '#7c3aed10', color: '#7c3aed' }}
                >
                  {perm.name || perm.slug || String(perm.id)}
                </Tag>
              ))}
              {permissions.length > 3 && (
                <Tag
                  className="!rounded-full !border-0 !text-xs"
                  style={{ background: '#f1f5f9', color: '#64748b' }}
                >
                  +{permissions.length - 3} more
                </Tag>
              )}
            </div>
          );
        },
      },
      {
        title: 'Actions',
        key: 'actions',
        width: 200,
        render: (_: any, record: Role) => (
          <RoleActions
            role={record}
            onEdit={onEdit}
            onDelete={onDelete}
            onAssignPermissions={onAssignPermissions}
            onViewDetails={onViewDetails}
            deletingId={deletingId}
          />
        ),
      },
    ],
    [onEdit, onDelete, onAssignPermissions, onViewDetails, deletingId],
  );

  return (
    <Table
      columns={columns}
      dataSource={roles}
      rowKey={(record) => String(record.id)}
      loading={loading}
      pagination={
        total !== undefined
          ? {
              current: currentPage,
              pageSize: pageSize,
              total: total,
              showSizeChanger: true,
              showTotal: (total, range) =>
                `${range[0]}-${range[1]} of ${total} roles`,
              onChange: onPageChange,
              onShowSizeChange: onPageChange,
            }
          : false
      }
      locale={{
        emptyText: (
          <Empty
            description="No roles found"
            image={Empty.PRESENTED_IMAGE_SIMPLE}
          />
        ),
      }}
      scroll={{ x: 'max-content' }}
      className="[&_.ant-table-thead_.ant-table-cell]:!border-border [&_.ant-table-thead_.ant-table-cell]:!bg-muted/80 [&_.ant-table-thead_.ant-table-cell]:!text-muted-foreground [&_.ant-table-thead_.ant-table-cell]:!text-xs [&_.ant-table-thead_.ant-table-cell]:!font-medium [&_.ant-table-thead_.ant-table-cell]:!uppercase [&_.ant-table-thead_.ant-table-cell]:!tracking-wider"
    />
  );
}

