function UserAvatar({ user }: { user: User }) {
  const src = user.profile_pic ?? null;
  const first = user.first_name?.[0] ?? '';
  const last = user.last_name?.[0] ?? '';
  const initials = (first + last).toUpperCase() || '?';
  if (src && typeof src === 'string') {
    return (
      <Avatar
        src={`${URL}/${src.replace(/^\//, '')}`}
        alt={initials}
        size="default"
      />
    );
  }
  return (
    <Avatar
      size="default"
      className="bg-primary text-primary-foreground font-semibold"
      style={{ fontSize: 12 }}
    >
      {initials}
    </Avatar>
  );
}

export function UsersPanel() {
  const usersSearch = useRoleUiStore((s) => s.usersSearch);
  const setUsersSearch = useRoleUiStore((s) => s.setUsersSearch);
  const assignRoleUser = useRoleUiStore((s) => s.assignRoleUser);
  const setAssignRoleUser = useRoleUiStore((s) => s.setAssignRoleUser);
  const assignRoleId = useRoleUiStore((s) => s.assignRoleId);
  const setAssignRoleId = useRoleUiStore((s) => s.setAssignRoleId);

  const usersQuery = useUsersQuery();
  const rolesQuery = useRolesQuery();
  const updateUserRoleMutation = useUpdateUserRoleMutation();
  const canUpdateUsers = checkUserPermission([PERMISSIONS.employeeUpdate]);

  const users = usersQuery.data ?? [];
  const roles = rolesQuery.data ?? [];

  const filteredUsers = useMemo(() => {
    if (!usersSearch.trim()) return users;
    const q = usersSearch.trim().toLowerCase();
    return users.filter(
      (u) =>
        (u.first_name ?? '').toLowerCase().includes(q) ||
        (u.last_name ?? '').toLowerCase().includes(q) ||
        (u.email ?? '').toLowerCase().includes(q),
    );
  }, [users, usersSearch]);

  const handleAssignRoleSubmit = useCallback(async () => {
    if (!canUpdateUsers) return;
    if (!assignRoleUser || assignRoleId == null) return;
    try {
      await updateUserRoleMutation.mutateAsync({
        userId: assignRoleUser.id,
        roleId: assignRoleId,
      });
      message.success('Role assigned');
      setAssignRoleUser(null);
      setAssignRoleId(null);
    } catch (e: any) {
      message.error(e?.message ?? 'Failed to assign role');
    }
  }, [
    assignRoleUser,
    assignRoleId,
    updateUserRoleMutation,
    setAssignRoleUser,
    setAssignRoleId,
    canUpdateUsers,
  ]);

  const openAssignRole = useCallback(
    (user: User) => {
      setAssignRoleUser(user);
      setAssignRoleId(user.role?.id ?? null);
    },
    [setAssignRoleUser, setAssignRoleId],
