          >
            {record.role.roleName ?? record.role.name ?? record.role.rolename}
          </Tag>
        ) : (
          <Text type="secondary" className="!text-xs">
            No role
          </Text>
        ),
    },
    {
      title: 'Permissions',
      key: 'permissions',
      render: (_: any, record: User) => {

      render: (_: any, record: User) => {
        const perms = record.role?.permissions ?? [];
        if (perms.length === 0)
          return (
            <Text type="secondary" className="!text-xs">
              —
            </Text>
          );
        return (
          <Space size={[0, 4]} wrap>
            {perms.slice(0, 2).map((p) => (
              <Tag
                key={String(p.id)}
                className="bg-muted text-muted-foreground !rounded-full !border-0 !text-xs"
              >
                {p.name ?? p.slug ?? String(p.id)}
              </Tag>
            ))}
            {perms.length > 2 && (
              <Tag className="bg-muted text-muted-foreground !rounded-full !border-0 !text-xs">
                +{perms.length - 2}
              </Tag>
            )}
          </Space>
        );
      },
    },
    {
      title: '',
      key: 'action',
      width: 48,
      align: 'right' as const,
      render: (_: any, record: User) =>
        !canUpdateUsers ? null : record.role == null ? (
          <Tooltip title="Assign Role">
            <Button
              type="text"
              size="small"
              icon={<PlusOutlined />}
              onClick={() => openAssignRole(record)}
              className="!text-primary hover:!bg-primary/5 !rounded-lg"
            />
          </Tooltip>
        ) : (
          <Tooltip title="Change Role">
            <Button
              type="text"
              size="small"
              icon={<EditOutlined />}
              onClick={() => openAssignRole(record)}
