'use client';

import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { fetchJson } from '@/utils/api';
import { unwrapData } from '@/api/core/envelopes';
import type { ApiEnvelope } from '@/api/types/envelopes';
import { useAuthStore } from '@/store/auth';
import {
  DIRECTORY_USERS_QUERY_KEY,
  fetchDirectoryUsers,
} from '@/utils/directoryUsers';
import { EMPLOYEES_API_BASE } from '@/utils/constants';
import { checkUserPermission, PERMISSIONS } from '@/utils/permissions';

export type Permission = {
  id: string | number;
  name?: string;
  slug?: string;
  [k: string]: any;
};

export type Role = {
  id: string | number;
  roleName?: string;
  rolename?: string;
  name?: string;
  permissions?: Permission[];
  [k: string]: any;
};

export type RoleListParams = {
  page?: number;
  limit?: number;
  search?: string;
};

export type RoleCreateInput = {
  roleName: string;
};

export type RoleUpdateInput = {
  id: string | number;
  roleName?: string;
};

export type AssignPermissionsInput = {
  roleId: string | number;
  permissions: Array<string | number>;
};

export type User = {
  id: string | number;
  first_name?: string;
  last_name?: string;
  email?: string;
  profile_pic?: string | null;
  role?: Role | null;
  [k: string]: any;
};

export type UpdateUserRoleInput = {
  userId: string | number;
  roleId: string | number;
};

function useToken() {
  const token = useAuthStore((s) => s.token);
  return (
    token ??
    (typeof window !== 'undefined' ? localStorage.getItem('token') : null)
  );
}

function toQueryString(params: Record<string, any>) {
  const sp = new URLSearchParams();
  Object.entries(params).forEach(([k, v]) => {
    if (v === undefined || v === null || v === '') return;
    sp.set(k, String(v));
  });
  const qs = sp.toString();
  return qs ? `?${qs}` : '';
}

// Roles Query
export function useRolesQuery(params?: RoleListParams) {
  const token = useToken();
  const qs = params ? toQueryString(params) : '';
  const canViewRoles = checkUserPermission([PERMISSIONS.roleView]);

  return useQuery({
    queryKey: ['roles', params?.page, params?.limit, params?.search],
    queryFn: async () => {
      const res = await fetchJson<any>(`/role${qs}`, { token });
      // Legacy response shape: { data: [...] }
      const roles = unwrapData<Role[]>(
        { data: (res as Record<string, unknown>)?.data ?? res?.roles },
        [],
      );
      return Array.isArray(roles) ? roles : [];
    },
    enabled: !!token && canViewRoles,
    staleTime: 5 * 60 * 1000, // 5 minutes
  });
}

// Single Role Query
// Note: This endpoint may not exist in the backend. If it doesn't, use useRolesQuery and find the role.
export function useRoleQuery(roleId: string | number | null, roles?: Role[]) {
  const token = useToken();

  return useQuery({
    queryKey: ['role', roleId],
    queryFn: async () => {
      // Try to fetch single role first
      try {
        const res = await fetchJson<any>(`/role/${roleId}`, { token });
        const role = unwrapData<Role | null>(res, res as Role);
        if (role) return role;
      } catch {
        // If endpoint doesn't exist, fall back to finding in provided list
      }

      // Fallback: find role in the provided list
      if (roles) {
        return roles.find((r) => String(r.id) === String(roleId)) || null;
      }

      return null;
    },
    enabled: !!token && !!roleId,
    staleTime: 5 * 60 * 1000,
  });
}

// Permissions Query
export function usePermissionsQuery() {
  const token = useToken();
  const canViewPermissions = checkUserPermission([PERMISSIONS.permissionView]);
  return useQuery({
    queryKey: ['permissions'],
    queryFn: async () => {
      const res = await fetchJson<any>('/permission', { token });
      // Legacy response shape: { data: [...] }
      const permissions = unwrapData<Permission[]>(
        { data: (res as Record<string, unknown>)?.data ?? res?.permissions },
        [],
      );
      return Array.isArray(permissions) ? permissions : [];
    },
    enabled: !!token && canViewPermissions,
    staleTime: 5 * 60 * 1000,
  });
}

// Create Role Mutation
export function useCreateRoleMutation() {
  const token = useToken();

  const token = useToken();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (input: RoleCreateInput) => {
      return fetchJson<ApiEnvelope<Role>>('/role', {
        token,
        method: 'POST',
        body: input,
      });
    },
    meta: { successMessage: 'Role created successfully' },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['roles'] });
    },
  });
}

// Update Role Mutation
export function useUpdateRoleMutation() {
  const token = useToken();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (input: RoleUpdateInput) => {
      const { id, ...rest } = input;
      return fetchJson<ApiEnvelope<Role>>(`/role/${id}`, {
        token,
        method: 'PATCH',
        body: rest,
      });
    },
    meta: { successMessage: 'Role updated successfully' },
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({ queryKey: ['roles'] });
      queryClient.invalidateQueries({ queryKey: ['role', variables.id] });
    },
  });
}

// Delete Role Mutation
export function useDeleteRoleMutation() {
  const token = useToken();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (roleId: string | number) => {
      return fetchJson(`/role/${roleId}`, { token, method: 'DELETE' });
    },
    meta: { successMessage: 'Role deleted successfully' },
    onSuccess: (_, roleId) => {
      queryClient.invalidateQueries({ queryKey: ['roles'] });
      queryClient.invalidateQueries({ queryKey: ['role', roleId] });
    },
  });
}

// Assign Permissions to Role Mutation
export function useAssignPermissionsMutation() {
  const token = useToken();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async ({ roleId, permissions }: AssignPermissionsInput) => {
      return fetchJson<ApiEnvelope<Role>>(`/rolePermission/${roleId}`, {
        token,
        method: 'POST',
        body: { permissions },
      });
    },
    meta: { successMessage: 'Permissions assigned successfully' },
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({ queryKey: ['roles'] });
      queryClient.invalidateQueries({ queryKey: ['role', variables.roleId] });
      queryClient.invalidateQueries({ queryKey: DIRECTORY_USERS_QUERY_KEY });
    },
  });
}

// Users Query (for Roles page - list users with role/permissions)
export function useUsersQuery() {
  const token = useToken();
  const canViewUsers = checkUserPermission([PERMISSIONS.employeeView]);
  return useQuery({
    queryKey: DIRECTORY_USERS_QUERY_KEY,
    queryFn: () => fetchDirectoryUsers(token),
    enabled: !!token && canViewUsers,
    staleTime: 60 * 1000,
  });
}

// Update User Role Mutation (assign role to user)
export function useUpdateUserRoleMutation() {
  const token = useToken();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async ({ userId, roleId }: UpdateUserRoleInput) => {
      return fetchJson(
        `${EMPLOYEES_API_BASE.replace(/\/$/, '')}/update-user-role/${userId}`,
        {
          token,
          method: 'PATCH',
          body: { roleId },
        },
      );
    },
    meta: { successMessage: 'Role assigned successfully' },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: DIRECTORY_USERS_QUERY_KEY });
      queryClient.invalidateQueries({ queryKey: ['roles'] });
    },
  });
}

