import {
  signInWithEmailAndPassword,
  signInWithPopup,
  type User,
} from 'firebase/auth';
import {
  getFirebaseAuth,
  getGoogleAuthProvider,
  getMicrosoftOAuthProvider,
} from '@/utils/firebaseConfig';
import { ORG_AND_EMP_URL, URL as SERVICE_DESK_API_URL } from '@/utils/constants';
import { useAuthStore } from '@/store/auth';
import {
  domainLabelFromHostname,
  fetchTenantClientByDomain,
  type TenantClientRecord,
} from './tenantChecker';

export type DeskSignInResult = {
  token: string;
  user: Record<string, unknown>;
  activeCalendar: string | null;
};

type BackendUserRow = {
  id: string;
  tenantId: string;
  raw: Record<string, unknown>;
};

function readPasswordChangedFlag(claims: Record<string, unknown>): boolean {
  const keys = [
    'password_changed',
    'passwordChanged',
    'hasChangedPassword',
  ] as const;
  for (const k of keys) {
    if (k in claims) return Boolean((claims as Record<string, unknown>)[k]);
  }
  return true;
}

function mapFirebaseAuthError(err: unknown): Error {
  const code = (err as { code?: string })?.code;
  const msg = (err as { message?: string })?.message;
  switch (code) {
    case 'auth/invalid-email':
      return new Error('Invalid email address.');
    case 'auth/user-disabled':
      return new Error('This account has been disabled.');
    case 'auth/user-not-found':
    case 'auth/wrong-password':
    case 'auth/invalid-credential':
      return new Error('Incorrect email or password.');
    case 'auth/too-many-requests':
      return new Error('Too many attempts. Try again later.');
    case 'auth/popup-closed-by-user':
      return new Error('Sign-in was cancelled.');
    case 'auth/account-exists-with-different-credential':
      return new Error(
        'This email is already linked to another sign-in method. Sign in with your email and password first.',
      );
    default:
      return new Error(msg || 'Sign-in failed. Please try again.');
  }
}

function pickBootstrapCalendar(row: Record<string, unknown>): string | null {
  const v =
    row.activeCalendar ??
    row.active_calendar ??
    row.fiscalYearEndDate ??
    row.fiscal_year_end_date;
  if (v != null && String(v).trim()) return String(v).trim();
  return null;
}

/** Org / HRMS user row (profile, tenant). Not used for Service Desk RBAC. */
async function fetchOrgEmpUserByFirebaseUid(
  localId: string,
  bearer: string,
): Promise<Record<string, unknown> | null> {
  if (!ORG_AND_EMP_URL) return null;
  const base = ORG_AND_EMP_URL.replace(/\/+$/, '');
  const url = `${base}/users/firebase/${encodeURIComponent(localId)}`;
  const res = await fetch(url, {
    method: 'GET',
    headers: { Authorization: `Bearer ${bearer}` },
    cache: 'no-store',
  });
  if (!res.ok) return null;
  const j = (await res.json()) as Record<string, unknown>;
  return (j?.data ?? j) as Record<string, unknown>;
}

/** Local Service Desk `user` + `role` + `role.permissions` (Nest `GET /users/firebase/:localId`). */
async function fetchServiceDeskUserByFirebaseUid(
  localId: string,
  bearer: string,
  tenantIdHeader: string | undefined,
): Promise<Record<string, unknown> | null> {
  if (!SERVICE_DESK_API_URL?.trim()) return null;
  const base = SERVICE_DESK_API_URL.replace(/\/+$/, '');
  const url = `${base}/users/firebase/${encodeURIComponent(localId)}`;
  const headers: Record<string, string> = {
    Authorization: `Bearer ${bearer}`,
  };
  const tid = tenantIdHeader?.trim();
  if (tid) {
    headers.tenantId = tid;
    headers['x-tenant-id'] = tid;
  }
  const res = await fetch(url, { method: 'GET', headers, cache: 'no-store' });
  if (!res.ok) return null;
  const j = (await res.json()) as Record<string, unknown>;
  return (j?.data ?? j) as Record<string, unknown>;
}

/**
 * Keep HRMS/org fields for display (name, email, etc.) but identity + RBAC
 * come from the Service Desk DB (`id`, `tenantId`, `role`, teams, company).
 */
function mergeOrgHrmsProfileWithDeskIdentity(
  org: Record<string, unknown>,
  desk: Record<string, unknown>,
): Record<string, unknown> {
  const merged: Record<string, unknown> = { ...org };

  delete merged.userPermissions;
  delete merged.role;
  delete merged.roleId;
  delete merged.role_id;

  const deskTenant =
    desk.tenant_id != null
      ? String(desk.tenant_id).trim()
      : desk.tenantId != null
        ? String(desk.tenantId).trim()
        : '';
  const orgTenant =
    org.tenantId != null
      ? String(org.tenantId).trim()
      : org.tenant_id != null
        ? String(org.tenant_id).trim()
        : '';
  const tenantId = deskTenant || orgTenant;

  if (desk.id == null) {
    throw new Error(
      'Service Desk user record is missing an id. Contact your administrator.',
    );
  }

  merged.id = String(desk.id);
  merged.tenantId = tenantId;
  merged.tenant_id = tenantId;
  merged.role = desk.role ?? null;

  if (desk.local_id != null) merged.local_id = desk.local_id;
  if (desk.localId != null) merged.localId = desk.localId;

  for (const k of ['teams_access', 'managed_teams', 'company'] as const) {
    if (desk[k] !== undefined) merged[k] = desk[k];
  }

  return merged;
}

async function loadLoginBackendRow(
  localId: string,
  bearer: string,
): Promise<BackendUserRow | null> {
  const org = await fetchOrgEmpUserByFirebaseUid(localId, bearer);
  if (!org) return null;

  const orgTenantRaw = org.tenantId ?? org.tenant_id;
  if (orgTenantRaw == null || !String(orgTenantRaw).trim()) return null;

  if (!SERVICE_DESK_API_URL?.trim()) {
    throw new Error(
      'Service Desk API URL is not configured. Set NEXT_PUBLIC_SERVICE_DESK_API_URL or NEXT_PUBLIC_API_URL so role and permissions load from the Service Desk database.',
    );
  }

  const orgTenant = String(orgTenantRaw).trim();
  const desk = await fetchServiceDeskUserByFirebaseUid(
    localId,
    bearer,
    orgTenant,
  );
  if (!desk) {
    throw new Error(
      'Your account is not set up in Service Desk yet, or your session could not be verified. Ask an administrator to provision your user in Service Desk.',
    );
  }

  const merged = mergeOrgHrmsProfileWithDeskIdentity(org, desk);
  const sessionTenant = String(
    merged.tenantId ?? merged.tenant_id ?? orgTenant,
  ).trim();
  return {
    id: String(merged.id),
    tenantId: sessionTenant,
    raw: merged,
  };
}

function assertTenantGuard(
  tenantFromDomain: TenantClientRecord | null,
  backendTenantId: string,
): { ok: true } | { ok: false; message: string } {
  if (process.env.NODE_ENV !== 'production') return { ok: true };
  if (!tenantFromDomain) return { ok: true };
  if (tenantFromDomain.isPWA !== false) return { ok: true };
  if (tenantFromDomain.id !== backendTenantId) {
    return {
      ok: false,
      message:
        'Your account belongs to a different organization than this site. Please use the correct portal URL.',
    };
  }
  return { ok: true };
}

function splitDisplayName(display: string | null | undefined): {
  first: string;
  last: string;
} {
  const d = (display || '').trim();
  if (!d) return { first: '', last: '' };
  const parts = d.split(/\s+/);
  const first = parts[0] ?? '';
  const last = parts.slice(1).join(' ');
  return { first, last };
}

function buildDeskUserRecord(params: {
  fbUser: User;
  backend: BackendUserRow;
  emailFallback: string;
  password_changed: boolean;
  claims: Record<string, unknown>;
}): Record<string, unknown> {
  const { fbUser, backend, emailFallback, password_changed, claims } = params;
  const row = backend.raw;
  const email =
    (typeof row.email === 'string' && row.email) ||
    fbUser.email ||
    emailFallback;
  const { first: dnFirst, last: dnLast } = splitDisplayName(
    fbUser.displayName,
  );
  const first_name =
    (typeof row.first_name === 'string' && row.first_name) ||
    (typeof row.firstName === 'string' && row.firstName) ||
    dnFirst;
  const last_name =
    (typeof row.last_name === 'string' && row.last_name) ||
    (typeof row.lastName === 'string' && row.lastName) ||
    dnLast;

  const user_type =
    (typeof row.user_type === 'string' && row.user_type) ||
    (typeof row.userType === 'string' && row.userType) ||
    (typeof claims.user_type === 'string' && claims.user_type) ||
    (typeof claims.userType === 'string' && claims.userType) ||
    'employee';

  /** RBAC from merged row: Service Desk `role` (org/HRMS `role` was stripped at merge). */
  const deskRole = row.role;
  const { role: _roleStrippedFromSpread, ...rowWithoutRole } = row as Record<
    string,
    unknown
  > & { role?: unknown };

  let rolePermissionSlugs: string[] | undefined;
  if (deskRole && typeof deskRole === 'object') {
    const perms = (deskRole as { permissions?: unknown[] }).permissions;
    if (Array.isArray(perms) && perms.length) {
      const slugs = perms
        .map((p) =>
          typeof p === 'string' ? p : (p as { slug?: string })?.slug,
        )
        .filter((s): s is string => typeof s === 'string' && !!s.trim())
        .map((s) => s.trim().toLowerCase());
      if (slugs.length) rolePermissionSlugs = slugs;
    }
  }

  return {
    ...rowWithoutRole,
    id: backend.id,
    tenantId: backend.tenantId,
    localId: fbUser.uid,
    email,
    first_name,
    last_name,
    user_type,
    role: deskRole,
    ...(rolePermissionSlugs?.length ? { rolePermissionSlugs } : {}),
    password_changed,
  };
}

async function prepareTenantContext(): Promise<{
  hostname: string;
  domain: string;
  tenantFromDomain: TenantClientRecord | null;
}> {
  const hostname =
    typeof window !== 'undefined' ? window.location.hostname : '';
  useAuthStore.getState().setHostname(hostname);
  const domain = domainLabelFromHostname(hostname);
  const tenantFromDomain = domain
    ? await fetchTenantClientByDomain(domain)
    : null;
  return { hostname, domain, tenantFromDomain };
}

async function completeFirebaseSignIn(
  fbUser: User,
  emailFallback: string,
  tenantFromDomain: TenantClientRecord | null,
): Promise<DeskSignInResult> {
  if (!ORG_AND_EMP_URL?.trim()) {
    throw new Error(
      'ORG_AND_EMP_URL is not configured. Set it in the environment to sign in.',
    );
  }

  const token = await fbUser.getIdToken();
  const idTokenResult = await fbUser.getIdTokenResult();

  const idTokenResult = await fbUser.getIdTokenResult();
  const claims = (idTokenResult.claims ?? {}) as Record<string, unknown>;

  const backend = await loadLoginBackendRow(fbUser.uid, token);
  if (!backend) {
    throw new Error(
      'We could not load your user profile from the server. Please contact your administrator.',
    );
  }

  const guard = assertTenantGuard(tenantFromDomain, backend.tenantId);
  if (!guard.ok) throw new Error(guard.message);

  const password_changed = readPasswordChangedFlag(claims);
  const user = buildDeskUserRecord({
    fbUser,
    backend,
    emailFallback,
    password_changed,
    claims,
  });

  const activeCalendar = pickBootstrapCalendar(backend.raw);

  return { token, user, activeCalendar };
}

export async function signInWithDeskCredentials(
  email: string,
  password: string,
): Promise<DeskSignInResult> {
  const { tenantFromDomain } = await prepareTenantContext();
  const auth = getFirebaseAuth();
  try {
    const cred = await signInWithEmailAndPassword(
      auth,
      email.trim(),
      password,
    );
    return await completeFirebaseSignIn(
      cred.user,
      email.trim(),
      tenantFromDomain,
    );
  } catch (e) {
    throw mapFirebaseAuthError(e);
  }
}

export async function signInWithGoogleForDesk(): Promise<DeskSignInResult> {
  const { tenantFromDomain } = await prepareTenantContext();
  const auth = getFirebaseAuth();
  try {
    const res = await signInWithPopup(auth, getGoogleAuthProvider());
    const email = res.user.email || '';
    return await completeFirebaseSignIn(res.user, email, tenantFromDomain);
  } catch (e) {
    throw mapFirebaseAuthError(e);
  }
}

export async function signInWithMicrosoftForDesk(): Promise<DeskSignInResult> {
  const { tenantFromDomain } = await prepareTenantContext();
  const auth = getFirebaseAuth();
  try {
    const res = await signInWithPopup(auth, getMicrosoftOAuthProvider());
    const email = res.user.email || '';
    return await completeFirebaseSignIn(res.user, email, tenantFromDomain);
  } catch (e) {
    throw mapFirebaseAuthError(e);
  }
}

import { TENANT_MGMT_URL } from '@/utils/constants';
import { getTenantClientByDomain } from '@/api/services/tenant.service';
import { normalizeEnvUrl } from '@/utils/normalizeEnvUrl';

export type TenantClientRecord = {
  id: string;
  isPWA?: boolean;
  raw?: Record<string, unknown>;
};

/**
 * First hostname label before the first dot (e.g. `acme.app.example` → `acme`).
 * For `localhost`, returns `localhost`.
 */
export function domainLabelFromHostname(hostname: string): string {
  const h = (hostname || '').trim().toLowerCase();
  if (!h) return '';
  const i = h.indexOf('.');
  if (i <= 0) return h;
  return h.slice(0, i);
}

/**
 * Legacy tenant resolution via `NEXT_PUBLIC_TENANT_RESOLVE_URL` / default id.
 */
export async function resolveTenantId(
  hostname: string,
): Promise<string | null> {
  const def = process.env.NEXT_PUBLIC_DEFAULT_TENANT_ID ?? null;
  const tpl = process.env.NEXT_PUBLIC_TENANT_RESOLVE_URL?.trim();
  if (!tpl) return def;

  const url = tpl
    .replace('{host}', encodeURIComponent(hostname))
    .replace('{domain}', encodeURIComponent(hostname));

  try {
    const base = normalizeEnvUrl(url);
    const res = await fetch(base, { method: 'GET', cache: 'no-store' });
    if (!res.ok) return def;
    const j = (await res.json()) as Record<string, unknown>;
    const data = (j?.data ?? j) as Record<string, unknown>;
    const id =
      data?.tenantId ?? data?.tenant_id ?? data?.id ?? j?.tenantId ?? j?.id;
    if (id != null && String(id)) return String(id);
  } catch {
    // ignore
  }
  return def;
}

/**
 * CRM-aligned: GET `{TENANT_MGMT_URL}/clients/get-clients/domain/name/client-data/{domain}`.
 */
export async function fetchTenantClientByDomain(
  domain: string,
): Promise<TenantClientRecord | null> {
  const d = (domain || '').trim();
  if (!d || !TENANT_MGMT_URL) return null;

  try {
    const data = await getTenantClientByDomain(d);
    if (!data) return null;
    const id = data?.id ?? data?.tenantId ?? data?.tenant_id;
    if (id == null || !String(id)) return null;
    const isPWA = data?.isPWA ?? data?.is_pwa;
    return {
      id: String(id),
      isPWA: typeof isPWA === 'boolean' ? isPWA : undefined,
      raw: data,
    };
  } catch {
    return null;
  }
}

