    return (
      <main style={{ fontFamily: 'sans-serif', padding: '2rem' }}>
        <h1>Service Status</h1>
        <p>Backend unavailable (status: {res.status})</p>
      </main>
    );
  }
  const data = (await res.json()) as { status: string };
  return (
    <main style={{ fontFamily: 'sans-serif', padding: '2rem' }}>
      <h1>Service Status</h1>
      <p>Backend status: {data.status}</p>
    </main>
  );
}
